INSERT INTO texts VALUES(483,'Téléportation Parallèle',replace(replace('Sacrifiez 1 monstre Psychique avec un Niveau; Invoquez Spécialement 1 monstre Psychique de max. Niveau 7 depuis votre Deck ou Extra Deck, puis si le Niveau d''origine du monstre Sacrifié est différent de celui du monstre Invoqué Spécialement sur le Terrain, vous perdez des LP égaux à la différence x 1000. \r\nVous ne pouvez pas Invoquer Spécialement (monstres Psychique exclus) le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Téléportation Parallèle" par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511,'Penducoucou Labrynth',replace(replace('(Effet Rapide): vous pouvez défausser cette carte; ce tour, vous pouvez activer 1 Carte Piège Normal qui a été Posée ce tour, si vous contrôlez un monstre "Labrynth". \r\nSi une ou plusieurs cartes sont envoyées depuis votre main au Cimetière pour activer votre Carte Piège Normal ou votre carte ou effet "Labrynth" ("Penducoucou Labrynth" exclu), tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez ajouter cette carte à votre main, ou l''Invoquer Spécialement. \r\nVous ne pouvez utiliser chaque effet de "Penducoucou Labrynth" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Ajouter cette carte à la main ou l''Invoquer Spécialement','Activer en appliquant l''effet de "Penducoucou Labrynth".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000,'Dragon Dix-Mille',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement en Sacrifiant des monstres que vous contrôlez dont la somme des ATK/DEF est min. 10 000. \r\nSi elle est Invoquée de cette façon, l''ATK/DEF de cette carte deviennent 10 000.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27551,'Inverseur de Limite',replace(replace('Ciblez 1 monstre avec max. 1000 ATK dans votre Cimetière; Invoquez-le Spécialement en Position d''Attaque. \r\nSi la cible est changée en Position de Défense, détruisez-la ainsi que cette carte. \r\nLorsque cette carte quitte le Terrain, détruisez la cible. \r\nLorsque la cible est détruite, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32864,'La 13ème Tombe','Un zombie qui surgit de l''emplacement n°13, une tombe vide.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35699,'Dormeur ESPIRALE',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en bannissant 3 cartes "ESPIRALE" depuis votre Cimetière, et non Invocable Spécialement autrement. \r\nUne fois par tour, durant le tour de chaque joueur: vous pouvez cibler 1 carte "ESPIRALE" que vous contrôlez et max. 2 cartes contrôlées par votre adversaire; détruisez-les. \r\nSi cette carte sur le Terrain est détruite au combat ou par un effet de carte, et envoyée au Cimetière: détruisez autant de cartes que vous contrôlez que possible, et si vous le faites, Invoquez Spécialement 1 "Super Espion ESPIRALE" depuis votre main, Deck ou Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39015,'Sentinelle d''Assaut',replace(replace('Vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 monstre depuis votre main ou Deck qui liste spécifiquement "Activation Mode Assaut" dans son texte ("Sentinelle d''Assaut" exclu), et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (Monstres Synchro exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous pouvez cibler 1 monstre face recto que vous contrôlez; révélez 1 Monstre Synchro depuis votre Extra Deck, et si vous le faites, les Type et Attribut du monstre ciblé deviennent les mêmes que ceux du monstre révélé jusqu''à la fin de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Sentinelle d''Assaut" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Changer le Type/l''Attribut','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41546,'D/D Savant Thomas',replace(replace('Échelle Pendule = 6\r\n[ Effet Pendule ]\r\nDurant votre Main Phase: vous pouvez ajouter 1 Monstre Pendule "D/D" face recto depuis votre Extra Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "D/D Savant Thomas" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez cibler 1 carte "D/D" dans votre Zone Pendule; détruisez la carte, et si vous le faites, Invoquez Spécialement 1 monstre "D/D/D" de Niveau 8 depuis votre Deck en Position de Défense, mais le reste de ce tour, ses effets (s''il en a) sont annulés, et aussi, les dommages de combat reçus par votre adversaire seront divisés par deux. \r\nVous ne pouvez utiliser cet effet de "D/D Savant Thomas" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41777,'Amélioration-Gemmes','Sacrifiez 1 monstre "Chevalier-Gemmes", puis ciblez 1 monstre "Chevalier-Gemmes" dans votre Cimetière; Invoquez Spécialement la cible depuis le Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43227,'Magnum le Releveur',replace(replace('1 monstre Invoqué Spécialement depuis l''Extra Deck + 1 monstre dans la main	\r\nVous pouvez cibler 1 Magie "Polymérisation" ou Magie "Fusion" dans votre Cimetière; placez la carte au-dessous du Deck, puis piochez 1 carte. \r\nLorsqu''une autre carte ou son effet est activé (Effet Rapide): vous pouvez bannir 1 Magie "Polymérisation" ou Magie "Fusion" depuis votre Cimetière, puis ciblez 1 carte sur le Terrain; détruisez-la. \r\nVous ne pouvez utiliser chaque effet de "Magnum le Releveur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Récupérer et piocher','Bannir et détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44818,'Orbitael, Chevalier Étoilé',replace(replace('(Effet Rapide): vous pouvez cibler 1 monstre LUMIÈRE que vous contrôlez; Sacrifiez-le, et si vous le faites, Posez 1 Magie/Piège "Chevalier Étoilé" directement depuis votre Deck. \r\nSi un monstre LUMIÈRE Dragon de Niveau 7 face recto que vous contrôlez est renvoyé à la main, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte. \r\nVous ne pouvez utiliser chaque effet de "Orbitael, Chevalier Étoilé" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50755,'Cercle du Magicien','Lorsqu''un monstre Magicien déclare une attaque: chaque joueur Invoque Spécialement 1 monstre Magicien avec max. 2000 ATK depuis son Deck en Position d''Attaque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56889,'Duel Transdimensionnel',replace(replace('Ciblez 1 monstre "Rouages Ancients" que vous contrôlez; bannissez-le. \r\nDurant la prochaine Standby Phase, renvoyez le monstre banni sur le Terrain, et si vous le faites, son ATK devient le double de son ATK d''origine jusqu''à la fin de ce tour. \r\nSi min. 1 "Golem Rouages Ancients" ou "Golem Rouages Ancients - Frappe Ultime" que vous contrôlez va être détruit au combat ou par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59080,'Magia Magique - Tonnerre du Jugement',replace(replace('(Cette carte est toujours traitée comme carte "Magistus" et "Endymion".)	\r\nEnvoyez 1 autre carte "Magistus" face recto que vous contrôlez au Cimetière, ou retirez 2 Compteurs Magie depuis votre Terrain, puis activez 1 de ces effets (mais vous ne pouvez utiliser chaque effet de "Magia Magique - Tonnerre du Jugement" qu''une fois par tour);\r\n● Invoquez Spécialement 1 monstre Magicien depuis votre main, Extra Deck face recto ou Cimetière.\r\n● Bannissez 1 autre carte sur le Terrain.','\r',char(13)),'\n',char(10)),'Activer','Retirer des Compteurs Magie pour activer','Envoyer une carte au Cimetière pour activer','Invocation Spéciale','Bannir','','','','','','','','','','','');
INSERT INTO texts VALUES(62121,'Château des Illusions',replace(replace('FLIP: Augmentez de 200 points l''ATK et la DEF de tous les monstres de Type Zombie face recto sur le Terrain. \r\nTant que cette carte reste face recto sur le Terrain, l''ATK et la DEF des monstres de Type Zombie continuent d''augmenter de 200 points supplémentaires durant chacune de vos Standby Phases. \r\nCet effet continuera jusqu''à votre 4ème tour inclu suivant le tour de son activation.','\r',char(13)),'\n',char(10)),'Retourner','Augmenter l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64865,'Magicien Codeur Cyberse',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Cynet Rituel".\r\nSi un Monstre Lien que vous contrôlez va être utilisé comme Matériel Lien pour un monstre Cyberse, cette carte dans votre main peut aussi être utilisée comme Matériel.\r\nSi cette carte est envoyée depuis la main ou Terrain au Cimetière: vous pouvez envoyer 1 monstre Cyberse depuis votre Deck au Cimetière ou si cette carte Invoquée Rituellement a été envoyée au Cimetière, vous pouvez Invoquer Spécialement le monstre à la place, et aussi, dans n''importe quel cas, vous ne pouvez pas Invoquer Spécialement (monstres Cyberse exclus) le reste de ce tour.\r\nVous ne pouvez utiliser chaque effet de "Magicien Codeur Cyberse" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Envoyer au Cimetière','Envoyée au Cimetière après avoir été Invoquée Rituellement','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64866,'Magicien Codeur Cyberse',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Cynet Rituel".\r\nSi un Monstre Lien que vous contrôlez va être utilisé comme Matériel Lien pour un monstre Cyberse, cette carte dans votre main peut aussi être utilisée comme Matériel.\r\nSi cette carte est envoyée depuis la main ou Terrain au Cimetière: vous pouvez envoyer 1 monstre Cyberse depuis votre Deck au Cimetière ou si cette carte Invoquée Rituellement a été envoyée au Cimetière, vous pouvez Invoquer Spécialement le monstre à la place, et aussi, dans n''importe quel cas, vous ne pouvez pas Invoquer Spécialement (monstres Cyberse exclus) le reste de ce tour.\r\nVous ne pouvez utiliser chaque effet de "Magicien Codeur Cyberse" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Envoyer au Cimetière','Envoyée au Cimetière après avoir été Invoquée Rituellement','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96540,'Temps Frappé',replace(replace('Sacrifiez 1 monstre face recto; Invoquez Spécialement 1 monstre du même Type et Attribut d''origine que le monstre Sacrifié avait sur le Terrain, mais avec 1 Niveau de moins, depuis votre Deck. \r\nVous ne pouvez activer qu''1 "Temps Frappé" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98905,'Spectre Cipher','Si un ou plusieurs Monstres Xyz "Cipher" que vous contrôlez avec du Matériel Xyz sont détruits au combat ou par un effet de carte de votre adversaire, et envoyés à votre Cimetière: ciblez 1 de ces monstres; Invoquez-le Spécialement, et si vous le faites, Invoquez Spécialement 1 Monstre Xyz du même nom que le Monstre Xyz depuis votre Extra Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(102380,'Golem de Lave',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) sur le Terrain de votre adversaire en Sacrifiant 2 monstres qu''il contrôle. \r\nVous ne pouvez pas Invoquer/Poser Normalement le tour où vous Invoquez Spécialement cette carte. \r\nUne fois par tour, durant votre Standby Phase: recevez 1000 points de dommages.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Subissez 1000 dommages','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(109401,'Soldat de la Dimension des Ténèbres',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nVous pouvez bannir 1 carte depuis votre main, puis ciblez 1 de vos monstres TÉNÈBRES bannis; Invoquez Spécialement le monstre en Position de Défense face recto ou face verso. \r\nDurant la End Phase: infligez 100 points de dommages à votre adversaire pour chaque carte Posée sur le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Soldat de la Dimension des Ténèbres" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(111280,'Magie Étendue des Ténèbres',replace(replace('Appliquez ces effets dans l''ordre, selon le nombre de "Magicien Sombre" et/ou "Magicienne des Ténèbres" sur le Terrain et dans les Cimetières.\r\n● 1+: Jusqu''à la fin de ce tour, 1 monstre TÉNÈBRES Magicien sur le Terrain gagne 1000 ATK.\r\n● 2+: Ce tour, votre adversaire ne peut ni activer de cartes ni d''effets en réponse à l''activation de votre Carte Magie/Piège ou effet de Magie/Piège, et aussi, les Magies/Pièges que vous contrôlez ne peuvent pas être détruits par des effets de carte de votre adversaire.\r\n● 3+: Jusqu''à la fin de ce tour, les monstres TÉNÈBRES Magicien que vous contrôlez actuellement ne sont pas affectés par des effets de carte de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(114932,'Fracasseur Sismique','Deux fois par tour, vous pouvez envoyer au Cimetière 1 Carte Magie Continue ou Piège Continu face recto que vous contrôlez pour infliger 500 points de dommages à votre adversaire.','Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(122520,'Élève Céleste Potartiste',replace(replace('Durant le tour de chaque joueur: vous pouvez renvoyer 1 monstre "Potartiste" de min. Niveau 5 que vous contrôlez à la main; Invoquez Spécialement cette carte depuis votre main. \r\nVous ne pouvez utiliser cet effet de "Élève Céleste Potartiste" qu''une fois par tour. \r\nSi cette carte combat un monstre de votre adversaire, le monstre a ses effets annulés jusqu''à la fin de la Damage Step. \r\nAvant le calcul des dommages, si cette carte a attaqué un monstre de votre adversaire tant que vous contrôlez un autre monstre "Potartiste": vous pouvez détruire le monstre de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(123709,'Lancelord Laval',replace(replace('Vous pouvez Invoquer Normalement cette carte sans Sacrifice. \r\nSi vous le faites, durant la End Phase: envoyez-la au Cimetière. \r\nLorsque cette carte sur le Terrain est détruite et envoyée au Cimetière: vous pouvez cibler 1 de vos monstres FEU bannis; ajoutez la cible à votre main.','\r',char(13)),'\n',char(10)),'Invocation sans Sacrifice','Envoyer cette carte au Cimetière','Ajouter à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(126218,'Dé-crâne',replace(replace('Lancez un dé à six faces. \r\nJusqu''à la fin de ce tour, tous les monstres actuellement contrôlés par votre adversaire perdent une ATK/DEF égales au résultat x 100.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(128454,'Oieressort Potartiste',replace(replace('Vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 2 cartes parmi les Monstres Pendules que vous contrôlez et/ou les cartes "Magicien" et "Potartiste" dans votre Zone Pendule; renvoyez-les toutes les deux à la main. \r\nVous ne pouvez utiliser cet effet de "Oieressort Potartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(131182,'Magicien Miracle',replace(replace('Si vous contrôlez un "Magicien Miracle", vous ne pouvez pas Invoquer cette carte. \r\nVotre adversaire ne peut pas sélectionner un autre monstre face recto comme cible d''une attaque. \r\nSi cette carte est détruite au combat, Invoquez-la Spécialement sur le Terrain de votre adversaire à la fin de la Battle Phase. \r\nSi cette carte est détruite par l''effet d''une Carte Magie ou Piège, détruisez 1 monstre contrôlé par votre adversaire.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Détruire 1 monstre(s) contrôlé(s) par l''adversaire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(132308,'Princesse Rikka',replace(replace('Durant votre Main Phase: vous pouvez Invoquer Spécialement cette carte depuis votre main, mais tant qu''elle est face recto dans la Zone Monstre, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Plante exclus). \r\nLorsque votre adversaire active un effet de monstre, tant que vous contrôlez un monstre "Rikka" (Effet Rapide): vous pouvez mélanger cette carte depuis votre main ou Cimetière dans le Deck, et Sacrifiez 1 monstre Plante; annulez l''effet. \r\nVous ne pouvez utiliser chaque effet de "Princesse Rikka" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(135598,'Souris des Clés','Lorsque cette carte est détruite au combat et envoyée au Cimetière, vous pouvez ajouter 1 monstre de Type Bête de Niveau 3 ou moins depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(146746,'Attelage de la Colère à Double Traction',replace(replace('2 monstres Machine	\r\nNon utilisable comme Matériel Lien. \r\nVous ne pouvez utiliser qu''1 des effets suivants de "Attelage de la Colère à Double Traction" par tour, et uniquement une fois le tour.\r\n● Durant la Main Phase (Effet Rapide): vous pouvez envoyer 1 monstre depuis votre main ou Terrain au Cimetière, puis ciblez 1 monstre Machine de Niveau 10 dans votre Cimetière; Invoquez-le Spécialement en Position de Défense, mais annulez ses effets.\r\n● Si cette carte est dans votre Cimetière: vous pouvez envoyer 1 carte depuis votre main ou Terrain au Cimetière; Invoquez Spécialement cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(164710,'Espièglerie des Gnomes',replace(replace('Ce tour, réduisez le Niveau de tous les monstres dans la main de chaque joueur de 1 (même après qu''ils sont Invoqués/Posés). \r\nVous pouvez bannir cette carte depuis le Cimetière; ce tour, réduisez le Niveau de tous les monstres dans la main de chaque joueur de 1 (même après qu''ils sont Invoqués/Posés).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(168917,'Hept Vylon',replace(replace('Une fois par tour: vous pouvez cibler 1 Carte Monstre "Vylon" que vous contrôlez comme Carte d''Équipement; Invoquez Spécialement la cible en Position de Défense face recto. \r\nBannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(176392,'Prototype Koa''ki Meiru',replace(replace('Si un ou plusieurs monstres "Koa''ki Meiru" face recto sur le Terrain doivent être détruits durant la End Phase, vous pouvez détruire cette carte à la place. \r\nLorsqu''un ou plusieurs monstres "Koa''ki Meiru" face recto sur le Terrain sont détruits durant la End Phase, vous pouvez Invoquer Spécialement 1 "Jeton Koa''ki Meiru" (Type Rocher/TERRE/Niveau 4/ATK 1800/DEF 1800).','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Prototype Koa''ki Meiru" à la place de la destruction ?','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(176393,'Jeton Koa''ki Meiru','Invoqué Spécialement avec l''effet de "Prototype Koa''ki Meiru".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(191749,'Flash Hero !!',replace(replace('Bannissez "H - Cœur Passionné", "E - Appel de Détresse", "R - Justice Vertueuse" et "O - Au-delà de l''Âme" depuis votre Cimetière; Invoquez Spécialement 1 Monstre Normal "HÉROS Élémentaire" depuis votre Deck. \r\nCe tour, tous les Monstres Normaux "HÉROS Élémentaire" que vous contrôlez actuellement peuvent attaquer directement votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(197042,'Exosœur Retournia',replace(replace('Si tous les monstres que vous contrôlez sont des monstres "Exosœur" (min. 1): payez 800 LP, puis ciblez 1 carte contrôlée par votre adversaire ou dans son Cimetière; bannissez-la, puis vous pouvez appliquer 1 des effets suivants.\r\n● Immédiatement après la résolution de cet effet, Invoquez par Xyz 1 Monstre Xyz "Exosœur" en utilisant des monstres que vous contrôlez.\r\n● Si vous avez Invoqué par Xyz ce tour, bannissez 1 carte contrôlée par votre adversaire.	\r\nVous ne pouvez activer qu''1 "Exosœur Retournia" par tour.','\r',char(13)),'\n',char(10)),'Invocation Xyz','Bannir une carte','Ne rien faire','','','','','','','','','','','','','');
INSERT INTO texts VALUES(209710,'Clown Flick',replace(replace('Si vous contrôlez min. 2 autres monstres Cyberse et que vous n''avez aucune carte dans votre main: vous pouvez payer 1000 LP; piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Clown Flick" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(212652,'Piège du Scorpion Venimeux','Lorsqu''un monstre de votre adversaire déclare une attaque: détruisez-le, puis infligez 300 points de dommages à votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(213326,'E - Appel de Détresse','Ajoutez 1 monstre "HÉROS Élémentaire" depuis votre Deck à votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(218704,'Fenrir',replace(replace('Cette carte ne peut ni être Invoquée par Invocation Normale ni être Posée. \r\nCette carte ne peut être Invoquée par Invocation Spéciale qu''en retirant du jeu 2 monstres EAU de votre Cimetière. \r\nSi cette carte détruit un monstre de votre adversaire à l''issue d''un combat, votre adversaire saute sa prochaine Draw Phase.','\r',char(13)),'\n',char(10)),'Passer la Draw Phase','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(220414,'Membre du Tour Potartiste',replace(replace('Au début de votre Battle Phase: vous pouvez placer 1 Compteur sur cette carte (max. 2). \r\nCette carte gagne l''effet suivant, selon le nombre de Compteurs sur elle.\r\n● 1: Une fois par tour, lorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez annuler l''attaque.\r\n● 2: Vous pouvez Sacrifier cette carte; jusqu''à la 2e End Phase de votre adversaire, bannissez tous les monstres sur le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(242146,'Baliste Brise-Murailles','Si un monstre équipé de cette carte attaque un monstre en Position de Défense face verso, augmentez l''ATK du monstre équipé de 1500 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(255998,'Guerrier d''Intervention',replace(replace('Durant votre Main Phase 1, vous pouvez activer l''effet de cette carte. \r\nSi vous le faites, elle peut attaquer directement votre adversaire ce tour. \r\nLes autres monstres ne peuvent pas attaquer durant le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Attaque directe','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(259314,'Gantelet Inzektor',replace(replace('Ciblez 1 monstre "Inzektor" face recto que vous contrôlez; équipez cette carte à la cible. \r\nIl gagne 1000 DEF et ne peut pas être détruit par des effets de carte de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(263926,'Bonze Toutseul',replace(replace('Ni Invocable Normalement ni Invocable Spécialement si vous contrôlez un monstre. \r\nVous pouvez Invoquer Spécialement cette carte (depuis votre main) en Position d''Attaque. \r\nSi un ou plusieurs autres monstres sont Invoqués sur votre Terrain tant que vous contrôlez ce monstre: détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(269012,'Chaînes d''Entrave du Dieu',replace(replace('Les monstres de min. Niveau 10 sur le Terrain ne peuvent être ni ciblés ni détruits par des effets de carte. \r\nSi un monstre de min. Niveau 10 détruit un monstre au combat et l''envoie au Cimetière: le joueur qui contrôlait le monstre détruit reçoit 1000 points de dommages. \r\nLorsque cette carte sur le Terrain est détruite par un effet de carte et envoyée au Cimetière: vous pouvez ajouter 1 monstre DIVIN depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Subissez 1000 dommages','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(269510,'Prison de Feu',replace(replace('Tous les monstres Dragon sur le Terrain gagnent 300 DEF. \r\nS''il y a des Monstres Lien sur le Terrain, aucun joueur ne peut Invoquer par Lien de Monstres Lien avec une Classification Lien inférieure à la plus haute Classification Lien sur le Terrain. \r\nLes monstres (Monstres Lien exclus) ne peuvent pas attaquer. \r\nAppliquez les effets suivants tant que min. 2 Monstres Lien Cyberse sont sur le Terrain.\r\n● Annulez les effets activés de monstres Cyberse.\r\n● Les monstres Cyberse ne peuvent ni attaquer, ni être ciblés avec une attaque, ni être ciblés par des effets de carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(276357,'Sauvetage Shinobiseau',replace(replace('Si un ou plusieurs monstres Spirit face recto que vous contrôlez sont renvoyés à votre main tant que cette carte est face recto sur le Terrain (sauf durant la Damage Step): vous pouvez cibler 1 carte contrôlée par votre adversaire; détruisez-la. \r\nLorsqu''un monstre de votre adversaire déclare une attaque: vous pouvez bannir 1 monstre Spirit depuis votre Cimetière; annulez l''attaque, puis terminez la Battle Phase. \r\nVous ne pouvez utiliser chaque effet de "Sauvetage Shinobiseau" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Détruire une carte','Annuler l''attaque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(282886,'Sirènemure Abyssnose',replace(replace('Lorsque cette carte détruit un monstre de votre adversaire au combat et l''envoie au Cimetière: vous pouvez défausser 1 monstre EAU au Cimetière; Invoquez Spécialement 1 monstre "Sirènemure" depuis votre Deck en Position de Défense face recto. \r\nVous ne pouvez utiliser l''effet de "Sirènemure Abyssnose" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(284224,'Double Avatar - Mitsu-Jaku Éveillé',replace(replace('"Pieds du Double Avatar - Kokoku" + 2 monstres "Double Avatar"	\r\nLa première fois que chaque Monstre Fusion "Double Avatar" que vous contrôlez va être détruit au combat chaque tour, il n''est pas détruit. \r\nUne fois par tour, durant votre Main Phase: vous pouvez renvoyer tous les Magies/Pièges contrôlés par votre adversaire à la main. \r\nLorsqu''un effet de monstre est activé sur le Terrain de votre adversaire tant que vous contrôlez min. 2 Monstres Fusion (Effet Rapide): vous pouvez détruire le monstre. \r\nVous ne pouvez utiliser cet effet de "Double Avatar - Mitsu-Jaku Éveillé" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(286392,'Guerrier à Réaction',replace(replace('"Avion à Réaction Synchronique" + 1 monstre non-Syntoniseur ou plus	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez cibler 1 carte contrôlée par votre adversaire; renvoyez-la à la main. \r\nSi cette carte est dans votre Cimetière: vous pouvez Sacrifier 1 monstre de max. Niveau 2; Invoquez Spécialement cette carte en Position de Défense, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Guerrier à Réaction" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(291414,'Dragon de la Convergence des Volontés',replace(replace('Non utilisable comme Matériel Synchro, sauf pour l''Invocation Synchro d''un monstre "Majestueux". \r\nLe nom de cette carte devient "Dragon Majestueux" tant qu''elle est sur le Terrain ou dans le Cimetière. \r\nLorsque vous piochez cette carte: vous pouvez la révéler; Invoquez-la Spécialement depuis votre main, puis, si vous contrôlez un Monstre Synchro Dragon de min. Niveau 8, vous pouvez Invoquer Spécialement 1 monstre Dragon de Niveau 1 depuis votre Deck. \r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Dragon de la Convergence des Volontés" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Invoquer Spécialement 1 monstre Dragon de Niveau 1 depuis le Deck ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(293542,'Loup de Guerre T.G.',replace(replace('Lorsqu''un ou plusieurs monstres de max. Niveau 4 sont Invoqués Spécialement (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nUne fois par tour, durant la End Phase, si cette carte est dans le Cimetière parce qu''elle a été détruite sur le Terrain et y a été envoyée ce tour: vous pouvez ajouter 1 monstre "T.G." ("Loup de Guerre T.G." exclu) depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(295517,'Océan Légendaire',replace(replace('(Cette carte est toujours traitée comme "Umi".)	\r\nTous les monstres EAU sur le Terrain gagnent 200 ATK/DEF. \r\nRéduisez le Niveau de tous les monstres EAU dans la main de chaque joueur et sur le Terrain de 1.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(296499,'Règles Tribales',replace(replace('Sélectionnez 1 Type de monstre. \r\nLes monstres de ce Type ne peuvent attaquer. \r\nSacrifiez 1 monstre de votre Terrain à chacune de vos Standby Phases. \r\nSinon, cette carte est détruite.','\r',char(13)),'\n',char(10)),'Sacrifier 1 monstre pour maintenir "Règles Tribales" ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(298846,'Colchica Farstar',replace(replace('1 monstre non-Lien "Farstar"	\r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Colchica Farstar" qu''une fois par tour. \r\nLorsqu''un monstre est détruit au combat impliquant votre monstre "Farstar", tant que cette carte est dans votre Cimetière: vous pouvez bannir cette carte, puis ciblez le monstre détruit; infligez des dommages à votre adversaire égaux à l''ATK du monstre. \r\nVous ne pouvez utiliser cet effet de "Colchica Farstar" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet de dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(303660,'Amplificateur',replace(replace('Équipable uniquement à "Jinzo". \r\nL''activation et l''effet de cette carte ne peuvent pas être annulés. \r\nL''effet du monstre équipé "Les Cartes Piège, et leurs effets sur le Terrain, ne peuvent pas être activés. Annulez tous les effets de Piège sur le Terrain." devient "Votre adversaire ne peut activer ni de Cartes Piège ni leurs effets sur le Terrain. Annulez tous les effets de Piège contrôlé par votre adversaire." Lorsque cette carte quitte le Terrain, détruisez le monstre équipé.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(313513,'Rouage Magique',replace(replace('Envoyez 3 cartes "Rouages Ancients" que vous contrôlez au Cimetière. \r\nVous pouvez Invoquer Spécialement jusqu''à 1 "Golem Rouages Ancients" depuis votre main et 1 depuis votre Deck, sans tenir compte des conditions d''Invocation. \r\nPuis, détruisez tous les monstres que vous contrôlez excepté "Golem Rouages Ancients". \r\nVous ne pouvez pas Invoquer Normalement ou Poser jusqu''à la fin de votre prochain tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(324483,'Spadassin des Flammes Ultime',replace(replace('"Spadassin des Flammes" + "Dragon des Flammes Combattant"	\r\nVous pouvez cibler 1 monstre contrôlé par votre adversaire; détruisez-le, et si vous le faites, infligez 500 points de dommages à votre adversaire. \r\nCeci est un Effet Rapide si cette carte est équipée avec une Carte d''Équipement. \r\nAu début de la Damage Step, si cette carte combat: vous pouvez doubler l''ATK de cette carte jusqu''à la fin de ce tour, mais si vous le faites, détruisez-la durant la End Phase de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Spadassin des Flammes Ultime" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Détruire un monstre de l''adversaire','Doubler l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(327051,'Vritra Magistus',replace(replace('Ciblez 1 monstre "Magistus" de max. Niveau 4 dans votre Cimetière; Invoquez-le Spécialement. \r\nSi une ou plusieurs cartes "Magistus" dans votre Zone Magie & Piège vont être détruites par un effet de carte de votre adversaire, vous pouvez bannir cette carte depuis votre Cimetière à la place. \r\nVous ne pouvez utiliser chaque effet de "Vritra Magistus" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(336369,'Gusto Squirro','Lorsque cette carte est détruite par un effet de carte et envoyée au Cimetière: vous pouvez Invoquer Spécialement 1 monstre "Gusto" de min. Niveau 5 depuis votre Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(336601,'Protecteur Lunaire',replace(replace('Si votre adversaire contrôle min. 2 monstres, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Protecteur Lunaire" qu''une fois par tour de cette façon. \r\nSi cette carte est Invoquée Normalement ou Spécialement, et que votre adversaire contrôle un monstre: vous pouvez cibler 1 monstre LUMIÈRE de Niveau 4 ("Protecteur Lunaire" exclu) dans votre Cimetière; ajoutez-le à votre main. \r\nVous ne pouvez utiliser cet effet de "Protecteur Lunaire" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(340002,'Éléphantmarteau Potartiste',replace(replace('Si vous contrôlez min. 2 cartes "Potartiste", vous pouvez Invoquer Normalement cette carte sans Sacrifice. \r\nNe peut pas attaquer sauf si vous contrôlez une autre carte "Potartiste". \r\nLorsque cette carte déclare une attaque: vous pouvez renvoyer toutes les Cartes Magie/Piège contrôlées par votre adversaire à la main.','\r',char(13)),'\n',char(10)),'Invocation sans Sacrifice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(342673,'Magicien Sombre le Magicien de Magie Noire',replace(replace('Le nom de cette carte devient "Magicien Sombre" tant qu''elle est sur le Terrain. \r\nVous ne pouvez utiliser chacun des effets suivants de "Magicien Sombre le Magicien de Magie Noire" qu''une fois par tour. \r\nSi "Sarcophage Brillant" est sur le Terrain: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte est détruite par un effet de carte et qu''un monstre de min. Niveau 5 est sur le Terrain: vous pouvez Invoquer Spécialement cette carte, puis vous pouvez Poser 1 Magie/Piège depuis votre Deck qui mentionne "Magicien Sombre".','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale','Poser une Magie/Piège ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(359563,'Cauchemar Colonie du Mal',replace(replace('2 monstres TÉNÈBRES de Niveau 4	\r\nLorsque votre adversaire Invoque Spécialement un ou plusieurs monstres (sauf durant la Damage Step): vous pouvez détacher 1 Matériel de cette carte; changez ces monstres Invoqués Spécialement en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face verso','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(365213,'Arrivée dans la Lumière',replace(replace('Lorsque cette carte est activée: placez 1 monstre Dragon de Niveau 1 depuis votre main ou Deck au-dessus du Deck. \r\nAucun joueur ne peut renvoyer ni "Dragon Poussière d''Étoile" ni un Monstre Synchro qui le mentionne, depuis le Terrain à l''Extra Deck. \r\nSi un ou plusieurs Monstres Synchro sont Invoqués Spécialement (sauf durant la Damage Step): vous pouvez appliquer 1 de ces effets, mais vous ne pouvez pas appliquer le même effet de "Arrivée dans la Lumière" de nouveau ce tour.\r\n● Piochez 1 carte.\r\n● Invoquez Spécialement 1 Syntoniseur depuis votre main.','\r',char(13)),'\n',char(10)),'Appliquer 1 effet','Piochez 1 carte(s)','Invoquer Spécialement 1 Syntoniseur(s) depuis la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(368382,'Brachion Dinobrume',replace(replace('Échelle Pendule = 6\r\n[ Effet Pendule ]\r\nUne fois, tant que cette carte est dans votre Zone Pendule, vous pouvez annuler un effet de carte activé qui cible une ou plusieurs autres cartes "Dinobrume" que vous contrôlez, puis détruisez cette carte.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi vous ne contrôlez pas "Brachion Dinobrume" dans votre Zone Monstre et que votre adversaire contrôle un monstre qui a la plus haute ATK sur le Terrain (même en cas d''égalité), vous pouvez Invoquer Spécialement cette carte (depuis votre main).','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Brachion Dinobrume" ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(373085,'Hymniste en Feu',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez envoyer un nombre de cartes du dessus du Deck de votre adversaire au Cimetière, égal au nombre de cartes qu''il contrôle. \r\nSi cette carte est Invoquée Spécialement: vous pouvez envoyer un nombre de cartes du dessus de votre Deck au Cimetière, égal au nombre de cartes contrôlées par votre adversaire. \r\nVous ne pouvez utiliser cet effet de "Hymniste en Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(387282,'Sœur Gagaga',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez ajouter 1 Carte Magie/Piège "Gagaga" depuis votre Deck à votre main. \r\nVous pouvez cibler 1 autre monstre "Gagaga" que vous contrôlez; jusqu''à la fin de ce tour, les Niveaux du monstre et de cette carte deviennent la somme de leurs Niveaux actuels. \r\nVous ne pouvez utiliser cet effet de "Sœur Gagaga" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Changer le Niveau','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(402416,'Embrasement Destruction !!!',replace(replace('Un monstre de min. Niveau 10 sur le Terrain avec "Éxodia" dans son nom d''origine gagne ces effets.\r\n● Vous pouvez payer la moitié de vos LP; détruisez autant de cartes dans les Zones Magie & Piège que possible, puis équipez 5 monstres "l''Interdit" depuis votre main et/ou Deck à cette carte comme Magies d''Équipement qui lui donnent chacune 2000 ATK, et aussi, vous ne pouvez pas activer les effets d''autres cartes le reste de ce tour.\r\n● Si cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire.','\r',char(13)),'\n',char(10)),'L''effet de "Embrasement Destruction !!!" est actuellement appliqué.','Détruire les Magies/Pièges sur le Terrain, puis équiper des monstres "L''Interdit"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(402568,'Électro-Girafe',replace(replace('Cette carte peut attaquer directement. \r\nSi cette carte inflige des dommages de combat à votre adversaire par une attaque directe: jusqu''à la fin de ce tour, votre adversaire ne peut activer ni de cartes ni d''effets.','\r',char(13)),'\n',char(10)),'L''adversaire ne peut pas activer de cartes ou d''effets','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(403847,'Les Forces A.','Tous les monstres de Type Guerrier que vous contrôlez gagnent 200 ATK pour chaque monstre de Type Guerrier ou Magicien que vous contrôlez.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(410904,'Éveil des Possédées - Rasenryu',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main ou Deck) en envoyant 1 monstre Magicien face recto et 1 monstre VENT de max. Niveau 4 face recto que vous contrôlez au Cimetière. \r\nVous ne pouvez utiliser chacun des effets suivants de "Éveil des Possédées - Rasenryu" qu''une fois par tour. \r\nLorsque cette carte est Invoquée Spécialement par son effet: vous pouvez renvoyer 1 carte contrôlée par votre adversaire à la main. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez ajouter 1 carte "Artiste du Vent Spirituel" ou 1 Magie/Piège "Possédé" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423585,'Prêtre Invocateur',replace(replace('Tant que cette carte est face recto sur le Terrain, elle ne peut pas être Sacrifiée. \r\nSi cette carte est Invoquée Normalement ou par Flip: changez cette carte en Position de Défense. \r\nUne fois par tour: vous pouvez défausser 1 Magie; Invoquez Spécialement 1 monstre de Niveau 4 depuis votre Deck, mais le monstre ne peut pas attaquer ce tour.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423705,'Gearfried le Chevalier de Fer','Si au moins l''un des joueurs équipe une ou plusieurs Cartes d''Équipement à cette carte: détruisez ces Cartes d''Équipement.','Détruire des Cartes d''Équipement','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423706,'Gearfried le Chevalier de Fer','Si au moins l''un des joueurs équipe une ou plusieurs Cartes d''Équipement à cette carte: détruisez ces Cartes d''Équipement.','Détruire des Cartes d''Équipement','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(425934,'Gobelin Cupide','Tant que cette carte reste face recto sur votre Terrain, aucun joueur ne peut activer "l''effet d''activer en défaussant de sa main".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(433377,'Blitzclique - Précurseur',replace(replace('Si une ou plusieurs cartes sont détruites par un effet de votre carte "Blitzclique" (sauf durant la Damage Step): vous pouvez cibler 1 monstre Tonnerre dans votre Cimetière; ajoutez-le à votre main. \r\nDurant votre Main Phase: vous pouvez Invoquer Spécialement 1 monstre Tonnerre depuis votre main, puis détruisez cette carte. \r\nSi une ou plusieurs cartes sont détruites par un effet de votre carte "Blitzclique", tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez ajouter cette carte à votre main. \r\nVous ne pouvez utiliser chaque effet de "Blitzclique - Précurseur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet de récupération','Invocation Spéciale','Renvoyer à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(440556,'Requin Bahamut',replace(replace('2 monstres EAU de Niveau 4	\r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte; Invoquez Spécialement 1 Monstre Xyz EAU de max. Rang 3 depuis votre Extra Deck. \r\nCette carte ne peut pas attaquer le reste de ce tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(458748,'Le Livre de la Loi',replace(replace('Sacrifiez 1 monstre "Invokhé"; Invoquez Spécialement 1 monstre "Invokhé" depuis votre Extra Deck d''un Attribut d''origine différent de celui du monstre. \r\n(Ceci est traité comme une Invocation Fusion.) \r\nVous ne pouvez activer qu''1 "Le Livre de la Loi" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(464362,'Tigre Frourreur',replace(replace('"Lames du Lutin Tranchant" + 1 monstre "Peluchimal" ou plus	\r\nLorsque cette carte est Invoquée par Fusion: vous pouvez cibler un nombre de cartes sur le Terrain, inférieur ou égal au nombre de Matériels de Fusion utilisés pour son Invocation Fusion; détruisez-les. \r\nTous les monstres "Frourreur" que vous contrôlez gagnent 300 ATK pour chaque monstre "Peluchimal" et monstre "Frourreur" que vous contrôlez. \r\nVous ne pouvez contrôler qu''1 "Tigre Frourreur".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(473469,'Neige Impérieuse',replace(replace('Vous pouvez Activer cette carte lorsqu''1 ou plusieurs de vos Cartes Piège sont détruites et envoyées du Terrain dans le Cimetière par l''effet d''une carte contrôlée par votre adversaire. \r\nDétruit 1 Carte Magie ou Piège sur le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(487395,'Gremlin des Eaux','Cette créature aquatique hante les monolithes glaciaires de l''Antarctique. Son pouvoir surnaturel lui permet de s''infiltrer dans les pores de n''importe quelle substance pour la transformer en glace.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(494922,'Seigneur de Guerre Susanowo Samouraï Supralourd',replace(replace('1 Syntoniseur de Type Machine + 1 monstre non-Syntoniseur "Samouraï Supralourd" ou plus	\r\nCette carte peut attaquer tant qu''elle est en Position de Défense face recto. \r\nSi elle le fait, appliquez sa DEF pour le calcul des dommages. \r\nUne fois par tour, durant le tour de chaque joueur, si vous n''avez aucune Carte Magie/Piège dans votre Cimetière: vous pouvez cibler 1 Carte Magie/Piège dans le Cimetière de votre adversaire; Posez-la sur votre Terrain, mais bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(525110,'Prisomate Cerise',replace(replace('Lorsque cette carte est détruite au combat et envoyée au Cimetière, vous pouvez Invoquer Spécialement jusqu''à 2 monstres "Prisomate" depuis votre Deck. \r\nIls ne peuvent pas être utilisés en tant que Monstres-Matériels de Synchro ce tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invoquer Spécialement un autre monstre ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(545781,'Mahaama le Dragon Féérique',replace(replace('Durant le tour de votre adversaire, lorsqu''un joueur reçoit des dommages de combat: vous pouvez Invoquer Spécialement cette carte depuis votre main, puis appliquez 1 de ces effets.\r\n● Gagnez des LP égaux aux dommages de combat.\r\n● Infligez des dommages à votre adversaire égaux aux dommages de combat.','\r',char(13)),'\n',char(10)),'Gagner des LP','Infliger des dommages','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(549481,'Rat Préventif','Cette créature protégée par une carapace de poils se défend avec panache.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(561300,'La Virulente Vipère',replace(replace('Vous pouvez révéler cette carte dans votre main; Invoquez-la Spécialement, ou si votre adversaire ne contrôle aucun monstre, Invoquez-la Spécialement sur son Terrain en Position de Défense à la place. \r\nUne fois par tour, durant votre Standby Phase: recevez 500 points de dommages. \r\nSi cette carte est bannie ou envoyée au Cimetière par un effet de carte: vous pouvez cibler 1 Magie/Piège Posé contrôlé par votre adversaire; détruisez-le. \r\nVotre adversaire ne peut pas activer la carte en réponse à l''activation de cet effet. \r\nVous ne pouvez utiliser cet effet de "La Virulente Vipère" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet de dommages','Effet de destruction','','','','','','','','','','','','','');
INSERT INTO texts VALUES(564541,'Dragon Totem',replace(replace('Peut être traitée comme 2 Sacrifices pour l''Invocation Sacrifice d''un monstre Dragon. \r\nUne fois par tour, durant votre Standby Phase, si cette carte est dans votre Cimetière et que tous les monstres dans votre Cimetière sont Dragon: vous pouvez Invoquer Spécialement cette carte en Position d''Attaque, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne devez contrôler aucun monstre pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(572850,'Scheiren des Tiarmentations',replace(replace('Durant votre Main Phase: vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, envoyez 1 monstre depuis votre main au Cimetière, puis, envoyez les 3 cartes du dessus de votre Deck au Cimetière. \r\nSi cette carte est envoyée au Cimetière par un effet de carte (sauf durant la Damage Step): vous pouvez Invoquer par Fusion 1 Monstre Fusion depuis votre Extra Deck, en plaçant les Matériels Fusion mentionnés sur celui-ci (cette carte incluse depuis votre Cimetière) depuis votre main, Terrain et/ou Cimetière, au-dessous du Deck dans l''ordre de votre choix. \r\nVous ne pouvez utiliser chaque effet de "Scheiren des Tiarmentations" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(575512,'Circuit Structure-PSY',replace(replace('Si un ou plusieurs monstres "Structure-PSY" sont Invoqués Spécialement sur votre Terrain (sauf durant la Damage Step), vous pouvez: immédiatement après la résolution de cet effet, Invoquez par Synchronisation 1 Monstre Synchro, en utilisant uniquement des monstres "Structure-PSY" que vous contrôlez. \r\nAu début de la Damage Step, si un monstre "Structure-PSY" que vous contrôlez combat un monstre de votre adversaire: vous pouvez défausser 1 monstre "Structure-PSY"; jusqu''à la fin de ce tour, votre monstre combattant gagne une ATK égale à l''ATK du monstre défaussé.','\r',char(13)),'\n',char(10)),'Synchro Invoquer en utilisant vos monstres "Circuit Structure-PSY" comme Matériel','Augmenter l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(581014,'Daigusto Émeral',replace(replace('2 monstres de Niveau 4	\r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte, puis activez 1 de ces effets;\r\n● Ciblez 3 monstres dans votre Cimetière; mélangez-les tous les 3 dans le Deck, puis piochez 1 carte.\r\n● Ciblez 1 monstre (Monstres à Effet exclus) dans votre Cimetière; Invoquez Spécialement la cible.','\r',char(13)),'\n',char(10)),'Activer 1 effet','Récupérer et piocher','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(595626,'Ankuriboh',replace(replace('Lorsqu''un monstre de votre adversaire déclare une attaque: vous pouvez défausser cette carte, puis ciblez 1 monstre dans l''un des Cimetières (cette carte exclue); Invoquez-le Spécialement sur votre Terrain, mais envoyez-le au Cimetière durant la End Phase.\r\nSi cette carte est détruite au combat ou par un effet de carte et envoyée au Cimetière: vous pouvez ajouter 1 "Monster Reborn" depuis votre Deck ou Cimetière à votre main durant la End Phase de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Ankuriboh" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un monstre','Ajouter "Carte Magie "Monster Reborn"" à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(596051,'Crochet de Serpent','Diminuez la DEF du monstre sélectionné de 500 points durant le tour où cette carte est Activée.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(598988,'Dragon Arc-en-Ciel Corrompu',replace(replace('Cette carte ne peut ni être Invoquée Normalement ni être Posée. \r\nCette carte ne peut pas être Invoquée Spécialement, excepté en retirant du jeu 1 "Dragon Arc-en-Ciel" depuis votre main ou Deck. \r\nIl ne peut y avoir qu''1 seul monstre "Corrompu" face recto sur le Terrain. \r\nLes autres monstres que vous contrôlez ne peuvent pas déclarer d''attaque. \r\nS''il n''y a aucune Carte Magie de Terrain face recto sur le Terrain, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(601193,'Virgile, Star du Rock des Abysses Ardents',replace(replace('1 Syntoniseur + 1 monstre non-Syntoniseur ou plus	\r\nVous ne pouvez contrôler qu''1 "Virgile, Star du Rock des Abysses Ardents". \r\nUne fois par tour: vous pouvez défausser 1 carte "Abysses Ardents", puis ciblez 1 carte contrôlée par votre adversaire ou dans son Cimetière; mélangez-la dans le Deck. \r\nSi cette carte sur le Terrain est détruite au combat ou par un effet de carte, et envoyée au Cimetière: vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser cet effet de "Virgile, Star du Rock des Abysses Ardents" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer au Deck','Piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(612115,'Retiarius, Bête Gladiateur','Lorsque cette carte est Invoquée Spécialement par l''effet d''un monstre "Bête Gladiateur": vous pouvez cibler 1 carte dans le Cimetière de votre adversaire; bannissez-la. À la fin de la Battle Phase, si cette carte a combattu: vous pouvez la mélanger dans le Deck; Invoquez Spécialement 1 monstre "Bête Gladiateur" ("Retiarius, Bête Gladiateur" exclu) depuis votre Deck.','Bannir','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(613013,'Requin Veiss',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez Sacrifier 1 monstre Poisson; Invoquez Spécialement 1 monstre "Requin" Poisson depuis votre Deck, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres EAU exclus) le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Requin Veiss" qu''une fois par tour. \r\nUn Monstre Xyz "Requin Drakonien" qui a cette carte comme Matériel gagne cet effet.\r\n● Une fois par tour, lorsqu''une Carte Magie/Piège ou effet de Magie/Piège est activé (Effet Rapide): vous pouvez détacher 2 Matériels de cette carte; annulez l''effet, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Annuler l''activation d''un effet de Magie/Piège (Requin Veiss)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(613496,'Surréglage',replace(replace('Si vous contrôlez un Syntoniseur: Invoquez Spécialement 1 Syntoniseur depuis votre main, Deck ou Cimetière, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Synchro exclus) depuis l''Extra Deck le reste de ce tour après la résolution de cette carte. \r\nVous ne pouvez activer qu''1 "Surréglage" par tour.','\r',char(13)),'\n',char(10)),'Activer','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(637216,'Monster Express',replace(replace('Vous pouvez cibler 1 monstre face recto que vous contrôlez; envoyez 1 monstre depuis votre Extra Deck au Cimetière du même Type d''origine que le monstre face recto, mais le reste de ce tour, vous ne pouvez pas Invoquer Spécialement de monstres (monstres du même Type d''origine que le monstre envoyé au Cimetière par cet effet exclus). \r\nVous ne pouvez utiliser cet effet de "Monster Express" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645087,'Gadget Cyberse',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez cibler 1 monstre de max. Niveau 2 dans votre Cimetière; Invoquez-le Spécialement en Position de Défense, mais ses effets sont annulés. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez Invoquer Spécialement 1 "Jeton Gadget" (Cyberse/LUMIÈRE/Niveau 2/ATK 0/DEF 0). \r\nVous ne pouvez utiliser cet effet de "Gadget Cyberse" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un monstre depuis le Cimetière','Invoquer Spécialement un Jeton','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645088,'Jeton Gadget','Invoqué Spécialement avec l''effet de "Gadget Cyberse".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645794,'Crapaud Majesspectre - Ogama',replace(replace('Échelle Pendule = 5\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nLorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez Poser 1 Carte Magie/Piège "Majesspectre" directement depuis votre Deck, mais elle ne peut pas être activée ce tour. \r\nVous ne pouvez utiliser cet effet de "Crapaud Majesspectre - Ogama" qu''une fois par tour. \r\nTant que cette carte est dans votre Zone Monstre, votre adversaire ne peut pas la cibler avec des effets de carte, et aussi, elle ne peut pas être détruite par des effets de carte de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(652362,'Ammonite Alien','Lorsque cette carte est Invoquée Normalement: vous pouvez cibler 1 monstre "Alien" de max. Niveau 4 dans votre Cimetière; Invoquez-le Spécialement, mais détruisez-le durant la End Phase.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(653675,'Surpassement Synchro',replace(replace('Ciblez un nombre de votre choix de Monstres Synchro Dragon de Niveau 7 ou 8 dans votre Cimetière; Invoquez-les Spécialement en Position de Défense, mais leur Niveau devient 1 et leurs effets sont annulés, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (Monstres Synchro exclus) depuis l''Extra Deck le reste de ce tour. \r\nLorsqu''un Monstre Synchro que vous contrôlez est détruit au combat: vous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 "Dragon Cramoisi" depuis votre Extra Deck. \r\nVous ne pouvez utiliser chaque effet de "Surpassement Synchro" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(674561,'Éruption des Ténèbres','Ciblez 1 monstre TÉNÈBRES avec max. 1500 ATK dans votre Cimetière; ajoutez la cible à votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(675319,'Signe du Zodiaque',replace(replace('Tous les monstres "Zoodiaque" que vous contrôlez gagnent 300 ATK/DEF. \r\nLes monstres contrôlés par votre adversaire ne peuvent pas cibler les monstres de Type Bête-Guerrier face recto que vous contrôlez (monstre de Type Bête-Guerrier que vous contrôlez avec la plus haute ATK exclu, et en cas d''égalité, vous choisissez) avec une attaque. \r\nUne fois par tour, si un ou plusieurs monstres "Zoodiaque" que vous contrôlez vont être détruits par un effet de carte, vous pouvez détruire 1 monstre dans votre main ou sur votre Terrain à la place d''1 monstre "Zoodiaque".','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Signe du Zodiaque" pour détruire un autre monstre à la place ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(691925,'Échange Solaire','Défaussez 1 monstre "Seigneur Lumière"; piochez 2 cartes, puis envoyez les 2 cartes du dessus de votre Deck au Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(698785,'Dragon Tonnerre Final',replace(replace('2 Monstres Normaux de Niveau 8	\r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte; détruisez tous les autres monstres sur le Terrain.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(703897,'Crescendo Orcust',replace(replace('Lorsqu''une Carte Magie/Piège ou un effet de monstre est activé tant que vous contrôlez un Monstre Lien "Orcust": annulez l''activation, et si vous le faites, bannissez la carte. \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 monstre TÉNÈBRES Machine depuis votre Deck ou bannissement à votre main. \r\nVous ne pouvez pas Invoquer Spécialement (monstres TÉNÈBRES Machine exclus) le tour où vous activez cet effet. \r\nVous ne pouvez utiliser qu''1 effet de "Crescendo Orcust" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(706925,'Tireur de l''Atlantide',replace(replace('Lorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez Invoquer Spécialement 1 monstre "Atlantide" Serpent de Mer de max. Niveau 4 ("Tireur de l''Atlantide" exclu) depuis votre Deck. \r\nSi cette carte est envoyée au Cimetière pour activer un effet de monstre EAU: ciblez 1 carte Posée contrôlée par votre adversaire; détruisez la cible.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Détruire une carte Posée','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(712559,'Village Amazonesse',replace(replace('Tous les monstres "Amazonesse" gagnent 200 ATK. \r\nUne fois par tour, lorsqu''un monstre "Amazonesse" est détruit au combat ou par un effet de carte, et envoyé au Cimetière: vous pouvez Invoquer Spécialement 1 monstre "Amazonesse" depuis votre Deck d''un Niveau inférieur ou égal au monstre "Amazonesse" dans le Cimetière.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(720147,'Morsure Boss Genèraideur',replace(replace('Sacrifiez un nombre de votre choix de monstres "Genèraideur", puis ciblez 1 Monstre Xyz face recto que vous contrôlez; attachez-lui exactement autant de monstres "Genèraideur" (monstres Sacrifiés pour activer cet effet exclus) depuis votre main, Terrain et/ou Cimetière. \r\nVous ne pouvez activer qu''1 "Morsure Boss Genèraideur" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(732302,'Temple des Crânes','Un mystérieux temple de crânes et d''os qui attire les ennemis sans méfiance.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(734741,'Rubic, Malebranche des Abysses Ardents',replace(replace('Si vous contrôlez un monstre (monstres "Abysses Ardents" exclus), détruisez cette carte. \r\nNon utilisable comme Matériel de Synchro, sauf pour l''Invocation Synchro d''un Monstre Synchro "Abysses Ardents". \r\nSi vous ne contrôlez aucune Carte Magie/Piège: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nVous ne pouvez utiliser cet effet de "Rubic, Malebranche des Abysses Ardents" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(739444,'Batterigon Vorticulaire',replace(replace('3 monstres TÉNÈBRES Dragon	\r\nSi cette carte est Invoquée Spécialement: vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser cet effet de "Batterigon Vorticulaire" qu''une fois par tour. \r\nSi cet effet se résout, les Zones Monstres inutilisées pointées par cette carte ne peuvent pas être utilisées le reste de ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(744887,'Utgarda, Boss Genèraideur de la Délusion',replace(replace('Vous ne pouvez contrôler qu''1 "Utgarda, Boss Genèraideur de la Délusion". \r\n(Effet Rapide): vous pouvez Sacrifier 2 monstres "Genèraideur" et/ou monstres Rocher, puis ciblez 1 carte sur le Terrain; bannissez-la. \r\nVous ne pouvez utiliser cet effet de "Utgarda, Boss Genèraideur de la Délusion" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(756652,'Doron','Ce monstre se divise en deux et lance son attaque à partir de deux côtés opposés.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759393,'Hiita la Charmeuse de Feu','FLIP: Ciblez 1 monstre FEU contrôlé par votre adversaire; prenez le contrôle du monstre tant que cette carte est face recto sur le Terrain.','Prendre le contrôle d''1 monstre FEU contrôlé par l''adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759394,'Hiita la Charmeuse de Feu','FLIP: Ciblez 1 monstre FEU contrôlé par votre adversaire; prenez le contrôle du monstre tant que cette carte est face recto sur le Terrain.','Prendre le contrôle d''1 monstre FEU contrôlé par l''adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759395,'Hiita la Charmeuse de Feu','FLIP: Ciblez 1 monstre FEU contrôlé par votre adversaire; prenez le contrôle du monstre tant que cette carte est face recto sur le Terrain.','Prendre le contrôle d''1 monstre FEU contrôlé par l''adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(770365,'Impératrice de la Prophétie',replace(replace('2 monstres de Type Magicien de Niveau 5	\r\nCette carte gagne 300 ATK pour chaque Matériel Xyz attaché à un monstre que vous contrôlez. \r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte; mélangez votre Deck, puis dévoilez les 5 cartes du dessus de votre Deck, détruisez un nombre de monstres sur le Terrain inférieur ou égal au nombre de cartes "Livre de Magie" dévoilées, et aussi, après ça, placez les cartes dévoilées au-dessus du Deck dans l''ordre de votre choix.','\r',char(13)),'\n',char(10)),'Révéler le Deck','Détruire un monstre sur le Terrain ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(786906,'Heure Fatidique','Ciblez 1 monstre qui ne peut pas être Invoqué/Posé Normalement dans l''un des Cimetières; Invoquez-le Spécialement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(799183,'Bouclier du Super Soldat',replace(replace('Lorsqu''une Carte Magie/Piège ou effet de monstre qui cible un ou plusieurs monstres sur le Terrain est activé, tant que vous contrôlez un monstre "Soldat du Lustre Noir": annulez l''activation, et si vous le faites, détruisez la carte. \r\nSi cette carte est dans votre Cimetière: vous pouvez retirer 1 Compteur Magie depuis votre Terrain; Posez cette carte, mais bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(811734,'D/D/D Changement de Contrat',replace(replace('Lorsqu''un monstre de votre adversaire déclare une attaque: activez 1 de ces effets;\r\n● Bannissez 1 monstre "D/D/D" depuis votre Cimetière, et si vous le faites, le monstre attaquant perd une ATK égale à l''ATK du monstre banni.\r\n● Ajoutez 1 Monstre Pendule "D/D" de max. Niveau 4 depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Bannir un monstre','Chercher dans le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(816427,'Dame de la Néo Cloche de Feu',replace(replace('(Effet Rapide): vous pouvez envoyer 1 monstre FEU depuis votre main au Cimetière, puis ciblez 1 carte dans le Cimetière de votre adversaire; bannissez la carte. \r\nSi une carte est bannie depuis le Cimetière de votre adversaire, tant que vous contrôlez ce monstre (sauf durant la Damage Step): vous pouvez envoyer 1 monstre FEU avec max. 200 DEF ("Dame de la Néo Cloche de Feu" exclu) depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Dame de la Néo Cloche de Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(821049,'Visas Amritara',replace(replace('1+ Syntoniseur + 1 monstre LUMIÈRE	\r\nLe nom de cette carte devient "Visas Starfrost" tant qu''elle est sur le Terrain. \r\nVous ne pouvez utiliser chacun des effets suivants de "Visas Amritara" qu''une fois par tour. \r\nSi cette carte est Invoquée par Synchronisation: vous pouvez ajouter 1 Magie/Piège qui mentionne "Visas Starfrost" depuis votre Deck à votre main. \r\nDurant votre Main Phase: vous pouvez détruire 1 monstre que vous contrôlez, et aussi, tous les Monstres Synchro que vous contrôlez gagnent 800 ATK ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(844056,'Flèches Rouges',replace(replace('Ciblez max. 2 monstres face recto dans les Zones Monstre Extra; jusqu''à la End Phase, bannissez-les. \r\nVous ne pouvez activer qu''1 "Flèches Rouges" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(847217,'Épée Scelleuse d''Orichalque',replace(replace('Les effets du monstre équipé sont annulés. \r\nSi vous avez une carte dans votre Zone Terrain: vous pouvez cibler 1 Monstre à Effet que vous contrôlez; le Monstre à Effet gagne cet effet jusqu''à la fin du tour de votre adversaire.\r\nVous ne pouvez utiliser l''effet précédent de "Épée Scelleuse d''Orichalque" qu''une fois par tour.\r\n● Une fois par tour (Effet Rapide): vous pouvez envoyer 1 carte depuis votre main au Cimetière, puis ciblez 1 carte face recto sur le Terrain; détruisez la cible.','\r',char(13)),'\n',char(10)),'Obtenir un effet','L''effet de "Épée Scelleuse d''Orichalque" est actuellement appliqué.','Effet de destruction (Épée Scelleuse d''Orichalque)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(847915,'Mur Numéro',replace(replace('Activable uniquement si vous contrôlez un monstre "Numéro". \r\nLes monstres "Numéro" sur le Terrain ne peuvent pas être détruits par des effets de carte, et ne peuvent pas être détruits au combat sauf avec un autre monstre "Numéro". \r\nLorsqu''un monstre "Numéro" que vous contrôlez est détruit, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(856784,'Pioche du Destin',replace(replace('Si vos LP sont inférieurs à ceux de votre adversaire et que votre adversaire contrôle un monstre avec la plus haute ATK sur le Terrain (même en cas d''égalité): révélez 3 cartes de noms différents depuis votre Deck, placez-les aléatoirement au-dessus de votre Deck, puis piochez 1 carte. \r\nLe reste de ce tour après la résolution de cette carte, vous ne pouvez pas Poser de Magies/Pièges, et aussi, vous ne pouvez activer qu''une carte ou effet supplémentaire. \r\nVous ne pouvez activer qu''1 "Pioche du Destin" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(863795,'Invocateur Galactique',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre "Photon" ou "Galactique" ("Invocateur Galactique" exclu) dans votre Cimetière; Invoquez-le Spécialement en Position de Défense. \r\nVous pouvez cibler 1 autre monstre LUMIÈRE que vous contrôlez; jusqu''à la fin de ce tour, il devient de Niveau 4. \r\nVous ne pouvez utiliser chaque effet de "Invocateur Galactique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(875572,'Crowley, Magistus Talentueux',replace(replace('Si cette carte face recto est utilisée comme Matériel Fusion, son nom peut être traité comme "Aleister l''Invokhateur". \r\nVous ne pouvez utiliser chacun des effets suivants de "Crowley, Magistus Talentueux" qu''une fois par tour. \r\nSi cette carte est ajoutée à votre main, sauf en la piochant: vous pouvez l''Invoquer Spécialement. \r\nSi cette carte est Invoquée Normalement ou Spécialement (sauf durant la Damage Step): vous pouvez Invoquer par Fusion 1 Monstre Fusion "Magistus" ou "Invokhé" depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Fusion','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(876330,'Arsenal Dragunité - Mystletainn',replace(replace('Vous pouvez Invoquer Spécialement cette carte depuis votre main en envoyant 1 monstre "Dragunité" face recto que vous contrôlez au Cimetière. \r\nLorsque cette carte est Invoquée Normalement ou Spécialement depuis la main, vous pouvez sélectionner 1 monstre "Dragunité" de Type Dragon dans votre Cimetière et l''équiper à cette carte.','\r',char(13)),'\n',char(10)),'Équiper','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(879958,'Armure Port Parallèle',replace(replace('Ciblez 1 Monstre Lien que vous contrôlez; équipez-le avec cette carte. \r\nVotre adversaire ne peut pas cibler le monstre équipé avec des effets de carte, et aussi, il ne peut pas être détruit au combat. \r\nVous pouvez bannir cette carte et 2 Monstres Lien depuis votre Cimetière, puis ciblez 1 Monstre Lien que vous contrôlez; durant chaque Battle Phase ce tour, il peut faire une seconde attaque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(885016,'Multi-Univers',replace(replace('Activez uniquement si vous ne contrôlez pas de carte face recto dans votre Zone Terrain. \r\nVous pouvez cibler 1 Magie de Terrain qui est bannie ou dans l''un des Cimetières; détruisez cette carte, et si vous le faites, placez la carte ciblée face recto dans votre Zone Terrain. \r\nVous ne pouvez utiliser cet effet de "Multi-Univers" qu''une fois par tour. \r\nSi une ou plusieurs cartes dans la Zone Terrain vont être détruites par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(897409,'Cent Galactique',replace(replace('Lorsque cette carte est activée: vous pouvez envoyer 1 carte "Photon" ou "Galactique" depuis votre Deck au Cimetière. \r\nSi "Dragon Photon aux Yeux Galactiques" est Invoqué Spécialement sur votre Terrain (sauf durant la Damage Step): vous pouvez regarder l''Extra Deck de votre adversaire, puis vous pouvez appliquer 1 de ces effets.\r\n● Bannissez-en 1 monstre.\r\n● Invoquez Spécialement 1 monstre "Numéro" depuis celui-ci sur votre Terrain.	\r\nVous ne pouvez utiliser cet effet de "Cent Galactique" qu''une fois par tour. \r\nVous ne pouvez activer qu''1 "Cent Galactique" par tour.','\r',char(13)),'\n',char(10)),'Envoyer une carte de votre Deck au Cimetière ?','Bannir','Invocation Spéciale','Ne rien faire','','','','','','','','','','','','');
INSERT INTO texts VALUES(899287,'Glife, l''Oiseau Fantôme',replace(replace('Vous pouvez défausser cette carte; ajoutez 1 "Château Doré de Stromberg" depuis votre Deck à votre main. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 carte dans la Zone Magie & Piège de votre adversaire; détruisez-la. \r\nVous ne pouvez utiliser cet effet de "Glife, l''Oiseau Fantôme" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(900787,'Gae Bulg, Chevalier Dragunité',replace(replace('1 Syntoniseur Dragon + 1+ monstre non-Syntoniseur Bête Ailée	\r\nUne fois par combat, si cette carte combat, durant la Damage Step (Effet Rapide): vous pouvez bannir 1 monstre Bête Ailée depuis votre Cimetière; jusqu''à la fin de ce tour, cette carte gagne l''ATK d''origine du monstre.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(904185,'Atterrissage Vertical',replace(replace('Sacrifiez un nombre de votre choix de monstres VENT (Jetons exclus); Invoquez Spécialement un nombre égal de "Jeton Bête Fantôme Méca" (Type Machine/VENT/Niveau 3/ATK 0/DEF 0). \r\nVous ne pouvez activer qu''1 "Atterrissage Vertical" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(904186,'Jeton Bête Fantôme Méca','Invoqué Spécialement avec l''effet d''un monstre "Bête Fantôme Méca" et des cartes associées.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(911883,'Dai Imprévu','Si vous ne contrôlez aucun monstre: Invoquez Spécialement 1 Monstre Normal de max. Niveau 4 depuis le Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(917796,'Gagagatag',replace(replace('Jusqu''à votre prochaine Standby Phase, tous les monstres "Gagaga" que vous contrôlez actuellement gagnent 500 ATK pour chaque monstre "Gagaga" que vous contrôlez actuellement. \r\nVous ne pouvez activer qu''1 "Gagagatag" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(923596,'Geargiarmure',replace(replace('Une fois par tour: vous pouvez changer cette carte en Position de Défense face verso. \r\nLorsque cette carte est retournée face recto: vous pouvez ajouter 1 monstre "Geargia" ("Geargiarmure" exclu) depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face verso','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(938717,'Caporal Amorceur - Dynamo du Commandement',replace(replace('Vous pouvez cibler max. 2 monstres "Gadget" Machine que vous contrôlez ou dans votre Cimetière de noms différents; Invoquez Spécialement cette carte depuis votre main, puis équipez ces cibles à cette carte (peu importe leur Type). \r\nVous ne pouvez utiliser cet effet de "Caporal Amorceur - Dynamo du Commandement" qu''une fois par tour. \r\nGagne 1000 ATK pour chaque monstre équipé à cette carte par cet effet.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(952523,'Traptrix Cularia',replace(replace('2 monstres Insecte et/ou Plante	\r\nCette carte Invoquée par Lien n''est pas affectée par des effets de Piège. \r\nVous ne pouvez utiliser chacun des effets suivants de "Traptrix Cularia" qu''une fois par tour. \r\nAprès que vous activez une Carte Piège Normal "Trappe", vous pouvez la Poser au lieu de l''envoyer au Cimetière. \r\nDurant votre End Phase: vous pouvez cibler 1 monstre "Traptrix" dans votre Cimetière; Invoquez-le Spécialement en Position de Défense.','\r',char(13)),'\n',char(10)),'','La Poser au lieu de l''envoyer au Cimetière ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(967928,'Pénalité !',replace(replace('Lorsque votre adversaire a 4 cartes dans sa main: activez 1 de ces effets.\r\n● Votre adversaire ne peut pas piocher durant sa prochaine Draw Phase.\r\n● Votre adversaire ne peut activer aucune Carte Magie/Piège ce tour.','\r',char(13)),'\n',char(10)),'Votre adversaire ne peut pas piocher durant sa prochaine Draw Phase','Votre adversaire ne peut pas activer de Cartes Magie/Piège ce tour','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(975299,'B.E.F. Zelos',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 "Campagne de Recrutement" depuis votre Deck à votre main. \r\nLes monstres "B.E.S." que vous contrôlez gagnent 500 ATK/DEF, votre adversaire ne peut pas les cibler avec des effets de carte, et aussi, ils ne peuvent pas être détruits par des effets de carte de votre adversaire. \r\nUne fois par tour: vous pouvez Invoquer Spécialement 1 monstre "B.E.S." depuis votre main. \r\nSi un ou plusieurs monstres "B.E.S." sont Invoqués Normalement ou Spécialement sur votre Terrain: placez 1 Compteur sur eux.','\r',char(13)),'\n',char(10)),'Ajouter "Campagne de Recrutement" à votre main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(980973,'Dragon Armé LV3','Durant votre Standby Phase: vous pouvez envoyer cette carte au Cimetière; Invoquez Spécialement 1 "Dragon Armé LV5" depuis votre main ou Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(980974,'Dragon Armé LV3','Durant votre Standby Phase: vous pouvez envoyer cette carte au Cimetière; Invoquez Spécialement 1 "Dragon Armé LV5" depuis votre main ou Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(981540,'Quasi-Continuité','Ciblez 1 monstre sur le Terrain; ce tour, le monstre ne peut pas être détruit au combat, et aussi, les dommages de combat que vous recevez d''attaques impliquant le monstre sont divisés par deux.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(983995,'Rebond',replace(replace('Lorsque votre adversaire active une Carte Magie/Piège ou un effet de monstre qui renvoie une ou plusieurs cartes depuis le Terrain à la main: annulez l''effet, et si vous le faites, envoyez 1 carte depuis la main de votre adversaire (au hasard) ou depuis son Terrain au Cimetière. \r\nLorsque cette carte Posée est détruite par un effet de carte de votre adversaire et envoyée au Cimetière: piochez 1 carte.','\r',char(13)),'\n',char(10)),'Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(984114,'Expressroid','Lorsque cette carte est Invoquée: vous pouvez cibler 2 monstres "roid" ("Expressroid" exclu) dans votre Cimetière; ajoutez les cibles à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(987311,'D/D/D Alexandre, Roi des Rafales',replace(replace('1 Syntoniseur "D/D" + 1 monstre non-Syntoniseur ou plus	\r\nSi un ou plusieurs autres monstres "D/D" sont Invoqués Normalement ou Spécialement sur votre Terrain, tant que vous contrôlez cette carte face recto (sauf durant la Damage Step): vous pouvez cibler 1 monstre "D/D" de max. Niveau 4 dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser cet effet de "D/D/D Alexandre, Roi des Rafales" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1003028,'Chien Plongeur',replace(replace('Si votre adversaire contrôle un monstre et que tous les monstres face recto que vous contrôlez (min. 1) sont Niveau 4, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Chien Plongeur" qu''une fois par tour de cette façon. \r\nCette carte ne peut pas être utilisée comme Matériel Xyz pour une Invocation Xyz, sauf pour l''Invocation Xyz d''un monstre de Type Guerrier.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1003840,'Carrefour Robot Lumière d''Étoile',replace(replace('Vous pouvez Sacrifier 1 monstre Syntoniseur; Invoquez Spécialement 1 monstre "Synchronique" de Niveau différent de celui que le monstre Sacrifié avait sur le Terrain depuis votre Deck. \r\nDurant le tour de votre adversaire, si vous Invoquez Spécialement un Monstre Synchro depuis votre Extra Deck: ciblez 1 carte sur le Terrain; mélangez-la dans le Deck. \r\nVous ne pouvez utiliser chaque effet de "Carrefour Robot Lumière d''Étoile" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1005587,'Trappe du Vide','Lorsque votre adversaire Invoque Spécialement un ou plusieurs monstres avec min. 2000 ATK: annulez les effets d''1 de ces monstres avec min. 2000 ATK, et si vous le faites, détruisez-le.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1006081,'Robot Changeur',replace(replace('Vous ne pouvez utiliser l''effet suivant de "Robot Changeur" qu''une fois par tour. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre "Robot" ("Robot Patrouilleur", "Chevalier Robotisé", "Robot d''Assistance au Combat", "Robot Hyper Synchronique" et "Robot Vrille Koa''ki Meiru" exclus) sur le Terrain, puis activez 1 de ces effets;\r\n● Augmentez son Niveau de 1.\r\n● Réduisez son Niveau de 1.','\r',char(13)),'\n',char(10)),'Changer le Niveau','Augmenter le Niveau de 1','Réduire le Niveau de 1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1033312,'Décision Douloureuse',replace(replace('Envoyez 1 Monstre Normal de max. Niveau 4 depuis votre Deck au Cimetière, et si vous le faites, ajoutez 1 monstre de même nom depuis votre Deck à votre main. \r\nVous ne pouvez activer qu''1 "Décision Douloureuse" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1035143,'Ténèkuriboh',replace(replace('Lorsqu''un ou plusieurs monstres Démon et/ou un ou plusieurs Monstres Fusion que vous contrôlez sont ciblés par une attaque, ou qu''une carte ou un effet qui les cible est activé (Effet Rapide): vous pouvez défausser cette carte, puis ciblez 1 de ces monstres; jusqu''à la fin de ce tour, il ne peut être détruit ni au combat ni par des effets de carte, et aussi, ses effets activés dans la Zone Monstre ne peuvent pas être annulés. \r\nSi cette carte est envoyée depuis la main au Cimetière par un effet de carte: vous pouvez ajouter 1 "Polymérisation" depuis votre Deck ou Cimetière à votre main. \r\nVous ne pouvez utiliser chaque effet de "Ténèkuriboh" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Protection','Ajouter à la main','L''effet de "Ténèkuriboh" est actuellement appliqué.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1036974,'Malchance',replace(replace('Sélectionnez 1 monstre face recto contrôlé par votre adversaire. \r\nInfligez à votre adversaire des dommages égaux à la moitié de l''ATK d''origine du monstre sélectionné. \r\nVos monstres ne peuvent pas attaquer ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1041278,'Expulsion du Marqué',replace(replace('Sacrifiez 1 Monstre Fusion, puis ciblez 2 Monstres non-Fusion qui sont bannis et/ou dans au moins l''un des Cimetières; Invoquez Spécialement les deux monstres, 1 sur chaque Terrain. \r\nSi vous avez Sacrifié un Monstre Fusion qui mentionne "Albaz le Déchu" comme Matériel pour activer cette carte, vous pouvez Invoquer Spécialement les deux monstres sur votre Terrain à la place, en Position de Défense. \r\nVous ne pouvez activer qu''1 "Expulsion du Marqué" par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement 2 monstres sur votre Terrain en Position de Défense ?','Sélectionnez le monstre à Invoquer Spécialement sur votre Terrain','Sélectionnez le monstre à Invoquer Spécialement sur le Terrain de l''adversaire','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1045143,'Geargiano Mk-II','Lorsque cette carte est Invoquée Normalement ou par Flip: vous pouvez Invoquer Spécialement 1 monstre "Geargia" depuis votre main ou Cimetière en Position de Défense.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1047075,'Spadassin des Flammes Combattant',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 Magie/Piège qui mentionne "Spadassin des Flammes" depuis votre Deck à votre main. \r\nSi cette carte est envoyée au Cimetière: vous pouvez envoyer 1 "Spadassin des Flammes" ou 1 monstre qui le mentionne ("Spadassin des Flammes Combattant" exclu) depuis votre Deck ou Extra Deck au Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Spadassin des Flammes Combattant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Envoyer au Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050186,'Satellchevalier Unukalhai',replace(replace('Si cette carte est Invoquée: vous pouvez envoyer 1 carte "tellchevalier" ("Satellchevalier Unukalhai" exclu) depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser cet effet de "Satellchevalier Unukalhai" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050355,'Miroir des Rêves de la Terreur',replace(replace('Durant la End Phase: vous pouvez bannir cette carte; activez 1 "Miroir des Rêves de la Joie" directement depuis votre main ou Deck. \r\nVous ne pouvez utiliser cet effet de "Miroir des Rêves de la Terreur" qu''une fois par tour. \r\nChaque fois que votre adversaire Invoque Spécialement un ou plusieurs monstres, infligez 300 points de dommages à votre adversaire. \r\nCet effet est uniquement appliqué tant que vous contrôlez un monstre TÉNÈBRES "Miroir des Rêves".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050684,'Cour de Ferraille','Ajoutez 1 Syntoniseur "Ferraille" depuis votre Deck à votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1061200,'Cité Grand Prix F.A.',replace(replace('Augmentez le Niveau de tous les monstres "F.A." sur le Terrain de 2 durant la Main Phase et Battle Phase. \r\nVotre adversaire ne peut pas cibler de monstres "F.A." que vous contrôlez avec des effets de carte. \r\nSi cette carte face recto sur le Terrain est détruite par un effet de carte: vous pouvez ajouter 1 carte "F.A." ("Cité Grand Prix F.A." exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Cité Grand Prix F.A." qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1073952,'Pot de Sorcellerie','Envoyez 1 Piège Continu face recto que vous contrôlez au Cimetière; piochez 2 cartes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1082946,'Horloge Pyro de la Destinée',replace(replace('Avancez le décompte des tours de 1. \r\nLe tour de l''activation de cette carte se poursuit normalement.','\r',char(13)),'\n',char(10)),'Sélectionnez la carte pour faire avancer le compteur de tours','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1102515,'Imitateur des Ténèbres LV3','Si cette carte est détruite au combat et envoyée au Cimetière: piochez 1 carte, mais si cette carte a été Invoquée Spécialement par l''effet de "Imitateur des Ténèbres LV1", piochez 2 cartes à la place.','Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1118137,'Pouvoir des Gardiens',replace(replace('Si une attaque impliquant le monstre équipé est déclarée: placez 1 Compteur Magie sur cette carte. \r\nLe monstre équipé gagne 500 ATK/DEF pour chaque Compteur Magie sur cette carte. \r\nSi le monstre équipé va être détruit au combat ou par un effet de carte, vous pouvez retirer 1 Compteur Magie depuis votre Terrain à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1122030,'Vandalisme Artmage -Agression-',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 "Medius le Pur" depuis votre Deck à votre main. \r\nVous pouvez cibler 1 monstre face recto que vous contrôlez; si le monstre face recto va être utilisé comme Matériel Fusion ce tour, il peut être traité comme monstre "Artmage". \r\nVous ne pouvez utiliser cet effet de "Vandalisme Artmage -Agression-" qu''une fois par tour. \r\nSi "Acropole Académique des Arts Ésotériques Artmage" que vous contrôlez va être détruit par un effet de carte, vous pouvez envoyer cette carte que vous contrôlez au Cimetière à la place. \r\nVous ne pouvez activer qu''1 "Vandalisme Artmage -Agression-" par tour.','\r',char(13)),'\n',char(10)),'Traiter comme un monstre "Artmage"','Ajouter ce monstre à la main ?','L''effet de "Vandalisme Artmage -Agression-" est actuellement appliqué.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1127737,'Champ de Bataille D.D. de Sargasso',replace(replace('Chaque fois qu''un monstre est Invoqué par Xyz: le joueur Invoquant reçoit 500 points de dommages. \r\nDurant la End Phase de chaque joueur, le joueur du tour reçoit 500 points de dommages s''il contrôle un Monstre Xyz face recto.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1142880,'Cyber Dragon Nächster',replace(replace('Le nom de cette carte devient "Cyber Dragon" tant qu''elle est sur le Terrain ou dans le Cimetière. \r\nVous pouvez défausser 1 autre monstre; Invoquez Spécialement cette carte depuis votre main. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre Machine avec 2100 ATK ou DEF dans votre Cimetière; Invoquez-le Spécialement, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Machine exclus) le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Cyber Dragon Nächster" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1149109,'Verrouillage de Deck',replace(replace('Aucun joueur ne peut ajouter de cartes depuis le Deck à sa main, sauf en les piochant. \r\nLes monstres ne peuvent pas être Invoqués Spécialement depuis le Main Deck. \r\nDurant votre 2e Standby Phase après activation, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1151281,'Phosphéroglacier Subterreur Béhémoth',replace(replace('FLIP: Vous pouvez envoyer 1 carte depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser cet effet de "Phosphéroglacier Subterreur Béhémoth" qu''une fois par tour.\r\nLorsqu''un monstre face recto que vous contrôlez est retourné face verso, si vous ne contrôlez aucun monstre face recto: vous pouvez Invoquer Spécialement cette carte depuis votre main en Position de Défense. \r\nUne fois par tour: vous pouvez changer cette carte en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1154611,'Leanchoilia Paléozoïque',replace(replace('Ciblez 1 carte bannie; renvoyez-la au Cimetière. \r\nUne fois par Chaîne, lorsqu''une Carte Piège est activée tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte comme un Monstre Normal (Aqua/EAU/Niveau 2/ATK 1200/DEF 0).	\r\n(Cette carte N''EST PAS traitée comme un Piège.) \r\nSi elle est Invoquée de cette façon, cette carte n''est pas affectée par des effets de monstre, et aussi, bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1157683,'Invasion Cyberténébreuse',replace(replace('Une fois par tour: vous pouvez activer 1 de ces effets;\r\n● Ciblez 1 Monstre à Effet "Cyberténébreu" que vous contrôlez; équipez 1 monstre Dragon ou Machine depuis l''un des Cimetières comme une Magie d''Équipement qui lui donne 1000 ATK.\r\n● Envoyez 1 Carte d''Équipement que vous contrôlez équipée à un monstre Machine au Cimetière; détruisez 1 carte contrôlée par votre adversaire.	\r\nVous ne pouvez utiliser chaque effet de "Invasion Cyberténébreuse" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Équiper','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1164211,'Bouclier de la Dynastie Millénaire',replace(replace('Non destructible par des effets de Magie/Piège. \r\nVous ne pouvez utiliser chacun des effets suivants de "Bouclier de la Dynastie Millénaire" qu''une fois par tour. \r\nSi cette carte est dans votre main: vous pouvez la placer dans votre Zone Magie & Piège comme Magie Continue face recto. \r\nTant que cette carte est une Magie Continue: vous pouvez soit payer 2000 LP soit révéler 1 "Ânkh Millénaire" dans votre main; Invoquez Spécialement cette carte, puis vous pouvez ajouter 1 "Ânkh Millénaire" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Le placer comme Carte Magie','Invocation Spéciale','Révéler "Ânkh Millénaire" ?','Ajouter "Ânkh Millénaire" à votre main ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(1174075,'Drytron Mu Bêta Fafnir',replace(replace('2+ monstres de Niveau 1	\r\nLorsque vous Invoquez Rituellement, vous pouvez détacher un ou plusieurs Matériels de cette carte comme le ou les monstres requis pour l''Invocation Rituelle. \r\nVous ne pouvez utiliser chacun des effets suivants de "Drytron Mu Bêta Fafnir" qu''une fois par tour. \r\nSi cette carte est Invoquée par Xyz: vous pouvez envoyer 1 carte "Drytron" depuis votre Deck au Cimetière. \r\nLorsque votre adversaire active une Carte Magie/Piège, tant que vous contrôlez un Monstre Rituel Machine (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''activation, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Annuler et détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1184620,'Kojikocy','Chasseur d''hommes aux bras puissants capables de broyer des pierres.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1186447,'Sorcier Horoscope, le Magicien Observateur des Étoiles',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nLorsqu''une Carte Magie ou effet de Magie activé par votre adversaire est résolu, si vous contrôlez un Monstre Pendule "Magicien" ou monstre "Yeux Impairs", vous pouvez annuler l''effet, puis détruisez cette carte.\r\nVous ne pouvez utiliser cet effet de "Sorcier Horoscope, le Magicien Observateur des Étoiles" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez défausser 1 autre Monstre Pendule "Magicien", monstre "Potartiste", ou monstre "Yeux Impairs"; Invoquez Spécialement cette carte depuis votre main.\r\nSi cette carte est Invoquée Spécialement: vous pouvez ajouter 1 Monstre Pendule avec 2500 ATK depuis votre Deck à votre main.\r\nVous pouvez cibler 1 Carte Monstre Pendule que vous contrôlez; détruisez-la, puis vous pouvez ajouter 1 Monstre Pendule face recto depuis votre Extra Deck à votre main.\r\nVous ne pouvez utiliser chaque effet de "Sorcier Horoscope, le Magicien Observateur des Étoiles" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet d''ajout à la main','Effet de destruction','Ajouter à la main?','Appliquer l''effet de "Sorcier Horoscope, le Magicien Observateur des Étoiles" pour annuler ?','','','','','','','','','','','');
INSERT INTO texts VALUES(1186448,'Sorcier Horoscope, le Magicien Observateur des Étoiles',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nLorsqu''une Carte Magie ou effet de Magie activé par votre adversaire est résolu, si vous contrôlez un Monstre Pendule "Magicien" ou monstre "Yeux Impairs", vous pouvez annuler l''effet, puis détruisez cette carte.\r\nVous ne pouvez utiliser cet effet de "Sorcier Horoscope, le Magicien Observateur des Étoiles" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez défausser 1 autre Monstre Pendule "Magicien", monstre "Potartiste", ou monstre "Yeux Impairs"; Invoquez Spécialement cette carte depuis votre main.\r\nSi cette carte est Invoquée Spécialement: vous pouvez ajouter 1 Monstre Pendule avec 2500 ATK depuis votre Deck à votre main.\r\nVous pouvez cibler 1 Carte Monstre Pendule que vous contrôlez; détruisez-la, puis vous pouvez ajouter 1 Monstre Pendule face recto depuis votre Extra Deck à votre main.\r\nVous ne pouvez utiliser chaque effet de "Sorcier Horoscope, le Magicien Observateur des Étoiles" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet d''ajout à la main','Effet de destruction','Ajouter à la main?','Appliquer l''effet de "Sorcier Horoscope, le Magicien Observateur des Étoiles" pour annuler ?','','','','','','','','','','','');
INSERT INTO texts VALUES(1187243,'Vent Arrière de Gusto',replace(replace('Équipable uniquement à un monstre "Gusto". \r\nLe monstre équipé ne peut pas être détruit par des effets de carte de votre adversaire. \r\nVous ne pouvez utiliser chacun des effets suivants de "Vent Arrière de Gusto" qu''une fois par tour. \r\nVous pouvez bannir cette carte depuis votre Cimetière, et défaussez 1 monstre VENT; ajoutez 1 Magie/Piège "Gusto" depuis votre Deck à votre main. \r\nVous pouvez activer cet effet selon le Niveau/Rang du monstre équipé;\r\n● Max. 4: Invoquez Spécialement 1 monstre "Gusto" depuis votre Deck d''un Type différent du monstre équipé.\r\n● Min. 5: Invoquez Spécialement 1 Syntoniseur de Niveau 1 depuis votre Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1197847,'Onde Spirale Spectre',replace(replace('Équipable uniquement à un Monstre Normal. \r\nLa première fois que le monstre équipé va être détruit au combat chaque tour, il n''est pas détruit. À la fin de la Battle Phase, si le monstre équipé a combattu: vous pouvez Invoquer Spécialement 1 "Dragon Spirale Spectre" depuis votre main, Deck ou Cimetière, et équipez-le avec cette carte, puis s''il en a, votre adversaire défausse 1 carte. \r\nVous ne pouvez utiliser cet effet de "Onde Spirale Spectre" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1200843,'Miroir de Yata',replace(replace('Équipable uniquement à un Monstre Spirit. \r\nVous n''êtes pas obligé d''activer l''effet qui renvoie le monstre équipé dans votre main. \r\nSi le monstre équipé doit être détruit au combat, détruisez cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1218214,'Dharma Cubique',replace(replace('Vous ne recevez aucun dommage de combat d''attaques impliquant vos monstres "Cubique". \r\nVous ne pouvez utiliser chacun des effets suivants de "Dharma Cubique" qu''une fois par tour, durant votre Main Phase:\r\n● Vous pouvez envoyer 1 carte "Cubique" depuis votre main au Cimetière, et si vous le faites, piochez 1 carte.\r\n● Vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre "Cubique" dans votre Cimetière; ajoutez-le à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1224927,'Catastrophe Infernale','Lorsqu''un monstre de votre adversaire déclare une attaque: détruisez toutes les Cartes Magie/Piège sur le Terrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1225009,'Arianna la Domestique Labrynth',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 carte "Labrynth" ("Arianna la Domestique Labrynth" exclu) depuis votre Deck à votre main. \r\nSi un ou plusieurs autres monstres quittent le Terrain par votre effet de Piège Normal (sauf durant la Damage Step): vous pouvez piocher 1 carte, puis vous pouvez appliquer cet effet.\r\n● Depuis votre main, soit Invoquez Spécialement 1 monstre Démon, soit Posez 1 Magie/Piège.	\r\nVous ne pouvez utiliser qu''1 effet de "Arianna la Domestique Labrynth" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Piocher','Invoquer Spécialement depuis la main','Poser depuis la main','Ne rien faire','','','','','','','','','','','');
INSERT INTO texts VALUES(1248895,'Destruction en Chaîne','Lorsqu''un ou plusieurs monstres avec max. 2000 ATK sont Invoqués: ciblez-en 1; détruisez toutes les cartes de ce nom dans la main et Main Deck de son contrôleur.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1249315,'Héraut de la Lumière Pure',replace(replace('2 monstres de Niveau 2	\r\nVous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre dans votre Cimetière; ajoutez-le à votre main, puis mélangez 1 carte depuis votre main dans le Deck. \r\nVous ne pouvez utiliser l''effet de "Héraut de la Lumière Pure" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1259814,'Arc-en-Cielution RVB','Une fois par tour: vous pouvez cibler 1 monstre face recto sur le Terrain; son Type est changé en Machine, et aussi, il gagne les Attributs LUMIÈRE/TÉNÈBRES/TERRE/EAU/FEU/VENT (même si cette carte quitte le Terrain).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1259915,'Coup de Tonnerre des Bêtes Sacrées',replace(replace('Durant votre Main Phase: vous pouvez placer face recto 2 "Coup de Tonnerre des Bêtes Sacrées" depuis votre main, Deck et/ou Cimetière sur votre Terrain, puis vous pouvez révéler 1 monstre "Bêtes Sacrées" de Niveau 10 dans votre main, puis placez face recto 1 "Paradis Perdu des Bêtes Sacrées" depuis votre Deck dans votre Zone Terrain. \r\nDurant la End Phase de votre adversaire, si cette carte est dans votre Cimetière: vous pouvez ajouter cette carte à votre main. \r\nVous ne pouvez utiliser chaque effet de "Coup de Tonnerre des Bêtes Sacrées" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet de placement','Renvoyer à la main','Montrer à votre adversaire ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1264319,'Fusion Chevalier-Gemmes',replace(replace('Invoquez par Fusion 1 Monstre Fusion "Chevalier-Gemmes" depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain. \r\nSi cette carte est dans votre Cimetière: vous pouvez bannir 1 monstre "Chevalier-Gemmes" depuis votre Cimetière; ajoutez cette carte à votre main.','\r',char(13)),'\n',char(10)),'Invocation Fusion','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1264320,'Fusion Chevalier-Gemmes',replace(replace('Invoquez par Fusion 1 Monstre Fusion "Chevalier-Gemmes" depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain. \r\nSi cette carte est dans votre Cimetière: vous pouvez bannir 1 monstre "Chevalier-Gemmes" depuis votre Cimetière; ajoutez cette carte à votre main.','\r',char(13)),'\n',char(10)),'Invocation Fusion','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1269512,'Armure Complète - Lancier Rayon Utopique',replace(replace('3 monstres de Niveau 4	\r\nUne fois par tour, vous pouvez aussi Invoquer par Xyz "Armure Complète - Lancier Rayon Utopique" en défaussant 1 Magie/Piège et en utilisant 1 Monstre Xyz de max. Rang 4 que vous contrôlez. \r\n(Transférez ses Matériels à cette carte.) \r\nLes monstres contrôlés par votre adversaire perdent 500 ATK. \r\nAu début de la Battle Phase: vous pouvez annuler les effets de tous les monstres en Position d''Attaque actuellement contrôlés par votre adversaire. \r\nLorsque cette carte attaquante détruit un monstre de l''adversaire au combat: vous pouvez détacher 1 Matériel de cette carte; elle peut faire une seconde attaque à la suite.','\r',char(13)),'\n',char(10)),'L''Invoquer par Xyz en utilisant un Monstre Xyz de Rang 4 ou moins que vous contrôlez ?','','Annuler les effets des monstres en Position d''Attaque contrôlés par l''adversaire','Détacher une Matériel Xyz pour attaquer à nouveau','','','','','','','','','','','','');
INSERT INTO texts VALUES(1274455,'Singetroopers Kozmo',replace(replace('Durant le tour de chaque joueur: vous pouvez bannir cette carte; Invoquez Spécialement 1 monstre "Kozmo" de min. Niveau 4 depuis votre main. \r\nVous ne pouvez utiliser cet effet de "Singetroopers Kozmo" qu''une fois par tour. \r\nUne fois par tour: vous pouvez payer 1000 LP, puis ciblez 1 monstre "Kozmo" de Type Psychique dans votre Cimetière; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un monstre "Kozmo" depuis votre main','Invoquer Spécialement un monstre "Kozmo" depuis votre Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1278431,'Armature Rouages Ancients',replace(replace('Vous pouvez défausser 1 carte; ajoutez 1 "Golem Rouages Ancients", ou 1 Magie/Piège qui le mentionne, depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Armature Rouages Ancients" qu''une fois par tour. \r\nSi cette carte attaque, votre adversaire ne peut pas activer de Cartes Magie/Piège jusqu''à la fin de la Damage Step. \r\nSi cette carte face recto contrôlée par son propriétaire quitte le Terrain à cause d''un effet de carte de l''adversaire: vous pouvez Invoquer Spécialement max. 3 "Golem Rouages Ancients" et/ou "Golem Rouages Ancients - Frappe Ultime" depuis votre main, en ignorant leurs conditions d''Invocation.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1280391,'Avènement d''Atlantis',replace(replace('Le nom de cette carte devient "Umi" tant qu''elle est dans la Zone Magie & Piège.\r\nVous ne pouvez utiliser chacun des effets suivants de "Avènement d''Atlantis" qu''une fois par tour.\r\nDurant votre Main Phase: vous pouvez placer 1 "Atlantis, la Ville du Dragon" ou "Umi" depuis votre Deck face recto dans votre Zone Terrain.\r\nSi cette carte est envoyée au Cimetière: vous pouvez ajouter 1 monstre Serpent de Mer de Niveau 7 depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Effet de placement','Effet d''ajout à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1281505,'Tétra Vylon',replace(replace('Si cette carte est envoyée depuis la Zone Carte Monstre au Cimetière: vous pouvez payer 500 Life Points, puis ciblez 1 monstre face recto que vous contrôlez; équipez cette carte à la cible. \r\nSi le monstre équipé va être détruit, vous pouvez détruire cette Carte d''Équipement à la place.','\r',char(13)),'\n',char(10)),'Équiper comme Carte d''Équipement','Utiliser l''effet de "Tétra Vylon" à la place de la destruction ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1287123,'Ancien Faucon Élémentaire','Lorsque l''effet d''un Monstre à Effet qui détruit une ou plusieurs Cartes Magie ou Piège sur le Terrain est activé, vous pouvez envoyer 1 carte depuis votre main au Cimetière pour annuler son activation et détruire la carte.','Annuler l''activation et détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1295111,'Sanctuaire Salamangrande',replace(replace('Si vous Invoquez par Lien un Monstre Lien "Salamangrande", vous pouvez utiliser 1 Monstre Lien "Salamangrande" que vous contrôlez du même nom que celui-ci comme tout le Matériel. \r\nDurant le calcul des dommages, si votre monstre combat: vous pouvez payer 1000 LP, puis ciblez 1 Monstre Lien que vous contrôlez; faites devenir son ATK 0, et si vous le faites, gagnez des LP égaux à son ATK d''origine. \r\nVous ne pouvez utiliser chaque effet de "Sanctuaire Salamangrande" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Lien en utilisant uniquement un monstre du même nom comme Matériel','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1295442,'Aegirocassis de Création Jadeglace',replace(replace('Tant que cette carte est équipée à un monstre, le monstre équipé gagne 400 ATK/DEF pour chaque monstre banni. \r\nVous ne pouvez utiliser qu''1 des effets suivants de "Aegirocassis de Création Jadeglace" par tour, et uniquement une fois le tour. \r\nSi cette carte est dans votre main ou Cimetière (sauf durant la Damage Step) (Effet Rapide): vous pouvez cibler 1 monstre "Jadeglace" que vous contrôlez; équipez cette carte au monstre que vous contrôlez. \r\nTant que cette carte est équipée à un monstre: vous pouvez Invoquer Spécialement cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1315120,'Attaquant T.G.',replace(replace('Si uniquement votre adversaire contrôle un monstre, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nUne fois par tour, durant la End Phase, si cette carte est dans le Cimetière parce qu''elle a été détruite sur le Terrain et y a été envoyée ce tour: vous pouvez ajouter 1 monstre "T.G." ("Attaquant T.G." exclu) depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1322368,'Double Hélice ESPIRALE',replace(replace('2 monstres "ESPIRALE"	\r\nLe nom de cette carte devient "Super Espion ESPIRALE" tant qu''elle est sur le Terrain ou dans le Cimetière. \r\nVous pouvez déclarer 1 type de carte (Monstre, Magie ou Piège); révélez la carte du dessus du Deck de votre adversaire, et si vous le faites, et que son type correspond au type déclaré, prenez 1 monstre "ESPIRALE" depuis votre Deck ou Cimetière, et soit ajoutez-le à main soit Invoquez-le Spécialement dans votre zone pointée par cette carte. \r\nVous ne pouvez utiliser cet effet de "Double Hélice ESPIRALE" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Déclarer un type de carte','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1329620,'Criime des Tiarmentations',replace(replace('Lorsqu''une Carte Magie/Piège ou un effet de monstre est activé, tant que vous contrôlez "Visas Starfrost" ou un monstre "Tiarmentations": annulez l''activation, et si vous le faites, mélangez la carte dans le Deck, puis envoyez 1 monstre depuis votre main au Cimetière. \r\nSi cette carte est envoyée au Cimetière par un effet de carte: vous pouvez cibler 1 de vos monstres "Tiarmentations" bannis; ajoutez-le à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Criime des Tiarmentations" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1340142,'Varar, Concorde Vaalmonicain',replace(replace('2 monstres (un Monstre Lien "Vaalmonica" inclus)	\r\nNon affectée par des effets de carte (cartes "Vaalmonica" exclues), tant que vous avez min. 6 Compteurs Résonance sur votre Terrain. \r\nGagne 1 attaque supplémentaire durant chaque Battle Phase, pour chaque monstre "Vaalmonica" de Niveau 4 que vous contrôlez. \r\nUne fois par tour, lorsque votre adversaire va Invoquer Spécialement un ou plusieurs monstres, si vous avez 3+ Compteurs Résonance sur votre Terrain (Effet Rapide): vous pouvez annuler l''Invocation Spéciale, et si vous le faites, détruisez ces monstres, puis retirez 3 Compteurs Résonance depuis votre Terrain.','\r',char(13)),'\n',char(10)),'Non affecté','Attaques multiples','Annuler l''Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1344018,'Pendulegraphe du Temps',replace(replace('Votre adversaire ne peut pas cibler de monstres de Type Magicien que vous contrôlez avec des Cartes Piège ou effets de Piège. \r\nVous ne pouvez utiliser l''effet suivant de "Pendulegraphe du Temps" qu''une fois par tour. \r\nVous pouvez cibler 1 Carte Monstre Pendule "Magicien" dans votre Zone Monstre ou Zone Pendule, et 1 carte contrôlée par votre adversaire; détruisez-les. \r\nPuis, si cet effet n''a pas détruit 2 cartes, vous pouvez envoyer 1 carte sur le Terrain au Cimetière.','\r',char(13)),'\n',char(10)),'Détruire une carte','Envoyer 1 carte sur le Terrain au Cimetière ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1347977,'Garde Mystérieux','FLIP: Ciblez 1 monstre face recto sur le Terrain, et si vous contrôlez un monstre Guerrier, vous pouvez cibler 1 monstre face recto supplémentaire sur le Terrain; placez la première cible au-dessus du Deck, puis renvoyez la cible supplémentaire (s''il y en a une) à la main si vous contrôlez toujours un monstre Guerrier.','Renvoyer au Deck','Sélectionner 1 monstre face recto supplémentaire sur le Terrain à renvoyer à la main ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1353770,'Walhalla, Sanctuaire du Déchu',replace(replace('Une fois par tour: vous pouvez Invoquer Spécialement 1 monstre Elfe depuis votre main. \r\nVous ne devez contrôler aucun monstre pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1357146,'Crapaud Samouraï',replace(replace('Non utilisable comme Matériel Synchro. \r\nLe nom de cette carte devient "Grenouille Des" tant qu''elle est sur le Terrain. \r\nSi cette carte est dans votre Cimetière: vous pouvez bannir 1 monstre "Grenouille" depuis votre Cimetière; Invoquez Spécialement cette carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1362589,'Broyeur Photon','Si cette carte attaque, elle est changée en Position de Défense à la fin de la Damage Step.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1371589,'Koala Vampirique','Si cette carte inflige des dommages de combat à votre adversaire au combat avec un monstre: gagnez des LP égaux aux dommages de combat infligés.','Gagner des LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1372887,'Balade Partagée',replace(replace('Le reste de ce tour, chaque fois qu''une ou plusieurs cartes sont ajoutées depuis le Main Deck ou Cimetière à la main de votre adversaire, sauf en les piochant, vous piochez immédiatement 1 carte. \r\nVous ne pouvez activer qu''1 "Balade Partagée" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1409474,'Sphynx Flamme Chimérique',replace(replace('Votre adversaire ne peut pas cibler cette carte avec des effets de cartes. \r\nVous pouvez déclarer 1 type de carte (Monstre, Magie ou Piège); envoyez la carte du dessus de votre Deck au Cimetière, puis si elle était du type de carte déclaré, vous pouvez Invoquer Spécialement 1 monstre FEU depuis votre main ou Cimetière. \r\nVous ne pouvez utiliser cet effet de "Sphynx Flamme Chimérique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Déclarer un type de carte','Invoquer Spécialement 1 monstre FEU depuis votre main ou Cimetière ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1410324,'Aconity Farstar',replace(replace('Si vous contrôlez un Monstre Fusion ou Lien "Farstar": vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte est envoyée au Cimetière comme Matériel pour un Monstre Lien "Farstar": vous pouvez ajouter 1 "Fusion Farstar" ou "Diffusion Farstar" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Aconity Farstar" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Ajouter une carte Fusion à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1412158,'Super Roboyaro',replace(replace('"Roboyaro" + "Robolady"	\r\nVous pouvez faire une Invocation Spéciale de "Super Robolady" en renvoyant cette carte du Terrain dans le Extra Deck. \r\nVous ne pouvez pas utiliser cet effet durant le tour où ce monstre est Invoqué par Invocation Spéciale. \r\nDe plus, augmentez l''ATK de ce monstre de 1000 points durant la Damage Step lorsque ce monstre combat un monstre.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1426714,'Numéro 48 : Liche de l''Ombre',replace(replace('2 monstres de Niveau 3	\r\nUne fois par tour, durant le tour de votre adversaire: vous pouvez détacher 1 Matériel Xyz de cette carte; Invoquez Spécialement 1 "Jeton Vision" (Type Démon/TÉNÈBRES/Niveau 1/ATK 500/DEF 500). \r\n(Ceci est un Effet Rapide.) \r\nTant que vous contrôlez "Jeton Vision", votre adversaire ne peut pas cibler cette carte avec une attaque. \r\nCette carte gagne 500 ATK pour chaque "Jeton Vision" que vous contrôlez.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1426715,'Jeton Vision','Invoqué Spécialement avec l''effet de "Numéro 48 : Liche de l''Ombre".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1434352,'Nécromancien du Chaos','L''ATK de cette carte est égale au nombre de Cartes Monstre dans votre Cimetière x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1435851,'Trésor de Dragon','Un monstre de Type Dragon équipé de cette carte augmente son ATK et sa DEF de 300 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1463589,'Expérience Finale Anti-GMX',replace(replace('Activez uniquement si vous contrôlez un monstre "GMX". \r\nUne fois par tour, lorsque votre adversaire active un effet de monstre sur le Terrain (sauf durant la Damage Step): vous pouvez dévoiler les 5 cartes du dessus de votre Deck, puis si vous avez dévoilé une ou plusieurs cartes "GMX", annulez l''effet activé, et aussi, placez toutes les cartes dévoilées au-dessus ou au-dessous du Deck dans l''ordre de votre choix.','\r',char(13)),'\n',char(10)),'Excaver des cartes','Placer au-dessus du Deck','Placer au-dessous du Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1474910,'Soldat Abeille','Vous pouvez Sacrifier cette carte et 1 monstre Insecte face recto ("Soldat Abeille" exclu); piochez 2 cartes.','Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1475311,'Invitation des Ténèbres','Piochez 2 cartes, puis bannissez 1 monstre TÉNÈBRES depuis votre main, ou, si vous n''en avez aucun dans votre main, envoyez toute votre main au Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1482001,'Clara et Rushka, le Ventriloduo',replace(replace('1 monstre Invoqué/Posé Normalement	\r\nNon Invocable par Lien, sauf durant la Main Phase 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1487805,'Zer''oll le Trancheur Cosmique',replace(replace('2+ monstres Reptile	\r\nLes monstres contrôlés par votre adversaire avec des Compteurs-A sont changés en Position de Défense, et aussi, aucun joueur ne peut activer leurs effets. \r\nVous ne pouvez utiliser chacun des effets suivants de "Zer''oll le Trancheur Cosmique" qu''une fois par tour. \r\nSi cette carte est Invoquée par Lien: vous pouvez ajouter 1 carte depuis votre Deck à votre main qui a un effet qui place un ou plusieurs Compteurs-A. \r\nVous pouvez retirer 2 Compteurs-A depuis le Terrain; immédiatement après la résolution de cet effet, Invoquez Normalement 1 monstre Reptile.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1490690,'Protecteur Canopien',replace(replace('Une fois par Chaîne, lorsque votre adversaire active une carte ou un effet: vous pouvez Invoquer Spécialement 1 monstre "Horus" depuis votre main ou Cimetière, mais le reste de ce tour, vous ne pouvez pas Invoquer Spécialement de monstres du même nom d''origine par l''effet de "Protecteur Canopien". \r\nSi cette carte est envoyée depuis la main ou Terrain au Cimetière: vous pouvez Poser cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser cet effet de "Protecteur Canopien" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1498130,'Kagemusha des Six Samouraïs','Durant le tour de chaque joueur, lorsqu''exactement 1 monstre "Six Samouraïs" face recto que vous contrôlez est ciblé par une Carte Magie/Piège ou un effet de carte qui aurait pu cibler cette carte: vous pouvez activer cet effet; la Magie/Piège/effet cible désormais cette carte face recto sur le Terrain à la place.','Changer la cible','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1498449,'Faimena Queudragon',replace(replace('Durant la Main Phase (Effet Rapide): vous pouvez défausser cette carte; Invoquez par Fusion 1 monstre Dragon ou Magicien depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain. \r\nSi cette carte est envoyée au Cimetière comme Matériel pour une Invocation Fusion: vous pouvez Poser 1 Magie/Piège "Queudragon" depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Faimena Queudragon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet de Fusion','Poser Magie/Piège','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1508649,'Hexstia Altergeist',replace(replace('2 monstres "Altergeist"	\r\nGagne une ATK égale à l''ATK d''origine de chaque monstre "Altergeist" pointé par cette carte. \r\nLorsqu''une Carte Magie/Piège ou effet de Magie/Piège est activé (Effet Rapide): vous pouvez Sacrifier 1 monstre "Altergeist" pointé par cette carte; annulez l''activation, et si vous le faites, détruisez la carte. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez ajouter 1 carte "Altergeist" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Hexstia Altergeist" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1516510,'Dragon Pendule aux Yeux Runiques',replace(replace('"Dragon Pendule aux Yeux Impairs" + 1 monstre de Type Magicien	\r\nSi cette carte a été Invoquée par Fusion en utilisant un ou plusieurs monstres Invoqués par Pendulation sur le Terrain comme Matériels de Fusion, elle n''est pas affectée par des effets de carte de votre adversaire ce tour. \r\nAppliquez l''effet approprié, selon le Niveau d''origine du monstre utilisé comme Matériel de Fusion qui n''était pas "Dragon Pendule aux Yeux Impairs".\r\n● Max.	\r\nNiveau 4: Durant chaque Battle Phase, cette carte peut faire max. 2 attaques sur des monstres.\r\n● Min.	\r\nNiveau 5: Durant chaque Battle Phase, cette carte peut faire max. 3 attaques sur des monstres.','\r',char(13)),'\n',char(10)),'Peut faire jusqu''à 2 attaques sur des monstres','Peut faire jusqu''à 3 attaques sur des monstres','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1525329,'Le Chasseur aux 7 Armes',replace(replace('Lorsque cette carte est Invoquée par Invocation Normale, annoncez 1 Type de monstre. \r\nLorsque cette carte combat ce Type de monstre, augmentez l''ATK de celle-ci de 1000 points durant le calcul des dommages.','\r',char(13)),'\n',char(10)),'Déclarer un type de monstre','Augmenter l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1527418,'Wiz, Sage Mercefourrure',replace(replace('Si cette carte est Invoquée Spécialement: vous pouvez gagner 500 LP pour chaque monstre "Mercefourrure" que vous contrôlez de nom différent ("Wiz, Sage Mercefourrure" exclu). \r\nLorsque votre adversaire active une Carte Magie/Piège ou effet de Magie/Piège (Effet Rapide): vous pouvez défausser 1 carte "Mercefourrure"; annulez l''activation. \r\nVous ne pouvez utiliser chaque effet de "Wiz, Sage Mercefourrure" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1528054,'Lapin Silhouettochapeau',replace(replace('2 Monstres à Effet	\r\nSi cette carte combat un monstre, aucun de ces 2 monstres ne peut être détruit par ce combat. \r\nVous ne pouvez utiliser chacun des effets suivants de "Lapin Silhouettochapeau" qu''une fois par tour. \r\nSi cette carte est Invoquée par Lien: vous pouvez Poser 1 Piège Continu depuis votre Deck avec un effet qui s''Invoque Spécialement comme monstre, et aussi, cette carte ne peut pas être utilisée comme Matériel Lien ce tour. \r\nSi une carte dans la Zone Magie & Piège est Invoquée Spécialement dans la Zone Monstre (sauf durant la Damage Step): vous pouvez cibler 1 Magie/Piège contrôlé par votre adversaire; détruisez-le.','\r',char(13)),'\n',char(10)),'Poser une Carte Piège Continue','Détruire des cartes Magie/Piège','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1533292,'Genex-R Magma','Lorsque cette carte est Invoquée Normalement, vous pouvez ajouter 1 monstre "Genex-R" de Niveau 2 depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1539051,'Cadeau Spatial','Piochez 1 carte pour chaque monstre "Néo-Spacien" de nom différent que vous contrôlez.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1546123,'Dragon Cyber Ultime',replace(replace('"Cyber Dragon" + "Cyber Dragon" + "Cyber Dragon"	\r\nL''Invocation Fusion de cette carte ne peut être faite qu''avec les Matériels Fusion ci-dessus. \r\nSi cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1546124,'Dragon Cyber Ultime',replace(replace('"Cyber Dragon" + "Cyber Dragon" + "Cyber Dragon"	\r\nL''Invocation Fusion de cette carte ne peut être faite qu''avec les Matériels Fusion ci-dessus. \r\nSi cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1557341,'Rose, Guerrière de la Vengeance','Lorsque cette carte inflige des dommages de combat à votre adversaire: infligez 300 points de dommages à votre adversaire.','Subissez 300 dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1557499,'Arc et Flèches d''Argent','Un monstre de Type Elfe équipé de cette carte augmente son ATK et sa DEF de 300 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1561110,'Briseur Dragon ABC',replace(replace('"Attaque du Noyau A" + "Briseur du Draco B" + "Croc de la Vouivre C"	\r\nDoit d''abord être Invoquée Spécialement (depuis votre Extra Deck) en bannissant les cartes ci-dessus que vous contrôlez et/ou depuis votre Cimetière. \r\n(N''utilisez pas "Polymérisation".) \r\nUne fois par tour (Effet Rapide): vous pouvez défausser 1 carte, puis ciblez 1 carte sur le Terrain; bannissez-la. \r\nDurant le tour de votre adversaire (Effet Rapide): vous pouvez Sacrifier cette carte, puis ciblez 3 de vos monstres Union LUMIÈRE Machine bannis de noms différents; Invoquez-les Spécialement.','\r',char(13)),'\n',char(10)),'Défausser 1 carte ; bannir 1 carte sur le Terrain','Sacrifier cette carte ; Invoquer Spécialement vos monstres Union bannis','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1566817,'Service Cupide',replace(replace('Non affectée par les effets activés de monstres, sauf ceux d''un Niveau inférieur ou égal à cette carte. \r\nVous pouvez bannir max. 3 cartes depuis votre Cimetière; jusqu''à la fin de ce tour, augmentez le Niveau de cette carte de ce nombre. \r\nVous ne pouvez utiliser cet effet de "Service Cupide" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1571945,'Ninja Blanc','FLIP: Ciblez 1 monstre en Position de Défense sur le Terrain; détruisez la cible.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1580833,'Stégos Dinobrume',replace(replace('Échelle Pendule = 3\r\n[ Effet Pendule ]\r\nSi une ou plusieurs autres cartes "Dinobrume" que vous contrôlez vont être détruites au combat ou par un effet de carte de votre adversaire, vous pouvez détruire cette carte à la place.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi un autre Monstre Pendule que vous contrôlez combat un monstre de votre adversaire, après le calcul des dommages: vous pouvez détruire ces monstres.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Stégos Dinobrume" à la place de la destruction ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1586457,'Vaisseau Deep Space IX','Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en envoyant 1 autre monstre de Type Machine depuis votre main au Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1595137,'Daneen Évolué',replace(replace('"Daneen le Dino Revenu" + 1 monstre Dinosaure	\r\nSi cette carte est Invoquée Spécialement: vous pouvez ajouter 1 carte "GMX" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Daneen Évolué" qu''une fois par tour. \r\nSi vous dévoilez une ou plusieurs cartes par un effet de carte "GMX": vous pouvez activer l''effet suivant, selon où cette carte est à l''activation (mais vous ne pouvez utiliser chaque effet de "Daneen Évolué" qu''une fois par tour);\r\n● Terrain: Gagnez 1500 LP.\r\n● Cimetière: Invoquez Spécialement cette carte.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Activer l''effet','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1596508,'Forteresse Arsenal Dimensionnelle','Les cartes ne peuvent pas être envoyées du Deck au Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1607603,'Double Dai',replace(replace('Activez 1 de ces effets;\r\n● Si vous ne contrôlez aucun monstre: Invoquez Spécialement 1 monstre Guerrier de Niveau 4 depuis votre Deck.\r\n● Ciblez 1 monstre Guerrier que vous contrôlez; Invoquez Spécialement 1 monstre TERRE Guerrier d''un Niveau inférieur ou égal depuis votre Deck ou Cimetière.	\r\nVous ne pouvez activer qu''1 "Double Dai" par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement 1 monstre Guerrier de Niveau 4 depuis votre Deck','Cibler 1 monstre Guerrier que vous contrôlez ; Invoquer Spécialement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1621413,'Dragon Xyz du Requiem des Ténèbres',replace(replace('3 monstres de Niveau 5	\r\nSi cette carte a "Dragon Xyz de la Rébellion des Ténèbres" comme Matériel, elle gagne ces effets.\r\n● Une fois par tour: vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre face recto contrôlé par votre adversaire; changez son ATK à 0, et si vous le faites, cette carte gagne une ATK égale à l''ATK d''origine du monstre.\r\n● Lorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''activation, et si vous le faites, détruisez la carte, puis vous pouvez Invoquer Spécialement 1 Monstre Xyz depuis votre Cimetière.','\r',char(13)),'\n',char(10)),'Changer l''ATK/DEF','Annuler l''effet','Sélectionner un monstre à Invoquer Spécialement ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1637760,'Grande Corne du Paradis','Durant la Main Phase de votre adversaire, lorsqu''il va Invoquer Spécialement un ou plusieurs monstres: annulez l''Invocation, et si vous le faites, détruisez le monstre, puis votre adversaire pioche 1 carte, puis terminez la Main Phase.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1639384,'Chevalier Divin Grand Dragon d''Or',replace(replace('2 monstres de Niveau 8	\r\nUne fois par tour, durant le tour de chaque joueur: vous pouvez détacher 1 Matériel Xyz de cette carte, puis ciblez 1 monstre face recto sur le Terrain; ce tour, ses effets sont annulés, mais il n''est pas affecté par d''autres effets de carte.','\r',char(13)),'\n',char(10)),'Non affecté','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1641882,'Fusionniste','"Petit Ange" + "Mouton Mystique N°2"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1644289,'Segment Vylon',replace(replace('Équipable uniquement à un monstre "Vylon". \r\nIl ne peut pas être ciblé par des effets de monstre ou des effets de Piège de votre adversaire. \r\nSi cette carte face recto sur le Terrain est envoyée au Cimetière: vous pouvez ajouter 1 Carte Magie "Vylon" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1662004,'Confrérie du Poing de Feu - Esprit',replace(replace('Non utilisable comme Matériel Synchro, sauf pour l''Invocation Synchro d''un monstre Bête-Guerrier. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez cibler 1 monstre FEU de Niveau 3 avec max. 200 DEF dans votre Cimetière; Invoquez Spécialement la cible en Position de Défense, et si vous le faites, les monstres que vous contrôlez (monstres Bête-Guerrier exclus) ne peuvent pas attaquer le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Confrérie du Poing de Feu - Esprit" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1665819,'Réplicarte NAD',replace(replace('Vous pouvez bannir 1 autre monstre de min. Niveau 7 depuis votre main; Invoquez Spécialement cette carte depuis votre main. \r\nVous pouvez cibler 1 monstre face recto que vous contrôlez; Invoquez Spécialement 1 monstre depuis votre Deck de nom différent qui a min. 2 mêmes Niveau, ATK et/ou DEF, mais il ne peut pas activer ses effets ce tour. \r\nVous ne pouvez utiliser chaque effet de "Réplicarte NAD" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte','Invoquer Spécialement depuis le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1669772,'Purification de Magie','Défaussez 1 carte; détruisez toutes les Magies Continues face recto sur le Terrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1683982,'La Rancune du Serpent Venimeux',replace(replace('Les monstres non-Reptile que vous contrôlez ne peuvent pas attaquer, et aussi, vous ne pouvez pas activer leurs effets. \r\nVous ne pouvez utiliser chacun des effets suivants de "La Rancune du Serpent Venimeux" qu''une fois par tour. \r\nSi un ou plusieurs monstres Reptile face recto que vous contrôlez sont détruits au combat ou envoyés au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Reptile de max. Niveau 4 depuis votre Deck. \r\nSi cette carte est détruite dans la Zone Magie & Piège: vous pouvez renvoyer tous vos monstres Reptile bannis à votre Cimetière.','\r',char(13)),'\n',char(10)),'','Invoquer Spécialement depuis le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1686814,'Tzolkin Ultimaya',replace(replace('(Le Niveau d''origine de cette carte est toujours traité comme 12.)	\r\nNon Invocable par Synchronisation. \r\nUniquement Invocable Spécialement (depuis votre Extra Deck) en envoyant 2 monstres de min. Niveau 5 que vous contrôlez de même Niveau au Cimetière (1 Syntoniseur et 1 non-Syntoniseur). \r\nUne fois par tour, lorsqu''un ou plusieurs Magies/Pièges sont Posés sur votre Terrain (sauf durant la Damage Step): vous pouvez Invoquer Spécialement 1 Monstre Synchro "Électromécanique" ou 1 Monstre Synchro Dragon de Niveau 7 ou 8 depuis votre Extra Deck. \r\nTant que vous contrôlez un autre Monstre Synchro, les monstres ne peuvent pas cibler cette carte avec une attaque, et aussi, aucun joueur ne peut la cibler avec des effets de carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1688285,'Traptrix Pinguicula',replace(replace('2 monstres de Niveau 4	\r\nTant que cette carte a du Matériel, elle n''est affectée ni par des effets de Piège ni par les effets activés d''autres monstres du même Type que le Matériel de cette carte. \r\nVous ne pouvez utiliser chacun des effets suivants de "Traptrix Pinguicula" qu''une fois par tour. \r\nVous pouvez détacher 1 Matériel de cette carte; ajoutez 1 monstre "Traptrix" depuis votre Deck à votre main. \r\nSi un ou plusieurs monstres dont le propriétaire est votre adversaire sont envoyés au Cimetière ou bannis par un effet de carte (sauf durant la Damage Step): vous pouvez attacher 1 de ces monstres à cette carte comme Matériel.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1689516,'La Marche Triomphale des Animaux','Jusqu''à la fin de ce tour, tous les monstres Bête face recto que vous contrôlez gagnent 200 ATK pour chaque monstre Bête que vous contrôlez.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1697104,'Pièce Structure-PSY Epsilon',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement par un effet de carte, et non Invocable Spécialement autrement. \r\nDurant le tour de chaque joueur, lorsque votre adversaire active une Carte Piège tant que vous ne contrôlez aucun monstre: vous pouvez Invoquer Spécialement cette carte depuis votre main ainsi qu''1 "Pilote Structure-PSY" depuis votre main, Deck ou Cimetière, et si vous le faites, annulez l''activation, et si vous faites ça, détruisez la Carte Piège. \r\nDurant la End Phase, bannissez les monstres face recto Invoqués Spécialement par cet effet.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1710476,'Cyber Dragon Ultime Corrompu',replace(replace('(Cette carte n''est pas traitée comme une carte "Cyber Dragon".)	\r\nNi Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en bannissant 1 "Dragon Cyber Ultime" depuis votre Extra Deck. \r\nIl ne peut y avoir qu''1 monstre "Corrompu" sur le Terrain. \r\nLes autres monstres que vous contrôlez ne peuvent pas déclarer d''attaque. \r\nS''il n''y a aucune Magie de Terrain face recto sur le Terrain, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1710647,'Yoa l''Asutra Divin Épidémique',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en révélant 1 carte face verso que vous contrôlez et en la renvoyant à la main/Extra Deck.\r\nVous ne pouvez Invoquer Spécialement "Yoa l''Asutra Divin Épidémique" qu''une fois par tour de cette façon.\r\nVous ne pouvez utiliser chacun des effets suivants de "Yoa l''Asutra Divin Épidémique" qu''une fois par tour.\r\nDurant votre Main Phase: vous pouvez Poser 1 Magie/Piège "Asutra" depuis votre Deck.\r\nDurant le tour de votre adversaire (Effet Rapide): vous pouvez cibler 1 monstre face recto sur le Terrain; augmentez ou réduisez son Niveau de 1.','\r',char(13)),'\n',char(10)),'','Poser','Changer le Niveau','Augmenter le Niveau','Diminuer le Niveau','','','','','','','','','','','');
INSERT INTO texts VALUES(1712616,'Vol et Dard de la Coléoptroupe',replace(replace('Lorsque votre adversaire active un effet de monstre, tant que vous contrôlez un monstre "Coléoptroupe": annulez l''activation, et si vous le faites, détruisez-le. \r\nDurant votre End Phase, si cette carte est dans votre Cimetière et que vous contrôlez un monstre Insecte avec min. 3000 ATK: vous pouvez bannir 1 monstre Insecte depuis votre Cimetière; Posez cette carte. \r\nVous ne pouvez utiliser qu''1 effet de "Vol et Dard de la Coléoptroupe" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1735088,'Zenmaintenance Automate',replace(replace('2 monstres "Automate"	\r\nSi cette carte est détruite et envoyée au Cimetière: vous pouvez cibler 1 Monstre Xyz "Automate" que vous contrôlez; attachez-lui cette carte comme Matériel. \r\nVous ne pouvez utiliser chacun des effets suivants de "Zenmaintenance Automate" qu''une fois par tour.\r\n● Si cette carte est Invoquée par Lien: vous pouvez ajouter 1 carte "Automate" depuis votre Deck à votre main.\r\n● Vous pouvez bannir face verso 1 monstre "Automate" face recto que vous contrôlez; Invoquez Spécialement 1 monstre du même nom que la carte avait sur le Terrain depuis votre Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1759808,'Portrait Démoniaque',replace(replace('Ciblez 1 monstre face recto contrôlé par votre adversaire; Invoquez Spécialement 1 monstre de ce nom depuis votre Deck ou Extra Deck, mais mélangez-le dans le Deck durant la End Phase du prochain tour, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres depuis le Deck ou Extra Deck le reste de ce tour après la résolution de cette carte. \r\nVous ne pouvez activer qu''1 "Portrait Démoniaque" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1761063,'Nekogal N°1','Un chaton Elfe. En contraste avec son adorable beauté, il montre les griffes à ses ennemis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1764972,'Empereur Dragon de la Damnation/Mode Assaut',replace(replace('Cette carte ne peut ni être Invoquée Normalement ni être Posée. \r\nCette carte ne peut pas être Invoquée Spécialement, excepté avec "Activation Mode Assaut". \r\nLorsque cette carte est Invoquée Spécialement, Invoquez Spécialement sur votre Terrain un nombre de votre choix de monstres de Type Zombie depuis un des Cimetières. \r\nLes effets de ces monstres sont annulés, et ils sont détruits durant la End Phase ce tour. \r\nLorsque cette carte sur le Terrain est détruite, vous pouvez Invoquer Spécialement 1 "Empereur Dragon de la Damnation" depuis votre Cimetière.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invoquer Spécialement "Empereur Dragon de la Damnation"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1769875,'Chimère, Roi Bête Fantôme',replace(replace('1 monstre Bête + 1 monstre Démon	\r\nLe nom de cette carte devient "Chimère, Bête Mythique Volante" tant qu''elle est sur le Terrain ou dans le Cimetière. \r\nVous ne pouvez utiliser chacun des effets suivants de "Chimère, Roi Bête Fantôme" qu''une fois par tour. \r\nSi cette carte est Invoquée par Fusion: vous pouvez activer cet effet; durant la End Phase de ce tour, envoyez 1 carte au hasard depuis la main de votre adversaire au Cimetière. \r\nDurant le tour de votre adversaire (Effet Rapide): vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre Bête, Démon ou Illusion dans votre Cimetière; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1781310,'Fuh-Rin-Ka-Zan',replace(replace('Lorsqu''il y a des monstres VENT, EAU, FEU et TERRE face recto sur le Terrain: appliquez 1 de ces effets.\r\n● Détruisez tous les monstres contrôlés par votre adversaire.\r\n● Détruisez toutes les Cartes Magie/Piège contrôlées par votre adversaire.\r\n● Défaussez 2 cartes au hasard à votre adversaire.\r\n● Piochez 2 cartes.','\r',char(13)),'\n',char(10)),'Détruire tous les monstres que votre adversaire contrôle','Détruire toutes les Magies/Pièges que votre adversaire contrôle','Votre adversaire défausse 2 carte(s) au hasard','Piochez 2 carte(s)','','','','','','','','','','','','');
INSERT INTO texts VALUES(1784619,'Uraby','Rapide sur ses pattes, ce dinosaure lacère ses ennemis avec ses griffes acérées.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1784686,'L''Œil de Timée',replace(replace('(Cette carte est toujours aussi traitée comme "Dragon Légendaire Timée".)	\r\nCiblez 1 monstre "Magicien Sombre" ou "Magicienne des Ténèbres" que vous contrôlez; Invoquez par Fusion 1 Monstre Fusion qui mentionne le monstre sur le Terrain comme Matériel depuis votre Extra Deck, en l''utilisant comme le Matériel Fusion. \r\nVous ne pouvez activer qu''1 "L''Œil de Timée" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1799464,'Transcigale',replace(replace('Si cette carte est Invoquée Spécialement: vous pouvez Invoquer Spécialement 1 "Jeton Mue" (Insecte/TERRE/Niveau 3/ATK 0/DEF 0). \r\nTant que le Jeton Invoqué Spécialement par cet effet est sur le Terrain, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Insecte exclus) depuis l''Extra Deck. \r\nVous ne pouvez utiliser cet effet de "Transcigale" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1799465,'Jeton Mue','Invoqué Spécialement avec l''effet de "Transcigale". Tant que ce Jeton reste sur le Terrain, le joueur qui l''a Invoqué Spécialement ne peut pas Invoquer Spécialement des monstres depuis l''Extra Deck, sauf s''il s''agit de monstres de Type Insecte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1801154,'Un Champ Centrifuge','Lorsqu''un ou plusieurs Monstres de Fusion sont détruits par un effet de carte et envoyés au Cimetière: son propriétaire cible 1 Monstre-Matériel de Fusion dans son Cimetière qui est listé sur le Monstre de Fusion; le joueur Invoque Spécialement la cible.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1802450,'Cérémonie de Sceau du Mokuton','Une fois par tour: vous pouvez Sacrifier 1 monstre TERRE face recto, puis ciblez max. 2 cartes dans le Cimetière de l''adversaire; bannissez les cibles.','Utiliser l''effet de "Cérémonie de Sceau du Mokuton" maintenant ?','Bannir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1804528,'Cercueil des Ténèbres',replace(replace('Lorsque cette carte face verso est détruite et envoyée au Cimetière, votre adversaire doit sélectionner et exécuter 1 des effets suivants:\r\n● Défausser au hasard 1 carte de sa main.\r\n● Sélectionner 1 monstre sur son Terrain et le détruire.','\r',char(13)),'\n',char(10)),'Choisir un effet','Défaussez 1 carte(s) au hasard depuis votre main','Détruire 1 monstre que vous contrôlez','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1825445,'Union Super Quantique - Magnaformation',replace(replace('Durant votre Main Phase 1, votre adversaire ne peut pas cibler de cartes "Super Quant" sur le Terrain avec des effets de carte. \r\nVous pouvez cibler 1 Monstre Xyz "Super Quant" que vous contrôlez; attachez-lui 1 autre monstre face recto que vous contrôlez comme Matériel. \r\nVous ne pouvez utiliser cet effet de "Union Super Quantique - Magnaformation" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1826676,'Chevalier Jouet',replace(replace('Non Invocable Spécialement depuis le Deck. \r\nSi votre adversaire contrôle plus de monstres que vous, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nLorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez Invoquer Spécialement 1 "Chevalier Jouet" depuis votre main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1828513,'Shien, Ombre des Six Samouraïs',replace(replace('2 monstres "Six Samouraïs" de Niveau 4	\r\nUne fois par tour (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre "Six Samouraïs" que vous contrôlez avec moins de 2000 ATK; jusqu''à la fin de ce tour, son ATK d''origine devient 2000.','\r',char(13)),'\n',char(10)),'Changer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1833916,'Challenger Héroïque - Mille Lames',replace(replace('Une fois par tour, si cette carte est en Position d''Attaque: vous pouvez défausser 1 carte "Héroïque" ("Barrière Héroïque" et "Explosion Héroïque" exclus); Invoquez Spécialement 1 monstre "Héroïque" depuis votre Deck, et si vous le faites, changez cette carte en Position de Défense, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres "Héroïque" exclus) le reste de ce tour. \r\nLorsque vous recevez des dommages tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte en Position d''Attaque. \r\nVous ne pouvez utiliser cet effet de "Challenger Héroïque - Mille Lames" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1834107,'Électro-Sphèrum','Lorsqu''un monstre de Type Tonnerre que vous contrôlez inflige des dommages de combat à votre adversaire, gagnez des Life Points équivalents aux dommages infligés.','Gagner des LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1834753,'Téléportateur Multiple',replace(replace('Cette carte ne peut pas être Invoquée Spécialement. \r\nVous pouvez payer 2000 Life Points pour Invoquer Spécialement 2 monstres de Type Psychique de Niveau 3 depuis votre Deck. \r\nCet effet ne peut être utilisé qu''une fois tant que cette carte est face recto sur le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1845204,'Fusion Instantanée',replace(replace('Payez 1000 LP; Invoquez Spécialement 1 Monstre Fusion de max. Niveau 5 depuis votre Extra Deck, mais il ne peut pas attaquer, et aussi, il est détruit durant la End Phase. \r\n(Ceci est traité comme Invocation Fusion.) \r\nVous ne pouvez activer qu''1 "Fusion Instantanée" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1855886,'Balafre de la Vendetterreur',replace(replace('Si cette carte est envoyée au Cimetière: vous pouvez ajouter 1 Magie/Piège "Vendetterreur" depuis votre Deck à la main. \r\nSi un ou plusieurs monstres sur le Terrain sont Sacrifiés, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez bannir 1 autre monstre Zombie depuis votre Cimetière; Invoquez Spécialement cette carte, et si vous le faites, tant qu''elle est face recto dans la Zone Monstre, vous ne pouvez pas Invoquer Spécialement de monstres (monstres "Vendetterreur" exclus). \r\nVous ne pouvez utiliser chaque effet de "Balafre de la Vendetterreur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1855932,'Bujintei Kagutsuchi',replace(replace('2 monstres de Type Bête-Guerrier de Niveau 4	\r\nLorsque cette carte est Invoquée par Xyz: envoyez les 5 cartes du dessus de votre Deck au Cimetière (ou tout votre Deck, si vous en avez moins de 5), et aussi, cette carte gagne 100 ATK pour chaque carte "Bujin" envoyée au Cimetière par cet effet. \r\nSi un ou plusieurs monstres "Bujin" de Type Bête-Guerrier que vous contrôlez vont être détruits au combat ou par un effet de carte, vous pouvez détacher 1 Matériel Xyz de cette carte au lieu de détruire 1 de ces monstres. \r\nVous ne pouvez contrôler qu''1 "Bujintei Kagutsuchi".','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','Utiliser l''effet de "Bujintei Kagutsuchi" à la place de la destruction ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861629,'Décodeur Bavard',replace(replace('2+ Monstres à Effet	\r\nGagne 500 ATK pour chaque monstre pointé par cette carte. \r\nLorsque votre adversaire active une carte ou un effet qui cible une ou plusieurs cartes que vous contrôlez (Effet Rapide): vous pouvez Sacrifier 1 monstre pointé par cette carte; annulez l''activation, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'Annuler l''activation et détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861630,'Décodeur Bavard',replace(replace('2+ Monstres à Effet	\r\nGagne 500 ATK pour chaque monstre pointé par cette carte. \r\nLorsque votre adversaire active une carte ou un effet qui cible une ou plusieurs cartes que vous contrôlez (Effet Rapide): vous pouvez Sacrifier 1 monstre pointé par cette carte; annulez l''activation, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'Annuler l''activation et détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861631,'Décodeur Bavard',replace(replace('2+ Monstres à Effet	\r\nGagne 500 ATK pour chaque monstre pointé par cette carte. \r\nLorsque votre adversaire active une carte ou un effet qui cible une ou plusieurs cartes que vous contrôlez (Effet Rapide): vous pouvez Sacrifier 1 monstre pointé par cette carte; annulez l''activation, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'Annuler l''activation et détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1872843,'Morphée, Chevalier Blanc du Miroir des Rêves',replace(replace('Si cette carte est Invoquée Spécialement par l''effet d''un monstre "Miroir des Rêves": vous pouvez activer cet effet; ce tour, cette carte ne peut être détruite ni au combat ni par des effets de carte. \r\nDurant la Main ou Battle Phase, si "Miroir des Rêves de la Terreur" est dans une Zone Terrain (Effet Rapide): vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 "Morphée, Chevalier Noir du Miroir des Rêves" depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Morphée, Chevalier Blanc du Miroir des Rêves" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1876841,'Scannen Morphtronique',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 1 monstre "Morphtronique" depuis votre main.\r\n● Position d''Attaque: Une fois par tour, durant votre Main Phase: vous pouvez ajouter 1 Magie/Piège "Morphtronique" depuis votre Deck à votre main, puis placez 1 carte depuis votre main au-dessus du Deck.\r\n● Position de Défense: Une fois par tour, durant votre Main Phase: vous pouvez ajouter 1 monstre "Morphtronique" de max. Niveau 4 depuis votre Cimetière à votre main, puis placez 1 carte depuis votre main au-dessus du Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1896112,'Explosion Dimensionnelle',replace(replace('Renvoyez 1 Monstre de Fusion face recto que vous contrôlez dans le Extra Deck. \r\nLes deux joueurs sélectionnent jusqu''à 2 de leurs monstres retirés du jeu, puis les Invoquent Spécialement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1906812,'Sprind le Dragon Filefer',replace(replace('"Albaz le Déchu" + 1 Monstre à Effet Invoqué Spécialement ce tour	\r\nDurant votre Main Phase: vous pouvez déplacer cette carte que vous contrôlez dans une autre de vos Zones Monstre Main, puis vous pouvez détruire toutes les autres cartes face recto dans la colonne de cette carte. \r\nDurant la End Phase, si cette carte est dans le Cimetière parce qu''elle y a été envoyée ce tour: vous pouvez ajouter à votre main ou Invoquer Spécialement 1 monstre "Springans" ou 1 "Albaz le Déchu" depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Sprind le Dragon Filefer" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Détruire toutes les autres cartes face recto dans la colonne de cette carte ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1918087,'Fonctionnaire Gobelin',replace(replace('Vous pouvez Activer cette carte lorsque les Life Points de votre adversaire sont de 3000 points ou moins. \r\nInfligez 500 points de dommages aux Life Points de votre adversaire durant chacune de ses Standby Phases.','\r',char(13)),'\n',char(10)),'Infligez 500 points de dommages à votre adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1929294,'Lutine à la Clé','Le cœur des ennemis les plus féroces fond comme neige au soleil à la vue de cette adorable petite fée.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1942635,'Butin Boss Genèraideur',replace(replace('Tant que vous contrôlez un Jeton, les monstres de votre adversaire ne peuvent pas cibler les Monstres à Effet "Genèraideur" avec une attaque. \r\nSi un Monstre à Effet "Genèraideur" est détruit au combat: votre adversaire pioche 1 carte. \r\nVous ne pouvez utiliser cet effet de "Butin Boss Genèraideur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1945387,'Maître Nova, HÉROS Élémentaire',replace(replace('1 monstre "HÉROS Élémentaire" + 1 monstre FEU	\r\nUniquement Invocable par Fusion. \r\nSi cette carte détruit un monstre de l''adversaire au combat: piochez 1 carte.','\r',char(13)),'\n',char(10)),'Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1948619,'Conducteur de Miracles, HÉROS Xtra',replace(replace('2 monstres "HÉROS"	\r\nSi un monstre "HÉROS" est Invoqué Normalement ou Spécialement dans votre zone pointée par cette carte: ciblez 1 Magie "Polymérisation", 1 Magie "Fusion" ou 1 Magie Jeu-Rapide "Change" dans votre Cimetière; Posez la cible. \r\nVous ne pouvez activer cet effet de "Conducteur de Miracles, HÉROS Xtra" qu''une fois par tour. \r\nSi cette carte est détruite au combat et envoyée au Cimetière, ou si cette carte en votre possession est détruite par un effet de carte de l''adversaire et envoyée à votre Cimetière: Invoquez Spécialement 1 monstre "HÉROS" depuis votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1953925,'Ingénieur Rouages Ancients',replace(replace('Annulez les effets de Piège qui ciblent cette carte, et si vous le faites, détruisez la Carte Piège. \r\nSi cette carte attaque, votre adversaire ne peut pas activer de Cartes Magie/Piège jusqu''à la fin de la Damage Step. À la fin de la Damage Step, si cette carte a attaqué: ciblez 1 Magie/Piège contrôlé par votre adversaire; détruisez la cible.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1965724,'Explosion de Mokey Mokey','Si un monstre Elfe face recto que vous contrôlez est détruit tant que vous contrôlez "Mokey Mokey", l''ATK de chaque "Mokey Mokey" que vous contrôlez va devenir 3000 jusqu''à la fin de ce tour.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1966438,'Âme Désenchaînée Abominable',replace(replace('Vous ne pouvez Invoquer Spécialement un ou plusieurs "Âme Désenchaînée Abominable" qu''une fois par tour. \r\nSi une ou plusieurs cartes que vous contrôlez sont détruites au combat ou par un effet de carte: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte est Invoquée Spécialement: vous pouvez défausser 1 carte; détruisez 1 carte sur le Terrain. \r\nUne fois par tour, durant la End Phase, si cette carte est dans le Cimetière parce qu''elle a été détruite sur le Terrain et y a été envoyée ce tour: vous pouvez Invoquer Spécialement cette carte, mais placez-la au-dessous du Deck lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1969506,'Rituel de Marionnette',replace(replace('Si votre adversaire a min. 2000 Life Points de plus que vous: vous pouvez cibler 2 monstres "Poupée Truquée" de Niveau 8 dans votre Cimetière; Invoquez Spécialement les cibles. \r\nVous ne pouvez activer qu''1 "Rituel de Marionnette" par tour. \r\nVous ne pouvez pas mener votre Battle Phase le tour où vous activez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1980574,'Escadrille des Longues Oreilles',replace(replace('Durant la Main Phase de votre adversaire (Effet Rapide): vous pouvez cibler 1 monstre face recto que vous contrôlez; Invoquez Spécialement cette carte depuis votre main, et si vous le faites, immédiatement après la résolution de cet effet, Invoquez par Synchronisation 1 Monstre Synchro en utilisant cette carte que vous contrôlez et la cible. \r\nVous ne pouvez utiliser cet effet de "Escadrille des Longues Oreilles" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1984618,'Serviteur de Nadir',replace(replace('Envoyez 1 monstre depuis votre Extra Deck au Cimetière, puis ajoutez 1 "Albaz le Déchu" ou monstre "Dogmatika" depuis votre Deck ou Cimetière à votre main, qui a une ATK inférieure ou égale au monstre envoyé dans le Cimetière, et aussi, vous ne pouvez pas Invoquer Spécialement depuis l''Extra Deck le reste de ce tour après la résolution de cette carte. \r\nVous ne pouvez activer qu''1 "Serviteur de Nadir" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1992816,'Numéro 9 : Sphère Dyson',replace(replace('2 monstres de Niveau 9	\r\nDurant votre Main Phase 1, si votre adversaire contrôle un monstre avec une ATK supérieure à cette carte: vous pouvez détacher 1 Matériel de cette carte; ce tour, cette carte peut attaquer directement. \r\nUne fois par Battle Step, si cette carte avec du Matériel est attaquée (Effet Rapide): vous pouvez annuler l''attaque. \r\nLorsque cette carte est ciblée par une attaque tant qu''elle n''a pas de Matériel: vous pouvez cibler 2 monstres dans votre Cimetière; attachez ces monstres à cette carte comme Matériel.','\r',char(13)),'\n',char(10)),'Annuler l''attaque','Attacher du Matériel','Attaque directe','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1995985,'Spadassin Silencieux LV3',replace(replace('Annulez les effets de Magie de votre adversaire qui ciblent cette carte. \r\nDurant votre Standby Phase: vous pouvez envoyer cette carte face recto au Cimetière; Invoquez Spécialement 1 "Spadassin Silencieux LV5" depuis votre main ou Deck. \r\nVous ne pouvez pas activer cet effet le tour où cette carte est Invoquée ou retournée face recto.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2006591,'Éveil du Butin du Péché',replace(replace('Si votre adversaire contrôle min. 3 monstres et que vous contrôlez un monstre Illusion de min. Niveau 5: ciblez max. 3 cartes contrôlées par votre adversaire; renvoyez-les à la main. \r\nSi vous contrôlez un monstre Illusion de min. Niveau 5 et que cette carte est dans votre Cimetière: vous pouvez Poser cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser qu''1 effet de "Éveil du Butin du Péché" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','Poser','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2009101,'Aile Noire - Mistral le Tourbillon',replace(replace('Si vous contrôlez un monstre "Aile Noire" ("Aile Noire - Mistral le Tourbillon" exclu), vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nUne fois par tour: vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; l''ATK/DEF de la cible deviennent la moitié de son ATK/DEF actuelles.','\r',char(13)),'\n',char(10)),'Diviser l''ATK/DEF par deux','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2047519,'Soldats Embusqués','Lorsque votre adversaire Invoque Normalement ou par Flip un monstre: Invoquez Spécialement 1 monstre TÉNÈBRES de max. Niveau 4 depuis votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2055403,'Trappe Espace-Temps','Lorsque votre adversaire Invoque Spécialement un ou plusieurs monstres depuis la main ou l''Extra Deck: mélangez ces monstres dans le Deck, puis vous perdez 1000 LP pour chaque monstre renvoyé.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2061963,'Numéro 104 : Mascarade',replace(replace('3 monstres de Niveau 4	\r\nDurant la Battle Phase, lorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''activation, et si vous le faites, infligez 800 points de dommages à votre adversaire. \r\nUne fois par tour, durant votre Main Phase: vous pouvez envoyer la carte du dessus du Deck de votre adversaire au Cimetière.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Envoyer du Deck au Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2067935,'Lanista, Bête Gladiateur','Lorsque cette carte est Invoquée Spécialement par l''effet d''un monstre "Bête Gladiateur": ciblez 1 monstre "Bête Gladiateur" dans votre Cimetière; bannissez la cible, et jusqu''à la End Phase, le nom de cette carte devient le nom de la cible. À la fin de la Battle Phase, si cette carte a attaqué ou a été attaquée: vous pouvez la mélanger dans le Deck; Invoquez Spécialement 1 monstre "Bête Gladiateur" ("Lanista, Bête Gladiateur" exclu) depuis votre Deck.','Bannir','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2084239,'Plaines Marécageuses','Tous les monstres Type Aqua/EAU/Niveau 2 ou moins gagnent 1200 points d''ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2088870,'Ver - Victoire',replace(replace('FLIP: Détruisez tous les monstres face recto sur le Terrain, excepté les monstres "Ver" de Type Reptile. \r\nCette carte gagne 500 points d''ATK pour chaque monstre "Ver" de Type Reptile dans votre Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2089016,'Roquette Tuspa Chronomal',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez envoyer 1 monstre "Chronomal" depuis votre Deck ou Extra Deck au Cimetière, puis ciblez 1 monstre face recto sur le Terrain; jusqu''à la fin de ce tour, il perd une ATK égale au Niveau/Rang du monstre envoyé au Cimetière x 200. \r\nUn Monstre Xyz "Numéro" qui a été Invoqué en utilisant cette carte sur le Terrain comme Matériel gagne cet effet.\r\n● Durant chaque Battle Phase, cette carte peut faire max. 2 attaques sur des monstres.	\r\nVous ne pouvez utiliser chaque effet de "Roquette Tuspa Chronomal" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','L''effet de "Roquette Tuspa Chronomal" est actuellement appliqué.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2091298,'Praesepe de la Constellée',replace(replace('2 monstres "Constellée" de Niveau 4	\r\nUne fois par tour, durant la Damage Step de chaque joueur, lorsqu''un monstre "Constellée" que vous contrôlez attaque ou est attaqué: vous pouvez détacher 1 Matériel Xyz de cette carte; jusqu''à la End Phase, le monstre gagne 1000 ATK.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2095764,'Bixi, Eau du Yang Zing',replace(replace('Lorsque cette carte que vous contrôlez est détruite au combat ou par un effet de carte, et envoyée à votre Cimetière: vous pouvez Invoquer Spécialement 1 monstre "Yang Zing" ("Bixi, Eau du Yang Zing" exclu) depuis votre Deck en Position d''Attaque. \r\nVous ne pouvez utiliser cet effet de "Bixi, Eau du Yang Zing" qu''une fois par tour. \r\nUne fois par tour, durant la Main Phase ou Battle Phase de votre adversaire, vous pouvez: immédiatement après la résolution de cet effet, Invoquez par Synchronisation 1 Monstre Synchro, en utilisant uniquement des monstres "Yang Zing" que vous contrôlez (ceci est un Effet Rapide). \r\nUn Monstre Synchro qui a utilisé cette carte comme Matériel de Synchro n''est pas affecté par des effets de Piège.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','L''effet de "Bixi, Eau du Yang Zing" est actuellement appliqué.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2099841,'Monde Souriant','Jusqu''à la fin de ce tour, tous les monstres face recto actuellement sur le Terrain gagnent 100 ATK pour chaque monstre actuellement sur le Terrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2102065,'Brinegir',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre EAU dans votre Cimetière; jusqu''à la fin de ce tour, cette carte gagne une ATK égale à l''ATK du monstre. \r\nSi cette carte est envoyée au Cimetière: vous pouvez cibler 1 monstre EAU que vous contrôlez; jusqu''à la fin de ce tour, il gagne 1000 ATK. \r\nVous ne pouvez utiliser chaque effet de "Brinegir" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2106266,'Gaïa au Galop',replace(replace('Votre adversaire ne peut activer ni de cartes ni d''effets durant la Battle Phase, tant que "Gaïa le Dragon Champion" est dans votre Zone Monstre. \r\nVous pouvez activer 1 des effets suivants.\r\n● Vous pouvez révéler 1 monstre "Gaïa le Chevalier Implacable" dans votre main; ajoutez 1 monstre Dragon de Niveau 5 depuis votre Deck à votre main.\r\n● Vous pouvez révéler 1 monstre Dragon de Niveau 5 dans votre main; ajoutez 1 monstre "Gaïa le Chevalier Implacable" depuis votre Deck à votre main.	\r\nVous ne pouvez utiliser cet effet de "Gaïa au Galop" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter 1 monstre Dragon de Niveau 5 à la main','Ajouter 1 monstre "Gaïa le Chevalier Implacable" à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2111707,'Canon Dragon-XY',replace(replace('"Tête de Canon X" + "Tête de Dragon Y"	\r\nDoit d''abord être Invoquée Spécialement (depuis votre Extra Deck) en bannissant les cartes ci-dessus que vous contrôlez. \r\n(N''utilisez pas "Polymérisation".) \r\nNon Invocable Spécialement depuis le Cimetière. \r\nVous pouvez défausser 1 carte, puis ciblez 1 Magie/Piège face recto contrôlé par votre adversaire; détruisez la cible.','\r',char(13)),'\n',char(10)),'Détruire des Magies/Pièges','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2116237,'Loka Samsara',replace(replace('Bannissez 1 "Visas Starfrost" face recto depuis votre Zone Monstre (jusqu''à la End Phase); Invoquez Spécialement 1 monstre "Heart" avec 3000 ATK depuis votre Extra Deck, en ignorant ses conditions d''Invocation, mais il ne peut activer ses effets qu''une fois tant qu''il est face recto sur le Terrain, et aussi, bannissez-le face verso durant la End Phase. \r\nSi votre adversaire Invoque Spécialement un ou plusieurs monstres depuis l''Extra Deck, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez ajouter cette carte à votre main. \r\nVous ne pouvez utiliser chaque effet de "Loka Samsara" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Renvoyer sur le Terrain les monstres bannis à l''activation','Bannir face verso le monstre Invoqué Spécialement','','','','','','','','','','','','');
INSERT INTO texts VALUES(2118022,'Hyosube','Cet amphibien est doué pour l''attaque, mais sa défense laisse à désirer.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2122975,'Capture de Piège',replace(replace('Défaussez 1 carte pour placer cette carte dans la Chaîne en réponse à une Carte Piège que vous avez activée. \r\nLorsque cette dernière est envoyée au Cimetière, renvoyez-la dans la main de son propriétaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2129638,'Dragon Jumelé d''Explosion aux Yeux Bleus',replace(replace('"Dragon Blanc aux Yeux Bleus" + "Dragon Blanc aux Yeux Bleus"	\r\nUniquement soit Invocable par Fusion soit Invocable Spécialement en envoyant les monstres ci-dessus que vous contrôlez au Cimetière. \r\nNon destructible au combat. \r\nPeut faire max. 2 attaques sur des monstres durant chaque Battle Phase. À la fin de la Damage Step, lorsque cette carte attaque un monstre de l''adversaire, mais que le monstre de l''adversaire n''a pas été détruit au combat: vous pouvez bannir le monstre de l''adversaire.','\r',char(13)),'\n',char(10)),'Bannir un monstre de l''adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2130625,'Guérisseur Angélique',replace(replace('Vous pouvez Activer cette carte lorsque vous recevez des dommages à vos Life Points. \r\nAugmentez vos Life Points de 1000 points. \r\nPuis, augmentez vos Life Points de 500 points pour chaque autre carte "Guérisseur Angélique" dans votre Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2133971,'Contrôleur d''Union',replace(replace('1 monstre LUMIÈRE Machine + "Tête Action-Y" ou "Tank Zillion-Z"	\r\nDoit d''abord être Invoquée Spécialement (depuis votre Extra Deck) en bannissant les cartes ci-dessus que vous contrôlez. \r\nSi cette carte est Invoquée Spécialement depuis l''Extra Deck: vous pouvez ajouter 1 Magie/Piège depuis votre Deck à votre main qui mentionne "monstre Union" dans son texte. \r\nVous ne pouvez utiliser cet effet de "Contrôleur d''Union" qu''une fois par tour. \r\nUne fois par tour, durant votre Main Phase: vous pouvez Invoquer Spécialement 1 monstre Normal ou Union LUMIÈRE Machine depuis votre main.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2134346,'Prêtre d''Asura',replace(replace('Non Invocable Spécialement. \r\nDurant la End Phase du tour où cette carte est Invoquée Normalement ou retournée face recto: renvoyez-la à la main. \r\nCette carte peut attaquer une fois chacun des monstres contrôlés par votre adversaire.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2137678,'Armée Meklord de Granel',replace(replace('Gagne 100 ATK pour chaque monstre "Meklord" (cette carte exclue) sur le Terrain. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; jusqu''à la fin de ce tour, divisez par deux l''ATK de la cible.','\r',char(13)),'\n',char(10)),'Diviser l''ATK par deux','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2139640,'Amabie','Au début de votre Main Phase 1: vous pouvez révéler cette carte dans votre main; chaque joueur gagne 300 LP.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2144946,'Grand Prix F.A. Tout-Terrain',replace(replace('Augmentez le Niveau de tous les monstres "F.A." sur le Terrain de 2 durant la Main Phase uniquement. \r\nVous ne pouvez utiliser chacun des effets suivants de "Grand Prix F.A. Tout-Terrain" qu''une fois par tour.\r\n● Lorsqu''un monstre "F.A." que vous contrôlez est détruit au combat: vous pouvez défausser 1 carte au hasard depuis la main de votre adversaire.\r\n● Si cette carte face recto sur le Terrain est détruite par un effet de carte: vous pouvez ajouter 1 carte "F.A." ("Grand Prix F.A. Tout-Terrain" exclu) depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2148918,'Art Ninjitsu Armure de Brume de Rouille','Lorsqu''un ou plusieurs monstres sont Invoqués Spécialement sur le Terrain de votre adversaire, si vous contrôlez un monstre "Ninja": divisez par deux l''ATK actuelle de ces monstres Invoqués Spécialement.','Changer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2158562,'Cyber Prima','Si cette carte est Invoquée par Sacrifice: détruisez toutes les Magies face recto sur le Terrain.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2191144,'Papillopérative de Nuit',replace(replace('3 monstres de Niveau 4	\r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte; cette carte gagne 300 ATK pour chaque Matériel Xyz attaché à un monstre sur le Terrain.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2196767,'Joueur Légendaire',replace(replace('Une fois par tour, vous pouvez lancer une pièce 3 fois et appliquer les effets suivants:\r\n● 3 "face": Détruisez tous les monstres contrôlés par votre adversaire.\r\n● 2 "face": Défaussez 1 carte au hasard de la main de votre adversaire.\r\n● 1 "face": Détruisez 1 carte que vous contrôlez.\r\n● 3 "pile": Défaussez toutes les cartes de votre main.','\r',char(13)),'\n',char(10)),'Lancer une pièce','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2203790,'Hyunlei, Sabre XX',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur "Sabre X"	\r\nLorsque cette carte est Invoquée par Synchronisation: vous pouvez cibler max. 3 Magies/Pièges sur le Terrain; détruisez-les.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204038,'Valkyrie-Brunhilde',replace(replace('Non affectée par les effets de Magie de votre adversaire. \r\nGagne 500 ATK pour chaque monstre contrôlé par votre adversaire. \r\nLorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez faire perdre exactement 1000 DEF à cette carte, et si vous le faites, vos monstres "Valkyrie-" ne peuvent pas être détruits au combat ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204140,'Le Livre de la Vie','Ciblez 1 monstre Zombie dans votre Cimetière et 1 monstre dans le Cimetière de votre adversaire; Invoquez Spécialement la première cible, et aussi, bannissez la seconde cible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2220237,'Gardna de Sécurisation',replace(replace('1 Monstre Lien Cyberse	\r\nAprès que cette carte est Invoquée Spécialement, vous ne recevez aucun dommage d''effet le reste de ce tour. \r\nUne fois par tour, si vous allez recevoir des dommages de combat ou d''effet, vous ne recevez aucun dommage. \r\nNon utilisable comme Matériel Lien. \r\nVous ne pouvez contrôler qu''1 "Gardna de Sécurisation".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2250266,'Agrafeuse Morphtronique',replace(replace('● En Position d''Attaque: Tant que cette carte est face recto sur le Terrain, votre adversaire ne peut pas sélectionner un autre monstre comme cible d''une attaque.	\r\nSi cette carte est détruite au combat, le monstre qui a détruit cette carte perd 300 d''ATK.\r\n● En Position de Défense: Cette carte ne peut pas être détruite au combat.	\r\nSi cette carte est attaquée, après le calcul des dommages, sélectionnez 1 monstre face recto en Position d''Attaque contrôlé par votre adversaire. \r\nChangez-le en Position de Défense et cette carte en Position d''Attaque.','\r',char(13)),'\n',char(10)),'Diminuer l''ATK','Passer en Position d''Attaque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2254222,'Aile Synchronique Vitesseroid',replace(replace('Échelle Pendule = 4\r\n[ Effet Pendule ]\r\nUne fois par tour: vous pouvez détruire cette carte et 1 Carte Monstre Pendule VENT de Niveau 2 dans votre Zone Pendule, et si vous le faites, Invoquez Spécialement 1 "Dragon Synchro de l''Aile Claire" depuis votre Extra Deck (ceci est traité comme Invocation Synchro), et aussi, le reste de ce tour, les cartes dans vos Zones Pendule ne peuvent pas être détruites par des effets de carte, et vous ne pouvez pas Invoquer Spécialement (monstres VENT exclus).\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est ajoutée face recto à votre Extra Deck, et que vous contrôlez min. 2 Types différents de Monstres Synchro VENT: vous pouvez envoyer 1 Magie/Piège "Vitesseroid" depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser cet effet de "Aile Synchronique Vitesseroid" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Envoyer au Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263869,'Pourfendeuse Ultime',replace(replace('Votre adversaire ne peut pas activer d''effets de monstre en réponse à l''activation de cette carte. \r\nEnvoyez 1 monstre depuis votre Extra Deck au Cimetière, puis ciblez 1 monstre contrôlé par votre adversaire du même type de carte (Fusion, Synchro, Xyz, Pendule ou Lien); mélangez-le dans le Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263870,'Pourfendeuse Ultime',replace(replace('Votre adversaire ne peut pas activer d''effets de monstre en réponse à l''activation de cette carte. \r\nEnvoyez 1 monstre depuis votre Extra Deck au Cimetière, puis ciblez 1 monstre contrôlé par votre adversaire du même type de carte (Fusion, Synchro, Xyz, Pendule ou Lien); mélangez-le dans le Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2266498,'Réunion Vendetterreur',replace(replace('Révélez 1 Monstre Rituel "Vendetterreur" dans votre main, Invoquez Spécialement un nombre de votre choix de monstres "Vendetterreur" bannis de noms différents en Position de Défense face verso, dont le Niveau total est exactement égal au Niveau du Monstre Rituel révélé, Sacrifiez tous ces monstres en Position de Défense face verso, puis Invoquez Rituellement le Monstre Rituel depuis votre main. \r\nVous devez être capable d''Invoquer Rituellement pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2273734,'Satellchevalier Altaïr',replace(replace('Si cette carte est Invoquée: vous pouvez cibler 1 monstre "tellchevalier" ("Satellchevalier Altaïr" exclu) dans votre Cimetière; Invoquez Spécialement le monstre en Position de Défense, et aussi, les monstres que vous contrôlez (monstres "tellchevalier" exclus) ne peuvent pas attaquer le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Satellchevalier Altaïr" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2287848,'Révolution Vendetterreur',replace(replace('Défaussez 1 carte, puis ciblez 1 monstre "Vendetterreur" et 1 Magie Rituelle dans votre Cimetière; Invoquez Spécialement le monstre en Position de Défense, et si vous le faites, ajoutez la Magie Rituelle à votre main. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 5 de vos monstres Zombie bannis; mélangez-les dans votre Deck, puis piochez 1 carte. \r\nVous ne pouvez utiliser chaque effet de "Révolution Vendetterreur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295440,'Un pour Un','Envoyez 1 monstre depuis votre main au Cimetière; Invoquez Spécialement 1 monstre de Niveau 1 depuis votre main ou Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295441,'Un pour Un','Envoyez 1 monstre depuis votre main au Cimetière; Invoquez Spécialement 1 monstre de Niveau 1 depuis votre main ou Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295831,'Symbole d''Amitié',replace(replace('Pour activer cette carte, vous devez la piocher pour votre pioche normale durant votre Draw Phase tant que votre adversaire contrôle min. 3 monstres et que vous ne contrôlez aucune carte, révélez-la, et gardez-la révélée jusqu''à la Main Phase 1. \r\nDurant votre Main Phase 1 du même tour: vous pouvez activer cette carte depuis votre main; révélez 1 carte depuis votre Deck, et ajoutez-la à votre main.','\r',char(13)),'\n',char(10)),'Garder "Symbole d''Amitié" révélé ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311090,'Spright de la Carotte',replace(replace('Si vous contrôlez un monstre de Niveau/Link 2, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Spright de la Carotte" qu''une fois par tour de cette façon. \r\nLorsque votre adversaire active une Carte Magie/Piège ou effet de Magie/Piège (Effet Rapide): vous pouvez Sacrifier 1 autre monstre de Niveau/Rang/Link 2; annulez l''effet, puis si vous avez Sacrifié un monstre de Rang/Link 2 pour activer cet effet, vous pouvez détruire la carte. \r\nVous ne pouvez utiliser cet effet de "Spright de la Carotte" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Détruire cette carte ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311603,'Overdrive','Véhicule blindé tout-terrain armé d''une grosse mitrailleuse.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2314238,'Attaque de Magie Noire','Si vous contrôlez "Magicien Sombre": détruisez tous les Magies/Pièges contrôlés par votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2316186,'Princesse Curran',replace(replace('Cette carte ne peut ni être Invoquée par Invocation Normale ni être Posée. \r\nCette carte ne peut pas être Invoquée par Invocation Spéciale, excepté par l''effet du "Procès des Princesses". \r\nDurant votre Standby Phase, infligez 600 points de dommages aux Life Points de votre adversaire pour chaque monstre sur le Terrain de votre adversaire.','\r',char(13)),'\n',char(10)),'Infliger des dommages aux LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2322421,'Guerrier de la Route',replace(replace('"Route Synchronique" + 2 monstres non-Syntoniseur ou plus	\r\nUne fois par tour: vous pouvez Invoquer Spécialement 1 monstre de Type Guerrier ou Machine de max. Niveau 2 depuis votre Deck.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2326738,'Des Lacooda',replace(replace('Une fois par tour: vous pouvez changer cette carte en Position de Défense face verso. \r\nSi cette carte est Invoquée par Flip: piochez 1 carte.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face verso','Piocher 1 carte','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333365,'Týr, Champion Nordique',replace(replace('Votre adversaire ne peut pas cibler les monstres "Nordique" ("Týr, Champion Nordique" exclu) avec une attaque. \r\nS''il n''y a aucun autre monstre "Nordique" sur le Terrain, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333466,'Gandora-G le Dragon de la Destruction',replace(replace('Gagne 300 ATK pour chaque carte bannie. \r\nVous ne pouvez utiliser chacun des effets suivants de "Gandora-G le Dragon de la Destruction" qu''une fois par tour. \r\nSi vous contrôlez "Sarcophage Brillant": vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nVous pouvez payer la moitié de vos LP; détruisez autant d''autres cartes sur le Terrain que possible, et si vous le faites, bannissez-les, puis Invoquez Spécialement 1 monstre de max. Niveau 7 qui mentionne "Sarcophage Brillant" depuis votre Deck, et augmentez son Niveau du nombre de cartes détruites par cet effet.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement depuis la main','Détruire une carte','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2339825,'Fin T.G.',replace(replace('Lorsqu''une Carte Magie/Piège ou un effet de monstre est activé tant que vous contrôlez un monstre "T.G." Machine: annulez l''activation, et si vous le faites, détruisez la carte. \r\nSi un ou plusieurs Monstres Synchro sont bannis tant que cette carte est dans votre Cimetière: vous pouvez Poser cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser qu''1 effet de "Fin T.G." par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2344618,'Mascarade de Clair de Lune',replace(replace('Durant votre Main Phase, si cette carte a été activée ce tour: vous pouvez envoyer 1 monstre "Clair de Lune" depuis votre Deck au Cimetière. \r\nSi vous Invoquez par Fusion un monstre "Clair de Lune": vous pouvez ajouter 1 "Polymérisation" depuis votre Cimetière ou bannissement à votre main, puis vous pouvez défausser 1 carte, et si vous le faites, une fois, si vous Invoquez par Fusion un monstre "Clair de Lune" ce tour, vous pouvez aussi bannir des monstres depuis votre Cimetière comme Matériel. \r\nVous ne pouvez utiliser chaque effet de "Mascarade de Clair de Lune" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Ajouter à la main','Défausser une carte ?','L''effet de "Mascarade de Clair de Lune" est actuellement appliqué.','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347477,'Microcodeur',replace(replace('Si un monstre Cyberse que vous contrôlez va être utilisé comme Matériel Lien pour un monstre "Codeur Bavard", cette carte dans votre main peut aussi être utilisée comme Matériel. \r\nSi cette carte est envoyée depuis la main ou Terrain au Cimetière comme Matériel pour l''Invocation Lien d''un monstre "Codeur Bavard": vous pouvez soit ajouter 1 Magie/Piège "Cynet" depuis votre Deck à votre main, soit si cette carte sur le Terrain a été utilisée comme Matériel, vous pouvez ajouter 1 monstre Cyberse de Niveau 4 à la place. \r\nVous ne pouvez utiliser chaque effet de "Microcodeur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Envoyer du Terrain au Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347656,'Adorable Labrynth du Château d''Argent',replace(replace('Votre adversaire ne peut pas activer d''effets de monstre en réponse à l''activation de vos Cartes Piège Normal. \r\nVous ne pouvez utiliser chacun des effets suivants de "Adorable Labrynth du Château d''Argent" qu''une fois par tour. \r\nVous pouvez cibler 1 Piège Normal dans votre Cimetière; Posez-le sur votre Terrain, mais il ne peut pas être activé sauf si vous contrôlez un monstre Démon. \r\nSi un ou plusieurs autres monstres quittent le Terrain par votre effet de Piège Normal (sauf durant la Damage Step): vous pouvez détruire 1 carte dans la main de votre adversaire (au hasard) ou sur son Terrain.','\r',char(13)),'\n',char(10)),'','Sélectionner 1 carte dans la main ou sur le Terrain de l''adversaire à détruire','L''effet de "Adorable Labrynth du Château d''Argent" est actuellement appliqué.','Sélectionner au hasard 1 carte dans la main de l''adversaire à détruire','Sélectionner 1 carte contrôlée par l''adversaire à détruire','','','','','','','','','','','');
INSERT INTO texts VALUES(2347657,'Adorable Labrynth du Château d''Argent',replace(replace('Votre adversaire ne peut pas activer d''effets de monstre en réponse à l''activation de vos Cartes Piège Normal. \r\nVous ne pouvez utiliser chacun des effets suivants de "Adorable Labrynth du Château d''Argent" qu''une fois par tour. \r\nVous pouvez cibler 1 Piège Normal dans votre Cimetière; Posez-le sur votre Terrain, mais il ne peut pas être activé sauf si vous contrôlez un monstre Démon. \r\nSi un ou plusieurs autres monstres quittent le Terrain par votre effet de Piège Normal (sauf durant la Damage Step): vous pouvez détruire 1 carte dans la main de votre adversaire (au hasard) ou sur son Terrain.','\r',char(13)),'\n',char(10)),'','Sélectionner 1 carte dans la main ou sur le Terrain de l''adversaire à détruire','L''effet de "Adorable Labrynth du Château d''Argent" est actuellement appliqué.','Sélectionner au hasard 1 carte dans la main de l''adversaire à détruire','Sélectionner 1 carte contrôlée par l''adversaire à détruire','','','','','','','','','','','');
INSERT INTO texts VALUES(2347658,'Adorable Labrynth du Château d''Argent',replace(replace('Votre adversaire ne peut pas activer d''effets de monstre en réponse à l''activation de vos Cartes Piège Normal. \r\nVous ne pouvez utiliser chacun des effets suivants de "Adorable Labrynth du Château d''Argent" qu''une fois par tour. \r\nVous pouvez cibler 1 Piège Normal dans votre Cimetière; Posez-le sur votre Terrain, mais il ne peut pas être activé sauf si vous contrôlez un monstre Démon. \r\nSi un ou plusieurs autres monstres quittent le Terrain par votre effet de Piège Normal (sauf durant la Damage Step): vous pouvez détruire 1 carte dans la main de votre adversaire (au hasard) ou sur son Terrain.','\r',char(13)),'\n',char(10)),'','Sélectionner 1 carte dans la main ou sur le Terrain de l''adversaire à détruire','L''effet de "Adorable Labrynth du Château d''Argent" est actuellement appliqué.','Sélectionner au hasard 1 carte dans la main de l''adversaire à détruire','Sélectionner 1 carte contrôlée par l''adversaire à détruire','','','','','','','','','','','');
INSERT INTO texts VALUES(2356994,'Long-Nez le Géant',replace(replace('Cette carte ne peut pas être Invoquée par Invocation Spéciale. \r\nCette carte retourne dans la main de son propriétaire durant la End Phase du tour où elle a été Invoquée par Invocation Normale ou retournée face recto. \r\nSi cette carte inflige des dommages de combat aux Life Points de votre adversaire, celui-ci saute la Battle Phase de son prochain tour.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','Passer la Battle Phase','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2359348,'Espace Pendule','Si tous les monstres que vous contrôlez sont des Monstres Pendule (min. 1): ciblez 2 cartes dans vos Zones Pendule; détruisez les deux cartes, et si vous le faites, aucun joueur ne peut Invoquer Spécialement le reste de ce tour, sauf par Invocation Pendule.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2362787,'Lumière de Rédemption','Payez 800 Life Points, puis ciblez 1 de vos monstres LUMIÈRE bannis; ajoutez la cible à votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2364438,'Retour Mayakashi',replace(replace('Prenez 1 carte "Mayakashi" ("Retour Mayakashi" exclu) depuis votre Deck, et soit ajoutez-la à votre main soit envoyez-la au Cimetière. \r\nVous ne pouvez activer qu''1 "Retour Mayakashi" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2368215,'Acteur des Abysses - Hyperdirecteur',replace(replace('1 Monstre Pendule "Acteur des Abysses"	\r\nVous pouvez cibler 1 carte dans votre Zone Pendule; Invoquez-la Spécialement, puis placez 1 Monstre Pendule "Acteur des Abysses" de nom différent, depuis votre Deck ou Extra Deck face recto dans votre Zone Pendule, et aussi, vous ne pouvez Invoquer ni Normalement ni Spécialement de monstres (monstres "Acteur des Abysses" exclus) le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Acteur des Abysses - Hyperdirecteur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2370081,'Carapace d''Acier','Un monstre EAU équipé de cette carte augmente son ATK de 400 points et diminue sa DEF de 200 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2371506,'Reflet Xyz','Lorsqu''une Carte Magie/Piège ou un effet de monstre qui cible un ou plusieurs Monstres Xyz face recto sur le Terrain est activé: annulez l''activation, et si vous le faites, détruisez la/le, puis infligez 800 points de dommages à votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2372506,'Chapeaux Magiques du Chaos',replace(replace('Lorsque votre adversaire active un effet de monstre ou une Carte Magie Normale/Piège Normal: choisissez 3 Magies/Pièges de noms différents depuis votre Deck et 1 monstre dans votre Zone Monstre Main qui mentionne "Rituel de la Lumière et des Ténèbres". \r\nInvoquez Spécialement les Magies/Pièges comme Monstres Normaux (Magicien/TÉNÈBRES/Niveau 8/ATK 0/DEF 0) en Position de Défense face verso (leur nom devient "Chapeaux Magiques du Chaos" même tant qu''ils sont face verso), Posez le monstre choisi s''il est face recto, et mélangez-les sur le Terrain. \r\nPuis l''effet activé de votre adversaire devient "Détruisez 1 monstre contrôlé par votre adversaire en Position de Défense face verso".','\r',char(13)),'\n',char(10)),'Activer','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2376209,'Eldonia Paléozoïque',replace(replace('Ciblez 1 monstre face recto sur le Terrain; jusqu''à la fin de ce tour, il gagne 500 ATK/DEF. \r\nUne fois par Chaîne, lorsqu''une Carte Piège est activée tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte comme un Monstre Normal (Aqua/EAU/Niveau 2/ATK 1200/DEF 0).	\r\n(Cette carte N''EST PAS traitée comme un Piège.) \r\nSi elle est Invoquée de cette façon, cette carte n''est pas affectée par des effets de monstre, et aussi, bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2377034,'Hérisson de la Néo Cloche de Feu',replace(replace('Si cette carte est détruite au combat: ciblez 1 carte dans le Cimetière de votre adversaire; bannissez-la. \r\nSi cette carte sur le Terrain est détruite par un effet de carte: ciblez 1 monstre FEU avec max. 200 DEF ("Hérisson de la Néo Cloche de Feu" exclu) dans votre Cimetière; ajoutez la cible à votre main.','\r',char(13)),'\n',char(10)),'Bannir','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2390019,'Ojamassimilation',replace(replace('Révélez 1 Monstre Fusion LUMIÈRE Machine depuis votre Extra Deck et bannissez un nombre de votre choix de monstres "Ojama" depuis votre main, Terrain face recto et/ou Cimetière; Invoquez Spécialement un nombre de Matériels Fusion de noms différents dont les noms sont spécifiquement listés sur la carte que vous avez révélée, depuis votre main, Deck et/ou Cimetière, égal au nombre de monstres bannis pour activer cet effet. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 3 de vos monstres "Ojama" bannis; mélangez-les dans le Deck, puis piochez 1 carte.','\r',char(13)),'\n',char(10)),'Continuer à sélectionner des monstres à bannir ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2396042,'Cavalerie d''Acier de Dinon',replace(replace('Échelle Pendule = 5\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nAu début de la Damage Step, si cette carte combat un Monstre Pendule: jusqu''à la fin de la Damage Step, l''ATK/DEF de cette carte deviennent la moitié de son ATK/DEF actuelles.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2403771,'Dragon Électromécanique',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nUne fois par tour: vous pouvez révéler 3 Magies d''Équipement depuis votre Deck, puis votre adversaire en ajoute 1 au hasard à votre main, et mélangez les autres cartes dans le Deck. \r\nSi cette carte va être détruite tant qu''elle est équipée avec une ou plusieurs Magies d''Équipement, vous pouvez envoyer 1 de ces cartes au Cimetière à la place.','\r',char(13)),'\n',char(10)),'Sélectionner une Carte d''Équipement à ajouter à la main','Utiliser l''effet de "Dragon Électromécanique" à la place de la destruction ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2405631,'Guoglim, Lance du Ghoti',replace(replace('1 Syntoniseur Poisson + 1+ monstre non-Syntoniseur	\r\nAu début de la Damage Step, si cette carte combat un monstre de l''adversaire: vous pouvez bannir le monstre de l''adversaire. \r\nDurant la Standby Phase de votre adversaire: vous pouvez bannir cette carte, puis, si les monstres utilisés comme Matériel pour l''Invocation Synchro de cette carte sont tous dans votre Cimetière, vous pouvez tous les Invoquer Spécialement, mais bannissez-les lorsqu''ils quittent le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Guoglim, Lance du Ghoti" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Invoquer Spécialement le monstre Matériel Synchro ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407147,'Servante Volcan Laval','Lorsque cette carte est envoyée au Cimetière, si vous avez un monstre "Laval" dans votre Cimetière ("Servante Volcan Laval" exclu): vous pouvez envoyer 1 monstre "Laval" depuis votre Deck à votre Cimetière.','Envoyer au Cimetière','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407234,'Numéro 69 : Emblème Héraldique',replace(replace('3 monstres de Niveau 4	\r\nSi cette carte est Invoquée Spécialement: annulez les effets de tous les autres Monstres Xyz actuellement sur le Terrain. \r\nVous pouvez cibler 1 autre Monstre Xyz face recto sur le Terrain; jusqu''à la End Phase, le nom de cette carte devient le nom d''origine du monstre, et aussi, remplacez cet effet avec les effets d''origine du monstre. \r\nVous ne pouvez utiliser cet effet de "Numéro 69 : Emblème Héraldique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Obtenir l''effet','Terminer l''effet copié','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2411269,'Dragon Agave',replace(replace('2+ monstres (Jetons exclus)	\r\nSi cette carte est Invoquée par Lien: vous pouvez appliquer ces effets dans l''ordre, selon les Types des monstres dans les Cimetières (ignorez ceux qui ne s''appliquent pas). \r\nVous ne pouvez utiliser cet effet de "Dragon Agave" qu''une fois par tour.\r\n● Infligez 100 points de dommages à votre adversaire pour chaque Dragon.\r\n● Cette carte gagne 200 ATK pour chaque Dinosaure.\r\n● Tous les monstres actuellement contrôlés par votre adversaire perdent 300 ATK pour chaque Serpent de Mer.\r\n● Vous gagnez 400 LP pour chaque Wyrm.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2414168,'Résistance Interrompue',replace(replace('Lorsque vous recevez des dommages de combat: vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, elle gagne une ATK égale aux dommages que vous avez reçus. \r\nUne fois par tour, durant le calcul des dommages, lorsqu''un autre monstre en Position de Défense que vous contrôlez est attaqué par un monstre de l''adversaire (Effet Rapide): vous pouvez activer cet effet; durant ce calcul des dommages, la DEF de votre monstre attaqué devient égale à la DEF de cette carte, et aussi, il ne peut pas être détruit par ce combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2419596,'Numéro 101 : Honneur Silencieux ARCHE - Asile de l''Âme',replace(replace('2 monstres de Niveau 4	\r\nVous pouvez détacher 1 Matériel de cette carte, puis activez 1 de ces effets;\r\n● Choisissez 1 monstre de Niveau 4 (le monstre détaché exclu) dans votre Cimetière, et ajoutez 1 monstre de Niveau 4 du même Type et Attribut, mais de nom différent, depuis votre Deck à votre main.\r\n● Ciblez 1 monstre contrôlé par votre adversaire; attachez-le à cette carte.	\r\nVous ne pouvez utiliser cet effet de "Numéro 101 : Honneur Silencieux ARCHE - Asile de l''Âme" qu''une fois par tour.\r\nSi cette carte va être détruite, vous pouvez détacher 1 Matériel de cette carte à la place.','\r',char(13)),'\n',char(10)),'Activer','Ajouter à la main','Comme Matériel Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2419597,'Numéro 101 : Honneur Silencieux ARCHE - Asile de l''Âme',replace(replace('2 monstres de Niveau 4	\r\nVous pouvez détacher 1 Matériel de cette carte, puis activez 1 de ces effets;\r\n● Choisissez 1 monstre de Niveau 4 (le monstre détaché exclu) dans votre Cimetière, et ajoutez 1 monstre de Niveau 4 du même Type et Attribut, mais de nom différent, depuis votre Deck à votre main.\r\n● Ciblez 1 monstre contrôlé par votre adversaire; attachez-le à cette carte.	\r\nVous ne pouvez utiliser cet effet de "Numéro 101 : Honneur Silencieux ARCHE - Asile de l''Âme" qu''une fois par tour.\r\nSi cette carte va être détruite, vous pouvez détacher 1 Matériel de cette carte à la place.','\r',char(13)),'\n',char(10)),'Activer','Ajouter à la main','Comme Matériel Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2420921,'Shire l''Esprit, Seigneur Lumière',replace(replace('Cette carte gagne 300 ATK pour chaque monstre "Seigneur Lumière" de nom différent dans votre Cimetière. \r\nDurant chacune de vos End Phases: envoyez les 2 cartes du dessus de votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'Envoyer 2 cartes depuis le Deck au Cimetière','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2434862,'Ascension Cubique',replace(replace('Lorsqu''un monstre de l''adversaire déclare une attaque: Invoquez Spécialement 1 "Vijam la Graine Cubique" depuis votre Deck, et si vous le faites, transférez-lui la cible de l''attaque, et faites le calcul des dommages. \r\nSi votre adversaire a min. 2000 LP de plus que vous: vous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 "Vijam la Graine Cubique" depuis votre main, Deck ou Cimetière, puis, si uniquement votre adversaire contrôlait un monstre lorsque cet effet a été activé, vous pouvez Invoquer Spécialement max. 2 "Vijam la Graine Cubique" supplémentaires. \r\nVous ne pouvez utiliser cet effet de "Ascension Cubique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement et changer la cible de l''attaque','Invocation Spéciale','Invoquer Spécialement un autre monstre ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2460565,'Capitaine en Maraude',replace(replace('Les monstres contrôlés par votre adversaire ne peuvent pas cibler de monstres Guerrier (celui-ci exclu) avec une attaque. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre de max. Niveau 4 depuis votre main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2461031,'Inzektor Coccinelle',replace(replace('Une fois par tour: vous pouvez équiper 1 monstre "Inzektor" depuis votre main ou Cimetière à cette carte. \r\nTant que cette carte est équipée à un monstre, le Niveau du monstre est augmenté de 2, et aussi, il gagne une ATK/DEF égales à l''ATK/DEF de cette carte. \r\nTant que cette carte est équipée à un monstre: vous pouvez envoyer cette Carte d''Équipement au Cimetière, puis ciblez 1 monstre face recto que vous contrôlez; augmentez le Niveau de la cible de 1 ou 2.','\r',char(13)),'\n',char(10)),'Équiper','Augmenter le Niveau','Augmenter de 1 Niveau','Augmenter de 2 Niveaux','','','','','','','','','','','','');
INSERT INTO texts VALUES(2463794,'Requiem du Démonforgeron',replace(replace('1 monstre LUMIÈRE Démon	\r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Requiem du Démonforgeron" qu''une fois par tour. \r\nDurant la Main Phase (Effet Rapide): vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 monstre "Démonforgeron" depuis votre main ou Deck. \r\nVous pouvez cibler 1 monstre non-Lien LUMIÈRE Démon que vous contrôlez; équipez cette carte depuis votre Terrain ou Cimetière au monstre que vous contrôlez comme Magie d''Équipement qui lui donne 600 ATK. \r\nVous ne pouvez utiliser cet effet de "Requiem du Démonforgeron" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet d''Équipement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2468169,'Meisei, Le Maître des Sceaux','Une des rares personnes à savoir maîtriser convenablement un Talisman. Son passé est un mystère.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2483611,'Omotics Aquatique','Elle manipule l''eau de sa jarre tel de puissant dragon.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2501624,'Magicienne des Ténèbres l''Apprentie du Magicien',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en défaussant 1 carte, et si vous le faites, le nom de cette carte devient "Magicienne des Ténèbres". \r\nVous ne pouvez Invoquer Spécialement "Magicienne des Ténèbres l''Apprentie du Magicien" qu''une fois par tour de cette façon. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 "Sarcophage Brillant" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Magicienne des Ténèbres l''Apprentie du Magicien" qu''une fois par tour. \r\nGagne 300 ATK pour chaque monstre qui mentionne "Sarcophage Brillant" dans les Cimetières.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Ajouter à la main','Augmenter l''ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2504891,'Crâne Chevalier','"Sagesse Salie" + "Cerveau Ancien"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2507443,'Première Lueur',replace(replace('Activez 1 de ces effets;\r\n● Sacrifiez 1 monstre TERRE Guerrier, et si vous le faites, Invoquez Spécialement 1 monstre LUMIÈRE Guerrier depuis votre main ou Deck.\r\n● Durant la Main Phase: immédiatement après la résolution de cet effet, Invoquez Normalement 1 monstre Guerrier depuis votre main.	\r\nDurant votre Main Phase: vous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 monstre "Cyber" Guerrier ou Elfe depuis votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Première Lueur" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Activer','Ajouter à la main','Sacrifier et Invoquer Spécialement','Invocation Normale','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511717,'Six Samouraïs Légendaires - Kageki',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre "Six Samouraïs" de max. Niveau 4 depuis votre main. \r\nTant que vous contrôlez un monstre "Six Samouraïs" de nom différent, cette carte gagne 1500 ATK.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2519690,'Gaïa le Dragon Champion Galopant au Ciel',replace(replace('1 monstre "Gaïa le Chevalier Implacable" + 1 monstre de Type Dragon	\r\nLe nom de cette carte devient "Gaïa le Dragon Champion" tant qu''elle est sur le Terrain. \r\nSi cette carte est Invoquée Spécialement: vous pouvez ajouter 1 "Charge Tournoyante" à votre main depuis votre Deck ou votre Cimetière. \r\nLorsque cette carte déclare une attaque sur un monstre adverse: vous pouvez changer la position de combat du monstre adverse.','\r',char(13)),'\n',char(10)),'Ajouter 1 carte "Charge Tournoyante" à la main','Changer la position de combat d''un monstre de l''adversaire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2521011,'Confrérie du Poing de Feu - Hirondelle',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en envoyant 3 Cartes Magie/Piège "Formation Feu" face recto que vous contrôlez au Cimetière. \r\nLorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez Poser 1 Carte Piège "Formation Feu" directement depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Confrérie du Poing de Feu - Hirondelle" qu''une fois par tour. \r\nLes monstres de Type Bête-Guerrier face recto que vous contrôlez ne peuvent pas être ciblés par des effets de carte de votre adversaire.','\r',char(13)),'\n',char(10)),'Poser','Piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2525268,'Bouclier Divin, le Chevalier Magique',replace(replace('Si cette carte est Invoquée Normalement: placez 1 Compteur Magie sur elle (max. 1). \r\nUne fois par tour, si un ou plusieurs monstres Magicien sur le Terrain vont être détruits, vous pouvez retirer 1 Compteur Magie depuis votre Terrain pour chacun de ces monstres à la place.','\r',char(13)),'\n',char(10)),'Placer des Compteurs Magie','Utiliser l''effet de "Bouclier Divin, le Chevalier Magique" à la place de la destruction ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2526224,'Avatar Grand Roi du Feu Kirin',replace(replace('Durant la Main Phase, si cette carte est dans votre main (Effet Rapide): vous pouvez détruire 1 autre monstre FEU dans votre main ou Terrain face recto, et si vous le faites, Invoquez Spécialement cette carte. \r\nSi cette carte est détruite et envoyée au Cimetière: vous pouvez Invoquer Spécialement 1 monstre "Roi du Feu" ou "Rois du Feu" ("Avatar Grand Roi du Feu Kirin" exclu) depuis votre main ou Cimetière, puis vous pouvez détruire 1 carte sur le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Avatar Grand Roi du Feu Kirin" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Détruire 1 carte sur le Terrain ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2530830,'Dragon Épée Cipher aux Yeux Galactiques',replace(replace('3 monstres de Niveau 9	\r\nVous pouvez aussi Invoquer par Xyz cette carte en utilisant un Monstre Xyz "Yeux Galactiques" de Rang 8 que vous contrôlez comme Matériel. \r\n(Transférez ses Matériels à cette carte.) \r\nNon utilisable comme Matériel pour une Invocation Xyz. \r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 carte sur le Terrain; détruisez-la. \r\nSi cette carte Invoquée par Xyz que vous contrôlez est détruite au combat avec un monstre attaquant de l''adversaire ou détruite par un effet de carte de l''adversaire, et envoyée à votre Cimetière: vous pouvez cibler 1 "Dragon Cipher aux Yeux Galactiques" dans votre Cimetière; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'Invoquer Xyz en utilisant le Monstre Xyz "Yeux Galactiques" comme Matériel ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2542230,'Cocon Rouge',replace(replace('Ciblez 1 Monstre Synchro de Type Dragon que vous contrôlez; équipez-lui cette carte. \r\nTant qu''il combat un monstre de votre adversaire, jusqu''à la fin de la Damage Step, annulez les effets de tous les monstres face recto contrôlés par votre adversaire. \r\nDurant la End Phase, si cette carte est dans le Cimetière parce qu''elle y a été envoyée ce tour: vous pouvez cibler 1 "Dragon Rouge Archdémon" dans votre Cimetière; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2547033,'Rocher Hanté Altergeist',replace(replace('Si cette carte a été Posée par l''effet d''une carte "Altergeist", vous pouvez l''activer le tour où elle a été Posée. \r\nLorsque cette carte est activée: envoyez 1 monstre "Altergeist" depuis votre main au Cimetière. \r\nLorsque votre adversaire active une Carte Piège (sauf durant la Damage Step): vous pouvez envoyer 1 monstre "Altergeist" depuis votre main au Cimetière; annulez l''effet, et si vous le faites, détruisez la carte. \r\nVous ne pouvez utiliser chaque effet de "Rocher Hanté Altergeist" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Activer en appliquant l''effet de "Altergeist".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2561846,'Cellule de Corruption "A"','Mettez 1 Compteur-A sur 1 monstre face recto sur le Terrain de votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2563463,'Cavalier de Gryphon Errant',replace(replace('Durant la Main Phase, si vous ne contrôlez aucun monstre ou contrôlez "Jeton Aventurier" (Effet Rapide): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nLorsqu''une carte ou un effet est activé tant que vous contrôlez "Jeton Aventurier" (Effet Rapide): vous pouvez mélanger cette carte dans le Deck, et si vous le faites, annulez l''activation, et si vous faites ça, détruisez la carte. \r\nVous ne pouvez utiliser chaque effet de "Cavalier de Gryphon Errant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2572890,'Ouragan Majesspectre','Lorsqu''un ou plusieurs monstres vont être Invoqués Spécialement, ou qu''un effet de monstre est activé: Sacrifiez 1 monstre VENT Magicien; annulez l''Invocation ou l''activation, et si vous le faites, détruisez la carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2584136,'Choctopus',replace(replace('Lorsque cette carte est détruite au combat avec un monstre de votre adversaire et envoyée au Cimetière: vous pouvez équiper cette carte au monstre de votre adversaire. \r\nL''ATK du monstre devient 0, et aussi, il ne peut pas changer sa position de combat.','\r',char(13)),'\n',char(10)),'Équiper','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2602411,'Sorcier Buster, Épée Destructrice',replace(replace('Vous pouvez cibler 1 "Buster Blader" que vous contrôlez; équipez ce monstre depuis votre main ou votre Terrain à la cible. \r\nTant que cette carte est équipée à un monstre, les monstres dans le Cimetière de votre adversaire ne peuvent pas activer leurs effets. \r\nVous pouvez envoyer cette Carte d''Équipement au Cimetière, puis ciblez 1 monstre "Épée Destructrice" ("Sorcier Buster, Épée Destructrice" exclu) dans votre Cimetière; ajoutez-le à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2606417,'Boîte du Renversement',replace(replace('Une fois par tour, durant la Standby Phase: lancez un dé à six faces et placez un nombre de Compteurs sur cette carte égal au résultat (max. 6).\r\nLorsqu''un effet de monstre est activé sur le Terrain de votre adversaire, ou une fois par combat, durant le calcul des dommages, si un monstre de l''adversaire attaque: vous pouvez retirer 1 Compteur de cette carte, puis ciblez 1 des monstres; jouez à pile ou face.\r\nSi vous gagnez, vous pouvez Invoquer Spécialement 1 monstre qui mentionne "Magicien du Temps des Ténèbres" depuis votre Deck, et si vous le faites, jusqu''à la fin de ce tour, changez l''ATK du monstre ciblé à 0, et aussi, ses effets sont annulés.','\r',char(13)),'\n',char(10)),'Placer un marqueur','Lancer une pièce','Sélectionnez le nombre de compteurs à placer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2609443,'Vimana Chronomal',replace(replace('2 monstres de Niveau 5	\r\nUne fois par tour (Effet Rapide): vous pouvez cibler 1 monstre face recto sur le Terrain et 1 monstre "Chronomal" ou Monstre Xyz dans votre Cimetière; le monstre sur le Terrain gagne la moitié de l''ATK du monstre dans le Cimetière (jusqu''à la fin de ce tour), puis attachez le monstre depuis le Cimetière à cette carte comme Matériel. \r\nUne fois par tour, lorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez détacher 2 Matériels de cette carte; annulez l''activation.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK et réapprovisionner les Matériels','Annuler l''activation d''un monstre de l''adversaire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618045,'Chargeur Photon',replace(replace('Une fois par tour: jusqu''à votre prochaine Standby Phase, vous pouvez faire devenir l''ATK de cette carte le double de son ATK d''origine. \r\nCette carte ne peut pas attaquer le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Changer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618725,'Selandea, Partenaire GMX',replace(replace('Vous pouvez révéler cette carte dans votre main; Invoquez Spécialement 1 monstre "GMX" ou 1 monstre Dinosaure depuis votre main, et aussi, vous ne pouvez attaquer directement qu''avec des monstres "GMX" le reste de ce tour. \r\nSi cette carte est Invoquée Spécialement par un effet de monstre: vous pouvez Invoquer Spécialement 1 monstre "GMX" ou Dinosaure de max. Niveau 4 depuis votre main, Cimetière ou bannissement en Position de Défense. \r\nVous ne pouvez utiliser chaque effet de "Selandea, Partenaire GMX" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement depuis la main','Invoquer Spécialement depuis la main, le Cimetière ou le bannissement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2619149,'Samnite, Bête Gladiateur','Lorsque cette carte, qui a été Invoquée Spécialement par l''effet d''un monstre "Bête Gladiateur", détruit un monstre de l''adversaire au combat et l''envoie au Cimetière: vous pouvez ajouter 1 carte "Bête Gladiateur" depuis votre Deck à votre main. À la fin de la Battle Phase, si cette carte a combattu: vous pouvez la mélanger dans le Deck; Invoquez Spécialement 1 monstre "Bête Gladiateur" ("Samnite, Bête Gladiateur" exclu) depuis votre Deck.','Chercher dans le Deck','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625939,'Code de Bobine',replace(replace('Lorsqu''un monstre de l''adversaire déclare une attaque directe, tant que vous avez min. 3 monstres Cyberse dans votre Cimetière: annulez l''attaque, puis, vous pouvez Invoquer Spécialement max. 3 "Jeton Bobine" (Cyberse/LUMIÈRE/Niveau 1/ATK 0/DEF 0) en Position de Défense. \r\nCes Jetons ne peuvent pas être Sacrifiés pour une Invocation Sacrifice.','\r',char(13)),'\n',char(10)),'Invocation Spéciale d''un Jeton ?','Sélectionnez le nombre de Jetons à Invoquer Spécialement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625940,'Jeton Bobine','Invoqué Spécialement avec l''effet de "Code de Bobine". Ce Jeton ne peut pas être Sacrifié pour une Invocation Sacrifice.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2645637,'Yuki-Onna, Mayakashi du Zéro Absolu',replace(replace('2+ monstres Zombie	\r\nVous ne pouvez contrôler qu''1 "Yuki-Onna, Mayakashi du Zéro Absolu". \r\nAnnulez les effets activés des monstres bannis de votre adversaire. \r\nSi un monstre est Invoqué Spécialement depuis le Cimetière, ou si un effet de monstre est activé dans le Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 autre monstre face recto sur le Terrain; changez son ATK à 0, et si vous le faites, annulez ses effets. \r\nVous pouvez utiliser cet effet de "Yuki-Onna, Mayakashi du Zéro Absolu" max. deux fois par tour.','\r',char(13)),'\n',char(10)),'L''ATK devient 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2648201,'ZW - Armure Sleipnir',replace(replace('Vous pouvez cibler 1 monstre "Utopie" que vous contrôlez; équipez ce monstre depuis votre main ou votre Terrain à la cible. \r\nIl gagne 1000 ATK. \r\nLorsque cette carte que vous contrôlez est envoyée à votre Cimetière parce que le monstre équipé a été détruit par une carte de votre adversaire (au combat ou par un effet de carte): vous pouvez cibler 1 monstre "Utopie" dans votre Cimetière; Invoquez Spécialement la cible. \r\nVous ne pouvez contrôler qu''1 "ZW - Armure Sleipnir".','\r',char(13)),'\n',char(10)),'Équiper','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2656842,'Éclaireur Buggy de la Coléoptroupe',replace(replace('Vous ne pouvez pas Invoquer Spécialement de monstres (monstres Insecte exclus). \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez Invoquer Spécialement 1 "Éclaireur Buggy de la Coléoptroupe" depuis votre main, Deck ou Cimetière. \r\nVous ne pouvez utiliser cet effet de "Éclaireur Buggy de la Coléoptroupe" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2665273,'Jormungandr, Boss Genèraideur de l''Éternité',replace(replace('2+ monstres de Niveau 9	\r\nVous ne pouvez contrôler qu''1 "Jormungandr, Boss Genèraideur de l''Éternité". \r\nL''ATK/DEF d''origine de cette carte deviennent 1000 x son nombre de Matériels. \r\n(Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; chaque joueur pioche 1 carte, puis chaque joueur qui a pioché attache 1 carte depuis sa main ou Terrain à cette carte. \r\nVous ne pouvez utiliser cet effet de "Jormungandr, Boss Genèraideur de l''Éternité" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2671330,'Hyper Tête de Marteau','À la fin de la Damage Step, si un monstre de l''adversaire qui a combattu cette carte n''est pas détruit: renvoyez le monstre de l''adversaire à la main.','Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2674965,'Argostars - Stade à Domicile',replace(replace('Une fois par tour: vous pouvez payer 1000 LP; ajoutez 1 carte "Argostars" depuis votre Cimetière ou bannissement à votre main. \r\nChaque fois qu''un Piège Continu dans la Zone Magie & Piège est Invoqué Spécialement sur votre Terrain, infligez 500 points de dommages à votre adversaire. \r\nUne fois par Chaîne, si un Piège Continu active son effet dans votre Zone Monstre, tant que vous avez un monstre "Argostars" banni: vous pouvez cibler 1 carte face recto contrôlée par votre adversaire; jusqu''à la fin de ce tour, annulez ses effets.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Annuler','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2694423,'Ver Méduse',replace(replace('Vous pouvez retourner cette carte en Position de Défense face verso une fois par tour durant votre Main Phase. \r\nLorsque cette carte est Invoquée avec succès par Invocation Flip, détruisez 1 monstre sur le Terrain de votre adversaire.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face verso','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2725599,'Arbitre des Secours-AS',replace(replace('2+ monstres FEU	\r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Arbitre des Secours-AS" qu''une fois par tour. \r\nSi cette carte est Invoquée par Lien: vous pouvez ajouter 1 "Hydrant des Secours-AS" ou "QG des Secours-AS" depuis votre Deck ou Cimetière à votre main. \r\nSi vous activez une Carte Magie Jeu-Rapide "Secours-AS" ou une Carte Piège Normal "Secours-AS" (sauf durant la Damage Step): vous pouvez cibler 1 carte contrôlée par votre adversaire; détruisez-la. \r\nVous ne pouvez utiliser cet effet de "Arbitre des Secours-AS" que deux fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729285,'Chat Peluchimal',replace(replace('Si cette carte est envoyée au Cimetière comme Matériel de Fusion pour une Invocation Fusion: vous pouvez cibler 1 "Polymérisation" dans votre Cimetière; ajoutez-la à votre main. \r\nVous ne pouvez utiliser cet effet de "Chat Peluchimal" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729965,'Trunade Spatiale',replace(replace('Renvoyez max. 2 cartes sur le Terrain à la main, puis chaque joueur place un nombre de cartes depuis sa main au-dessous de son Deck dans l''ordre de son choix égal au nombre de cartes qui ont été renvoyées à sa main.\r\nVous ne pouvez activer qu''1 "Trunade Spatiale" par tour.','\r',char(13)),'\n',char(10)),'Activer','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2732323,'Dragon Appât','Si cette carte est ciblée par une attaque: ciblez 1 monstre Dragon de min. Niveau 7 dans votre Cimetière; Invoquez-le Spécialement, et si vous le faites, transférez-lui la cible de l''attaque et faites le calcul des dommages.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2743001,'Phénix Crystron',replace(replace('1 Monstre Synchro Syntoniseur + 1+ Monstre Synchro non-Syntoniseur	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez bannir toutes les Magies et tous les Pièges contrôlés par votre adversaire et dans son Cimetière. \r\nSi cette carte Invoquée par Synchronisation est détruite au combat ou par un effet de carte: vous pouvez cibler 1 autre monstre dans votre Cimetière; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'Bannir les Magies/Pièges sur le Terrain et dans le Cimetière','Invoquer Spécialement depuis le Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2752099,'Shaman de la Rose',replace(replace('Vous pouvez Sacrifier cette carte; piochez 1 carte. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre Plante dans votre Cimetière; ajoutez-le à votre main, puis si vous avez ajouté un monstre Plante dont le Niveau d''origine est min. 7, vous pouvez envoyer 1 monstre Plante depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser qu''1 effet de "Shaman de la Rose" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','Envoyer à nouveau 1 monstre Plante depuis le Deck au Cimetière ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2759860,'Impact Berceau-Gris',replace(replace('Vous pouvez cibler 1 autre carte "Berceau-Gris" que vous contrôlez et 1 carte contrôlée par votre adversaire; détruisez-les. \r\nDurant votre End Phase: vous pouvez ajouter 1 carte "Berceau-Gris" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Impact Berceau-Gris" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Détruire une carte','Ajouter 1 carte "Berceau-Gris" depuis le Deck à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2766877,'Daigusto Phénix',replace(replace('2 monstres de Niveau 2	\r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte pour cibler 1 monstre VENT face recto que vous contrôlez; ce tour, durant chaque Battle Phase, il peut attaquer deux fois.','\r',char(13)),'\n',char(10)),'Attaquer deux fois','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772236,'Électro-Chimère',replace(replace('1 Syntoniseur "Électro-" + 1+ monstre non-Syntoniseur Tonnerre	\r\nCette carte peut attaquer directement. \r\nSi cette carte inflige des dommages de combat à votre adversaire par une attaque directe: placez 1 carte au hasard depuis la main de votre adversaire au-dessus de son Deck.','\r',char(13)),'\n',char(10)),'Renvoyer au Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772337,'Princesse Prométhéenne, Donneuse de Flammes',replace(replace('2+ Monstres à Effet	\r\nVous ne pouvez pas Invoquer Spécialement (monstres FEU exclus). \r\nVous ne pouvez utiliser chacun des effets suivants de "Princesse Prométhéenne, Donneuse de Flammes" qu''une fois par tour. \r\nDurant votre Main Phase: vous pouvez Invoquer Spécialement 1 monstre FEU depuis votre Cimetière. \r\nSi un ou plusieurs monstres sont Invoqués Spécialement sur le Terrain de votre adversaire, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 monstre FEU que vous contrôlez et 1 monstre contrôlé par votre adversaire; détruisez-les, et si vous le faites, Invoquez Spécialement cette carte.','\r',char(13)),'\n',char(10)),'Réanimer','Détruire un monstre','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772338,'Princesse Prométhéenne, Donneuse de Flammes',replace(replace('2+ Monstres à Effet	\r\nVous ne pouvez pas Invoquer Spécialement (monstres FEU exclus). \r\nVous ne pouvez utiliser chacun des effets suivants de "Princesse Prométhéenne, Donneuse de Flammes" qu''une fois par tour. \r\nDurant votre Main Phase: vous pouvez Invoquer Spécialement 1 monstre FEU depuis votre Cimetière. \r\nSi un ou plusieurs monstres sont Invoqués Spécialement sur le Terrain de votre adversaire, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 monstre FEU que vous contrôlez et 1 monstre contrôlé par votre adversaire; détruisez-les, et si vous le faites, Invoquez Spécialement cette carte.','\r',char(13)),'\n',char(10)),'Réanimer','Détruire un monstre','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2779999,'Mur d''Épines','Lorsqu''un monstre de Type Plante que vous contrôlez est ciblé par une attaque: détruisez tous les monstres en Position d''Attaque contrôlés par votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2783661,'Majesté avec des Yeux de Bleu',replace(replace('Envoyez 1 monstre "Yeux Bleus" depuis votre main ou Deck au Cimetière, puis ciblez 1 monstre face recto sur le Terrain; il ne peut pas attaquer tant qu''il est face recto sur le Terrain. \r\nVous ne pouvez activer qu''1 "Majesté avec des Yeux de Bleu" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2792265,'Agent du Catabolisme',replace(replace('(Cette carte n''est pas traitée comme une carte "Agent".)	\r\nCe monstre peut attaquer directement les Life Points de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2801664,'Guerriers Anciens - Vaillant Zhang De',replace(replace('Durant votre tour uniquement, gagne 300 ATK pour chaque monstre contrôlé par votre adversaire. \r\nVous ne pouvez utiliser chacun des effets suivants de "Guerriers Anciens - Vaillant Zhang De" qu''une fois par tour.\r\n● Si vous contrôlez min. 2 monstres "Guerriers Anciens": vous pouvez Invoquer Spécialement cette carte depuis votre main.\r\n● Si votre adversaire contrôle plus de monstres que vous: vous pouvez activer cet effet; durant chaque Battle Phase ce tour, cette carte peut faire max. 2 attaques sur des monstres.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2810642,'Pièce Structure-PSY Bêta',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement par un effet de carte, et non Invocable Spécialement autrement. \r\nLorsqu''un monstre de votre adversaire déclare une attaque tant que vous ne contrôlez aucun monstre: vous pouvez Invoquer Spécialement cette carte depuis votre main ainsi qu''1 "Pilote Structure-PSY" depuis votre main, Deck ou Cimetière, et si vous le faites, détruisez le monstre attaquant, puis terminez la Battle Phase. \r\nDurant la End Phase, bannissez les monstres face recto Invoqués Spécialement par cet effet.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2815176,'Zebufera, Païen Saint Vaalmonicain',replace(replace('1 Monstre à Effet	\r\nNon Invocable par Lien sauf si vous avez min. 3 Compteurs Résonance sur une ou plusieurs Cartes Monstre Démon dans vos Zones Pendule. \r\nVous ne pouvez Invoquer Spécialement "Zebufera, Païen Saint Vaalmonicain" qu''une fois par tour. \r\nSi une ou plusieurs cartes que vous contrôlez vont être détruites au combat ou par un effet de carte, vous pouvez retirer 3 Compteurs Résonance depuis votre Zone Pendule à la place. \r\nUne fois par tour de l''adversaire (Effet Rapide): vous pouvez cibler 1 de vos Magies Normales/Pièges Normaux "Vaalmonica" qui est banni ou dans votre Cimetière; appliquez l''effet d''activation de la carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819435,'Pacifis, la Cité Spectre',replace(replace('(Le nom de cette carte est toujours traité comme "Umi".)	\r\nVous ne pouvez Invoquer ni Normalement ni Spécialement de Monstres à Effet le tour où vous activez un effet de cette carte (même si cette carte quitte le Terrain). \r\nUne fois par tour, si vous Invoquez Normalement ou Spécialement exactement 1 Monstre Normal (et aucune autre carte): ajoutez 1 carte "Spirale Spectre" depuis votre Deck à votre main. \r\nSi votre adversaire active une carte ou un effet (sauf durant la Damage Step), et que vous ne contrôlez aucun Jeton: vous pouvez Invoquer Spécialement 1 "Jeton Spirale Spectre" (Type Wyrm/EAU/Niveau 8/ATK 2000/DEF 2000).','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Jeton','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819436,'Jeton Spirale Spectre','Invoqué Spécialement avec l''effet de "Pacifis, la Cité Spectre".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830619,'Vipère de flammes','Serpent cracheur de feu qui va si vite qu''il est difficile à viser.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830693,'Kuriboh Arc-en-Ciel',replace(replace('Vous ne pouvez utiliser chaque effet de "Kuriboh Arc-en-Ciel" qu''une fois par tour.\r\n● Lorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez cibler le monstre attaquant; équipez cette carte depuis votre main au monstre.	\r\nIl ne peut pas attaquer.\r\n● Lorsqu''un monstre de l''adversaire déclare une attaque directe tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte, mais bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'Équiper','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2833249,'Tribu D.','Tous les monstres sur votre Terrain deviennent de Type Dragon jusqu''à la End Phase.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2834264,'Corne Armure de la Coléoptroupe',replace(replace('2 monstres Insecte	\r\nVous ne pouvez pas Invoquer Spécialement de monstres (monstres Insecte exclus). \r\nVous ne pouvez utiliser chacun des effets suivants de "Corne Armure de la Coléoptroupe" qu''une fois par tour. \r\nDurant votre Main Phase, vous pouvez: immédiatement après la résolution de cet effet, Invoquez Normalement 1 monstre Insecte. \r\nSi cette carte est dans votre Cimetière: vous pouvez bannir 3 autres monstres Insecte depuis votre Cimetière; Invoquez Spécialement cette carte, mais bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2843014,'Poisson Lune Agile',replace(replace('Lorsque cette carte est détruite au combat et envoyée au Cimetière, envoyez 1 monstre de Type Poisson depuis votre Deck au Cimetière. \r\nEnsuite, vous pouvez Invoquer Spécialement 1 "Poisson Lune Agile" depuis votre Deck.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Invoquer Spécialement "Poisson Lune Agile" ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2851070,'Reflect Bounder',replace(replace('Avant le calcul des dommages, si cette carte est attaquée par un monstre de l''adversaire et était en Position d''Attaque au début de la Damage Step: infligez des dommages à votre adversaire égaux à l''ATK du monstre attaquant. \r\nSi vous le faites, après le calcul des dommages: détruisez cette carte.','\r',char(13)),'\n',char(10)),'Infliger des dommages','S''autodétruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2857636,'Phénix, Chevalier du Cauchemar',replace(replace('2 monstres de noms différents	\r\nSi cette carte est Invoquée par Lien: vous pouvez défausser 1 carte, puis ciblez 1 Magie/Piège contrôlé par votre adversaire; détruisez-le, puis, si cette carte était co-liée lorsque cet effet a été activé, vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser cet effet de "Phénix, Chevalier du Cauchemar" qu''une fois par tour. \r\nLes monstres co-liés que vous contrôlez ne peuvent pas être détruits au combat.','\r',char(13)),'\n',char(10)),'','Piocher 1 carte ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2863439,'Reflet Infernal N°2','Monstre à plumes qui invoque des renforcements d''un miroir qu''il tient dans ses mains.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2881864,'Naglfar, Boss Genèraideur du Feu',replace(replace('Vous ne pouvez contrôler qu''1 "Naglfar, Boss Genèraideur du Feu". \r\nSi une ou plusieurs cartes que vous contrôlez vont être détruites au combat ou par un effet de carte, vous pouvez détruire 1 monstre "Genèraideur" ou 1 monstre Bête-Guerrier que vous contrôlez à la place. \r\nVous ne pouvez utiliser cet effet de "Naglfar, Boss Genèraideur du Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2896663,'ZW - Hallebarde Dragonique',replace(replace('2 monstres de Niveau 5	\r\nNe peut pas attaquer directement. \r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte; ajoutez 1 Magie/Piège "Zexal" depuis votre Deck à votre main. \r\nVous pouvez cibler 1 monstre "Utopie" que vous contrôlez; équipez-lui cette carte que vous contrôlez. \r\nIl gagne 3000 ATK. \r\nLorsque le monstre équipé détruit un monstre au combat: vous pouvez Invoquer Spécialement sur votre Terrain un nombre de votre choix de Cartes Monstre "ZW -" qui lui sont équipées.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Traiter comme Carte d''Équipement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2903036,'Poupée de Sacrifice',replace(replace('Sacrifiez 1 monstre; Invoquez Spécialement 1 monstre de Niveau 7 depuis votre main qui est Invocable/Posable Normalement. \r\nIl ne peut pas attaquer ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906250,'Lutteur','Serpent sournois au corps épais qui s''enroule autour des monstres ennemis et les étouffe.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906939,'Trichiliocosme Asutrashen',replace(replace('Vous pouvez cibler un nombre de votre choix de cartes face verso que vous contrôlez; ajoutez un nombre de cartes "Asutra" de noms différents l''une de l''autre (Magies de Terrain exclues) depuis votre Deck à votre main, égal au nombre de cartes ciblées qui sont toujours face verso, puis envoyez les cartes face verso au Cimetière.\r\nSi une ou plusieurs cartes deviennent Posées sur le Terrain, tant que vous contrôlez un monstre "Asutra" et une carte face verso: vous pouvez cibler 1 carte sur le Terrain; renvoyez-la à la main.\r\nVous ne pouvez utiliser chaque effet de "Trichiliocosme Asutrashen" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Renvoyer à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2924048,'Dépôt Karakuri',replace(replace('Activable uniquement si vous contrôlez un monstre "Karakuri" en Position de Défense face recto. \r\nAnnulez l''activation d''une Carte Magie ou Piège de votre adversaire et détruisez-la.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2926176,'Malédiction du Roi','Annulez l''activation d''une Carte Magie ou Piège qui inclut comme effet la destruction d''1 Carte Magie ou Piège et détruisez-la.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2930675,'Clé de l''Héritage du Monde',replace(replace('Lorsque cette carte est activée: vous pouvez cibler 1 de vos monstres "Mekk-Chevalier" ou cartes "Héritage du Monde" bannis; ajoutez-le à votre main. \r\nAnnulez les effets de Piège de l''adversaire qui s''activent dans la même colonne qu''un monstre "Mekk-Chevalier" que vous contrôlez.','\r',char(13)),'\n',char(10)),'Ajouter la carte bannie à votre main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2932235,'Horreur de l''Ombre Mille',replace(replace('(Effet Rapide): vous pouvez envoyer cette carte depuis votre main ou Terrain au Cimetière; placez 1 "Septième de Barian" depuis votre main ou Deck face recto dans votre Zone Terrain, et aussi, vous ne pouvez pas Invoquer Spécialement depuis l''Extra Deck (Monstres Xyz exclus) jusqu''à la fin de votre prochain tour.\r\nSi un ou plusieurs Monstres Xyz sont Invoqués Spécialement tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte, et aussi, vous ne recevez aucun dommage d''effet de vos effets de carte le reste de ce tour.\r\nVous ne pouvez utiliser chaque effet de "Horreur de l''Ombre Mille" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Placer dans la Zone Terrain','Invocation Spéciale','L''effet de "Horreur de l''Ombre Mille" est actuellement appliqué.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2948263,'Golem Gogogo - Forme Or',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en Sacrifiant 1 monstre "Gogogo", et non Invocable Spécialement autrement. \r\nL''ATK de cette carte devient le double de l''ATK d''origine du monstre Sacrifié. \r\nTous les dommages de combat que votre adversaire reçoit d''attaques impliquant cette carte sont divisés par deux. \r\nUne fois par tour, durant le tour de chaque joueur, si un effet de monstre est activé sur le Terrain de votre adversaire: cette carte perd exactement 1500 ATK, et si elle le fait, annulez l''effet.','\r',char(13)),'\n',char(10)),'Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2956282,'Barkion Naturia',replace(replace('1 Syntoniseur TERRE + 1+ monstre non-Syntoniseur TERRE	\r\nLorsqu''une Carte Piège est activée (Effet Rapide): vous pouvez bannir 2 cartes depuis votre Cimetière; annulez l''activation, et si vous le faites, détruisez la carte. \r\nCette carte doit être face recto sur le Terrain pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Annuler l''activation d''une Carte Piège et la détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2957055,'Dragon à tête ersatz','Dragon à deux têtes doté d''une paire de mâchoires capables de déchirer l''ennemi en lambeaux.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2964201,'Ryu-Ran','Ce féroce petit dragon se cache dans un œuf à l''air faussement inoffensif.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971090,'Orion, le Roi du combat','Personne n''est revenu pour conter les légendes de ce puissant magicien du combat.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971446,'Argument de Vente',replace(replace('Si votre adversaire ajoute une ou plusieurs cartes depuis le Deck à sa main, sauf en les piochant, par son effet de carte: révélez 1 carte depuis votre Deck, et ajoutez-la à votre main, mais vous ne pouvez activer ni de cartes ni d''effets de cartes de ce nom le reste de ce tour. \r\nVous ne pouvez activer qu''1 "Argument de Vente" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2978414,'Numéro 46 : Dragluon',replace(replace('2 monstres de Type Dragon de Niveau 8	\r\nUne fois par tour, si vous ne contrôlez aucun autre monstre: vous pouvez détacher 1 Matériel Xyz de cette carte, puis activez 1 de ces effets.\r\n● Invoquez Spécialement 1 monstre de Type Dragon depuis votre main.\r\n● Ciblez 1 monstre de Type Dragon contrôlé par votre adversaire; prenez le contrôle de la cible.\r\n● Jusqu''à la fin du tour de votre adversaire, les monstres de Type Dragon contrôlés par votre adversaire ne peuvent pas activer leurs effets.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement 1 monstre Dragon depuis votre main','Prendre le contrôle de 1 monstre Dragon contrôlé par votre adversaire','Les monstres Dragon contrôlés par votre adversaire ne peuvent pas activer leurs effets','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2980764,'Lumière Sacrée',replace(replace('Aucun joueur ne peut ni Invoquer Normalement ou Spécialement de monstres TÉNÈBRES ni déclarer d''attaque avec un monstre TÉNÈBRES. \r\nCette carte ne peut pas être détruite au combat avec un monstre TÉNÈBRES, et aussi, vous ne recevez aucun dommage de combat de ce combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2986553,'Chevalier de la Rose du Crépuscule',replace(replace('Les monstres contrôlés par votre adversaire ne peuvent pas cibler de monstres Plante avec une attaque. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre Plante de max. Niveau 4 depuis votre main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992036,'Astro Meklord l''Éradicateur',replace(replace('Ciblez 3 monstres "Meklord" de noms différents dans votre Cimetière; ajoutez-les à votre main, OU Invoquez-les Spécialement, en ignorant leurs conditions d''Invocation. \r\nJusqu''à la fin de votre prochain tour après activation de cette carte, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Machine exclus). \r\nSi vous contrôlez un monstre "Astro Meklord" ou "Astre Meklord": vous pouvez bannir cette carte depuis votre Cimetière; détruisez 1 Monstre Synchro contrôlé par votre adversaire, et si vous le faites, infligez des dommages à votre adversaire égaux à son ATK d''origine. \r\nVous ne pouvez utiliser chaque effet de "Astro Meklord l''Éradicateur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992467,'Click et Écho',replace(replace('Non utilisable comme Matériel pour une Invocation Fusion, Synchro ou Xyz. \r\nNon Sacrifiable tant qu''elle est face recto dans la Zone Monstre. \r\nSi cette carte est envoyée au Cimetière comme Matériel pour une Invocation Lien: Invoquez Spécialement cette carte en Position de Défense, sur le Terrain de l''adversaire du joueur qui a Invoqué par Lien. \r\nVous ne pouvez utiliser cet effet de "Click et Écho" que deux fois par tour. \r\nTant que cette carte qui a été Invoquée par son effet est dans la Zone Monstre, vous devez garder votre main révélée.','\r',char(13)),'\n',char(10)),'','Gardez votre main révélée','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2994495,'Onde de Fuhma','Ciblez 1 monstre face recto sur le Terrain; détruisez 1 monstre sur le Terrain du même Attribut, mais de nom différent du monstre.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3019642,'Queue Cyberténébreuse',replace(replace('Si cette carte est Invoquée Normalement: ciblez 1 monstre Dragon de max. Niveau 3 dans votre Cimetière; équipez le monstre Dragon à cette carte. \r\nGagne une ATK égale à l''ATK d''origine du monstre qui lui est équipé par cet effet. \r\nSi cette carte détruit un monstre de l''adversaire au combat: infligez 300 points de dommages à votre adversaire. \r\nSi cette carte va être détruite au combat, détruisez le monstre équipé à la place.','\r',char(13)),'\n',char(10)),'Équiper','Infliger des dommages','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3026686,'Valkyrie-Dritte',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 carte "Valkyrie-" ("Valkyrie-Dritte" exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Valkyrie-Dritte" qu''une fois par tour. \r\nGagne 200 ATK pour chacun des monstres bannis de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3027001,'Piège Truqué',replace(replace('Vous pouvez Activer cette carte lorsque votre adversaire utilise une Carte Magie, Piège ou Monstre à Effet qui détruit une ou des Cartes Piège sur votre Terrain. \r\nDétruisez cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3030892,'Singe de Laboratoire','Lorsque cette carte est détruite au combat et envoyée au Cimetière, vous pouvez Invoquer Spécialement 1 monstre "Bête Gladiateur" de Niveau 4 ou moins depuis votre Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3040496,'Chef du Chaos, le Dragon Magique Chaotique',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez dévoiler les 5 cartes du dessus de votre Deck, et si vous le faites, vous pouvez ajouter 1 monstre LUMIÈRE ou TÉNÈBRES dévoilé à votre main, et aussi, envoyez les cartes restantes au Cimetière. \r\nVous pouvez bannir 1 monstre LUMIÈRE et 1 monstre TÉNÈBRES (cette carte exclue) depuis votre main et/ou Cimetière; Invoquez Spécialement cette carte depuis votre Cimetière, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Chef du Chaos, le Dragon Magique Chaotique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Sélectionner une carte à ajouter à la main ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3048768,'Angello Vaalmonica',replace(replace('Échelle Pendule = 3\r\n[ Effet Pendule ]\r\nChaque fois que vous gagnez des LP tant que vous contrôlez une Carte Monstre Démon dans votre autre Zone Pendule, placez 1 Compteur Résonance sur cette carte. \r\nUne fois par tour, lorsqu''un monstre de l''adversaire déclare une attaque, vous pouvez: immédiatement après la résolution de cet effet, Invoquez par Lien 1 Monstre Lien "Vaalmonica".\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est dans votre main: vous pouvez défausser 1 autre carte; prenez 1 "Dimonno Vaalmonica" depuis votre Deck, et placez cette carte et la carte dans vos Zones Pendule. \r\nDurant votre Main Phase, si cette carte a été Invoquée Normalement ou Spécialement ce tour: vous pouvez bannir 1 Magie Normale/Piège Normal "Vaalmonica" depuis votre Cimetière; appliquez un effet de la carte qui inclut un gain de LP. \r\nVous ne pouvez utiliser chaque effet de "Angello Vaalmonica" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Placer cette carte et "Dimonno Vaalmonica" depuis votre Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055018,'Obsidim, la Cité Cendrée',replace(replace('Les monstres face recto Invoqués Spécialement contrôlés par votre adversaire deviennent Pyro durant votre tour uniquement. \r\nVous ne pouvez utiliser chacun des effets suivants de "Obsidim, la Cité Cendrée" qu''une fois par tour. \r\nDurant votre End Phase: vous pouvez cibler 1 "Obsidim, la Cité Cendrée" dans votre Cimetière; placez-le au-dessous de votre Deck, puis piochez 1 carte. \r\nSi cette carte dans la Zone Terrain est détruite ou bannie: vous pouvez Invoquer Spécialement 1 monstre "Cendré" depuis votre Deck.','\r',char(13)),'\n',char(10)),'','Récupérer et piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055837,'Piège du Tampon Effaceur',replace(replace('Lorsqu''un effet qui inflige des dommages aux Life Points est activé (exceptés les dommages de combat), annulez les dommages infligés à vos Life Points. \r\nVotre adversaire sélectionne ensuite 1 carte de sa main et la défausse.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3056267,'Usurpatrice du Trône',replace(replace('FLIP: Sélectionnez 1 monstre de votre adversaire et échangez-le avec celui-ci. \r\nCette effet ne peut pas être Activé durant la Battle Phase.','\r',char(13)),'\n',char(10)),'Échanger le contrôle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064425,'Canon Détonâme Samouraï Supralourd',replace(replace('Vous pouvez cibler 1 monstre "Samouraï Supralourd" que vous contrôlez; équipez ce monstre depuis votre main ou votre Terrain à la cible. \r\nIl gagne 1000 DEF. \r\nDurant la Battle Phase de chaque joueur, lorsque votre adversaire active un effet de carte tant que vous contrôlez un monstre "Samouraï Supralourd" en Position de Défense: vous pouvez bannir cette carte depuis votre Cimetière; annulez l''activation, et si vous le faites, détruisez-la, puis détruisez autant de monstres sur le Terrain que possible (min. 1), et si vous le faites, chaque joueur reçoit 1000 points de dommages.','\r',char(13)),'\n',char(10)),'Équiper à un monstre "Samouraï Supralourd"','Annuler et détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064783,'Horreur de l''Ombre de l''Étincelle',replace(replace('Si vous Invoquez Normalement ou Spécialement un ou plusieurs monstres "Horreur de l''Ombre" et/ou Monstres Xyz "Mascarade": vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, piochez 1 carte, puis si vous avez pioché un monstre "Horreur de l''Ombre", vous pouvez l''Invoquer Spécialement.\r\nCette carte peut être traitée comme 2 Matériels pour l''Invocation Xyz d''un Monstre Xyz "Numéro" qui nécessite min. 3 Matériels.\r\nVous ne pouvez utiliser chaque effet de "Horreur de l''Ombre de l''Étincelle" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3070049,'Dragon de Neige','Lorsque cette carte est détruite au combat ou par un effet de carte, et envoyée au Cimetière: placez 1 Compteur Glace sur chaque monstre face recto sur le Terrain.','Placer un marqueur','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072077,'Retour du Zombie',replace(replace('Durant votre Standby Phase: vous pouvez payer 500 Life Points; ajoutez cette carte depuis votre Cimetière à votre main. \r\nVous ne devez avoir aucune carte dans votre main pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072808,'Aile Noire - Hillen le Vent de Tengu',replace(replace('Lorsque vous recevez 2000 ou plus de dommages de combat lors d''une attaque directe d''un monstre de votre adversaire quand cette carte est dans le Cimetière, sélectionnez 1 monstre "Aile Noire" de Niveau 3 ou moins dans votre Cimetière. \r\nInvoquez Spécialement ce monstre et cette carte depuis le Cimetière. \r\nLeurs effets sont annulés. \r\nChaque joueur ne peut utiliser l''effet de "Aile Noire - Hillen le Vent de Tengu" qu''une fois par Duel.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078380,'Timée le Dragon Uni',replace(replace('Vous pouvez envoyer 1 monstre Magicien, ou 1 Magie/Piège qui mentionne "Magicien Sombre", depuis votre main ou Terrain face recto au Cimetière; Invoquez Spécialement cette carte depuis votre main. \r\nDurant votre Main Phase: vous pouvez Invoquer par Fusion 1 Monstre Fusion depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain comme Matériel (un monstre Magicien inclus). \r\nVous ne pouvez utiliser chaque effet de "Timée le Dragon Uni" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078576,'Yata-Garasu',replace(replace('Non Invocable Spécialement. \r\nDurant la End Phase du tour où cette carte a été Invoquée Normalement ou retournée face recto: renvoyez-la à la main. \r\nSi cette carte inflige des dommages de combat à votre adversaire: sautez la Draw Phase de son prochain tour.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','Sautez votre prochaine Phase de Pioche','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3084730,'Bio-Armure d''Insecte',replace(replace('Si cette carte est dans votre main ou Cimetière et que vous ne contrôlez pas "Bio-Armure d''Insecte": vous pouvez cibler 1 monstre Insecte que vous contrôlez; équipez-lui cette carte, mais bannissez-le lorsqu''il quitte le Terrain, et aussi, bannissez cette Carte d''Équipement lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser cet effet de "Bio-Armure d''Insecte" qu''une fois par tour. \r\nLe monstre équipé gagne 1500 ATK/2000 DEF uniquement durant la Battle Phase et Main Phase 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3096468,'Tatsunécro',replace(replace('Si ce monstre Invoqué/Posé Normalement va être utilisé comme Matériel Synchro, 1 monstre dans votre main peut être utilisé comme 1 des autres Matériels. \r\nSi vous faites ça, tous les Matériels pour l''Invocation sont bannis au lieu d''être envoyés au Cimetière. \r\nVous ne pouvez pas Invoquer Spécialement de monstres (monstres Zombie exclus).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3103067,'Arme Redirectrice d''Attaque',replace(replace('Lorsqu''un monstre déclare une attaque: activez 1 de ces effets;\r\n● Détruisez le monstre attaquant.\r\n● Ciblez 1 monstre sur l''un des Terrains (le monstre attaquant exclu); transférez-lui la cible de l''attaque et faites le calcul des dommages.	\r\nVous ne pouvez activer qu''1 "Arme Redirectrice d''Attaque" par tour.','\r',char(13)),'\n',char(10)),'Détruire le monstre attaquant','Changer la cible de l''attaque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3105404,'Étincelle Brillante',replace(replace('Si un ou plusieurs monstres "Chevalier-Gemmes" face recto que vous contrôlez sont détruits par une attaque ou effet de carte de votre adversaire: ciblez 1 de ces monstres détruits; infligez des dommages à votre adversaire égaux à son ATK d''origine. \r\nSi cette carte est dans votre Cimetière: vous pouvez envoyer 1 carte "Chevalier-Gemmes" depuis votre main au Cimetière; ajoutez cette carte à votre main. \r\nVous ne pouvez activer qu''1 "Étincelle Brillante" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3111207,'Dragon Lappis',replace(replace('Si cette carte est ajoutée depuis le Deck à votre main: vous pouvez révéler cette carte; Invoquez-la Spécialement. \r\nSi cette carte est ajoutée depuis votre Cimetière à votre main par un effet de carte: vous pouvez révéler cette carte; Invoquez Spécialement cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser qu''1 effet de "Dragon Lappis" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113667,'Heavy Metal Raiders',replace(replace('La première fois que chaque monstre TÉNÈBRES Machine que vous contrôlez va être détruit au combat chaque tour, il n''est pas détruit, et si vous avez reçu des dommages de combat du combat, il gagne autant d''ATK après le calcul des dommages, et garde ce gain d''ATK tant que cette carte est sur le Terrain. \r\nUne fois par tour, si un monstre que vous contrôlez qui était TÉNÈBRES Machine à l''origine détruit une ou plusieurs cartes sur le Terrain au combat ou par un effet de carte: vous pouvez Invoquer Spécialement 1 monstre TÉNÈBRES Machine depuis votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113836,'Séraphinite, Chevalier-Gemmes',replace(replace('1 monstre "Chevalier-Gemmes" + 1 monstre LUMIÈRE	\r\nDoit d''abord être Invoquée par Fusion avec les Matériels Fusion ci-dessus. \r\nDurant votre Main Phase, vous pouvez Invoquer/Poser Normalement 1 monstre en plus de votre Invocation/Pose Normale. \r\n(Vous ne pouvez gagner cet effet qu''une fois par tour.)','\r',char(13)),'\n',char(10)),'Invoquer par l''effet de "Séraphinite, Chevalier-Gemmes"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3117804,'Grand Benkei Samouraï Supralourd',replace(replace('Lorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez changer sa position de combat. \r\nLes monstres "Samouraï Supralourd" que vous contrôlez peuvent attaquer tant qu''ils sont en Position de Défense face recto. \r\nS''ils le font, appliquez leur DEF pour le calcul des dommages.','\r',char(13)),'\n',char(10)),'Changer la position de combat','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3121655,'Robot Dragoprise',replace(replace('Si vous contrôlez un Monstre Synchro, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Robot Dragoprise" qu''une fois par tour de cette façon. \r\nLorsqu''un Monstre Synchro que vous contrôlez déclare une attaque: vous pouvez bannir cette carte depuis votre Cimetière; jusqu''à la fin de ce tour, le monstre que vous contrôlez gagne 800 ATK. \r\nVous ne pouvez utiliser cet effet de "Robot Dragoprise" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129133,'Delta d''Invitation',replace(replace('Lorsque cette carte est activée: vous pouvez envoyer 1 monstre Zombie de min. Niveau 5 depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser chacun des effets suivants de "Delta d''Invitation" qu''une fois par tour. \r\nSi un monstre Zombie est sur le Terrain: vous pouvez Invoquer Spécialement 1 "Jeton Delta" (Zombie/TÉNÈBRES/Niveau 5/ATK 0/DEF 0). \r\nSi un ou plusieurs monstres sont ajoutés depuis le Cimetière à la main, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez ajouter cette carte à votre main. \r\nVous ne pouvez activer qu''1 "Delta d''Invitation" par tour.','\r',char(13)),'\n',char(10)),'Activer','Invocation Spéciale','Ajouter à la main','Envoyer la carte au Cimetière ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129134,'Jeton Delta','Invoqué Spécialement avec l''effet de "Delta d''Invitation".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129527,'Bouc Émissaire Endormi',replace(replace('Invoquez Spécialement max. 4 "Jeton Bouc Émissaire" (Bête/TERRE/Niveau 1/ATK 0/DEF 0) en Position de Défense, puis si votre adversaire contrôle un monstre, vous pouvez Invoquer Spécialement 1 "Guerrier Panthère Rapide" depuis votre Deck, et aussi, le reste de ce tour, les Jetons ne peuvent pas être Sacrifiés pour une Invocation Sacrifice, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Fusion exclus) depuis l''Extra Deck.\r\nSi une ou plusieurs cartes que vous contrôlez qui mentionnent "Magicien du Temps des Ténèbres" vont être détruites au combat ou par un effet de carte, vous pouvez détruire 1 Jeton que vous contrôlez qui a été Invoqué Spécialement par cet effet à la place.','\r',char(13)),'\n',char(10)),'Activer','Sélectionnez le nombre d''Invocations Spéciales','Invoquer Spécialement {CARD} ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129528,'Jeton Bouc Émissaire',replace(replace('Invoqué Spécialement par l''effet de « Bouc Émissaire Endormi ». \r\nSi une carte sur votre Terrain dont le nom contient « Magicien du Temps des Ténèbres » va être détruite au combat ou par un effet de carte, vous pouvez détruire cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129529,'Jeton Bouc Émissaire',replace(replace('Invoqué Spécialement par l''effet de « Bouc Émissaire Endormi ». \r\nSi une carte sur votre Terrain dont le nom contient « Magicien du Temps des Ténèbres » va être détruite au combat ou par un effet de carte, vous pouvez détruire cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129530,'Jeton Bouc Émissaire',replace(replace('Invoqué Spécialement par l''effet de « Bouc Émissaire Endormi ». \r\nSi une carte sur votre Terrain dont le nom contient « Magicien du Temps des Ténèbres » va être détruite au combat ou par un effet de carte, vous pouvez détruire cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129531,'Jeton Bouc Émissaire',replace(replace('Invoqué Spécialement par l''effet de « Bouc Émissaire Endormi ». \r\nSi une carte sur votre Terrain dont le nom contient « Magicien du Temps des Ténèbres » va être détruite au combat ou par un effet de carte, vous pouvez détruire cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129635,'Malédiction Tiki',replace(replace('Invoquez Spécialement cette carte comme un Monstre à Effet (Type Rocher/TÉNÈBRES/Niveau 4/ATK 1800/DEF 1000).	\r\n(Cette carte est toujours aussi une Carte Piège.) \r\nTant que cette carte est un Monstre à Effet, si une autre Carte Piège qui est un monstre combat un monstre de votre adversaire, après le calcul des dommages: détruisez le monstre de votre adversaire.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134241,'Kamakiri Volant N°2','Cette mante volante se nourrit essentiellement d''insectes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134857,'Orcustrion',replace(replace('2+ Monstres à Effet (un monstre "Orcust" inclus)	\r\nCette carte liée ne peut être détruite ni au combat ni par des effets de carte. \r\nVous pouvez cibler 3 de vos monstres Machine bannis; mélangez-les dans le Deck, et si vous le faites, l''ATK/DEF des monstres liés actuellement contrôlés par votre adversaire deviennent 0, et aussi, leurs effets sont annulés. \r\nVous ne pouvez utiliser cet effet de "Orcustrion" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3136426,'Limite de Niveau - Zone B','Changez tous les monstres de min. Niveau 4 face recto en Position de Défense.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3137279,'Ixeep, Présage du Ghoti',replace(replace('Si un ou plusieurs monstres Poisson sont bannis (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nDurant la Standby Phase du prochain tour après que cette carte a été bannie: vous pouvez cibler 1 de vos Pièges "Ghoti" qui est banni ou dans votre Cimetière; Posez la cible. \r\nVous ne pouvez utiliser chaque effet de "Ixeep, Présage du Ghoti" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3146695,'Réacteur Psychique',replace(replace('Si vous contrôlez un monstre de Type Psychique: le reste de ce tour, appliquez cet effet à tous les monstres Type Psychique que vous contrôlez actuellement. \r\nLorsqu''un monstre de Type Psychique que vous contrôlez combat un monstre de votre adversaire, après le calcul des dommages: bannissez le monstre de Type Psychique, et aussi, bannissez le monstre de votre adversaire.','\r',char(13)),'\n',char(10)),'Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149401,'Dragon de la Fierté et de l''Âme Ultime',replace(replace('3 monstres avec 2500 ATK/DEF d''origine	\r\nTant que vous contrôlez cette carte Invoquée par Fusion, votre adversaire ne peut pas la cibler avec des effets de carte, et aussi, elle ne peut pas être détruite par des effets de carte de votre adversaire. \r\nTant que vous avez min. 25 cartes dans votre Cimetière, cette carte Invoquée par Fusion gagne 4500 ATK/DEF. \r\nUne fois par tour, si votre adversaire a min. 25 cartes dans son Cimetière: vous pouvez détruire toutes les cartes contrôlées par votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149764,'Masque de Tutan','Lorsqu''une Carte Magie/Piège qui cible exactement 1 monstre Zombie sur le Terrain (et aucune autre carte) est activée: annulez l''activation, et si vous le faites, détruisez-la.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3160805,'Échange de Jour et Nuit',replace(replace('Vous ne pouvez utiliser qu''1 effet de "Échange de Jour et Nuit" par tour, et uniquement une fois le tour. \r\nVous pouvez activer 1 de ces effets;\r\n● Envoyez 1 monstre LUMIÈRE de Type Guerrier depuis votre main au Cimetière, puis ajoutez 1 monstre TÉNÈBRES de Type Guerrier du même Niveau que le monstre envoyé avait dans votre main, depuis votre Deck à votre main.\r\n● Envoyez 1 monstre TÉNÈBRES de Type Guerrier depuis votre main au Cimetière, puis ajoutez 1 monstre LUMIÈRE de Type Guerrier du même Niveau que le monstre envoyé avait dans votre main, depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Activer l''effet','Utiliser l''effet de "Échange de Jour et Nuit" maintenant ?','Envoyer 1 monstre LUMIÈRE au Cimetière, ajouter 1 monstre TÉNÈBRES à la main','Envoyer 1 monstre TÉNÈBRES au Cimetière, ajouter 1 monstre LUMIÈRE à la main','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167439,'Châtiment du Monde Ténébreux',replace(replace('Lorsqu''un ou plusieurs monstres vont être Invoqués Normalement ou Spécialement: vous pouvez annuler l''Invocation, et si vous le faites, détruisez ces monstres, puis défaussez 1 monstre Démon. \r\nSi un ou plusieurs monstres "Monde Ténébreux" que vous contrôlez vont être détruits au combat ou par un effet de carte de l''adversaire, vous pouvez bannir cette carte depuis votre Cimetière à la place. \r\nVous ne pouvez utiliser chaque effet de "Châtiment du Monde Ténébreux" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167573,'Roi des Poupées',replace(replace('Lorsque votre adversaire ajoute une ou plusieurs Cartes Monstre à sa main, excepté en les piochant, vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi vous le faites, détruisez-la durant la End Phase de votre prochain tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3170832,'Takuhee','Cet oiseau est réputé pour être un présage funeste.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3171055,'Dissipation en Chaîne','Lorsqu''une Carte Magie/Piège est activée: détruisez toutes les cartes dans le Deck du contrôleur du même nom que la carte activée.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3204467,'Ver - Solide',replace(replace('Cette carte gagne 100 points de DEF pour chaque monstre "Ver" de Type Reptile dans votre Cimetière. \r\nSi votre adversaire subit des dommages de combat en attaquant cette carte, sélectionnez 1 Carte Magie ou Piège contrôlée par votre adversaire à la fin de la Damage Step, et détruisez-la.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3211439,'Apocryphes Interdites','Déclarez 1 type de carte de monstre (Fusion, Synchro ou Xyz); si min. 2 monstres du type déclaré sont sur le Terrain, faites envoyer chaque joueur tous les monstres de ce type depuis leur Terrain au Cimetière.','Fusion','Synchro','Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3233859,'Maniroue Psychique',replace(replace('Si vous contrôlez un monstre de Niveau 3 ("Maniroue Psychique" exclu), vous pouvez Invoquer Spécialement cette carte (depuis votre main) en Position de Défense. \r\nVous ne pouvez Invoquer Spécialement "Maniroue Psychique" qu''une fois par tour de cette façon. \r\nSi cette carte est envoyée au Cimetière comme Matériel Synchro: vous pouvez cibler 1 monstre sur le Terrain avec une ATK inférieure à celle du Monstre Synchro qui a utilisé cette carte comme Matériel; détruisez-le. \r\nVous ne pouvez utiliser cet effet de "Maniroue Psychique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3244563,'Lance-Bouclier','Ciblez 1 monstre face recto sur le Terrain; jusqu''à la fin de ce tour, il gagne 400 ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3248469,'Aspirante Abeille !',replace(replace('Durant la End Phase: vous pouvez envoyer cette carte depuis votre main ou Terrain au Cimetière; dévoilez un nombre de cartes du dessus de votre Deck, égal au nombre de Zones Magie & Piège inutilisées de votre adversaire, et vous pouvez Poser 1 Piège dévoilé sur votre Terrain (mais envoyez-le au Cimetière durant la prochaine End Phase), et aussi, placez les cartes restantes au-dessous du Deck dans l''ordre de votre choix. \r\nVous ne pouvez utiliser cet effet de "Aspirante Abeille !" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Poser 1 Carte Piège ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3259760,'Envoûtement','Jusqu''à la fin de ce tour, tous les monstres face recto actuellement contrôlés par votre adversaire ne peuvent être ni Sacrifiés ni utilisés comme Matériel pour une Invocation Fusion, Synchro, Xyz ou Lien.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3280747,'Sixième Sens',replace(replace('Déclarez 2 nombres de 1 à 6, puis votre adversaire lance un dé à six faces, et si le résultat est un des nombres que vous avez déclarés, vous piochez autant de cartes. \r\nSinon, envoyez un nombre de cartes du dessus de votre Deck au Cimetière égal au résultat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3283679,'Évoltile Lagosucho',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez envoyer 1 monstre "Évolsaure" depuis votre Deck au Cimetière. \r\nLorsque cette carte est retournée face recto: vous pouvez Invoquer Spécialement 1 monstre "Évoltile" depuis votre Deck.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285551,'Rite de l''Aramesir',replace(replace('Si vous ne contrôlez aucun "Jeton Aventurier": Invoquez Spécialement 1 "Jeton Aventurier" (Elfe/TERRE/Niveau 4/ATK 2000/DEF 2000), puis si vous ne contrôlez pas "Aventure Fatidique", vous pouvez placer 1 "Aventure Fatidique" depuis votre Deck face recto dans votre Zone Magie & Piège. \r\nVous ne pouvez pas activer les effets des monstres sur le Terrain (ceux des monstres Invoqués Spécialement exclus) le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Rite de l''Aramesir" par tour.','\r',char(13)),'\n',char(10)),'Placer "Aventure Fatidique" depuis votre Deck ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285552,'Jeton Aventurier','Invoqué Spécialement avec l''effet de "Rite de l''Aramesir".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3287359,'Caspar, Cerveau de la Magie de Mousquet',replace(replace('2 monstres (un monstre LUMIÈRE Démon inclus)	\r\nDurant le tour de chaque joueur, vous pouvez activer des Cartes Magie/Piège "Magie de Mousquet" depuis votre main. \r\nSi cette carte est Invoquée par Lien: vous pouvez prendre 2 cartes "Magie de Mousquet" (un monstre inclus) depuis votre main et/ou Deck, Invoquez-en Spécialement 1 monstre sur votre Terrain et Posez l''autre sur le Terrain de votre adversaire. \r\nVous ne pouvez utiliser cet effet de "Caspar, Cerveau de la Magie de Mousquet" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer','Activer en appliquant l''effet de "Caspar, Cerveau de la Magie de Mousquet".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3289027,'Parl, Ermite du Monde Ténébreux',replace(replace('Si cette carte est défaussée au Cimetière par un effet de carte: vous pouvez cibler 1 monstre "Monde Ténébreux" ("Parl, Ermite du Monde Ténébreux" exclu) dans votre Cimetière; Invoquez-le Spécialement sur l''un des Terrains, puis, si cette carte a été défaussée depuis votre main à votre Cimetière par un effet de carte de l''adversaire, vous pouvez Invoquer Spécialement, sur l''un des Terrains, 1 de vos monstres Démon qui est banni, ou dans votre main ou Cimetière. \r\nVous ne pouvez utiliser cet effet de "Parl, Ermite du Monde Ténébreux" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Invoquer Spécialement 1 monstre supplémentaire ?','Invocation Spéciale sur votre Terrain','Invocation Spéciale sur le Terrain de votre adversaire','','','','','','','','','','','','');
INSERT INTO texts VALUES(3292267,'Dragon Céleste Hiératique du Seigneur d''Héliopolis',replace(replace('2 monstres de Niveau 8	\r\nUne fois par tour, lorsque votre adversaire active une carte ou un effet qui cible une ou plusieurs cartes sur votre Terrain, dans votre Cimetière et/ou une ou plusieurs de vos cartes bannies (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''activation, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3294539,'Dragon aux Épées Cramoisi',replace(replace('1 Syntoniseur "Diapason" + 1+ non-Syntoniseur	\r\n(Cette carte est toujours traitée comme "Épéiste Cramoisi".)	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez prendre 1 monstre de min. Niveau 8 qui ne peut pas être Invoqué/Posé Normalement depuis votre Deck ou Cimetière, et soit ajoutez-le à votre main soit Invoquez-le Spécialement, mais annulez ses effets. \r\nVous ne pouvez utiliser cet effet de "Dragon aux Épées Cramoisi" qu''une fois par tour. \r\nAu début de la Damage Step, si cette carte combat un monstre de min. Niveau 5: vous pouvez détruire le monstre.','\r',char(13)),'\n',char(10)),'Effet d''ajout à la main','Effet de destruction','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3298689,'Les Chevaliers Fantômes du Lancement Magie-Rang-Plus',replace(replace('Durant la Main Phase: ciblez 1 Monstre Xyz TÉNÈBRES que vous contrôlez avec aucun Matériel; Invoquez Spécialement 1 Monstre Xyz TÉNÈBRES qui a 1 Rang de plus que le monstre que vous contrôlez depuis votre Extra Deck, en l''utilisant comme Matériel, et si vous le faites, attachez-lui cette carte comme Matériel supplémentaire. \r\n(Ceci est traité comme une Invocation Xyz. Transférez ses Matériels au monstre Invoqué.) \r\nDurant votre Main Phase: vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Monstre Xyz TÉNÈBRES que vous contrôlez; attachez 1 monstre "Les Chevaliers Fantômes" depuis votre main au monstre comme Matériel.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Matériel Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3300267,'Dragon Hiératique de Su',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en Sacrifiant 1 monstre "Hiératique". \r\nUne fois par tour: vous pouvez Sacrifier 1 monstre "Hiératique" (cette carte exclue) depuis votre main ou votre Terrain pour cibler 1 Carte Magie/Piège contrôlée par votre adversaire; détruisez la cible. \r\nLorsque cette carte est Sacrifiée: Invoquez Spécialement 1 Monstre Normal de Type Dragon depuis votre main, Deck ou Cimetière, et son ATK/DEF deviennent 0.','\r',char(13)),'\n',char(10)),'Détruire','Invocation Spéciale','Mode d''Invocation : Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3322931,'Vent Stellaire Wolfrayet',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nVous ne pouvez contrôler qu''1 "Vent Stellaire Wolfrayet". \r\nGagne 300 ATK chaque fois que l''effet d''un autre monstre est activé, tant que l''ATK de cette carte est inférieure à 4000. \r\nUne fois par tour, si l''ATK de cette carte est min. 4000 (Effet Rapide): vous pouvez mélanger cette carte ainsi que tous les monstres contrôlés par votre adversaire dans le Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3355732,'Kosmochlor Jadeglace',replace(replace('Si une carte face recto est dans une Zone Terrain, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Kosmochlor Jadeglace" qu''une fois par tour de cette façon. \r\nTant que "Berceau Enion de Cénote Jadeglace" est sur le Terrain, les monstres contrôlés par votre adversaire ne peuvent activer leurs effets que le tour où ils sont Invoqués. \r\nSi votre monstre "Jadeglace" combat un monstre de l''adversaire, le monstre de l''adversaire perd 1000 ATK durant ce calcul des dommages uniquement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3356494,'Dragon Fusolaire aux Yeux Galactiques',replace(replace('2 monstres LUMIÈRE (un monstre avec min. 2000 ATK inclus)	\r\nSi cette carte est Invoquée par Lien: vous pouvez cibler 1 monstre "Photon" ou "Galactique" dans votre Cimetière; ajoutez-le à votre main. \r\nDurant la Main Phase de votre adversaire (Effet Rapide): vous pouvez défausser 1 carte "Photon" et 1 carte "Galactique", OU défaussez 1 "Dragon Photon aux Yeux Galactiques", puis ciblez 1 monstre Invoqué Spécialement contrôlé par votre adversaire; détruisez-le. \r\nVous ne pouvez utiliser chaque effet de "Dragon Fusolaire aux Yeux Galactiques" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Défausser "Néo Dragon Photon aux Yeux Galactiques" ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3361010,'Kitsuni Kitsunebi',replace(replace('Tous les monstres face recto sur le Terrain deviennent FEU. \r\nSi votre adversaire a un monstre FEU sur son Terrain ou dans son Cimetière, tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte. \r\nVous ne pouvez utiliser cet effet de "Kitsuni Kitsunebi" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3366982,'Dragon du Glaive de l''Alligator',replace(replace('"Bébé Dragon" + "Glaive de l''Alligator"	\r\nCette carte peut attaquer directement votre adversaire s''il contrôle uniquement des monstres TERRE, EAU ou FEU face recto.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3370104,'Cyber Phœnix',replace(replace('Tant que cette carte est en Position d''Attaque, annulez les effets de Magie/Piège qui ciblent 1 monstre Machine que vous contrôlez (et aucune autre carte). \r\nLorsque cette carte est détruite au combat et envoyée au Cimetière: vous pouvez piocher 1 carte.','\r',char(13)),'\n',char(10)),'Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3376703,'Force Arcane V - Le Pape',replace(replace('Vous pouvez défausser cette carte; ce tour, votre adversaire ne peut activer ni de cartes ni d''effets lorsqu''un ou plusieurs monstres "Force Arcane" sont Invoqués sur votre Terrain. \r\nSi cette carte est Invoquée: lancez une pièce.\r\n● Face: Invoquez Spécialement 1 monstre "Force Arcane" de max. Niveau 4 depuis votre Deck de nom différent des monstres que vous contrôlez et dans votre Cimetière.\r\n● Pile: Invoquez Spécialement 1 monstre "Force Arcane" depuis votre Deck sur le Terrain de votre adversaire.','\r',char(13)),'\n',char(10)),'Votre adversaire ne peut pas activer d''effets','Invoquer Spécialement depuis le Deck','Face recto','Face verso','','','','','','','','','','','','');
INSERT INTO texts VALUES(3381441,'Prêtresse des Protecteurs du Tombeau',replace(replace('Tant qu''il n''y a aucune Magie de Terrain face recto, le Terrain est traité comme "Vallée Mortuaire". \r\nTous les monstres "Protecteurs du Tombeau" sur le Terrain gagnent 200 ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3395226,'Mozarta la Maestria de la Musique',replace(replace('Une fois par tour: vous pouvez Invoquer Spécialement 1 monstre LUMIÈRE de Type Elfe depuis votre main. \r\nVous ne pouvez pas Invoquer Spécialement d''autres monstres (monstres LUMIÈRE exclus) le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3405259,'Croc de la Vouivre C',replace(replace('Une fois par tour, vous pouvez SOIT: ciblez 1 monstre LUMIÈRE Machine que vous contrôlez; équipez cette carte à la cible, SOIT: déséquipez cette carte et Invoquez-la Spécialement. \r\nUn monstre équipé avec cette carte n''est pas affecté par les effets de Piège de votre adversaire, et aussi, si le monstre équipé va être détruit au combat ou par un effet de carte, détruisez cette carte à la place. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Union depuis votre main.','\r',char(13)),'\n',char(10)),'Équiper','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3410461,'Alba-Lenatus le Dragon des Abysses',replace(replace('"Albaz le Déchu" + 1+ monstre Dragon	\r\nNon utilisable comme Matériel Fusion. \r\nUniquement soit Invocable par Fusion soit Invocable Spécialement en envoyant les cartes ci-dessus depuis les Zones Monstre au Cimetière. \r\nPeut attaquer un nombre de fois des monstres chaque Battle Phase, inférieur ou égal au nombre de Matériels utilisés pour elle. \r\nUne fois par tour, durant la End Phase, si cette carte est dans le Cimetière parce qu''elle y a été envoyée ce tour: vous pouvez ajouter 1 Magie Normale "Polymérisation" ou Magie Normale "Fusion" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3422200,'Soufefnir Crystron',replace(replace('Si cette carte est dans votre main ou Cimetière: vous pouvez défausser 1 carte "Crystron" ("Soufefnir Crystron" exclu); Invoquez Spécialement cette carte en Position de Défense, puis détruisez 1 carte que vous contrôlez. \r\nSi cette carte sur le Terrain est détruite au combat ou par un effet de carte: vous pouvez Invoquer Spécialement 1 monstre "Crystron" depuis votre Deck en Position de Défense. \r\nVous ne pouvez utiliser chaque effet de "Soufefnir Crystron" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3428069,'Buster Blader, Maître de l''Épée Destructrice',replace(replace('Le nom de cette carte devient "Buster Blader" tant qu''elle est sur le Terrain ou dans le Cimetière. \r\nSi un ou plusieurs monstres contrôlés par votre adversaire sont détruits au combat ou par un effet de carte, et envoyés au Cimetière: vous pouvez cibler 1 de ces monstres détruits; équipez-le à cette carte. \r\nUne fois par tour: vous pouvez envoyer 1 Carte Monstre que vous contrôlez qui est équipée à cette carte au Cimetière; détruisez tous les monstres contrôlés par votre adversaire du même Type que le monstre envoyé au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3429238,'Guerrier Foreur',replace(replace('"Perceuse Synchronique" + 1+ monstre non-Syntoniseur	\r\nUne fois par tour, durant votre Main Phase 1: vous pouvez diviser par deux l''ATK de cette carte, et si vous le faites, elle peut attaquer directement votre adversaire ce tour. \r\nUne fois par tour: vous pouvez défausser 1 carte, et si vous le faites, bannissez cette carte. \r\nDurant votre prochaine Standby Phase: Invoquez Spécialement cette carte qui a été bannie par cet effet, puis ajoutez 1 monstre depuis votre Cimetière à votre main.','\r',char(13)),'\n',char(10)),'L''ATK devient la moitié','Bannir cette carte','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3431737,'Bête d''Assaut','Vous pouvez défausser cette carte au Cimetière; ajoutez 1 "Activation Mode Assaut" depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3434362,'Mammouth Rouilletainrable',replace(replace('Si cette carte est dans votre main: vous pouvez bannir un nombre de Monstres Lien Machine depuis votre Extra Deck dont la somme des Classifications Lien est égale à exactement 5; Invoquez Spécialement cette carte. \r\nVous pouvez cibler 1 carte que vous contrôlez et 1 carte contrôlée par votre adversaire; renvoyez-les à la main. \r\nCeci est un Effet Rapide si cette carte est liée à un Monstre Lien Machine de min. Link-3. \r\nVous ne pouvez utiliser chaque effet de "Mammouth Rouilletainrable" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Renvoyer à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3441553,'Destruction Chatoyante des Bêtes Sacrées',replace(replace('Activez 1 de ces effets;\r\n● Lorsque votre adversaire active une carte ou un effet en réponse à l''activation de votre activation d''effet de monstre "Bête Sacrée": annulez l''effet de l''adversaire.\r\n● Révélez 1 monstre "Bête Sacrée" de Niveau 10 dans votre main; défaussez 1 carte, et si vous le faites, ajoutez 1 "Porte des Illusions" depuis votre Deck à votre main.\r\n● Mélangez 3 Pièges "Bête Sacrée" depuis votre Cimetière et/ou bannissement dans le Deck, puis ciblez 1 carte contrôlée par votre adversaire; détruisez-la.	\r\nVous ne pouvez activer qu''1 "Destruction Chatoyante des Bêtes Sacrées" par tour.','\r',char(13)),'\n',char(10)),'Activer','Annuler l''effet','Effet d''ajout à la main','Effet de destruction','','','','','','','','','','','','');
INSERT INTO texts VALUES(3461403,'Le Bushi Immortel Déplore le Corps Mortel',replace(replace('Tous les monstres dans votre Cimetière deviennent des monstres Guerrier. \r\nUne fois par tour, durant la End Phase: vous pouvez détruire tous les monstres que vous contrôlez.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3486020,'Yoko, Mayakashi de la Grâce',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nVous ne pouvez contrôler qu''1 "Yoko, Mayakashi de la Grâce". \r\nVous ne pouvez utiliser chacun de ces effets de "Yoko, Mayakashi de la Grâce" qu''une fois par tour.\r\n● Si un Monstre Synchro en votre possession, dont le Niveau d''origine est 11, est détruit au combat ou par un effet de carte de l''adversaire tant que cette carte est dans le Cimetière: vous pouvez bannir 1 autre monstre Zombie depuis votre Cimetière, et si vous le faites, Invoquez Spécialement cette carte.\r\n● Si cette carte est Invoquée Spécialement depuis le Cimetière: vous pouvez détruire 1 monstre contrôlé par votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3492538,'Armure d''Insecte avec Canon Laser',replace(replace('Équipable uniquement à un monstre Insecte. \r\nIl gagne 700 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493058,'Déphon',replace(replace('Lancez un dé à six faces et appliquez le résultat.\r\n● 2, 3 ou 4: Détruisez 1 Magie/Piège sur le Terrain.\r\n● 5: Détruisez 2 Magies/Pièges sur le Terrain.\r\n● 1 ou 6: Vous recevez 1000 points de dommages.','\r',char(13)),'\n',char(10)),'Lancer un dé','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493978,'Don Tortue','Lorsque cette carte est Invoquée avec succès par Invocation Normale ou Invocation Flip, vous pouvez faire l''Invocation Spéciale du nombre de votre choix de "Don Tortue" depuis votre main.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3496543,'Butin du Péché de la Forêt Blanche',replace(replace('Si vous contrôlez un monstre Démon, Illusion ou Magicien: activez 1 de ces effets;\r\n● Invoquez Spécialement 1 monstre Démon, Illusion ou Magicien depuis votre main.\r\n● Invoquez par Fusion 1 Monstre Fusion depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain.	\r\nSi cette carte est envoyée au Cimetière pour activer un effet de monstre: vous pouvez Poser cette carte.\r\nVous ne pouvez utiliser chaque effet de "Butin du Péché de la Forêt Blanche" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer l''effet','Poser','Invoquer Spécialement depuis la main','Invocation Fusion','','','','','','','','','','','','');
INSERT INTO texts VALUES(3507053,'Canard Séchoir Électroménageur',replace(replace('1 monstre "Électroménageur"	\r\nNon utilisable comme Matériel Lien le tour où elle est Invoquée par Lien. \r\nCette carte liée gagne 1000 ATK. \r\nUne fois par tour, durant votre Battle Phase, si cette carte est co-liée (sauf durant la Damage Step): vous pouvez échanger la position de 2 monstres "Électroménageur" dans vos Zones Monstre Main (cette carte incluse), et si vous le faites, l''autre monstre peut faire une seconde attaque durant chaque Battle Phase ce tour. \r\nUne fois par tour, lorsque cette carte qui n''est pas co-liée est ciblée avec une attaque: vous pouvez annuler l''attaque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3510565,'Oiseau Furtif',replace(replace('Une fois par tour: vous pouvez changer cette carte en Position de Défense face verso. \r\nLorsque cette carte est Invoquée par Flip: infligez 1000 points de dommages à votre adversaire.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face verso','Infligez 1000 points de dommages à votre adversaire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3519195,'Assaut Maléfique',replace(replace('Défaussez 1 carte; prenez 1 monstre "HÉROS du Mal" de max. Niveau 4 depuis votre Deck, et soit ajoutez-le à votre main soit Invoquez-le Spécialement, et aussi, le reste de ce tour après la résolution de cette carte, vous ne pouvez pas Invoquer Spécialement (monstres "HÉROS" exclus) depuis l''Extra Deck. \r\nSi cette carte est dans votre Cimetière, sauf le tour où elle y a été envoyée: vous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 "Fusion des Ténèbres" depuis votre Cimetière à votre main. \r\nVous ne pouvez utiliser chaque effet de "Assaut Maléfique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Recycler','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3534077,'Wolfbark Soldat Entraîneur',replace(replace('Vous pouvez cibler 1 monstre FEU Bête-Guerrier de Niveau 4 dans votre Cimetière; Invoquez-le Spécialement en Position de Défense, mais annulez ses effets. \r\nVous ne pouvez utiliser cet effet de "Wolfbark Soldat Entraîneur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3536537,'Zahak Colonie du Mal','Si cette carte face recto que vous contrôlez est détruite par une carte de votre adversaire (au combat ou par un effet de carte) et envoyée à votre Cimetière: ciblez 1 monstre Invoqué Spécialement de min. Niveau 5 sur le Terrain; détruisez la cible.','Détruire un monstre','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3544583,'Allvain l''Essence de la Vanité','2 Monstres Normaux','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3549275,'Jarre Dés',replace(replace('FLIP: Chaque joueur lance un dé à six faces. \r\nLe joueur avec le résultat le plus faible reçoit des dommages égaux au résultat de son adversaire x 500. \r\nCependant, si le résultat du gagnant est 6, le perdant reçoit 6000 points de dommages. \r\nSi les résultats sont les mêmes, chaque joueur relance le dé.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3557275,'Poussièron Blanc','Le plus fier des Poussièrons.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3560069,'Latence',replace(replace('Si cette carte est ajoutée depuis votre Cimetière à votre main par un effet de carte: vous pouvez l''Invoquer Spécialement depuis votre main. \r\nSi cette carte Invoquée de cette façon est envoyée au Cimetière comme Matériel Lien: vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser chaque effet de "Latence" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3567660,'Recul Lien',replace(replace('Ciblez 1 Monstre Lien que vous contrôlez dans la Zone Monstre Extra; déplacez le monstre que vous contrôlez dans votre Zone Monstre Main qu''il pointe, puis, vous pouvez envoyer un nombre de cartes du dessus de votre Deck au Cimetière égal à sa Classification Lien. \r\nVous ne pouvez activer qu''1 "Recul Lien" par tour.','\r',char(13)),'\n',char(10)),'Déplacer vers une autre Zone','Sélectionnez une carte à déplacer','Envoyer une carte de votre Deck au Cimetière ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3573512,'Le Spadassin de Landstar','Loin d''être brillant à l''épée, ce guerrier féerique compte surtout sur ses mystérieux pouvoirs.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3574681,'Règle d''Or',replace(replace('(Cette carte est toujours traitée comme une carte "Cristal".)	\r\nPlacez face recto 2 monstres "Bête Cristalline" depuis votre Deck dans votre Zone Magie & Piège comme Magies Continues, puis Invoquez Spécialement 1 monstre "Bête Cristalline" depuis votre main ou Cimetière de nom différent de ces cartes, et si vous le faites, équipez-le avec cette carte. \r\nLorsque cette carte quitte le Terrain, détruisez le monstre. \r\nVous ne pouvez activer qu''1 "Règle d''Or" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3576031,'Potentiel Crystolique',replace(replace('Tous les monstres "Crystron" que vous contrôlez gagnent 300 ATK/DEF. \r\nUne fois par tour, durant la End Phase: vous pouvez piocher un nombre de cartes égal au nombre de Monstres Synchro "Crystron" que vous avez Invoqués par Synchronisation ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3580032,'Merlin',replace(replace('Vous ne pouvez utiliser chaque effet de "Merlin" qu''une fois par tour.\r\n● Vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 monstre "Chevalier Noble" depuis votre Deck.	\r\nVous ne pouvez pas Invoquer Spécialement de monstres (monstres "Chevalier Noble" exclus) le tour où vous activez cet effet.\r\n● (Effet Rapide): vous pouvez bannir cette carte depuis votre Cimetière; immédiatement après la résolution de cet effet, Invoquez par Synchronisation 1 Monstre Synchro "Chevalier Noble" en utilisant des monstres que vous contrôlez.\r\n● (Effet Rapide): vous pouvez bannir cette carte depuis votre Cimetière; immédiatement après la résolution de cet effet, Invoquez par Xyz 1 Monstre Xyz "Chevalier Noble" en utilisant des monstres que vous contrôlez.','\r',char(13)),'\n',char(10)),'Invoquer par Synchro 1 Monstre Synchro "Chevalier Noble"','Invoquer par Xyz 1 Monstre Xyz "Chevalier Noble"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3594985,'Draco Majesspectre - Ryu',replace(replace('Échelle Pendule = 5\r\n[ Effet Pendule ]\r\nSi vous avez une carte "Majesspectre" ou "Dracossassin" dans votre autre Zone Pendule: vous pouvez ajouter 1 carte "Majesspectre" depuis votre Deck à votre main, puis vous pouvez détruire 1 carte dans votre Zone Pendule. \r\nVous ne pouvez utiliser cet effet de "Draco Majesspectre - Ryu" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\n2 monstres de Niveau 4	\r\nSi vous pouvez Invoquer par Pendulation de Niveau 4, vous pouvez Invoquer par Pendulation cette carte face recto depuis votre Extra Deck. \r\nSi un ou plusieurs monstres sont Sacrifiés tant que cette carte est sur le Terrain (sauf durant la Damage Step): vous pouvez détacher 1 Matériel de cette carte; Invoquez Spécialement 1 monstre VENT Magicien de max. Niveau 6 depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Draco Majesspectre - Ryu" que max. deux fois par tour. \r\nSi cette carte dans la Zone Monstre est détruite au combat ou par un effet de carte, ou Sacrifiée: vous pouvez placer cette carte dans votre Zone Pendule.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Invoquer Spécialement depuis le Deck','Placer dans la Zone Pendule','Détruire 1 carte dans votre Zone Pendule ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3598351,'Bubble Toxique, HÉROS du Mal',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main), mais vous ne pouvez pas Invoquer Spécialement (monstres "HÉROS" exclus) le reste de ce tour. \r\nVous ne pouvez Invoquer Spécialement "Bubble Toxique, HÉROS du Mal" qu''une fois par tour de cette façon. \r\nSi cette carte est Invoquée Spécialement, et que vous contrôlez un Monstre Fusion qui doit être Invoqué Spécialement avec "Fusion des Ténèbres": vous pouvez piocher 2 cartes. \r\nVous ne pouvez utiliser cet effet de "Bubble Toxique, HÉROS du Mal" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3603242,'Déchiqueteur','Une fois par tour: vous pouvez envoyer 1 monstre de Type Machine depuis votre main au Cimetière, puis ciblez 1 monstre contrôlé par votre adversaire d''un Niveau inférieur ou égal à celui du monstre envoyé; détruisez la cible.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606209,'Chasseur d''esprits','Cette dangereuse créature brandit une épée avaleuse d''âmes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606728,'Fille Gagaga',replace(replace('Vous pouvez cibler 1 "Magicien Gagaga" que vous contrôlez; le Niveau de cette carte devient le Niveau actuel du monstre. \r\nUn Monstre Xyz qui a été Invoqué en utilisant uniquement cette carte et d''autres monstres "Gagaga" comme Matériel gagne cet effet.\r\n● Lorsqu''il est Invoqué par Xyz: vous pouvez cibler 1 monstre Invoqué Spécialement contrôlé par votre adversaire; son ATK devient 0.','\r',char(13)),'\n',char(10)),'Changer le Niveau','L''ATK devient 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606729,'Fille Gagaga',replace(replace('Vous pouvez cibler 1 "Magicien Gagaga" que vous contrôlez; le Niveau de cette carte devient le Niveau actuel du monstre. \r\nUn Monstre Xyz qui a été Invoqué en utilisant uniquement cette carte et d''autres monstres "Gagaga" comme Matériel gagne cet effet.\r\n● Lorsqu''il est Invoqué par Xyz: vous pouvez cibler 1 monstre Invoqué Spécialement contrôlé par votre adversaire; son ATK devient 0.','\r',char(13)),'\n',char(10)),'Changer le Niveau','L''ATK devient 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3611830,'Endymion, le Puissant Maître de Magie',replace(replace('Échelle Pendule = 8\r\n[ Effet Pendule ]\r\nVous pouvez retirer 6 Compteurs Magie depuis votre Terrain; Invoquez Spécialement cette carte depuis la Zone Pendule, puis comptez le nombre de cartes que vous contrôlez qui peuvent avoir un Compteur Magie, détruisez max. autant de cartes sur le Terrain, et si vous le faites, placez un nombre de Compteurs Magie sur cette carte égal au nombre de cartes détruites. \r\nVous ne pouvez utiliser cet effet de "Endymion, le Puissant Maître de Magie" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nUne fois par tour, lorsqu''une Carte Magie/Piège ou effet de Magie/Piège est activé (Effet Rapide): vous pouvez renvoyer 1 carte que vous contrôlez avec un Compteur Magie à la main, et si vous le faites, annulez l''activation, et si vous faites ça, détruisez-la. \r\nPuis, vous pouvez placer le même nombre de Compteurs Magie que la carte renvoyée avait sur cette carte. \r\nTant que cette carte a un Compteur Magie, votre adversaire ne peut pas la cibler avec des effets de carte, et aussi, elle ne peut pas être détruite par des effets de carte de votre adversaire. \r\nLorsque cette carte avec un Compteur Magie est détruite au combat: vous pouvez ajouter 1 Magie Normale depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','Placer un Compteur Magie ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3627449,'Gardien du Crâne',replace(replace('Ce monstre ne peut être Invoqué que par Invocation Rituelle avec la Carte Magie Rituelle, "La Prière de Novox". \r\nVous devez également sacrifier des monstres dont le total des Niveaux est égal à 7 ou plus du Terrain ou de votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3629090,'Idaten Ange Cyber',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Rituel de l''Ange Machine". \r\nSi cette carte est Invoquée Rituellement: vous pouvez ajouter 1 Magie Rituelle depuis votre Deck ou Cimetière à votre main. \r\nSi cette carte est Sacrifiée: vous pouvez faire gagner 1000 ATK/DEF à tous les Monstres Rituels que vous contrôlez.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3635138,'Émissaires des Ténèbres',replace(replace('Si vous recevez des dommages de combat ou d''effet: vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, gagnez 2000 LP, puis vous pouvez appliquer 1 de ces effets.\r\n● Invoquez Spécialement 1 "Émissaires des Ténèbres" depuis votre main, Deck ou Cimetière.\r\n● Détruisez max. 2 monstres en Position d''Attaque contrôlés par votre adversaire.	\r\nDurant la End Phase, si cette carte a été Invoquée Spécialement ce tour: vous pouvez cibler 1 Piège dans votre Cimetière; Posez-le.\r\nVous ne pouvez utiliser chaque effet de "Émissaires des Ténèbres" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Poser un Piège','Invocation Spéciale','Effet de destruction','Ne rien faire','','','','','','','','','','','');
INSERT INTO texts VALUES(3635139,'Émissaires des Ténèbres',replace(replace('Si vous recevez des dommages de combat ou d''effet: vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, gagnez 2000 LP, puis vous pouvez appliquer 1 de ces effets.\r\n● Invoquez Spécialement 1 "Émissaires des Ténèbres" depuis votre main, Deck ou Cimetière.\r\n● Détruisez max. 2 monstres en Position d''Attaque contrôlés par votre adversaire.	\r\nDurant la End Phase, si cette carte a été Invoquée Spécialement ce tour: vous pouvez cibler 1 Piège dans votre Cimetière; Posez-le.\r\nVous ne pouvez utiliser chaque effet de "Émissaires des Ténèbres" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Poser un Piège','Invocation Spéciale','Effet de destruction','Ne rien faire','','','','','','','','','','','');
INSERT INTO texts VALUES(3642509,'Grande Tornade, HÉROS Élémentaire',replace(replace('1 monstre "HÉROS Élémentaire" + 1 monstre VENT	\r\nUniquement Invocable par Fusion et non Invocable Spécialement autrement. \r\nSi cette carte est Invoquée par Fusion: divisez par deux l''ATK/DEF de tous les monstres face recto actuellement contrôlés par votre adversaire.','\r',char(13)),'\n',char(10)),'Changer l''ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3643300,'Le Pêcheur Légendaire','Tant que "Umi" est sur le Terrain, cette carte n''est pas affectée par les effets de Magie et ne peut pas être ciblée par des attaques, mais elle n''empêche pas votre adversaire de vous attaquer directement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3648368,'Patrouilleur, Allié de la Justice',replace(replace('Une fois par tour: vous pouvez défausser 1 carte, puis ciblez 1 monstre en Position de Défense face verso contrôlé par votre adversaire; changez la cible en Position d''Attaque face recto. \r\n(Les effets de monstres Flip ne sont pas activés.)','\r',char(13)),'\n',char(10)),'Changer la position de combat','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3657444,'Nâga Cyber',replace(replace('Vous pouvez activer 1 de ces effets.\r\n● Lorsque cette carte est ciblée par une attaque: vous pouvez bannir cette carte; piochez 1 carte, puis terminez la Battle Phase.\r\n● Vous pouvez cibler 1 monstre face recto que vous contrôlez et cette carte; bannissez les deux cibles, puis piochez 2 cartes.\r\n● Vous pouvez cibler 1 carte dans votre Cimetière; bannissez cette carte ainsi qu''1 carte depuis votre main, puis placez la cible au-dessus du Deck.','\r',char(13)),'\n',char(10)),'Bannissez cette carte, piochez 1 carte et terminez la Battle Phase','Bannissez les autres monstres et cette carte, puis piochez 2 cartes','Bannissez des cartes de votre main et cette carte, puis recyclez des cartes au Cimetière','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3659803,'Fusion en Surcharge','Invoquez par Fusion 1 Monstre Fusion TÉNÈBRES Machine depuis votre Extra Deck, en bannissant les Matériels Fusion mentionnés sur celui-ci depuis votre Terrain ou Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3679218,'Sirène, Chevalier du Cauchemar',replace(replace('1 monstre "Chevalier du Cauchemar" ("Sirène, Chevalier du Cauchemar" exclu)	\r\nSi cette carte est Invoquée par Lien: vous pouvez défausser 1 carte; Invoquez Spécialement 1 monstre "Chevalier du Cauchemar" depuis votre Deck, puis, si cette carte était co-liée lorsque cet effet a été activé, vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser cet effet de "Sirène, Chevalier du Cauchemar" qu''une fois par tour. \r\nLes monstres sur le Terrain perdent 1000 ATK/DEF, sauf s''ils sont co-liés.','\r',char(13)),'\n',char(10)),'','Piocher 1 carte ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3682106,'Double Piège','Sélectionnez 1 carte face recto sur le Terrain dont l''effet annule les effets des Cartes Piège et détruisez-la.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3685372,'Poupée Truquée Fanatix Machinix CXyz',replace(replace('3 monstres de Niveau 9	\r\nSi cette carte est Invoquée Spécialement: vous pouvez ajouter 1 Piège "Poupée" depuis votre Deck à votre main. \r\nVous pouvez détacher 1 Matériel de cette carte; Invoquez Spécialement 1 monstre depuis l''un des Cimetières sur le Terrain de votre adversaire en Position de Défense. \r\nSi un ou plusieurs monstres sont Invoqués Spécialement sur le Terrain de votre adversaire (sauf durant la Damage Step): vous pouvez en cibler 1; détruisez-le, et si vous le faites, infligez des dommages à votre adversaire égaux à la moitié de son ATK d''origine. \r\nVous ne pouvez utiliser chaque effet de "Poupée Truquée Fanatix Machinix CXyz" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invoquer Spécialement 1 monstre depuis l''un des Cimetières sur le Terrain de votre adversaire','Infliger des dommages','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3693034,'Hatago Karakuri',replace(replace('Ciblez 1 monstre "Karakuri" que vous contrôlez et 1 Monstre à Effet contrôlé par votre adversaire; changez la position de combat de votre monstre, et si vous le faites, annulez les effets du monstre de l''adversaire jusqu''à la fin de ce tour. \r\nSi vous contrôlez un ou plusieurs monstres "Karakuri": vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre face recto sur le Terrain; changez la position de combat du monstre. \r\nVous ne pouvez activer qu''1 "Hatago Karakuri" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3701074,'Guérison Obscure','Lorsque votre adversaire Invoque un ou plusieurs monstres, il(s) gagne(nt) un nombre de Life Points égal à la moitié de l''ATK d''1 des monstres Invoqué de votre choix.','Gagner des LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3715284,'Déployeur Obbligato, Armée Meklord',replace(replace('Durant votre Main Phase: vous pouvez activer cet effet; détruisez cette carte, et si vous le faites, Invoquez Spécialement 2 monstres "Armée Meklord" ("Déployeur Obbligato, Armée Meklord" exclu) depuis votre Deck en Position de Défense, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Machine exclus) le reste de ce tour. \r\nSi cette carte est envoyée au Cimetière: vous pouvez activer cet effet; durant la End Phase de ce tour, vous pouvez infliger 100 points de dommages à votre adversaire pour chaque monstre "Meklord" que vous contrôlez. \r\nVous ne pouvez utiliser chaque effet de "Déployeur Obbligato, Armée Meklord" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3717252,'Bête Marionnette de l''Ombre',replace(replace('FLIP: Vous pouvez piocher 2 cartes, puis défaussez 1 carte.\r\nSi cette carte est envoyée au Cimetière par un effet de carte: vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser qu''1 effet de "Bête Marionnette de l''Ombre" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Piochez 2 carte(s)','Piochez 1 carte(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3723262,'Sorcier @Ignister',replace(replace('Si vous contrôlez un monstre Cyberse qui a été Invoqué Spécialement depuis l''Extra Deck: vous pouvez cibler 1 monstre TÉNÈBRES Cyberse dans votre Cimetière; Invoquez Spécialement cette carte dans votre main ainsi que le monstre en Position de Défense, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres Cyberse exclus) le reste de ce tour. \r\nVous pouvez bannir cette carte depuis votre Terrain ou Cimetière, puis ciblez 1 monstre contrôlé par votre adversaire; changez sa position de combat. \r\nVous ne pouvez utiliser chaque effet de "Sorcier @Ignister" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Changer la position de combat','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3732747,'Elémentaire de l''Eau','Un esprit aquatique qui peut contrôler la brume pour aveugler ses adversaires.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3734202,'Arbre Sacré Naturia',replace(replace('Si cette carte est envoyée au Cimetière: ajoutez 1 carte "Naturia" ("Arbre Sacré Naturia" exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 des effets suivants de "Arbre Sacré Naturia" par tour, et uniquement une fois le tour.\r\n● Vous pouvez Sacrifier 1 monstre TERRE Insecte; Invoquez Spécialement 1 monstre TERRE Plante de max. Niveau 4 depuis votre Deck.\r\n● Vous pouvez Sacrifier 1 monstre TERRE Plante; Invoquez Spécialement 1 monstre TERRE Insecte de max. Niveau 4 depuis votre Deck.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement 1 monstre Plante TERRE','Invoquer Spécialement 1 monstre Insecte TERRE','Chercher dans le Deck','Utiliser l''effet ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3739500,'Maître de la Fin du Monde',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec une carte "Fin du Monde". \r\nLe nom de cette carte devient "Peine, Roi de l''Armageddon" tant qu''elle est dans la main ou sur le Terrain. \r\nVous ne pouvez utiliser chacun des effets suivants de "Maître de la Fin du Monde" qu''une fois par tour. \r\nVous pouvez révéler cette carte dans votre main, payez 2000 LP, puis bannissez 1 Magie Rituelle depuis votre Deck; appliquez l''effet d''activation de la carte qui Invoque Rituellement un monstre. \r\nVous pouvez payer 2000 LP; détruisez toutes les autres cartes sur le Terrain, puis cette carte gagne 2900 ATK.','\r',char(13)),'\n',char(10)),'Copier le Rituel','Effet de destruction','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3743515,'Sabresaure Fulminant',replace(replace('2 monstres de Niveau 4	\r\nVous pouvez détacher 1 Matériel de cette carte; détruisez 1 monstre Dinosaure dans votre main ou Terrain face recto, puis vous pouvez changer la position de combat d''1 monstre sur le Terrain. \r\nAu début de la Damage Step, si votre autre monstre Dinosaure combat: vous pouvez détruire cette carte, et si vous le faites, le monstre Dinosaure gagne 2000 ATK jusqu''à la fin de la Battle Phase. \r\nVous ne pouvez utiliser chaque effet de "Sabresaure Fulminant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Détruire','Détruire et augmenter l''ATK','Changer la position de combat ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3752422,'Niveauportier Potartiste',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nUne fois par tour: vous pouvez augmenter le Niveau de tous les monstres Invoqués par Pendule que vous contrôlez actuellement de 1 (même si cette carte quitte le Terrain).\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nUne fois par tour: vous pouvez déclarer un Niveau de 1 à 5, puis ciblez 1 autre monstre "Potartiste" que vous contrôlez; jusqu''à la fin de ce tour, réduisez le Niveau de cette carte du Niveau déclaré, et si vous le faites, augmentez le Niveau de l''autre monstre du même montant.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3758046,'D/D/D César, Roi des Vagues',replace(replace('2 monstres de Type Démon de Niveau 4	\r\nDurant le tour de chaque joueur: vous pouvez détacher 1 Matériel Xyz de cette carte; à la fin de la Battle Phase, Invoquez Spécialement autant de monstres détruits ce tour que possible depuis votre Cimetière, mais durant la prochaine Standby Phase, recevez 1000 points de dommages pour chaque monstre Invoqué Spécialement par cet effet. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez ajouter 1 carte "Contrat des Ténèbres" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "D/D/D César, Roi des Vagues" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement le monstre détruit ce tour à la fin de la Battle Phase','Chercher dans le Deck','Subir des dommages','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3773196,'Avion de Reconnaissance D.D.',replace(replace('Durant la End Phase, si cette carte est actuellement bannie, et a été bannie ce tour: Invoquez-la Spécialement en Position d''Attaque face recto. \r\nCet effet ne peut être activé qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3775068,'Indiora l''Empereur Cubique du Choc Mortel',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en envoyant 3 monstres "Cubique" que vous contrôlez au Cimetière, et non Invocable Spécialement autrement. \r\nSi elle est Invoquée de cette façon, cette carte gagne 2400 ATK. \r\nSi cette carte est Invoquée Spécialement depuis la main: infligez 800 points de dommages à votre adversaire. \r\nSi cette carte en votre possession est envoyée à votre Cimetière par une carte de votre adversaire (au combat ou par un effet de carte): vous pouvez cibler max. 3 monstres "Cubique" dans votre Cimetière; Invoquez-les Spécialement, puis vous pouvez ajouter 1 carte "Cubique" depuis votre Deck ou Cimetière à votre main.','\r',char(13)),'\n',char(10)),'Dommages d''effet','Invoquer Spécialement 1 monstre depuis le Cimetière','Ajouter 1 carte "Cubique" à votre main ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779493,'Administrateur du Crépuscule',replace(replace('"Sorcier du Crépuscule" + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée Spécialement, ou si un ou plusieurs autres monstres Magicien sont Invoqués Spécialement sur votre Terrain: vous pouvez cibler 1 carte dans le Cimetière de votre adversaire; bannissez-la. \r\nSi cette carte est détruite au combat, ou si cette carte dans la Zone Monstre de son propriétaire est détruite par un effet de carte de l''adversaire: vous pouvez cibler 1 monstre Magicien de max. Niveau 4 dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser cet effet de "Administrateur du Crépuscule" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Bannir des cartes du Cimetière de l''adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779662,'Andabata, Bête Gladiateur',replace(replace('"Auguste, Bête Gladiateur" + 2 monstres "Bête Gladiateur"	\r\nDoit d''abord être Invoquée Spécialement (depuis votre Extra Deck) en mélangeant les cartes ci-dessus que vous contrôlez dans le Deck. \r\n(N''utilisez pas "Polymérisation".) \r\nSi elle est Invoquée de cette façon: vous pouvez Invoquer Spécialement 1 Monstre Fusion "Bête Gladiateur" de max. Niveau 7 depuis votre Extra Deck, en ignorant ses conditions d''Invocation. À la fin de la Battle Phase, si cette carte a combattu: vous pouvez la renvoyer à l''Extra Deck; Invoquez Spécialement 2 monstres "Bête Gladiateur" depuis votre Deck.','\r',char(13)),'\n',char(10)),'','Invocation Spéciale','Sélectionnez "Bête Gladiateur"','Sélectionnez un monstre "Bête Gladiateur"','','','','','','','','','','','','');
INSERT INTO texts VALUES(3784434,'Rhynos Saccageurs',replace(replace('Une fois par tour, cette carte peut se déplacer vers une Zone Carte Monstre adjacente inoccupée. \r\nSi cette carte attaque le monstre dans la même colonne qu''elle, cette carte gagne 500 points d''ATK durant la Damage Step.','\r',char(13)),'\n',char(10)),'Déplacer vers une autre Zone','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3790062,'Numéro 65 : Génie Destructeur',replace(replace('2 monstres TÉNÈBRES de Niveau 2	\r\nLorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez détacher 2 Matériels de cette carte; annulez l''activation, et si vous le faites, infligez 500 points de dommages à votre adversaire.','\r',char(13)),'\n',char(10)),'Annuler l''activation et infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3792766,'Dauphinelle Farstar',replace(replace('2+ monstres "Farstar"	\r\nLorsque cette carte déclare une attaque tant qu''elle pointe un monstre "Farstar": vous pouvez cibler un nombre de vos cartes "Farstar" bannies, inférieur ou égal au nombre de Monstres Lien contrôlés par votre adversaire; ajoutez-les à votre main, et si vous le faites, cette carte gagne 1000 ATK pour chaque carte ajoutée jusqu''à la fin de ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3797883,'Machine à Sous','On dit que les capacités de cette machine varient en fonction de ses résultats.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3806388,'Cœur du Chaos',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement par un effet de carte. \r\nSi cette carte face recto va quitter le Terrain, bannissez-la à la place. \r\nVous ne pouvez utiliser chacun des effets suivants de "Cœur du Chaos" qu''une fois par tour. \r\nVous pouvez bannir 1 monstre TÉNÈBRES depuis votre main ou Cimetière; Invoquez Spécialement cette carte depuis votre main, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (Monstres Synchro LUMIÈRE ou TÉNÈBRES exclus) depuis l''Extra Deck le reste de ce tour. \r\nSi cette carte est Invoquée Spécialement: vous pouvez cibler 1 de vos "Carapace du Chaos" bannis; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3810071,'Moine Combattant','Les dommages de combat que le contrôleur de cette carte reçoit à l''issue d''un combat impliquant cette carte deviennent 0.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3814632,'Palais Céleste Gangaridai',replace(replace('2 monstres de Niveau 10	\r\nVous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 carte contrôlée par votre adversaire; détruisez la cible, et si vous le faites, infligez 1000 points de dommages à votre adversaire. \r\nVous ne pouvez utiliser l''effet de "Palais Céleste Gangaridai" qu''une fois par tour. \r\nNe peut pas attaquer le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Détruire et infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3819470,'Sept Outils du Bandit','Lorsqu''une Carte Piège est activée: payez 1000 LP; annulez l''activation, et si vous le faites, détruisez-la.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3825890,'Oracle des Protecteurs du Tombeau',replace(replace('Vous pouvez Invoquer par Sacrifice cette carte en Sacrifiant 1 monstre "Protecteurs du Tombeau". \r\nCette carte gagne 200 ATK pour chaque monstre "Protecteurs du Tombeau" dans votre Cimetière. \r\nSi cette carte face recto va être détruite, vous pouvez défausser 1 monstre "Protecteurs du Tombeau" à la place.','\r',char(13)),'\n',char(10)),'Invocation avec Sacrifice en utilisant un monstre dont le nom contient "Protecteurs du Tombeau"','Utiliser l''effet de remplacement de destruction de "Oracle des Protecteurs du Tombeau" ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3828844,'Strenna la Reine Rikka',replace(replace('2 monstres de Niveau 4	\r\nVous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre Plante ou carte "Rikka" dans votre Cimetière; ajoutez-le à votre main. \r\nSi cette carte avec du Matériel Xyz est Sacrifiée: vous pouvez Invoquer Spécialement 1 Monstre Xyz Plante de min. Rang 5 depuis votre Extra Deck ou Cimetière, puis vous pouvez lui attacher cette carte comme Matériel. \r\nVous ne pouvez utiliser chaque effet de "Strenna la Reine Rikka" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Superposer cette carte comme Matériel Xyz ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3837261,'Guerrier Dragonique',replace(replace('Vous pouvez défausser 1 carte; Invoquez Spécialement 1 monstre Dragon de max. Niveau 4 ("Guerrier Dragonique" exclu) depuis votre main ou Deck, mais annulez ses effets. \r\nVous ne pouvez utiliser cet effet de "Guerrier Dragonique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3841104,'Stratiae le Dino de la Déstratification',replace(replace('2 monstres (un monstre Dinosaure inclus)	\r\nSi cette carte est Invoquée par Lien: vous pouvez faire gagner à cette carte une ATK égale à la moitié de la somme des ATK d''origine des monstres Dinosaure utilisés comme Matériel.\r\nDurant votre Main Phase: vous pouvez Invoquer par Fusion 1 Monstre Fusion Dinosaure depuis votre Extra Deck, en bannissant ses Matériels depuis votre Terrain et/ou votre Cimetière, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres Dinosaure exclus) depuis l''Extra Deck le reste de ce tour.\r\nVous ne pouvez utiliser cet effet de "Stratiae le Dino de la Déstratification" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','Invocation Fusion','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3841833,'Ours Peluchimal',replace(replace('Vous pouvez envoyer cette carte depuis votre main au Cimetière; Posez 1 "Vendeur de Jouets" directement depuis votre Deck dans votre Zone Magie & Piège. \r\nVous pouvez Sacrifier cette carte, puis ciblez 1 "Polymérisation" dans votre Cimetière; ajoutez-la à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Ours Peluchimal" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Chercher dans le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3846170,'Karakuri 236 "Nisamu" le Soldat',replace(replace('Cette carte doit attaquer lorsque c''est possible. \r\nLorsque cette carte en Position d''Attaque face recto est sélectionnée comme cible d''une attaque, changez-la en Position de Défense. \r\nLorsque cette carte est détruite au combat et envoyée au Cimetière, vous pouvez Invoquer Spécialement 1 monstre "Karakuri" de Niveau 4 ou moins depuis votre Deck en Position d''Attaque face recto.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3859859,'Magicienne des Potartistes Célestes',replace(replace('Si vous contrôlez une Magie Continue: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte est Invoquée Spécialement depuis la main: vous pouvez envoyer 1 monstre LUMIÈRE Magicien de max. Niveau 4 depuis votre Deck au Cimetière. \r\nSi cette carte face recto quitte le Terrain: vous pouvez cibler 1 Magie/Piège sur le Terrain; détruisez-le. \r\nVous ne pouvez utiliser chaque effet de "Magicienne des Potartistes Célestes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3868277,'TGX3-DX2','Ciblez 3 monstres "T.G." dans votre Cimetière; mélangez-les tous les 3 dans votre Deck, puis piochez 2 cartes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3875465,'Monde Électrolyrique Électroménageur',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 carte "Électroménageur" (Magies de Terrain exclues) depuis votre Deck à votre main. \r\nUne fois par tour, si vous Invoquez par Lien un ou plusieurs Monstres Lien "Électroménageur": vous pouvez ajouter 1 monstre "Électroménageur" depuis votre Cimetière à votre main. \r\nUne fois par tour, lorsqu''un monstre déclare une attaque: vous pouvez déplacer 1 monstre "Électroménageur" que vous contrôlez dans une autre de vos Zones Monstre Main. \r\nVous ne pouvez activer qu''1 "Monde Électrolyrique Électroménageur" par tour.','\r',char(13)),'\n',char(10)),'Ajouter "Électroménageur" depuis votre Deck à votre main ?','','','Sélectionnez un monstre à déplacer','','','','','','','','','','','','');
INSERT INTO texts VALUES(3891471,'Réglage Psychique',replace(replace('Sélectionnez 1 monstre de Type Psychique dans votre Cimetière et Invoquez-le Spécialement en Position d''Attaque. \r\nIl est traité comme un monstre Syntoniseur. \r\nLorsque cette carte est retirée du Terrain, détruisez ce monstre. \r\nLorsque ce monstre est retiré du Terrain, détruisez cette carte. \r\nLorsque cette carte est envoyée au Cimetière, recevez des dommages équivalents au Niveau du monstre x 400.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3897065,'Super Véhicroid - Alliance Furtive',replace(replace('"Camionroid" + "Expressroid" + "Drillroid" + "Furtiroid"	\r\nUne fois par tour: vous pouvez cibler 1 monstre non-Machine face recto sur le Terrain; équipez la cible à cette carte. \r\nTant qu''elle est équipée avec un monstre par cet effet, cette carte peut attaquer une fois tous les monstres contrôlés par votre adversaire. \r\nSi cette carte attaque, son ATK d''origine est divisée par deux. \r\nSi cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','\r',char(13)),'\n',char(10)),'Équiper','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3900605,'Jarre Absorbante',replace(replace('FLIP: Détruisez toutes les Magies et tous les Pièges Posés sur le Terrain, puis chaque joueur pioche 1 carte pour chacune des cartes qu''il contrôlait détruites par cet effet. \r\nCe tour, vous ne pouvez pas Poser de cartes.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3909436,'Seigneur du Combat Vendetterreur',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec une Magie Rituelle "Vendetterreur". \r\nVous pouvez bannir 1 carte "Vendetterreur" depuis votre Cimetière et déclarer 1 type de carte (Monstre, Magie ou Piège); le reste de ce tour, votre adversaire ne peut activer ni de cartes ni d''effets de ce type. \r\nSi cette carte Invoquée Rituellement est envoyée au Cimetière: vous pouvez ajouter 1 Monstre Rituel depuis votre Deck à votre main, et si vous le faites, envoyez 1 monstre "Vendetterreur" depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Seigneur du Combat Vendetterreur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3912064,'Mercure l''Excursionniste',replace(replace('Lorsque cette carte est Invoquée par Sacrifice: vous pouvez changer tous les monstres sur le Terrain en Position d''Attaque face recto. \r\nVous pouvez Sacrifier 3 monstres pour Invoquer par Sacrifice (mais pas Poser) cette carte. \r\nSi elle est Invoquée de cette façon, tant que cette carte est sur le Terrain, tous les monstres contrôlés par votre adversaire perdent une ATK égale à leur ATK d''origine. \r\nCette carte peut faire une seconde attaque durant chaque Battle Phase.','\r',char(13)),'\n',char(10)),'Sacrifiez 3 monstres pour Invoquer','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3918345,'Slime Magique',replace(replace('Cette carte est traitée comme un Monstre Normal tant qu''elle est face recto sur le Terrain ou dans le Cimetière. \r\nTant que cette carte est un Monstre Normal sur le Terrain, vous pouvez l''Invoquer Normalement pour qu''elle devienne un Monstre à Effet avec cet effet.\r\n● Votre adversaire reçoit les dommages de combat que vous auriez dû recevoir de combats impliquant cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3954901,'Grand Dragon d''Or',replace(replace('Non Invocable Spécialement, sauf depuis le Cimetière et uniquement si elle y a été envoyée depuis le Terrain. \r\nSi cette carte est Invoquée Spécialement: ciblez 1 monstre dans votre Cimetière; cette carte gagne une ATK égale au Niveau du monstre x 200.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3957130,'Dragon Trisborrelle',replace(replace('2+ monstres TÉNÈBRES Dragon (un monstre "Rokkette" inclus)	\r\nSi cette carte est Invoquée par Lien: vous pouvez ajouter 1 "Amorce Rapide", "Interverrouillage Lourd" ou "Interverrouillage Double" depuis votre Deck à votre main. \r\nVous pouvez cibler 1 carte face recto que vous contrôlez et 1 monstre TÉNÈBRES Dragon dans votre Cimetière; détruisez la carte sur le Terrain, et si vous le faites, ajoutez l''autre monstre depuis votre Cimetière à votre main. \r\nVous ne pouvez utiliser chaque effet de "Dragon Trisborrelle" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet d''ajout à la main','Effet de récupération','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3966653,'Fleur Cardian Sanglicerpillon',replace(replace('1 Syntoniseur + 2 monstres non-Syntoniseur	\r\nSi un monstre "Fleur Cardian" que vous contrôlez attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire. \r\nUne fois par tour: vous pouvez bannir 1 monstre "Fleur Cardian" depuis votre Cimetière; jusqu''à la fin du prochain tour de votre adversaire, votre adversaire ne peut pas activer d''effets de carte dans le Cimetière, et aussi, il ne peut pas Invoquer Spécialement de monstres depuis le Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3972721,'Fréquence d''Avidité',replace(replace('Activable uniquement si vous détruisez un Monstre Synchro face recto contrôlé par votre adversaire ce tour, au combat ou par l''effet d''une carte. \r\nPiochez 2 cartes.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3985011,'Amulette','Cette créature a peut-être l''air maigre et faible, mais elle est protégée par une force mystique.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3987233,'Missus Radieux',replace(replace('2 monstres TERRE	\r\nTous les monstres TERRE sur le Terrain gagnent 500 ATK/DEF, et aussi, tous les monstres VENT sur le Terrain perdent 400 ATK/DEF. \r\nSi cette carte est détruite au combat ou par un effet de carte: vous pouvez cibler 1 monstre TERRE dans votre Cimetière; ajoutez-le à votre main. \r\nVous ne pouvez utiliser cet effet de "Missus Radieux" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3989465,'Ignis Lavalval',replace(replace('2 monstres de Niveau 3	\r\nSi cette carte attaque ou est attaquée, durant la Damage Step (du tour de chaque joueur): une fois par combat, vous pouvez détacher 1 Matériel Xyz de cette carte; jusqu''à la fin de ce tour, cette carte gagne 500 ATK.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4008212,'Brisez la Destinée',replace(replace('Ciblez 1 monstre "HÉROS de la Destinée" de min. Niveau 8 ou 1 "Soldat Dragon de l''Ultime Destinée" que vous contrôlez; détruisez-le, et si vous le faites, votre adversaire saute sa prochaine Main Phase 1. \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 Magie/Piège qui liste spécifiquement un nom de carte de monstre "HÉROS de la Destinée" ou "Soldat Dragon de l''Ultime Destinée" dans son texte ("Brisez la Destinée" exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Brisez la Destinée" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4017398,'Confiance Zexal',replace(replace('Ciblez 1 monstre "Utopie", "ZW -" ou "ZS -" dans votre Cimetière; ajoutez-le à votre main ou Invoquez-le Spécialement. \r\nSi votre adversaire a min. 2000 LP de plus que vous, sauf le tour où cette carte a été envoyée au Cimetière: vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Magie/Piège "Zexal" ("Confiance Zexal" exclu) dans votre Cimetière; ajoutez-le à votre main. \r\nVous ne pouvez utiliser chaque effet de "Confiance Zexal" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4019153,'Numéro 4 : Porte Numeron Catvari',replace(replace('3 monstres de Niveau 1	\r\nNon destructible au combat. À la fin de la Damage Step, si cette carte a combattu un monstre de l''adversaire: vous pouvez détacher 1 Matériel de cette carte; jusqu''à la fin de ce tour, doublez l''ATK de tous les monstres "Numeron" que vous contrôlez actuellement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4022819,'Dragon Hiératique d''Eset',replace(replace('Vous pouvez Invoquer Normalement cette carte sans Sacrifice, mais son ATK d''origine devient 1000. \r\nUne fois par tour: vous pouvez cibler 1 Monstre Normal Dragon face recto sur le Terrain; jusqu''à la End Phase, le Niveau de tous les monstres "Hiératique" face recto actuellement sur le Terrain devient le Niveau du monstre. \r\nLorsque cette carte est Sacrifiée: Invoquez Spécialement 1 Monstre Normal Dragon depuis votre main, Deck ou Cimetière, et faites devenir 0 son ATK/DEF.','\r',char(13)),'\n',char(10)),'Invocation sans Sacrifice','Changer le Niveau','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4026187,'Conteuse de l''Animal Féérique',replace(replace('1 monstre "Animal Féérique" LUMIÈRE + 1 monstre Magicien	\r\nLes monstres "Animal Féérique" que vous contrôlez ne peuvent pas être détruits au combat. \r\nVous ne pouvez utiliser chacun des effets suivants de "Conteuse de l''Animal Féérique" qu''une fois par tour. \r\nSi cette carte est Invoquée par Fusion en utilisant "Prince des Fées" comme Matériel: vous pouvez détruire autant de cartes contrôlées par votre adversaire que possible, et si vous le faites, infligez 500 points de dommages à votre adversaire pour chaque carte détruite. \r\nLorsque votre adversaire active une carte ou un effet (Effet Rapide): vous pouvez bannir 1 carte "Animal Féérique" depuis votre main ou Cimetière; annulez l''activation, et si vous le faites, détruisez la carte.','\r',char(13)),'\n',char(10)),'Effet de destruction','Annuler l''activation','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4031928,'Changement de Cœur','Ciblez 1 monstre contrôlé par votre adversaire; jusqu''à la End Phase, prenez-en le contrôle.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4035199,'Agrippe-Forme','Un nœud papillon chargé d''une horrible puissance, qui attaque un adversaire en contrôlant les autres.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4041838,'Maestro Ninja Sasuke','Au début de la Damage Step, si cette carte attaque un monstre en Position de Défense face recto: détruisez le monstre.','Détruire un monstre en Position de Défense face recto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4042268,'Tortue Île','Énorme tortue que l''on confond souvent avec une île.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4055337,'Orcust Chevalier du Cauchemar',replace(replace('Non destructible au combat avec un Monstre Lien. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre face recto sur le Terrain; vous ne pouvez pas Invoquer Spécialement (monstres TÉNÈBRES exclus) le reste de ce tour, et aussi, envoyez 1 monstre TÉNÈBRES Machine ("Orcust Chevalier du Cauchemar" exclu) depuis votre Deck au Cimetière, et si vous le faites, le monstre ciblé gagne une ATK égale au Niveau du monstre envoyé au Cimetière x 100 jusqu''à la fin de ce tour. \r\nVous ne pouvez utiliser cet effet de "Orcust Chevalier du Cauchemar" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4058065,'Salamandra Colonie du Mal',replace(replace('Max. \r\ndeux fois par tour: vous pouvez bannir 1 monstre depuis votre Cimetière; jusqu''à la fin du tour de votre adversaire, cette carte gagne 300 ATK.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4059313,'Canon de Flammes',replace(replace('(Cette carte est toujours aussi traitée comme une carte "Accélérateur de Flammes".)	\r\nJusqu''à la fin de ce tour, un "Le Dragon Ailé de Râ" que vous contrôlez gagne les effets suivants. \r\nL''activation et l''effet de cette carte ne peuvent être annulés.\r\n● Cette carte n''est pas affectée par des effets de carte de votre adversaire.\r\n● Lorsqu''une attaque impliquant cette carte est déclarée: vous pouvez Sacrifier un nombre de votre choix d''autres monstres qui n''ont pas déclaré d''attaque ce tour; jusqu''à la fin de ce tour, cette carte gagne une ATK égale à la somme des ATK d''origine des monstres Sacrifiés.\r\n● Après le calcul des dommages, si cette carte a attaqué: vous pouvez envoyer tous les monstres contrôlés par votre adversaire au Cimetière.','\r',char(13)),'\n',char(10)),'L''effet de "Canon de Flammes" est actuellement appliqué.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4063756,'Medicurius le Mécène du Pouvoir des Illusions',replace(replace('2+ monstres (un Monstre Fusion, Synchro, Xyz ou Lien inclus)	\r\nGagne ces effets selon le nombre de monstres qu''elle pointe.\r\n● 1+: Une fois par tour: vous pouvez annuler les effets de tous les monstres face recto actuellement contrôlés par votre adversaire, et aussi, leur ATK sera divisée par deux jusqu''à la fin de ce tour.\r\n● 2+: Non affectée par les effets activés de votre adversaire.\r\n● 3: Une fois par tour de l''adversaire (Effet Rapide): vous pouvez bannir cette carte, et aussi, bannissez toutes les cartes contrôlées par votre adversaire.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Effet de bannissement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4064256,'Monde Zombie',replace(replace('Tous les monstres sur le Terrain et dans les Cimetières deviennent des monstres Zombie. \r\nAucun joueur ne peut Invoquer par Sacrifice de monstres (monstres Zombie exclus).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4064925,'Avancée Rouages Ancients',replace(replace('Lorsque cette carte est activée: ajoutez 1 Magie/Piège "Rouages Ancients" ("Avancée Rouages Ancients" exclu) depuis votre Deck à votre main. \r\nUne fois par tour: vous pouvez Sacrifier 1 monstre; piochez 1 carte et appliquez cet effet le reste de ce tour (même si cette carte quitte le Terrain).\r\n● Vous pouvez Invoquer Normalement "Golem Rouages Ancients" ou les monstres de min. Niveau 5 qui le mentionnent sans Sacrifice.	\r\nVous ne pouvez pas Poser de cartes le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Avancée Rouages Ancients" par tour.','\r',char(13)),'\n',char(10)),'Sacrifier un monstre et piocher 1 carte','','Invoquer par l''effet de "Avancée Rouages Ancients"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4068622,'Aile Noire - Aurora la Lumière du Nord',replace(replace('Ni Invocable Normalement ni Posable. \r\nUniquement Invocable Spécialement (depuis votre main) en bannissant 2 monstres face recto que vous contrôlez (1 Syntoniseur "Aile Noire" et 1 non-Syntoniseur), et non Invocable Spécialement autrement. \r\nUne fois par tour: vous pouvez bannir 1 Monstre Synchro "Aile Noire" depuis votre Extra Deck; jusqu''à la End Phase, le nom et l''ATK d''origine de cette carte deviennent ceux du monstre, et remplacez cet effet par les effets d''origine du monstre.','\r',char(13)),'\n',char(10)),'Obtenir un effet de monstre','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4072687,'Résultat Inacceptable','Si vous contrôlez un monstre Magicien: Invoquez Spécialement 1 monstre "Sorcière de la Bonne Aventure" depuis votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4079728,'À Fond Springans !',replace(replace('2+ monstres "Springans" de Niveau 4	\r\nSi cette carte est Invoquée par Xyz ou envoyée au Cimetière: vous pouvez Invoquer Spécialement 1 "Capitaine Sargas Springans" depuis votre Deck ou Cimetière. \r\nVous pouvez détacher 2 Matériels de cette carte; ajoutez à votre main ou Invoquez Spécialement 1 des monstres suivants depuis votre Deck.\r\n● Monstre "Springans"\r\n● Monstre "Therion"\r\n● "Albaz le Déchu" ou 1 monstre qui le mentionne\r\nVous ne pouvez utiliser qu''1 effet de "À Fond Springans !" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet d''ajout à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081094,'Deuxième Sarcophage','Cette carte ne peut être placée sur le Terrain que par l''effet de "Premier Sarcophage".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081665,'Lanceur à Échasses Mageartiste',replace(replace('S''il n''y a aucun monstre sur le Terrain, vous pouvez Invoquer Spécialement cette carte (depuis votre main), mais vous ne pouvez ni Invoquer Normalement ni Poser Normalement le reste de ce tour. \r\nDurant le tour de chaque joueur, lorsqu''une carte ou un effet qui va infliger des dommages à votre adversaire est activé, tant que vous avez un autre monstre "Mageartiste" dans votre Cimetière: vous pouvez bannir cette carte depuis votre Cimetière; infligez 2000 points de dommage à votre adversaire. \r\nVous ne pouvez utiliser cet effet de "Lanceur à Échasses Mageartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081825,'Chaos Infini','Changez autant de monstres en Position de Défense sur le Terrain que possible en Position d''Attaque face recto, puis Invoquez Spécialement 1 monstre "Meklord" depuis votre Deck ou Cimetière, mais ses effets sont annulés, et aussi, il est détruit durant la End Phase.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4103668,'Tengu, Mayakashi des Ailes',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nVous ne pouvez contrôler qu''1 "Tengu, Mayakashi des Ailes". \r\nVous ne pouvez utiliser chacun de ces effets de "Tengu, Mayakashi des Ailes" qu''une fois par tour.\r\n● Si un Monstre Synchro en votre possession, dont le Niveau d''origine est 9, est détruit au combat ou par un effet de carte de l''adversaire tant que cette carte est dans le Cimetière: vous pouvez bannir 1 autre monstre Zombie depuis votre Cimetière, et si vous le faites, Invoquez Spécialement cette carte.\r\n● Si cette carte est Invoquée Spécialement depuis le Cimetière: vous pouvez détruire 1 Magie/Piège contrôlé par votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4130270,'Chasseresse B.G.','Les cartes sur le Terrain ne peuvent être renvoyées dans le Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4141820,'Démon Jinn, Prophète des Rituels',replace(replace('Lorsque vous Invoquez Rituellement un monstre, vous pouvez bannir cette carte depuis votre Cimetière comme 1 des monstres requis pour l''Invocation Rituelle. \r\nSi vous Invoquez Rituellement en utilisant cette carte, si le monstre Invoqué Rituellement inflige des dommages de combat à votre adversaire, il défausse 1 carte.','\r',char(13)),'\n',char(10)),'L''effet de "Démon Jinn, Prophète des Rituels" est actuellement appliqué.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4145852,'Bélierbélier du Zoodiaque',replace(replace('Si cette carte est détruite au combat ou par un effet de carte: vous pouvez cibler 1 monstre "Zoodiaque" ("Bélierbélier du Zoodiaque" exclu) dans votre Cimetière; Invoquez-le Spécialement. \r\nUn Monstre Xyz dont le Type d''origine est Bête-Guerrier et qui a cette carte comme Matériel gagne cet effet.\r\n● Lorsque votre adversaire active une Carte Piège ou effet de Piège qui cible cette carte (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''activation.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un monstre "Zoodiaque" depuis votre Cimetière','Annuler l''activation d''un effet de Carte Piège (Bélierbélier du Zoodiaque)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4145915,'Poupée Truquée Chevalier Monstrueux',replace(replace('Si cette carte est dans votre main: vous pouvez cibler 1 monstre "Poupée Truquée" dans votre Cimetière ou 1 monstre dans le Cimetière de votre adversaire; Invoquez-le Spécialement sur le Terrain de son propriétaire en Position de Défense, mais ses effets sont annulés, puis Invoquez Spécialement cette carte. \r\nSi cette carte est envoyée au Cimetière, sauf depuis la main: vous pouvez l''ajouter à votre main. \r\nVous ne pouvez utiliser chaque effet de "Poupée Truquée Chevalier Monstrueux" qu''une fois par tour, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres "Poupée Truquée" exclus) depuis l''Extra Deck le tour où vous activez un effet de cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4148264,'Brigadier Cancrelat Sombre Lumineux','Dans l''ombre se faufile la brigade des Cancrelats ! Leurs capacités cachées de vol leur permettent d''affronter les géants sur un pied d''égalité !','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4149689,'Ventilateur Gobelin',replace(replace('Lorsqu''un monstre de max. Niveau 2 est Invoqué par Flip, détruisez-le. \r\nSes effets ne s''activent pas à ce moment.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4160316,'Liens Centur-Ion',replace(replace('Placez 1 monstre "Centur-Ion" depuis votre main ou Cimetière dans votre Zone Magie & Piège comme Piège Continu face recto. \r\nSi un ou plusieurs Monstres Synchro "Centur-Ion" sont Invoqués Spécialement sur votre Terrain, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez bannir cette carte, puis ciblez 1 monstre "Centur-Ion" dans votre Cimetière; placez-le dans votre Zone Magie & Piège comme Piège Continu face recto. \r\nVous ne pouvez utiliser chaque effet de "Liens Centur-Ion" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4162088,'Dragon Cyber Laser',replace(replace('Cette carte ne peut ni être Invoquée par Invocation Normale ni être Posée. \r\nCette carte ne peut pas être Invoquée par Invocation Spéciale, excepté par "Unité de Génération Photonique". \r\nUne fois par tour, vous pouvez détruire 1 monstre avec une ATK ou une DEF supérieure ou égale à l''ATK de cette carte.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4167084,'Le Premier Ange Déchu',replace(replace('3 monstres TÉNÈBRES Elfe	\r\nVotre adversaire ne peut pas cibler de monstres Elfe que vous contrôlez avec des effets de carte. \r\nVous ne pouvez utiliser qu''1 des effets suivants de "Le Premier Ange Déchu" par tour, et uniquement une fois le tour. \r\nSi cette carte est Invoquée par Fusion en utilisant "Ange Déchu Étoile du Matin" comme Matériel: vous pouvez détruire toutes les cartes contrôlées par votre adversaire. \r\nDurant la Main Phase (Effet Rapide): vous pouvez payer 1000 LP; Invoquez Spécialement 1 monstre Elfe depuis votre main ou Cimetière en Position de Défense.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4168871,'Cartes Plumes Noires',replace(replace('Bannissez 1 monstre "Aile Noire" monstre depuis votre main; piochez 2 cartes. \r\nVous ne pouvez pas Invoquer Spécialement durant le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Cartes Plumes Noires" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4178474,'Interruption de Raigeki','Défaussez 1 carte, puis ciblez 1 carte sur le Terrain; détruisez-la.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4179255,'Ancien Dragon Pixie',replace(replace('1 Syntoniseur + 1 monstre non-Syntoniseur ou plus	\r\nAprès la résolution d''une Carte Magie de Terrain qui a été activée durant votre tour: piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Ancien Dragon Pixie" qu''une fois par tour. \r\nUne fois par tour: vous pouvez cibler 1 monstre en Position d''Attaque face recto sur le Terrain; détruisez la cible. \r\nIl doit y avoir une Carte Magie de Terrain face recto sur le Terrain pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Piocher','Détruire un monstre','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4179849,'Reine des Feuilles de l''Automne','Reine de la forêt d''émeraude et femme du roi des esprits, elle vit entourée d''un feuillage ardent.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4192696,'Éco, Esprit Mystique de la Forêt','Lorsque vous recevez des dommages par un effet de carte de l''adversaire (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, infligez des dommages à votre adversaire égaux aux dommages que vous avez reçus, et aussi, chaque joueur ne reçoit aucun autre dommage d''effet ce tour.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4206964,'Trappe','Lorsque votre adversaire Invoque Normalement ou par Flip un monstre avec min. 1000 ATK: ciblez le monstre; détruisez la cible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4215180,'Sucetty☆Miammy',replace(replace('Si vous contrôlez un monstre Link-1 ou un Monstre Synchro de Niveau 2, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Sucetty☆Miammy" qu''une fois par tour de cette façon. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 carte dans le Cimetière de votre adversaire; mélangez-la dans le Deck, ou, si cette carte a été Invoquée Spécialement par l''effet d''un Monstre Synchro, vous pouvez bannir la carte à la place. \r\nVous ne pouvez utiliser cet effet de "Sucetty☆Miammy" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Renvoyer au Deck','Le bannir à la place ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4215636,'Temple de la Vallée de Brume',replace(replace('Une fois par tour, lorsqu''un ou plusieurs monstres VENT sont détruits par un effet de carte et envoyés à votre Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement 1 monstre VENT de max. Niveau 3 depuis votre main ou Deck. \r\nSes effets sont annulés.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4227096,'Arrestation Erronée','Jusqu''à la fin de votre prochain tour après la résolution de cette carte, aucun joueur ne peut ajouter de cartes depuis son Deck à sa main, sauf en les piochant.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4230620,'Station Psionique',replace(replace('Lorsqu''un monstre de Type Psychique est Invoqué Normalement: vous pouvez payer 500 LP; augmentez son Niveau de 1 et son ATK de 300. \r\n(Ceci est valide même si cette carte quitte le Terrain.)','\r',char(13)),'\n',char(10)),'Augmenter le Niveau et l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4239451,'Crapaud du Tour Potartiste',replace(replace('Échelle Pendule = 3\r\n[ Effet Pendule ]\r\nUne fois par tour: vous pouvez cibler 1 monstre face recto sur le Terrain; jusqu''à la fin de ce tour, échangez son ATK et sa DEF actuelles.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nUne fois par tour, durant votre Battle Phase (sauf durant la Damage Step): vous pouvez cibler 1 monstre que vous contrôlez; changez sa position de combat, et si vous le faites, jusqu''à la fin de ce tour, échangez son ATK et sa DEF actuelles.','\r',char(13)),'\n',char(10)),'Échanger l''ATK et la DEF','Échanger l''ATK et la DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4252828,'Sirène Archère',replace(replace('Une fois par tour: vous pouvez cibler 1 monstre de max. Niveau 3 face recto que vous contrôlez; équipez la cible à cette carte. \r\n(Vous ne pouvez équiper qu''1 monstre à cette carte à la fois avec cet effet.) \r\nTant qu''elle est équipée avec un monstre par cet effet, cette carte gagne 800 ATK. \r\nSi cette carte va être détruite, vous pouvez détruire le monstre qui lui est équipé avec cet effet à la place.','\r',char(13)),'\n',char(10)),'Équiper','Utiliser l''effet de "Sirène Archère" à la place de la destruction ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4253484,'Hoplomaque, Bête Gladiateur','Si cette carte est Invoquée Spécialement par l''effet d''un monstre "Bête Gladiateur", sa DEF d''origine devient 2400. À la fin de la Battle Phase, si cette carte a attaqué ou a été attaquée, vous pouvez la renvoyer dans le Deck pour Invoquer Spécialement 1 monstre "Bête Gladiateur" depuis votre Deck, sauf "Hoplomaque, Bête Gladiateur".','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4259068,'Magie Economique','Vous ne payez pas de Life Points pour activer des Cartes Magie.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4266839,'Kiseitai',replace(replace('Lorsqu''un monstre de votre adversaire attaque cette carte en Position de Défense face verso, équipez-le avec celle-ci (les dommages ne sont pas appliqués). \r\nTraitez cette carte comme une Carte Magie d''Équipement. \r\nDurant chacune des Standby Phases de votre adversaire, augmentez vos Life Points de la moitié de l''ATK du monstre ainsi équipé.','\r',char(13)),'\n',char(10)),'Devenir une Carte d''Équipement','Gagner des LP','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4271596,'Roi de la Cité Cendrée',replace(replace('Si "Obsidim, la Cité Cendrée" est dans la Zone Terrain, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Roi de la Cité Cendrée" qu''une fois par tour de cette façon. \r\nDurant votre Main Phase: vous pouvez Invoquer Spécialement 1 monstre "Cendré" ("Roi de la Cité Cendrée" exclu) depuis votre main, ou si votre adversaire contrôle un monstre avec min. 2800 ATK, vous pouvez l''Invoquer Spécialement depuis votre Deck à la place. \r\nVous ne pouvez utiliser cet effet de "Roi de la Cité Cendrée" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4280258,'Apollousa, Arc de la Déesse',replace(replace('2+ monstres de noms différents (Jetons exclus)	\r\nVous ne pouvez contrôler qu''1 "Apollousa, Arc de la Déesse". \r\nL''ATK d''origine de cette carte devient 800 x le nombre de Matériels Lien utilisés pour son Invocation Lien. \r\nUne fois par Chaîne, lorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez faire perdre exactement 800 ATK à cette carte, et si vous le faites, annulez l''activation.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4280259,'Apollousa, Arc de la Déesse',replace(replace('2+ monstres de noms différents (Jetons exclus)	\r\nVous ne pouvez contrôler qu''1 "Apollousa, Arc de la Déesse". \r\nL''ATK d''origine de cette carte devient 800 x le nombre de Matériels Lien utilisés pour son Invocation Lien. \r\nUne fois par Chaîne, lorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez faire perdre exactement 800 ATK à cette carte, et si vous le faites, annulez l''activation.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4290468,'Rose Splendide',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nUne fois par tour: vous pouvez bannir 1 monstre Plante depuis votre Cimetière, puis ciblez 1 monstre face recto contrôlé par votre adversaire; jusqu''à la fin de ce tour, divisez par deux l''ATK de la cible. \r\nDurant la Battle Phase, si cette carte a attaqué: vous pouvez bannir 1 monstre Plante depuis votre Cimetière; divisez par deux l''ATK de cette carte jusqu''à la fin de ce tour, et si vous le faites, cette carte peut faire une seconde attaque durant cette Battle Phase.','\r',char(13)),'\n',char(10)),'Diminuer l''ATK','Effectuer une attaque supplémentaire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4333086,'Style du Coup de Situation Shiranui',replace(replace('Sacrifiez 1 monstre de Type Zombie, puis ciblez 2 cartes sur le Terrain; détruisez-les, puis bannissez 1 monstre "Shiranui" monstre depuis votre Deck. \r\nVous ne pouvez activer qu''1 "Style du Coup de Situation Shiranui" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4334811,'Recycleur de Ferraille',replace(replace('Lorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez envoyer 1 monstre Machine depuis votre Deck au Cimetière. \r\nUne fois par tour: vous pouvez mélanger 2 monstres TERRE Machine de Niveau 4 depuis votre Cimetière dans le Deck; piochez 1 carte.','\r',char(13)),'\n',char(10)),'Sélectionnez 1 monstre Machine à envoyer au Cimetière','Piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4335427,'Sophia, Déesse de la Renaissance',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en bannissant 1 Monstre Rituel, Fusion, Synchro et Xyz face recto depuis le Terrain. \r\nL''Invocation Spéciale de cette carte ne peut pas être annulée. \r\nSi cette carte est Invoquée Spécialement: bannissez toutes les autres cartes depuis la main, Terrain et Cimetière de chaque joueur. \r\nAucun joueur ne peut activer ni de cartes ni d''effets en réponse à l''activation de cet effet.','\r',char(13)),'\n',char(10)),'Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4335645,'Newdoria','Si cette carte est détruite au combat et envoyée au Cimetière: ciblez 1 monstre sur le Terrain; détruisez la cible.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4341721,'Hallo-Ween !','Ajoutez 1 "Hallo, l''Esprit des Farces" ou "Ween, l''Esprit des Friandises" depuis votre Deck ou Cimetière à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4357063,'Cité Babylone Chronomal','Une fois par tour: vous pouvez bannir 1 monstre "Chronomal" depuis votre Cimetière, puis ciblez 1 monstre "Chronomal" dans votre Cimetière du même Niveau que le monstre banni; Invoquez-le Spécialement.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4367330,'Exploselapin du Zoodiaque',replace(replace('Si cette carte est détruite au combat ou par un effet de carte: vous pouvez cibler 1 carte "Zoodiaque" ("Exploselapin du Zoodiaque" exclu) dans votre Cimetière; ajoutez-la à votre main. \r\nUn Monstre Xyz dont le Type d''origine est Bête-Guerrier et qui a cette carte comme Matériel Xyz gagne cet effet.\r\n● Durant le tour de chaque joueur, lorsque votre adversaire active une Carte Magie ou effet de Magie qui cible cette carte: vous pouvez détacher 1 Matériel Xyz de cette carte; annulez l''activation.','\r',char(13)),'\n',char(10)),'Ajouter une carte "Zoodiaque" depuis votre Cimetière à votre main','Annuler l''activation d''un effet de Carte Magie (Exploselapin du Zoodiaque)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4376658,'Hiita - Familier Possédé',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main ou Deck) en envoyant 1 "Hiita la Charmeuse de Feu" face recto et 1 monstre FEU face recto que vous contrôlez au Cimetière. \r\nSi cette carte Invoquée Spécialement par son effet attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4376659,'Hiita - Familier Possédé',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main ou Deck) en envoyant 1 "Hiita la Charmeuse de Feu" face recto et 1 monstre FEU face recto que vous contrôlez au Cimetière. \r\nSi cette carte Invoquée Spécialement par son effet attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4388680,'Assassin Revendetterreur',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec une Magie Rituelle "Vendetterreur". \r\nUne fois par combat, si cette carte combat un monstre de l''adversaire, durant le calcul des dommages (Effet Rapide): vous pouvez bannir 1 monstre Zombie depuis votre Cimetière; cette carte gagne 300 ATK. \r\nSi cette carte Invoquée Rituellement est envoyée au Cimetière: vous pouvez ajouter 1 Magie Rituelle depuis votre Deck à votre main, et si vous le faites, envoyez 1 monstre "Vendetterreur" depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser cet effet de "Assassin Revendetterreur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','Chercher dans le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4392470,'Léo, le Sorcier','Sorcier à cape noire qui est en fait un lion parlant déguisé.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4398189,'Sorcière de la Forêt Blanche',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 monstre "Forêt Blanche" depuis votre Deck à votre main, mais vous ne pouvez pas Invoquer Spécialement de monstres TÉNÈBRES depuis l''Extra Deck le reste de ce tour. \r\nLa première fois que chaque monstre "Forêt Blanche" que vous contrôlez va être détruit au combat chaque tour, il n''est pas détruit. \r\nVous pouvez cibler 1 monstre "Forêt Blanche" que vous contrôlez; ce tour, il est traité comme Syntoniseur. \r\nVous ne pouvez utiliser cet effet de "Sorcière de la Forêt Blanche" qu''une fois par tour. \r\nVous ne pouvez activer qu''1 "Sorcière de la Forêt Blanche" par tour.','\r',char(13)),'\n',char(10)),'Activer','','Devenir Syntoniseur','Ajouter une carte de votre Deck à votre main ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(4404099,'Dragon des Profondeurs',replace(replace('Placez 1 Compteur Océan sur cette carte durant la Standby Phase de chaque joueur. \r\nLorsque cette carte est retirée du Terrain, tous les monstres de Type Poisson et Serpent de Mer que vous contrôlez gagnent 200 points d''ATK pour chaque Compteur Océan sur cette carte, jusqu''à la End Phase.','\r',char(13)),'\n',char(10)),'Placer un marqueur','Augmenter l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4408198,'Exosœur Arment',replace(replace('Payez 800 LP, puis ciblez 1 monstre "Exosœur" que vous contrôlez; Invoquez Spécialement 1 Monstre Xyz "Exosœur" depuis votre Extra Deck d''un nom différent des cartes que vous contrôlez, en utilisant la cible comme Matériel. \r\n(Ceci est traité comme une Invocation Xyz. Transférez ses Matériels au monstre Invoqué.) \r\nVous ne pouvez activer qu''1 "Exosœur Arment" par tour. \r\nVous ne pouvez activer cette carte que durant le tour de votre adversaire, sauf si votre adversaire contrôle un monstre Invoqué Spécialement depuis le Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4417407,'Bête Fantôme Méca Fauconoir',replace(replace('Lorsque cette carte déclare une attaque: Invoquez Spécialement 1 "Jeton Bête Fantôme Méca" (Type Machine/VENT/Niveau 3/ATK 0/DEF 0). \r\nLe Niveau de cette carte est augmenté de la somme des Niveaux de tous les "Jeton Bête Fantôme Méca" que vous contrôlez. \r\nTant que vous contrôlez un Jeton, cette carte ne peut être détruite ni au combat ni par des effets de carte. \r\nUne fois par tour, durant le tour de chaque joueur: vous pouvez Sacrifier 1 Jeton, puis ciblez 1 monstre contrôlé par votre adversaire; changez la cible en Position de Défense face recto.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un Jeton','Changer la position de combat','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4417408,'Jeton Bête Fantôme Méca','Invoqué Spécialement avec l''effet d''un monstre "Bête Fantôme Méca" et des cartes associées.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4423206,'Invocateur Sabre XM',replace(replace('2 monstres de Niveau 3	\r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte; Invoquez Spécialement 1 monstre TERRE Guerrier ou Bête-Guerrier de Niveau 4 depuis votre Deck en Position de Défense, mais détruisez-le durant la End Phase.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4433488,'Cynet Cascade','Si vous Invoquez par Lien un Monstre Lien: vous pouvez cibler 1 monstre dans votre Cimetière utilisé comme son Matériel; Invoquez-le Spécialement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4440873,'Chute Catastrophique','Lorsque votre adversaire ajoute une ou plusieurs cartes depuis son Deck à sa main, y compris en piochant: il doit défausser 1 de ces cartes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4446672,'Explosif Rouages Ancients',replace(replace('Ciblez 1 monstre "Rouages Ancients" face recto sur votre Terrain lorsque vous activez cette carte. \r\nDétruisez le monstre ciblé et infligez un nombre de dommages égal à la moitié de son ATK d''origine à votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4450854,'Changement Qlimatique',replace(replace('Ajoutez max. 3 Cartes Monstre Pendule "Qli" face recto depuis votre Extra Deck à votre main. \r\nVous ne pouvez activer qu''1 "Changement Qlimatique" par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4466015,'Brûlure Venimeuse',replace(replace('Sélectionnez 1 monstre avec des Compteurs Venin. \r\nRetirez tous les Compteurs Venin de cette carte et infligez 700 points de dommages à votre adversaire pour chaque Compteur Venin enlevé.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4472318,'Dragon Bayerock',replace(replace('Si un ou plusieurs monstres que vous contrôlez ou dans votre main sont détruits au combat ou par un effet de carte: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte en possession de son propriétaire est détruite par une carte de l''adversaire: vous pouvez cibler 1 autre monstre Dinosaure et/ou 1 monstre Rocher dans votre Cimetière; Invoquez-les Spécialement. \r\nVous ne pouvez utiliser chaque effet de "Dragon Bayerock" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4474060,'MATOS ESPIRALE - Drone',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez regarder les 3 cartes du dessus du Deck de votre adversaire, et si vous le faites, placez-les au-dessus de son Deck dans l''ordre de votre choix. \r\n(Effet Rapide): vous pouvez Sacrifier cette carte, puis ciblez 1 monstre "ESPIRALE" que vous contrôlez; il gagne 500 ATK pour chaque carte contrôlée par votre adversaire. \r\nVous pouvez bannir cette carte et 1 carte "ESPIRALE" depuis votre Cimetière, puis ciblez 1 "Super Espion ESPIRALE" dans votre Cimetière; ajoutez-le à votre main.','\r',char(13)),'\n',char(10)),'Regarder les 3 cartes du dessus du Deck de votre adversaire','Augmenter l''ATK','Récupérer depuis le Cimetière','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4478086,'Spartiate Horloge',replace(replace('2 monstres Cyberse	\r\nSi cette carte est Invoquée par Lien: vous pouvez ajouter 1 "Cynet Fusion" depuis votre Deck à votre main. \r\nSi un ou plusieurs monstres sont Invoqués Spécialement dans une ou plusieurs zones pointées par cette carte (sauf durant la Damage Step): vous pouvez cibler 1 monstre Cyberse de max. Niveau 4 dans votre Cimetière; Invoquez-le Spécialement, mais annulez ses effets, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (Monstres Fusion exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Spartiate Horloge" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4483598,'Duplex Totalement Actif',replace(replace('Durant chaque Battle Phase, les monstres liés que vous contrôlez peuvent faire max. 2 attaques sur des monstres. \r\nVous ne pouvez utiliser chacun des effets suivants de "Duplex Totalement Actif" qu''une fois par tour. \r\nVous pouvez bannir 2 Monstres Lien depuis votre Cimetière; Invoquez Spécialement cette carte depuis votre main. \r\nSi cette carte est envoyée au Cimetière: vous pouvez cibler 1 monstre Cyberse que vous contrôlez; il gagne 1000 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4483989,'Préparation à la Contre-attaque',replace(replace('À chaque fois que votre adversaire déclare une attaque sur un monstre en Position de Défense face recto, tirez à pile ou face. \r\nSi vous gagnez, changez le monstre face recto en Position de Défense ciblé en Position d''Attaque. \r\nSi vous perdez, le contrôleur de cette carte reçoit des dommages égaux à la différence entre l'' ATK du monstre attaquant et la DEF du monstre attaqué.','\r',char(13)),'\n',char(10)),'Annoncer pile ou face','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4538826,'Empereur du Chaos, le Dragon de l''Armageddon',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nVous pouvez payer 1000 LP, puis ciblez 1 de vos monstres Dragon bannis; détruisez cette carte, et si vous le faites, ajoutez le monstre à votre main. \r\nVous ne pouvez utiliser cet effet de "Empereur du Chaos, le Dragon de l''Armageddon" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nNi Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main ou Extra Deck) en bannissant 1 monstre LUMIÈRE et 1 monstre TÉNÈBRES depuis votre Cimetière. \r\nVous ne pouvez Invoquer Spécialement "Empereur du Chaos, le Dragon de l''Armageddon" qu''une fois par tour de cette façon. \r\nUne fois par tour: vous pouvez payer la moitié de vos LP; envoyez autant de cartes que vous contrôlez que possible au Cimetière, sauf depuis la Zone Monstre Extra, et si vous le faites, envoyez un nombre de cartes contrôlées par votre adversaire au Cimetière, inférieur ou égal au nombre de vos cartes envoyées au Cimetière, puis, infligez 300 points de dommages à votre adversaire pour chaque carte envoyée à son Cimetière par l''effet de cette carte. \r\nSi cette carte face recto Invoquée Spécialement quitte le Terrain, renvoyez-la au-dessous du Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4542651,'Bouclier du Lustre Jaune','Augmentez la DEF de tous les monstres sur votre Terrain de 300 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4545683,'Granel, Empereur Meklord',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement par son propre effet. \r\nLorsqu''un monstre face recto que vous contrôlez est détruit par un effet de carte et envoyé au Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nUne fois par tour: vous pouvez cibler 1 Monstre Synchro contrôlé par votre adversaire; équipez la cible à cette carte. \r\nGagne une ATK/DEF égales à la moitié de vos LP et une ATK égale à la somme des ATK des monstres qui lui sont équipés par cet effet. \r\nVous pouvez cibler 1 de ces monstres équipés; Invoquez Spécialement la cible sur votre Terrain en Position de Défense.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Équiper un Monstre Synchro','Invoquer Spécialement le monstre équipé','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4545854,'Territoire Xyz',replace(replace('Lorsqu''un Monstre Xyz combat un autre monstre, durant le calcul des dommages uniquement, le Monstre Xyz gagne 200 ATK/DEF x son Rang. \r\nSi cette carte face recto sur le Terrain va être détruite par un effet de carte, vous pouvez détacher 1 Matériel Xyz d''un monstre que vous contrôlez à la place.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Territoire Xyz" à la place de la destruction ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4549095,'Boxeur Indomptable Contre Coup de Poing',replace(replace('Durant la Damage Step de chaque joueur, lorsqu''un monstre "Boxeur Indomptable" que vous contrôlez attaque ou est attaqué: vous pouvez bannir cette carte depuis votre main ou Cimetière; jusqu''à la fin de ce tour, le monstre gagne 1000 ATK. \r\nVous ne pouvez utiliser l''effet de "Boxeur Indomptable Contre Coup de Poing" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4550066,'Reconstrucerf','Lorsque cette carte détruit un monstre de l''adversaire au combat: vous pouvez cibler 1 monstre Cyberse avec max. 1500 ATK dans votre Cimetière; Invoquez-le Spécialement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4575541,'Ici Sont des Dragons',replace(replace('Invoquez Spécialement 1 monstre "Maître Dragon" depuis votre main, Cimetière ou bannissement, puis immédiatement après la résolution de cet effet, vous pouvez Invoquer par Xyz 1 Monstre Xyz "Maître Dragon" en utilisant uniquement des monstres "Maître Dragon" que vous contrôlez. \r\nDurant votre Main Phase: vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez un nombre de votre choix de vos monstres "Maître Dragon" bannis d''Attributs différents; renvoyez-les au Cimetière. \r\nVous ne pouvez utiliser qu''1 effet de "Ici Sont des Dragons" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet de récupération','Invocation Xyz ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4582942,'Rythme Suivi Vaalmonica',replace(replace('Appliquez 1 de ces effets. \r\nVous devez contrôler une Carte Monstre "Vaalmonica" pour activer et résoudre cet effet. \r\nSi vous contrôlez un Monstre Lien "Vaalmonica", vous pouvez appliquer les deux effets dans l''ordre.\r\n● Gagnez 500 LP, puis vous pouvez détruire 1 Magie/Piège sur le Terrain.\r\n● Recevez 500 points de dommages, puis vous pouvez renvoyer 1 monstre depuis le Terrain à la main.	\r\nVous ne pouvez activer qu''1 "Rythme Suivi Vaalmonica" par tour.','\r',char(13)),'\n',char(10)),'','Gagnez 500 LP','Subissez 500 dommages','Appliquer les deux','Détruire 1 Carte Magie/Piège sur le Terrain ?','Renvoyer 1 monstre sur le Terrain à la main ?','','','','','','','','','','');
INSERT INTO texts VALUES(4587638,'Terre Rugissante',replace(replace('Si un monstre de Type Bête que vous contrôlez attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire. \r\nSi vous infligez des dommages de combat à votre adversaire avec cet effet: ciblez 1 monstre face recto contrôlé par votre adversaire; la cible perd 500 ATK/DEF. \r\n(Ceci est valide même si cette carte quitte le Terrain.)','\r',char(13)),'\n',char(10)),'Diminuer l''ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4591250,'Impératrice Amazonesse',replace(replace('"Reine Amazonesse" + 1 monstre "Amazonesse"	\r\nLes autres cartes "Amazonesse" que vous contrôlez ne peuvent être détruites ni au combat ni par des effets de carte. \r\nSi votre monstre "Amazonesse" attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire. \r\nSi cette carte face recto Invoquée par Fusion est détruite au combat, ou quitte le Terrain à cause d''un effet de carte de l''adversaire tant que son propriétaire la contrôle: vous pouvez Invoquer Spécialement 1 "Reine Amazonesse" depuis votre main, Deck ou Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4599182,'Ce Sinistre Petit Vaurien',replace(replace('(Cette carte est toujours traitée comme carte "Enfernité".)	\r\nInvoquez Spécialement 1 de vos monstres "Enfernité" qui est banni, ou dans votre main ou Cimetière. \r\nSi un ou plusieurs monstres "Enfernité" face recto que vous contrôlez sont détruits au combat, ou quittent le Terrain à cause d''un effet de carte de l''adversaire, tant que cette carte est dans votre Cimetière: vous pouvez Poser cette carte. \r\nVous ne pouvez utiliser chaque effet de "Ce Sinistre Petit Vaurien" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4606229,'Dernier Espoir des Numéros',replace(replace('(Cette carte est toujours traitée comme une carte "Yeux Galactiques".)	\r\nPayez la moitié de vos LP, puis ciblez 2 monstres dans votre Cimetière; Invoquez-les Spécialement tous les deux, mais annulez leurs effets, puis, immédiatement après la résolution de cet effet, Invoquez par Xyz 1 Monstre Xyz "Numéro" en utilisant uniquement ces 2 monstres, et aussi, le reste de ce tour après la résolution de cette carte, vous ne pouvez Invoquer Spécialement qu''une fois de plus depuis l''Extra Deck. \r\nVous ne pouvez activer qu''1 "Dernier Espoir des Numéros" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4611269,'Alligator Lion','Tant que vous contrôlez un autre monstre Reptile, si un monstre Reptile que vous contrôlez attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4611341,'Mystify de la Force-S',replace(replace('2+ monstres (un monstre "Force-S" inclus)	\r\nTant que votre adversaire contrôle un monstre dans la colonne de cette carte, il ne peut ni cibler cette carte avec des effets de carte ni Invoquer Spécialement par un effet de monstre activé. \r\n(Effet Rapide): vous pouvez cibler 1 monstre sur le Terrain; déplacez-le dans une autre Zone Monstre Main sur le Terrain de son contrôleur. \r\nVous ne pouvez utiliser cet effet de "Mystify de la Force-S" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Déplacer','Sélectionnez le monstre à déplacer','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4614116,'Énergie Sombre','Un monstre de Type Démon équipé de cette carte augmente son ATK et sa DEF de 300 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4628897,'Imperion Magnum le Bot de Combat Supraconducteur',replace(replace('"Valkyrion, le Guerrier Magnétique" + "Berserkion, le Guerrier Magnétique Électrique"	\r\nUniquement Invocable par Fusion avec les Matériels de Fusion ci-dessus et non Invocable Spécialement autrement. \r\nUne fois par tour, durant le tour de chaque joueur, lorsque votre adversaire active une Carte Magie/Piège ou un effet de monstre: vous pouvez annuler l''activation, et si vous le faites, détruisez la carte. \r\nSi cette carte face recto contrôlée par son propriétaire quitte le Terrain à cause d''un effet de carte de l''adversaire: vous pouvez Invoquer Spécialement 1 "Valkyrion, le Guerrier Magnétique" ainsi qu''1 "Berserkion, le Guerrier Magnétique Électrique" depuis votre main et/ou Deck, en ignorant leurs conditions d''Invocation.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4632019,'Yamatako Orochi',replace(replace('Cette carte sur le Terrain peut être traitée comme un monstre de Niveau 8 lorsqu''elle est utilisée pour une Invocation Synchro. \r\nUn Monstre Synchro qui a utilisé cette carte comme Matériel gagne cet effet selon son Niveau d''origine.\r\n● Max. 8: Gagne 800 ATK/DEF.\r\n● Min. 9: Si cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','\r',char(13)),'\n',char(10)),'L''effet de "Yamatako Orochi" est actuellement appliqué.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4638410,'Intimidation du Tyran',replace(replace('Sacrifiez 1 monstre pour activer cette carte. \r\nTous vos monstres face recto sur le Terrain ne sont pas affectés par les autres Cartes Piège.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4647954,'ZS - Sage Ascensionné',replace(replace('Si vous ne contrôlez aucune carte, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nUn Monstre Xyz "Utopie" qui a été Invoqué en utilisant cette carte sur le Terrain comme Matériel gagne cet effet.\r\n● Si cette carte est Invoquée par Xyz: vous pouvez ajouter 1 Magie Normale "Magie-Rang-Plus" depuis votre Deck à votre main.	\r\nVous ne pouvez utiliser cet effet de "ZS - Sage Ascensionné" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Ajouter une Magie d''Ascension à la main (ZS - Sage Ascensionné)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4663194,'Ville-Prison de la Tour de l''Horloge - Ville Ténébreuse',replace(replace('Chaque fois que vous Invoquez Spécialement un ou plusieurs monstres "HÉROS de la Destinée" de min. Niveau 8: tous les monstres Guerrier que vous contrôlez actuellement gagnent 300 ATK.\r\nVous ne pouvez utiliser chacun des effets suivants de "Ville-Prison de la Tour de l''Horloge - Ville Ténébreuse" qu''une fois par tour.\r\nDurant votre Main Phase, si cette carte a été activée ce tour: vous pouvez ajouter 1 monstre "HÉROS de la Destinée", ou 1 carte qui mentionne un nom de carte de monstre "HÉROS de la Destinée", depuis votre Deck à votre main.\r\nSi cette carte est détruite: vous pouvez Invoquer Spécialement 1 monstre "HÉROS de la Destinée" depuis votre Deck (ceci est traité comme une Invocation Spéciale avec "Prison de la Tour de l''Horloge").','\r',char(13)),'\n',char(10)),'Ajouter à la main','Augmenter l''ATK','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4682617,'Rappel d''Acteur des Abysses',replace(replace('Si une Carte Magie ou effet de Magie "Script des Abysses" est activé ce tour: ajoutez un nombre de Monstres Pendule "Acteur des Abysses" face recto depuis votre Extra Deck à votre main, inférieur ou égal au nombre de Magies "Script des Abysses" dans votre Cimetière. \r\nPuis, vous pouvez Invoquer Spécialement un nombre de Monstres Pendule "Acteur des Abysses" depuis votre main de noms différents, inférieur ou égal au nombre de monstres ajoutés à la main par cet effet. \r\nVous ne pouvez pas Invoquer Spécialement de monstres (Monstres Pendule "Acteur des Abysses" exclus) le reste de ce tour. \r\nVous ne pouvez activer qu''1 "Rappel d''Acteur des Abysses" par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4688231,'Mithrilium Métalphose',replace(replace('1 monstre "Métalphose" + 1 Monstre Pendule	\r\nVous pouvez cibler 2 cartes "Métalphose" dans votre Cimetière et 1 carte sur le Terrain; mélangez les cibles depuis votre Cimetière dans le Deck, et si vous le faites, renvoyez la cible sur le Terrain à la main. \r\nVous ne pouvez utiliser cet effet de "Mithrilium Métalphose" qu''une fois par tour. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez Invoquer Spécialement 1 Monstre Pendule "Métalphose" depuis votre Cimetière ou Extra Deck face recto.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4694209,'Garde des Cartes',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: placez 1 Compteur Garde sur elle. \r\nCette carte gagne 300 ATK pour chaque Compteur Garde sur elle. \r\nUne fois par tour: vous pouvez cibler 1 autre carte face recto que vous contrôlez; retirez 1 Compteur Garde de cette carte, et si vous le faites, placez 1 Compteur Garde sur la cible (si jamais la carte va être détruite, retirez-lui 1 Compteur Garde à la place).','\r',char(13)),'\n',char(10)),'Placer un marqueur','Déplacer des marqueurs','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4709881,'Auram le Maître des Épées du Calice du Monde',replace(replace('2 monstres "Calice du Monde"	\r\nGagne 300 ATK pour chaque monstre "Héritage du Monde" dans votre Cimetière de nom différent. \r\nVous pouvez Sacrifier 1 monstre "Calice du Monde" pointé par cette carte, puis ciblez 1 autre monstre dans votre Cimetière; Invoquez-le Spécialement dans votre zone pointée par cette carte. \r\nVous ne pouvez utiliser cet effet de "Auram le Maître des Épées du Calice du Monde" qu''une fois par tour. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez Invoquer Spécialement 1 monstre "Calice du Monde" depuis votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4722253,'Gearfried Rayon Lumineux',replace(replace('Ni Invocable Normalement ni Posable. \r\nUniquement Invocable Spécialement (depuis votre main) en ayant min. 5 monstres LUMIÈRE de noms différents dans votre Cimetière et non Invocable Spécialement autrement. \r\nUne fois par tour, durant le tour de chaque joueur, lorsqu''une Carte Magie/Piège est activée: vous pouvez bannir 1 monstre de Type Guerrier depuis votre Cimetière; annulez l''activation, et si vous le faites, détruisez-la. \r\nTous les monstres face recto que vous contrôlez doivent être de Type Guerrier pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4729591,'Balance Kappa Électroménageur',replace(replace('1 monstre "Électroménageur"	\r\nNon utilisable comme Matériel Lien le tour où elle est Invoquée par Lien. \r\nVous pouvez Sacrifier cette carte co-liée; Invoquez Spécialement 1 Monstre Lien "Électroménageur" ("Balance Kappa Électroménageur" exclu) depuis votre Cimetière. \r\nVous pouvez Sacrifier cette carte qui n''est pas co-liée; Invoquez Spécialement 1 monstre "Électroménageur" de max. Niveau 4 depuis votre Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Balance Kappa Électroménageur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4731783,'Á Bao A Qou, l''Ombre Sans Lumière',replace(replace('2+ monstres (un monstre Démon inclus)	\r\nDurant la Main Phase (Effet Rapide): vous pouvez défausser 1 carte, puis activez 1 de ces effets;\r\n● Détruisez 1 carte sur le Terrain.\r\n● Bannissez cette carte (jusqu''à la End Phase), et si vous le faites, Invoquez Spécialement 1 monstre LUMIÈRE ou TÉNÈBRES depuis votre Cimetière.	\r\nDurant votre Standby Phase: vous pouvez piocher un nombre de cartes égal au nombre de Types de Monstre différents dans votre Cimetière, puis placez un nombre de cartes depuis votre main au-dessous du Deck dans l''ordre de votre choix, égal au nombre de cartes que vous avez piochées. \r\nVous ne pouvez utiliser chaque effet de "Á Bao A Qou, l''Ombre Sans Lumière" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer l''effet','Piocher','Détruire','Bannir et Invoquer Spécialement','','','','','','','','','','','','');
INSERT INTO texts VALUES(4731784,'Á Bao A Qou, l''Ombre Sans Lumière',replace(replace('2+ monstres (un monstre Démon inclus)	\r\nDurant la Main Phase (Effet Rapide): vous pouvez défausser 1 carte, puis activez 1 de ces effets;\r\n● Détruisez 1 carte sur le Terrain.\r\n● Bannissez cette carte (jusqu''à la End Phase), et si vous le faites, Invoquez Spécialement 1 monstre LUMIÈRE ou TÉNÈBRES depuis votre Cimetière.	\r\nDurant votre Standby Phase: vous pouvez piocher un nombre de cartes égal au nombre de Types de Monstre différents dans votre Cimetière, puis placez un nombre de cartes depuis votre main au-dessous du Deck dans l''ordre de votre choix, égal au nombre de cartes que vous avez piochées. \r\nVous ne pouvez utiliser chaque effet de "Á Bao A Qou, l''Ombre Sans Lumière" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer l''effet','Piocher','Détruire','Bannir et Invoquer Spécialement','','','','','','','','','','','','');
INSERT INTO texts VALUES(4732017,'Zombie en Fusion','Lorsque cette carte est Invoquée Spécialement depuis le Cimetière: piochez 1 carte.','Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4740489,'Champ Magnétique',replace(replace('Si vous contrôlez un monstre TERRE Rocher de max. Niveau 4: vous pouvez cibler 1 monstre "Guerrier Magnétique" de max. Niveau 4 dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser cet effet de "Champ Magnétique" qu''une fois par tour. \r\nUne fois par tour, à la fin de la Damage Step, lorsqu''un monstre TERRE Rocher que vous contrôlez a combattu un monstre de l''adversaire, mais que le monstre de l''adversaire n''a pas été détruit au combat: vous pouvez renvoyer le monstre de l''adversaire à la main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4754691,'Bugroth Amphibie MK-11',replace(replace('Tant que "Umi" n''est pas sur le Terrain, cette carte gagne 700 ATK, et aussi, elle ne peut pas attaquer directement. \r\nTant que "Umi" est sur le Terrain: vous pouvez cibler 1 monstre non-EAU face recto sur le Terrain; détruisez-le. \r\nVous ne pouvez utiliser cet effet de "Bugroth Amphibie MK-11" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4756629,'Kerykeion Colonie du Mal',replace(replace('Vous ne pouvez utiliser chaque effet de "Kerykeion Colonie du Mal" qu''une fois par tour. \r\nTant que cette carte est dans le Cimetière, si elle y a été envoyée ce tour, vous pouvez Invoquer Normalement 1 monstre "Colonie" avec 1 Sacrifice en moins.\r\nVous pouvez bannir 1 monstre "Colonie" depuis votre Cimetière, puis ciblez 1 monstre "Colonie" dans votre Cimetière; ajoutez la cible à votre main, et aussi, cette carte gagne l''effet suivant.\r\n● Ce tour: vous pouvez activer cet effet; Invoquez Normalement 1 monstre "Colonie".','\r',char(13)),'\n',char(10)),'Ajouter à la main 1 monstre depuis votre Cimetière dont le nom contient "Colonie"','Invoquer 1 monstre dont le nom contient "Colonie"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4779091,'Yubel - Terreur Incarnée',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement avec "Yubel". \r\nNon destructible au combat. \r\nVous ne recevez aucun dommage de combat de combats impliquant cette carte. \r\nAvant le calcul des dommages, si cette carte en Position d''Attaque face recto est ciblée par une attaque: infligez des dommages à votre adversaire égaux à l''ATK du monstre attaquant. \r\nUne fois par tour, durant votre End Phase: détruisez tous les autres monstres sur le Terrain. \r\nLorsque cette carte face recto quitte le Terrain: vous pouvez Invoquer Spécialement 1 "Yubel - Cauchemar Ultime" depuis votre main, Deck ou Cimetière.','\r',char(13)),'\n',char(10)),'Infliger des dommages','Détruire','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4779823,'Michael le Grand, Seigneur Lumière',replace(replace('1 Syntoniseur + min. 1 monstre non-Syntoniseur LUMIÈRE	\r\nUne fois par tour: vous pouvez payer 1000 LP, puis ciblez 1 carte sur le Terrain; bannissez la cible. \r\nLorsque cette carte est détruite: vous pouvez cibler un nombre de votre choix de monstres "Seigneur Lumière" dans votre Cimetière (cette carte exclue); mélangez-les dans le Deck, et si vous le faites, vous gagnez 300 LP pour chaque carte renvoyée. \r\nUne fois par tour, durant votre End Phase: envoyez les 3 cartes du dessus de votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'Bannir','Renvoyer au Deck','Envoyer au Cimetière','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4786063,'Armure de Feu Âme Samouraï Supralourd',replace(replace('Vous pouvez cibler 1 monstre "Samouraï Supralourd" que vous contrôlez; équipez ce monstre depuis votre main ou votre Terrain à la cible. \r\nSon Niveau devient 5. \r\nDurant le tour de chaque joueur: vous pouvez défausser cette carte, puis ciblez 1 monstre "Samouraï Supralourd" en Position de Défense que vous contrôlez; jusqu''à la fin de ce tour, il perd 800 DEF, mais il ne peut être détruit ni au combat ni par des effets de carte.','\r',char(13)),'\n',char(10)),'Équiper','Ne peut pas être détruit','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4796100,'Chimère, Bête Mythique Volante',replace(replace('"Gazelle, Roi des Bêtes Mythiques" + "Berfomet"	\r\n(Cette carte est toujours traitée comme une carte "Bête Fantôme".)	\r\nLorsque cette carte est détruite: vous pouvez cibler 1 "Berfomet" ou 1 "Gazelle, Roi des Bêtes Mythiques" dans votre Cimetière; Invoquez Spécialement la cible.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4807253,'Mangeur de Flammes Mageartiste',replace(replace('Durant le tour de chaque joueur, lorsqu''une carte ou un effet qui va vous infliger des dommages est activé: vous pouvez activer cet effet; le reste de ce tour, vous ne pouvez pas Invoquer Spécialement de monstres (monstres "Mageartiste" exclus), et aussi, Invoquez Spécialement cette carte depuis votre main, et si vous le faites, faites devenir ces dommages d''effet sur vous 0. \r\nSi elle est Invoquée de cette façon, bannissez-la lorsqu''elle quitte le Terrain. \r\nSi cette carte est Invoquée Normalement ou Spécialement: chaque joueur reçoit 500 points de dommages.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4810585,'Saga des Guerriers Anciens - La Défense de Changban',replace(replace('Si votre monstre "Guerriers Anciens" combat, votre adversaire ne peut pas activer de Cartes Magie/Piège jusqu''à la fin de la Damage Step. \r\nVous ne pouvez utiliser qu''1 des effets suivants de "Saga des Guerriers Anciens - La Défense de Changban" par tour, et uniquement une fois le tour.\r\n● Au début de la Battle Phase de votre adversaire: vous pouvez envoyer cette carte face recto depuis votre Zone Magie & Piège au Cimetière; ce tour, les monstres contrôlés par votre adversaire ne peuvent pas cibler de monstres "Guerriers Anciens" avec une attaque.\r\n● Lorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 monstre "Guerriers Anciens" depuis votre Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4810828,'Sauravis, l''Ancien et Ascensionné',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Bénédiction des Lutins". \r\nLorsque votre adversaire active une carte ou un effet qui cible un monstre que vous contrôlez (Effet Rapide): vous pouvez défausser cette carte; annulez l''activation. \r\nLorsque votre adversaire va Invoquer Spécialement un ou plusieurs monstres (Effet Rapide): vous pouvez renvoyer cette carte à la main; annulez l''Invocation Spéciale, et si vous le faites, bannissez ces monstres.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4820694,'Tempête de la Constellée',replace(replace('Durant votre End Phase: vous pouvez cibler 2 Monstres Xyz "Constellée" que vous contrôlez avec du Matériel Xyz; détachez tous les Matériels Xyz des deux Monstres Xyz, et si vous le faites, divisez par deux les LP de votre adversaire. \r\nVous ne pouvez utiliser cet effet de "Tempête de la Constellée" qu''une fois par Duel. \r\nUne fois par tour, durant votre Standby Phase: vous pouvez cibler 1 Monstre Xyz "Constellée" que vous contrôlez et 1 monstre "Constellée" dans votre Cimetière; attachez le monstre depuis le Cimetière au Monstre Xyz comme Matériel Xyz.','\r',char(13)),'\n',char(10)),'Changer les LP','Ajouter un Matériel Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4825390,'Livre de Comptes d''Ichiroku','Ciblez max. 2 monstres contrôlés par votre adversaire; bannissez-les jusqu''à la End Phase, puis votre adversaire gagne 1000 LP pour chaque monstre qui a quitté le Terrain par cet effet.','','Sélectionnez le monstre à renvoyer sur le Terrain','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4836680,'Voyant aux Yeux Impairs Potartiste',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nVous pouvez cibler 1 carte "Potartiste" ou "Yeux Impairs" dans votre Cimetière; ajoutez-la à votre main, puis détruisez cette carte. \r\nVous ne pouvez utiliser cet effet de "Voyant aux Yeux Impairs Potartiste" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nDurant votre Main Phase, si vous contrôlez cette carte Invoquée par Pendulation: vous pouvez activer l''effet suivant, selon sa position de combat;\r\n● Position d''Attaque: Vous pouvez bannir cette carte, puis ciblez 1 monstre "Potartiste" ou "Yeux Impairs" dans votre Cimetière; Invoquez-le Spécialement.\r\n● Position de Défense: Prenez 1 Monstre Pendule "Potartiste" ou "Yeux Impairs" depuis votre Deck, et soit ajoutez-le à votre Extra Deck face recto soit envoyez-le au Cimetière.	\r\nVous ne pouvez utiliser cet effet de "Voyant aux Yeux Impairs Potartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à l''Extra Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4837861,'Dragon Astro Meklord Triskélion',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 3 monstres "Meklord" de noms différents depuis votre Cimetière. \r\nUne fois par tour, lorsque cette carte déclare une attaque: vous pouvez regarder l''Extra Deck de votre adversaire et équiper 1 monstre depuis celui-ci à cette carte. \r\nCette carte gagne une ATK égale à la somme des ATK de ces monstres équipés. \r\nTant qu''elle est équipée avec un Monstre Synchro, cette carte peut faire max. 3 attaques sur des monstres durant chaque Battle Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4841383,'Floraison Ragnaraika',replace(replace('Les monstres Insecte, Plante et Reptile sur le Terrain gagnent 300 ATK/DEF, et aussi, tous les autres monstres sur le Terrain perdent 300 ATK/DEF. \r\nDurant votre Main Phase: vous pouvez activer 1 de ces effets;\r\n● Ajoutez 1 monstre "Ragnaraika" depuis votre Deck à votre main, puis défaussez 1 carte.\r\n● Invoquez Spécialement 1 de vos monstres "Ragnaraika" depuis votre main, Cimetière ou bannissement, en Position de Défense.	\r\nVous ne pouvez utiliser cet effet de "Floraison Ragnaraika" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Activer l''effet','Ajouter un monstre "Ragnaraika" à la main','Invoquer Spécialement un monstre "Ragnaraika"','','','','','','','','','','','','');
INSERT INTO texts VALUES(4848423,'Médecin Musclé','Si un joueur va recevoir des dommages de combats impliquant cette carte, il gagne autant de LP à la place.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4849037,'Performance de l''Épée','Vous pouvez Invoquer Rituellement cette carte avec "Danse Inaugurale".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4857085,'Lunettes Oméga',replace(replace('Équipable uniquement à un monstre que vous contrôlez. \r\nUne fois par tour, vous pouvez regarder 1 carte au hasard dans la main de votre adversaire. \r\nLe monstre équipé ne peut pas attaquer le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Révéler votre main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4861205,'L''Appel de la Momie',replace(replace('Une fois par tour: vous pouvez Invoquer Spécialement 1 monstre Zombie depuis votre main. \r\nVous ne devez contrôler aucun monstre pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4869446,'Jugement du Désert','Les positions de combat des monstres qui sont retournés face recto après l''activation de cette carte ne peuvent pas être changées.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4881365,'Chevalier Dragon du Glaive de l''Alligator',replace(replace('Peut attaquer directement.\r\nVous ne pouvez utiliser chacun des effets suivants de "Chevalier Dragon du Glaive de l''Alligator" qu''une fois par tour.\r\nSi cette carte est dans votre main: vous pouvez révéler 1 autre carte dans votre main qui mentionne "Magicien du Temps des Ténèbres"; Invoquez Spécialement cette carte.\r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter max. 2 Magies/Pièges de noms différents l''une de l''autre qui mentionnent "Magicien du Temps des Ténèbres" depuis votre Deck à votre main, puis défaussez 1 carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4891376,'Zalen le Dragon Enchaîné',replace(replace('1 Syntoniseur + 1+ Monstre Synchro	\r\nSi cette carte que vous contrôlez va être utilisée comme Matériel Synchro, vous pouvez la traiter comme non-Syntoniseur. \r\nLorsqu''une carte ou un effet est activé en réponse à l''activation d''une autre carte ou d''un autre effet (Effet Rapide): vous pouvez activer 1 de ces effets;\r\n● Annulez le premier effet, et si vous le faites, détruisez la carte.\r\n● Annulez le deuxième effet, et si vous le faites, détruisez la carte.	\r\nVous ne pouvez utiliser cet effet de "Zalen le Dragon Enchaîné" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Annuler l''effet','Annuler l''effet chaîné','Annuler l''effet auquel on a chaîné','','','','','','','','','','','','');
INSERT INTO texts VALUES(4896788,'Esprit du Pot de Cupidité','Lorsque cette carte est en Position d''Attaque face recto sur le Terrain, si un joueur active un "Pot de Cupidité", il peut piocher une carte supplémentaire.','Utiliser l''effet de "Esprit du Pot de Cupidité" pour piocher ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4904633,'Noyau Marionnette de l''Ombre',replace(replace('Invoquez Spécialement cette carte comme un Monstre à Effet (Magicien/TÉNÈBRES/Niveau 9/ATK 1450/DEF 1950).	\r\n(Cette carte est toujours aussi un Piège.) \r\nSi elle est Invoquée de cette façon, vous pouvez substituer ce monstre à 1 Matériel Fusion qui liste un Attribut sur une Carte Monstre Fusion "Marionnette de l''Ombre". \r\nSi cette carte est envoyée au Cimetière par un effet de carte: vous pouvez cibler 1 Magie/Piège "Marionnette de l''Ombre" ("Noyau Marionnette de l''Ombre" exclu) dans votre Cimetière; ajoutez-le à votre main.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4904812,'Fée Aquatique Genex','Lorsque cette carte est Invoquée Normalement: vous pouvez envoyer 1 monstre EAU depuis votre Deck au Cimetière; ajoutez 1 "Contrôleur Genex" depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4906301,'Protecteur Mortuaire','Durant le tour de votre adversaire: vous pouvez bannir cette carte depuis votre Cimetière; ce tour, annulez la prochaine attaque de monstre contrôlé par votre adversaire (ceci est un Effet Rapide).','Annuler 1 attaque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4909946,'Boss en Parade',replace(replace('Lorsque cette carte est activée: ajoutez 1 monstre "B.E.S." depuis votre Deck à votre main. \r\nUne fois par tour, durant votre Main Phase: vous pouvez détruire 1 monstre dans votre main ou Terrain, et si vous le faites, Invoquez Spécialement 1 monstre LUMIÈRE Machine avec 1200 ATK et max. 1000 DEF depuis votre Deck sur l''un des Terrains. \r\nVous pouvez bannir cette carte depuis votre Cimetière; placez face recto 1 "Campagne de Recrutement" depuis votre Deck ou Cimetière sur votre Terrain. \r\nVous ne pouvez activer qu''1 "Boss en Parade" par tour.','\r',char(13)),'\n',char(10)),'Activer','Invocation Spéciale','Placer','Invoquer Spécialement sur le Terrain de l''adversaire ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(4914353,'Isolant de l''Espace',replace(replace('2 monstres	\r\nLes monstres pointés par cette carte perdent 800 ATK/DEF. \r\nLorsqu''un Monstre Lien Cyberse est Invoqué par Lien sur votre Terrain, tant que cette carte dans le Cimetière, sauf le tour où cette carte a été envoyée au Cimetière: vous pouvez Invoquer Spécialement cette carte dans votre zone pointée par le monstre, mais elle ne peut pas être utilisée comme Matériel Lien, et aussi, bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4918855,'Vampire Voivode',replace(replace('Si cette carte est Invoquée Normalement: vous pouvez cibler max. 2 monstres dans le Cimetière de votre adversaire; Invoquez Spécialement ces monstres sur votre Terrain en Position de Défense, mais leurs effets sont annulés. \r\nLorsqu''un effet de monstre est activé, tant qu''un ou plusieurs monstres du même nom que celui-ci sont dans les Cimetières (Effet Rapide): vous pouvez annuler l''activation. \r\nSi un ou plusieurs monstres sont Invoqués Spécialement depuis le Cimetière de votre adversaire: vous pouvez Sacrifier 2 monstres; Invoquez Spécialement cette carte depuis votre Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Vampire Voivode" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Annuler l''activation','Invoquer Spécialement cette carte','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4920010,'Âmes des Oubliés','Esprit malfaisant créé à partir des âmes haineuses de ceux qui sont tombés au combat. Il grandit en assimilant les âmes de ses adversaires.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4923662,'Explosion Chaotique','Lorsqu''un monstre de votre adversaire déclare une attaque: Sacrifiez 1 monstre, puis ciblez le monstre attaquant; détruisez la cible, puis infligez 1000 points de dommages à votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4928565,'Kashtira des Tiarmentations',replace(replace('Durant la Main Phase (Effet Rapide): vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, bannissez 1 carte "Kashtira" ou "Tiarmentations" depuis votre main ou Cimetière. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez envoyer les 3 cartes du dessus du Deck de l''un des joueurs au Cimetière. \r\nSi cette carte est envoyée au Cimetière par un effet de carte: vous pouvez envoyer les 2 cartes du dessus de votre Deck au Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Kashtira des Tiarmentations" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Envoyer les 3 cartes du dessus de votre Deck au Cimetière','Envoyer les 3 cartes du dessus du Deck de votre adversaire au Cimetière','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4929256,'Mobius le Monarque de Glace','Lorsque cette carte est Invoquée par Sacrifice: vous pouvez cibler max. 2 Magies/Pièges sur le Terrain; détruisez les cibles.','Détruire jusqu''à 2 Cartes Magie/Piège sur le Terrain','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4931121,'Virus Force Maximum','Sacrifiez 1 monstre TÉNÈBRES avec min. 2000 DEF; regardez la main de votre adversaire, tous les monstres qu''il contrôle et toutes les cartes qu''il pioche jusqu''à la fin de son 3e tour après la résolution de cette carte, et détruisez tous ces monstres avec max. 1500 DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4931562,'Guerrier des montagnes','Redoutable guerrier capable de se déplacer facilement sur les terrains les plus difficiles.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4939890,'Hérisson Marionnette de l''Ombre',replace(replace('FLIP: Vous pouvez ajouter 1 Magie/Piège "Marionnette de l''Ombre" depuis votre Deck à votre main.\r\nSi cette carte est envoyée au Cimetière par un effet de carte: vous pouvez ajouter 1 monstre "Marionnette de l''Ombre" ("Hérisson Marionnette de l''Ombre" exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Hérisson Marionnette de l''Ombre" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Ajouter une Magie/Piège à la main','Ajouter un monstre à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4941482,'Araignée Espion','Lorsque cette carte est envoyée depuis le Terrain au Cimetière par l''effet d''une carte, prenez le contrôle d''un monstre en Position de Défense contrôlé par votre adversaire.','Prendre le contrôle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4965193,'Chasma, Maître Dragon des Aurores',replace(replace('2 monstres Dragon de Niveau 7	\r\n(Effet Rapide): vous pouvez envoyer 1 monstre "Maître Dragon" de Niveau 7 depuis votre Deck au Cimetière, et détachez 1 Matériel de cette carte; cet effet devient l''effet du monstre envoyé qui se défausse pour l''activer. \r\nSi cette carte est détruite au combat, ou si cette carte en possession de son propriétaire est détruite par un effet de carte de l''adversaire: vous pouvez Invoquer Spécialement 1 monstre "Maître Dragon" de Niveau 7 depuis votre Cimetière ou bannissement. \r\nVous ne pouvez utiliser chaque effet de "Chasma, Maître Dragon des Aurores" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Copier l''effet','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4991081,'Dragon de Harpie - Souffle de Feu Terrible',replace(replace('Les monstres ne peuvent pas cibler de monstres "Harpie" de max. Niveau 6 avec une attaque. \r\nVous ne pouvez utiliser chacun des effets suivants de "Dragon de Harpie - Souffle de Feu Terrible" qu''une fois par tour. \r\nSi vous contrôlez un monstre VENT de max. Niveau 6: vous pouvez Invoquer Spécialement cette carte depuis votre main en Position de Défense. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez envoyer 1 monstre VENT Bête Ailée depuis votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4993187,'W:P Bal Raffiné',replace(replace('2+ Monstres à Effet	\r\nLorsque votre adversaire active un effet de monstre sur le Terrain ou Cimetière (Effet Rapide): jusqu''à la End Phase, vous pouvez bannir cette carte qui a été Invoquée Spécialement ce tour; annulez l''effet, et si vous le faites, bannissez-le. \r\nDurant la Main Phase de votre adversaire, vous pouvez (Effet Rapide): immédiatement après la résolution de cet effet, Invoquez par Lien 1 Monstre Lien, et si cette carte que vous contrôlez va être utilisée comme Matériel pour l''Invocation Lien, vous pouvez aussi utiliser 1 monstre de max. Link-2 contrôlé par votre adversaire. \r\nAucun joueur ne peut activer les effets de Monstres Lien en réponse à l''activation de cet effet. \r\nVous ne pouvez utiliser chaque effet de "W:P Bal Raffiné" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler','Invocation Lien','Bannir jusqu''à la End Phase','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4997565,'Numéro 3 : Roi Cicada',replace(replace('2 monstres de Niveau 3	\r\nSi la position de combat de cette carte est changée: vous pouvez Invoquer Spécialement 1 monstre Insecte depuis votre main ou Cimetière en Position de Défense. \r\nLorsqu''un monstre sur le Terrain active son effet: vous pouvez détacher 1 Matériel de cette carte, puis ciblez le monstre; annulez ses effets, puis, soit faites gagner 500 DEF à 1 monstre Insecte sur le Terrain, soit changez sa position de combat. \r\nVous ne pouvez utiliser chaque effet de "Numéro 3 : Roi Cicada" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Augmenter la DEF','Changer la position de combat','','','','','','','','','','','','');
INSERT INTO texts VALUES(4998619,'Gundil le Béhémoth Cubique Destructeur',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en envoyant 3 monstres "Cubique" que vous contrôlez au Cimetière, et non Invocable Spécialement autrement. \r\nSi elle est Invoquée de cette façon, cette carte gagne 3000 ATK. \r\nCette carte peut faire une seconde et troisième attaque durant chaque Battle Phase. \r\nSi cette carte en votre possession est envoyée à votre Cimetière par une carte de votre adversaire (au combat ou par un effet de carte): vous pouvez cibler max. 3 monstres "Cubique" dans votre Cimetière; Invoquez-les Spécialement, puis vous pouvez ajouter 1 carte "Cubique" depuis votre Deck ou Cimetière à votre main.','\r',char(13)),'\n',char(10)),'Ajouter 1 carte "Cubique" à votre main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5008836,'Éxodia, le Défenseur Légendaire',replace(replace('Non Invocable Spécialement. \r\nVous pouvez Sacrifier 5 monstres pour Invoquer par Sacrifice (mais pas Poser) cette carte. \r\nL''ATK/DEF de cette carte deviennent la somme des ATK/DEF d''origine des monstres Sacrifiés. \r\nSi cette carte Invoquée de cette façon détruit un monstre TÉNÈBRES Démon dont le propriétaire est votre adversaire, vous gagnez le Duel à la fin de la Damage Step.','\r',char(13)),'\n',char(10)),'Sacrifier 5 monstres pour Invoquer','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5010422,'Astromorrigan, Princesse de la Prédiction','FLIP: Durant la End Phase de ce tour, détruisez autant de monstres en Position de Défense contrôlés par votre adversaire que possible, et si vous le faites, infligez 500 points de dommages à votre adversaire pour chaque monstre détruit.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5014629,'Porte-Submersibles Aéro Requin',replace(replace('2 monstres de Niveau 3	\r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte; infligez 100 points de dommages à votre adversaire pour chacun de vos monstres bannis.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5026221,'Stellnova Vague','Une fois par tour, durant votre Main Phase ou la Battle Phase de votre adversaire: vous pouvez Invoquer Spécialement 1 monstre "tellchevalier" depuis votre main.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5037726,'Hijiri, Artiste de la Lumière Spirituelle','Sacrifiez 1 monstre LUMIÈRE pour cibler 1 monstre banni; votre adversaire peut révéler 1 Carte Piège depuis sa main pour annuler l''effet de cette carte, sinon vous Invoquez Spécialement le monstre.','Révéler 1 Carte Piège à votre adversaire ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5041348,'Draco Berserker du Tenyi',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nLorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez le bannir. \r\nSi cette carte attaquante détruit un Monstre à Effet au combat et l''envoie au Cimetière: cette carte gagne une ATK égale à l''ATK d''origine du monstre détruit, et aussi, elle peut faire une seconde attaque sur un monstre durant cette Battle Phase. \r\nVous ne pouvez utiliser chaque effet de "Draco Berserker du Tenyi" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043010,'Dragon Pare-Feu',replace(replace('2+ monstres	\r\nUne fois, tant que cette carte est face recto sur le Terrain (Effet Rapide): vous pouvez cibler un nombre de monstres sur le Terrain et/ou dans le Cimetière, inférieur ou égal au nombre de monstres co-liés à cette carte; renvoyez-les à la main. \r\nSi un monstre pointé par cette carte est détruit au combat ou envoyé au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Cyberse depuis votre main. \r\nVous ne pouvez utiliser chaque effet de "Dragon Pare-Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer dans la main de son propriétaire','Invocation Spéciale','Effet déjà activé','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043011,'Dragon Pare-Feu',replace(replace('2+ monstres	\r\nUne fois, tant que cette carte est face recto sur le Terrain (Effet Rapide): vous pouvez cibler un nombre de monstres sur le Terrain et/ou dans le Cimetière, inférieur ou égal au nombre de monstres co-liés à cette carte; renvoyez-les à la main. \r\nSi un monstre pointé par cette carte est détruit au combat ou envoyé au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Cyberse depuis votre main. \r\nVous ne pouvez utiliser chaque effet de "Dragon Pare-Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer dans la main de son propriétaire','Invocation Spéciale','Effet déjà activé','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043012,'Dragon Pare-Feu',replace(replace('2+ monstres	\r\nUne fois, tant que cette carte est face recto sur le Terrain (Effet Rapide): vous pouvez cibler un nombre de monstres sur le Terrain et/ou dans le Cimetière, inférieur ou égal au nombre de monstres co-liés à cette carte; renvoyez-les à la main. \r\nSi un monstre pointé par cette carte est détruit au combat ou envoyé au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Cyberse depuis votre main. \r\nVous ne pouvez utiliser chaque effet de "Dragon Pare-Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer dans la main de son propriétaire','Invocation Spéciale','Effet déjà activé','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043013,'Dragon Pare-Feu',replace(replace('2+ monstres	\r\nUne fois, tant que cette carte est face recto sur le Terrain (Effet Rapide): vous pouvez cibler un nombre de monstres sur le Terrain et/ou dans le Cimetière, inférieur ou égal au nombre de monstres co-liés à cette carte; renvoyez-les à la main. \r\nSi un monstre pointé par cette carte est détruit au combat ou envoyé au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Cyberse depuis votre main. \r\nVous ne pouvez utiliser chaque effet de "Dragon Pare-Feu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer dans la main de son propriétaire','Invocation Spéciale','Effet déjà activé','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5050644,'Jardin d''Arôma',replace(replace('Une fois par tour, si vous contrôlez un monstre "Arôma": vous pouvez gagner 500 LP, et aussi, tous les monstres que vous contrôlez gagnent 500 ATK/DEF jusqu''à la fin du prochain tour de votre adversaire (même si cette carte quitte le Terrain). \r\nSi un monstre "Arôma" face recto que vous contrôlez est détruit au combat ou par un effet de carte, et envoyé au Cimetière: gagnez 1000 LP.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5052212,'Syntonisation de Combat',replace(replace('Retirez du jeu 1 monstre Syntoniseur depuis votre Cimetière. \r\nCiblez un monstre face recto que vous contrôlez, il gagne un montant d''ATK égal à l''ATK du monstre retiré.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5053103,'Bœuf de Combat','Monstre à la puissance foudroyante qui détruit ses ennemis d''un simple coup de hache.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5063379,'Flavian - Colisée de la Bête Gladiateur',replace(replace('Vous pouvez défausser 1 carte; ajoutez 1 monstre "Bête Gladiateur" depuis votre Deck à votre main. \r\nLorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez Invoquer Spécialement 1 monstre "Bête Gladiateur" depuis votre Deck, et il ne peut pas être détruit au combat. \r\nDurant la End Phase, si un monstre "Bête Gladiateur" a été Invoqué Spécialement depuis votre Deck ce tour: vous pouvez Poser 1 Piège "Gladiateur" depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Flavian - Colisée de la Bête Gladiateur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invoquer Spécialement depuis le Deck','Poser depuis le Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5067884,'Spinos Dinobrume',replace(replace('Échelle Pendule = 3\r\n[ Effet Pendule ]\r\nSi une ou plusieurs autres cartes "Dinobrume" que vous contrôlez vont être détruites au combat ou par un effet de carte de votre adversaire, vous pouvez détruire cette carte à la place.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez Sacrifier 1 autre monstre "Dinobrume", puis activez 1 de ces effets;\r\n● Cette carte peut attaquer directement votre adversaire ce tour.\r\n● Cette carte peut faire une seconde attaque durant chaque Battle Phase ce tour.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Spinos Dinobrume" pour remplacer la destruction ?','Attaque directe','Attaques multiples','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5068132,'Cigale du Rêve',replace(replace('Si vous contrôlez un monstre Insecte en Position d''Attaque, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Cigale du Rêve" qu''une fois par tour de cette façon. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre sur le Terrain; changez sa position de combat. \r\nVous ne pouvez utiliser cet effet de "Cigale du Rêve" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5087128,'Dragon Cartourokkette',replace(replace('Lorsqu''un effet de Monstre Lien qui cible cette carte face recto sur le Terrain est activé (Effet Rapide): vous pouvez détruire cette carte, puis détruisez 1 monstre dans la colonne où était cette carte, et si vous le faites, détruisez les monstres dans les zones adjacentes de la carte. \r\nDurant la End Phase, si cette carte est dans le Cimetière parce qu''elle a été détruite sur le Terrain au combat ou par un effet de carte et y a été envoyée ce tour: vous pouvez Invoquer Spécialement 1 monstre "Rokkette" ("Dragon Cartourokkette" exclu) depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Dragon Cartourokkette" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5088741,'Codeur Igniteur',replace(replace('2 monstres de Niveau 4	\r\nSi cette carte est Invoquée par Xyz: vous pouvez ajouter 1 Monstre Rituel Cyberse depuis votre Deck à votre main. \r\nVous pouvez détacher 1 Matériel de cette carte; Invoquez Rituellement 1 Monstre Rituel depuis votre main, en Sacrifiant des monstres depuis votre main ou Terrain dont le Niveau total est supérieur ou égal à son Niveau. \r\nSi cette carte est envoyée au Cimetière comme Matériel Lien: vous pouvez ajouter 1 Piège "A.I." depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Codeur Igniteur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet d''ajout à la main','Invocation Rituel','Ajouter à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5109321,'Débarquement sur Scène R.B.',replace(replace('Invoquez Spécialement 1 monstre "R.B." depuis votre Deck/Extra Deck de nom différent des cartes que vous contrôlez. \r\nSi un ou plusieurs monstres "R.B." que vous contrôlez vont être détruits au combat ou par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière à la place. \r\nVous ne pouvez pas Invoquer Spécialement (monstres Machine avec max. 1500 ATK d''origine exclus) depuis l''Extra Deck le tour où vous activez cette carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Remplacement de destruction','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5121528,'B.E.S. Derringer Core',replace(replace('Vous pouvez révéler 1 autre monstre "B.E.S." dans votre main; Invoquez Spécialement cette carte depuis votre main, puis placez 3 Compteurs sur cette carte. \r\nDurant la Main Phase (Effet Rapide): vous pouvez retirer 1 Compteur de cette carte, et activez 1 de ces effets;\r\n● Ajoutez 1 "Campagne de Recrutement" ou 1 Magie/Piège qui le mentionne depuis votre Deck à votre main.\r\n● Invoquez Spécialement 1 monstre "B.E.S." de max. Niveau 9 depuis votre Cimetière.	\r\nVous ne pouvez utiliser chaque effet de "B.E.S. Derringer Core" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Choisir un effet','Effet d''ajout à la main','Invocation Spéciale','','','','','','','','','','','','');
INSERT INTO texts VALUES(5125629,'Révolution Conceptuelle Corrompue',replace(replace('Vous pouvez activer cette carte depuis votre main en payant la moitié de vos LP.\r\nAjoutez à votre main, ou placez face recto dans votre Zone Terrain, 1 "Monde Corrompu" depuis votre Deck ou Cimetière, puis Invoquez Spécialement 1 monstre "Corrompu" depuis votre Deck ou Extra Deck en Position de Défense, en ignorant ses conditions d''Invocation, puis si votre adversaire contrôle un monstre avec min. 2500 ATK, tous les monstres face recto qu''il contrôle actuellement perdent 2500 ATK jusqu''à la fin de ce tour.\r\nVous ne pouvez activer qu''1 "Révolution Conceptuelle Corrompue" par tour.','\r',char(13)),'\n',char(10)),'Activer','Placer face recto','Activer en appliquant l''effet de "Révolution Conceptuelle Corrompue".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5126490,'Néos le Sage',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en envoyant 1 "Néos, HÉROS Élémentaire" face recto et 1 "Yubel" face recto que vous contrôlez au Cimetière. \r\nNon destructible par des effets de carte. À la fin de la Damage Step, si cette carte a combattu un monstre de l''adversaire: infligez des dommages à votre adversaire égaux à l''ATK du monstre de l''adversaire, et aussi, vous gagnez des LP égaux à la DEF du monstre de l''adversaire.','\r',char(13)),'\n',char(10)),'Gagner des LP et infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5128859,'Néos Marin, HÉROS Élémentaire',replace(replace('"Néos, HÉROS Élémentaire" + "Dauphin Marin Néo-Spacien"	\r\nDoit d''abord être Invoquée Spécialement (depuis votre Extra Deck) en mélangeant les cartes ci-dessus que vous contrôlez dans le Deck. \r\n(N''utilisez pas "Polymérisation".) \r\nUne fois par tour: vous pouvez détruire 1 carte au hasard dans la main de votre adversaire.','\r',char(13)),'\n',char(10)),'Défausser depuis la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5130393,'Chercheur Millénaire',replace(replace('Lorsque vous recevez min. 1000 points de dommages de combat ou d''effet: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nVous pouvez cibler 1 monstre dans le Cimetière de votre adversaire (monstres avec ? ATK exclus); votre adversaire peut choisir 1 monstre (monstres avec ? ATK exclus) depuis son Deck. \r\nS''il n''en choisit pas, ou si le monstre ciblé a une ATK supérieure au monstre choisi, Invoquez Spécialement le monstre ciblé sur votre Terrain, et si vous le faites, mélangez le monstre choisi dans le Deck. \r\nSinon, votre adversaire ajoute le monstre choisi à la main. \r\nVous ne pouvez utiliser chaque effet de "Chercheur Millénaire" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Sélectionner 1 monstre depuis votre Deck ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5133471,'Cyclone Galactique',replace(replace('Ciblez 1 Magie/Piège Posé sur le Terrain; détruisez-le. \r\nDurant votre Main Phase, sauf le tour où cette carte a été envoyée au Cimetière: vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Magie/Piège face recto sur le Terrain; détruisez-le. \r\nVous ne pouvez utiliser cet effet de "Cyclone Galactique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Détruire une Magie/Piège Posée','Détruire une Magie/Piège face recto','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5141117,'Âmépée - Le Dragon des Abysses',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement par un effet de monstre Wyrm. \r\nSi un monstre est banni par un effet de carte (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis le Cimetière (si elle y était lorsque le monstre a été banni) ou la main (même si elle n''y était pas), mais bannissez-la lorsqu''elle quitte le Terrain. \r\nSi cette carte est Invoquée Spécialement: vous pouvez cibler 1 carte dans la Zone Terrain et 1 monstre contrôlé par votre adversaire ou dans son Cimetière; bannissez-les. \r\nVous ne pouvez utiliser chaque effet de "Âmépée - Le Dragon des Abysses" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5148778,'Dragon Ailé Venin Affamé',replace(replace('Échelle Pendule = 10\r\n[ Effet Pendule ]\r\nChaque fois qu''un ou plusieurs monstres sont Invoqués Spécialement sur le Terrain de votre adversaire, placez 1 Compteur Prédateur sur celui-ci, et s''il est min. Niveau 2, il devient Niveau 1 tant qu''il a un Compteur Prédateur.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\n1 Monstre Fusion + 1 monstre "Aile Claire"	\r\nUne fois par tour, si votre adversaire Invoque Spécialement face recto un ou plusieurs monstres (sauf durant la Damage Step): vous pouvez en cibler 1; cette carte gagne une ATK égale à l''ATK du monstre, et si elle le fait, les effets du monstre sont annulés. \r\nCes changements durent jusqu''à la fin de ce tour. \r\nUne fois par tour, lorsqu''une autre carte ou son effet est activé sur le Terrain (Effet Rapide): vous pouvez détruire 1 carte sur le Terrain. \r\nSi cette carte dans la Zone Monstre est détruite: vous pouvez placer cette carte dans votre Zone Pendule.','\r',char(13)),'\n',char(10)),'','Annuler et augmenter l''ATK','Effet de destruction','Placer dans la Zone Pendule','','','','','','','','','','','','');
INSERT INTO texts VALUES(5153769,'Rafale Majesspectre','Ciblez 1 carte "Majesspectre" dans votre Zone Pendule; Invoquez-la Spécialement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5168381,'Effroyable Ruse de l''Archdémon','Si vous contrôlez un monstre Démon: ciblez 1 carte sur le Terrain; détruisez-la, puis, vous pouvez envoyer 1 monstre Démon depuis votre Deck au Cimetière.','Envoyer 1 monstre Démon depuis votre Deck au Cimetière ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5177985,'Maître de l''Épée Shiranui',replace(replace('Si cette carte est dans votre Cimetière et que vous contrôlez min. 2 monstres "Shiranui" de noms différents: vous pouvez Invoquer Spécialement cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nSi cette carte est bannie: vous pouvez cibler 1 monstre Zombie que vous contrôlez; jusqu''à la fin de ce tour, il gagne 600 ATK. \r\nVous ne pouvez utiliser chaque effet de "Maître de l''Épée Shiranui" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5182107,'Sécurité Samouraï Supralourd',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 Monstre Pendule Machine face recto depuis votre Extra Deck à votre main. \r\nSi vous n''avez aucun Magie/Piège dans votre Cimetière: vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 monstre TERRE Machine avec max. 1500 ATK ("Sécurité Samouraï Supralourd" exclu) depuis votre main ou Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Sécurité Samouraï Supralourd" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5183693,'Collier d''Ambition',replace(replace('Équipable uniquement à un Monstre Normal. \r\nS''il combat un monstre de Niveau supérieur, le monstre équipé gagne 500 ATK x la différence de Niveau, durant ce calcul des dommages uniquement. \r\nLorsque cette carte est envoyée au Cimetière: vous pouvez la placer au-dessus de votre Deck.','\r',char(13)),'\n',char(10)),'Placer au-dessus du Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5186893,'Dragon Zombie aux Yeux Rouges',replace(replace('Vous pouvez Invoquer par Sacrifice cette carte en Position d''Attaque en Sacrifiant 1 monstre Zombie. \r\nLorsque cette carte détruit un monstre Zombie au combat et l''envoie au Cimetière: vous pouvez Invoquer Spécialement le monstre Zombie.','\r',char(13)),'\n',char(10)),'Sacrifier 1 monstre Zombie pour Invoquer','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5205146,'Rouleau Compresseur Chenillinfini',replace(replace('Si un monstre TERRE Machine est Sacrifié ou banni face recto: vous pouvez Invoquer Spécialement cette carte depuis le Cimetière (si elle y était lorsque le monstre a été Sacrifié ou banni) ou la main (même si elle n''y était pas), mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser cet effet de "Rouleau Compresseur Chenillinfini" qu''une fois par tour. \r\nUn Monstre Xyz dont le Type d''origine est Machine et qui a cette carte comme Matériel gagne cet effet.\r\n● Les monstres face recto contrôlés par votre adversaire sont changés en Position de Défense, et aussi, ils perdent 1000 DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5206415,'Seigneur Dragon du Tonnerre',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 1 monstre Tonnerre de max. Niveau 8 depuis votre main ou Terrain face recto, durant le tour où un effet de monstre Tonnerre a été activé dans la main. \r\nUne fois par tour de l''adversaire (Effet Rapide): vous pouvez bannir 2 cartes (un monstre Tonnerre inclus) depuis votre Cimetière, puis ciblez 1 monstre Tonnerre que vous contrôlez; ce tour, votre adversaire ne peut pas le cibler avec des effets de carte. \r\nUne fois par tour, durant votre End Phase: vous pouvez envoyer 1 carte "Dragon du Tonnerre" depuis votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5208118,'Solution pour le Pendule',replace(replace('Une fois par tour, durant la Standby Phase: placez 1 Compteur T sur cette carte. \r\nUne fois par tour: vous pouvez cibler 1 Monstre Pendule dans votre Zone Monstre Main; pour chaque Compteur T sur cette carte, déplacez le Monstre Pendule dans une Zone Monstre (horizontale) adjacente, 1 déplacement à la fois. \r\nPuis, après avoir fini de déplacer, détruisez tous les Monstres Fusion ou Xyz contrôlés par votre adversaire dans la même colonne (finale), d''un Niveau/Rang inférieur ou égal à l''Échelle Pendule du monstre, et si vous le faites, infligez des dommages à votre adversaire égaux à la somme de leur ATK qu''ils avaient sur le Terrain.','\r',char(13)),'\n',char(10)),'','Sélectionnez le monstre à déplacer','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5220687,'Super Méga Agile Hamster','FLIP: Vous pouvez Invoquer Spécialement 1 monstre Bête de max. Niveau 3 depuis votre Deck en Position de Défense face verso.','Invocation Spéciale','Invoquer Spécialement 1 monstre Bête de Niveau 3 ou moins ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5230799,'Kidbrave, Magie de Mousquetaire',replace(replace('Durant le tour de chaque joueur, vous pouvez activer des Cartes Magie/Piège "Magie de Mousquet" depuis votre main. \r\nSi une Carte Magie/Piège est activée dans la colonne de cette carte: vous pouvez défausser 1 carte "Magie de Mousquet"; piochez 2 cartes. \r\nVous ne pouvez utiliser cet effet de "Kidbrave, Magie de Mousquetaire" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Défausser et piocher','Activer en appliquant l''effet de "Kidbrave, Magie de Mousquetaire".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5237827,'Ohm Vylon','Si cette carte est Invoquée Normalement: ciblez 1 Carte Magie d''Équipement dans votre Cimetière; bannissez la cible, et si vous le faites, ajoutez-la à votre main durant votre prochaine Standby Phase.','Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5244497,'Caméraclops',replace(replace('Si cette carte attaque un monstre face recto sur le Terrain, au début de la Damage Step: détruisez le monstre. \r\nSa DEF doit être supérieure à l''ATK de cette carte pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5253985,'Croisement d''Âmes',replace(replace('Durant la Main Phase: immédiatement après la résolution de cet effet, Invoquez par Sacrifice 1 monstre Bête Divine. \r\nLorsque vous le faites, vous pouvez Sacrifier un ou plusieurs monstres contrôlés par votre adversaire, même si vous ne les contrôlez pas, mais si vous Invoquez par Sacrifice de cette façon, appliquez cet effet.\r\n● Jusqu''à la fin du prochain tour après la résolution de cette carte, vous ne pouvez activer qu''1 carte ou effet par tour, sans prendre en compte les effets des monstres Bête Divine.	\r\nVous ne pouvez activer qu''1 "Croisement d''Âmes" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5255013,'La Voie Zefra',replace(replace('Activez cette carte uniquement si vous avez 2 cartes "Zefra" dans vos Zones Pendule, avec des Échelles Pendule actives de 1 et 7. \r\nSi cette carte est activée: mélangez tous les monstres que vous contrôlez (monstres "Zefra" exclus) dans le Deck. \r\nAucun joueur ne peut Invoquer Spécialement de monstres, sauf depuis la main ou l''Extra Deck. \r\nTant que vous avez une ou plusieurs cartes dans votre Zone Pendule, cette carte ne peut pas être ciblée par des effets de carte. \r\nDétruisez cette carte si une ou plusieurs cartes dans votre Zone Pendule sont détruites.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5257687,'Mâchoires de la Sombre Mort',replace(replace('FLIP: Prenez le contrôle d''1 monstre de votre adversaire jusqu''à la fin de ce tour. \r\nLorsque le monstre contrôlé attaque, il peut attaquer directement les Life Points de votre adversaire.','\r',char(13)),'\n',char(10)),'Prendre le contrôle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5259518,'Héliamphorhynchus Prédaplante',replace(replace('Si votre adversaire contrôle un monstre avec un Compteur Prédateur: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte en possession de son propriétaire est détruite par une carte de votre adversaire: vous pouvez cibler 1 monstre TÉNÈBRES Dragon ou 1 monstre TÉNÈBRES Plante ("Héliamphorhynchus Prédaplante" exclu) dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser chaque effet de "Héliamphorhynchus Prédaplante" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5265750,'Le Squelette des Mers','Navire pirate qui surgit de la brume pour couler tous les vaisseaux des alentours.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5267507,'Esprit de la Terre Immortel Nova Rouge',replace(replace('Il ne peut y avoir qu''1 monstre "Esprit de la Terre Immortel" sur le Terrain. \r\nDurant la Main Phase (Effet Rapide): vous pouvez bannir cette carte depuis votre main ou Cimetière; envoyez 1 "Dragon Rouge Archdémon" ou monstre "Esprit de la Terre Immortel" depuis votre main ou Zone Monstre face recto au Cimetière, puis vous pouvez appliquer 1 de ces effets.\r\n● Invoquez Spécialement 1 monstre "Esprit de la Terre" depuis votre Deck ou Extra Deck.\r\n● Invoquez Spécialement 1 "Dragon Nova Rouge" depuis votre Extra Deck. \r\n(Ceci est traité comme Invocation Synchro.)\r\nVous ne pouvez utiliser cet effet de "Esprit de la Terre Immortel Nova Rouge" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5284653,'Obliviwisp Colonie du Mal','Si cette carte combat un monstre, après le calcul des dommages: annulez les effets du monstre (y compris dans le Cimetière).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5285665,'Néo-Bubbleman, HÉROS Élémentaire',replace(replace('Cette carte ne peut ni être Invoquée par Invocation Normale ni être Posée. \r\nCette carte ne peut pas être Invoquée par Invocation Spéciale, excepté en envoyant "Bubbleman, HÉROS Élémentaire" de votre Terrain et "Métamorphose" de votre main au Cimetière. \r\nLe nom de cette carte est traité comme "Bubbleman, HÉROS Élémentaire" tant qu''elle est face recto sur le Terrain. \r\nDétruisez un monstre de votre adversaire qui combat cette carte à la fin de la Damage Step.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5288597,'Transmodification',replace(replace('Envoyez 1 monstre face recto que vous contrôlez au Cimetière; Invoquez Spécialement 1 monstre du même Type et Attribut que le monstre dans le Cimetière mais avec 1 Niveau de plus depuis votre Deck. \r\nVous ne pouvez activer qu''1 "Transmodification" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5291803,'Gardien Tula Chronomal',replace(replace('S''il y a une Carte Magie de Terrain face recto sur le Terrain, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez contrôler qu''1 "Gardien Tula Chronomal".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5298175,'Aquamarine, Sorcière de la Bonne Aventure',replace(replace('Lorsque vous piochez cette carte: vous pouvez la révéler; Invoquez-la Spécialement depuis votre main. \r\nSi cette carte est Invoquée Spécialement depuis la main: vous pouvez cibler 1 autre monstre face recto sur le Terrain; jusqu''à la Standby Phase de votre prochain tour, bannissez-le. \r\nVous ne pouvez utiliser chaque effet de "Aquamarine, Sorcière de la Bonne Aventure" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5309481,'Roi Ha Dès Ressuscité',replace(replace('"Zombie Épidémique" + 1+ monstre non-Syntoniseur Zombie	\r\nAnnulez les effets des Monstres à Effet détruits au combat avec les monstres Zombie que vous contrôlez.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5318639,'Typhon d''Espace Mystique','Ciblez 1 Magie/Piège sur le Terrain; détruisez la cible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5318640,'Typhon d''Espace Mystique','Ciblez 1 Magie/Piège sur le Terrain; détruisez la cible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5325155,'Tsukahagi, Mayakashi du Poison',replace(replace('Vous ne pouvez contrôler qu''1 "Tsukahagi, Mayakashi du Poison". \r\nSi un ou plusieurs monstres "Mayakashi" ("Tsukahagi, Mayakashi du Poison" exclu) en votre possession sont détruits au combat ou par un effet de carte de l''adversaire, tant que cette carte est dans le Cimetière: vous pouvez Invoquer Spécialement cette carte. \r\nVous ne pouvez pas Invoquer Spécialement de monstres (monstres "Mayakashi" exclus) depuis l''Extra Deck le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5325424,'Dragoncarnation','Ciblez 1 de vos monstres Type Dragon bannis; ajoutez la cible à votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5329790,'Interface Gardna',replace(replace('2 monstres Cyberse	\r\nLes monstres de votre adversaire ne peuvent pas cibler de monstres pointés par cette carte avec une attaque. \r\nLa première fois que cette carte va être détruite au combat chaque tour, elle n''est pas détruite, et vous ne recevez aucun dommage de combat de ce combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5338223,'Force-Évo',replace(replace('Sacrifiez 1 monstre "Évoltile"; Invoquez Spécialement 1 monstre "Évolsaure" depuis votre Deck. \r\n(Ceci est traité comme une Invocation Spéciale par l''effet d''un monstre "Évoltile".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5352328,'Exosœur Sophia',replace(replace('Si vous contrôlez un autre monstre "Exosœur": vous pouvez piocher 1 carte, puis si vous contrôlez "Exosœur Irène", vous gagnez 800 LP. \r\nSi votre adversaire sort une ou plusieurs cartes d''au moins l''un des Cimetières (sauf durant la Damage Step): vous pouvez Invoquer Spécialement 1 Monstre Xyz "Exosœur" depuis votre Extra Deck, en utilisant cette carte face recto que vous contrôlez comme Matériel. \r\n(Ceci est traité comme une Invocation Xyz.) \r\nVous ne pouvez utiliser chaque effet de "Exosœur Sophia" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Invocation Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5361647,'Boxeur Indomptable avec Protège-Dents',replace(replace('Si cette carte est ciblée par une attaque: détruisez cette carte. \r\nLorsque cette carte est envoyée au Cimetière par un effet de carte: vous pouvez cibler 1 monstre "Boxeur Indomptable" ("Boxeur Indomptable avec Protège-Dents" exclu) dans votre Cimetière; ajoutez-le à votre main.','\r',char(13)),'\n',char(10)),'Détruire','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5361816,'Pellinore le Chevalier Noble',replace(replace('Vous pouvez cibler 1 Magie d''Équipement "Armes Nobles" équipée à cette carte et 1 monstre face recto contrôlé par votre adversaire; détruisez-les, puis piochez 1 carte, et aussi, cette carte ne peut pas attaquer le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Pellinore le Chevalier Noble" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5368615,'Steam Gyroid','"Gyroid" + "Steamroid"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5370235,'Chimère Cyberténébreuse',replace(replace('Vous pouvez défausser 1 Magie/Piège; ajoutez 1 "Lien de Puissance" depuis votre Deck à votre main, vous ne pouvez utiliser que des monstres "Cyber" Dragon ou Machine comme Matériel Fusion ce tour, et aussi, une fois, lorsque vous Invoquez par Fusion ce tour, vous pouvez aussi bannir un ou plusieurs monstres depuis votre Cimetière comme Matériel. \r\nSi cette carte est envoyée au Cimetière: vous pouvez envoyer 1 monstre "Cyberténébreu" depuis votre Deck au Cimetière, de nom différent des cartes dans votre Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Chimère Cyberténébreuse" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5371656,'Epée du Dévoreur d''Ame',replace(replace('Vous ne pouvez équiper cette carte qu''à un Monstre Normal de Niveau 3 ou moins sur votre Terrain. \r\nLorsque vous activez cette carte, sacrifiez tous les Monstres Normaux (excepté les jetons) sur votre Terrain excepté le monstre équipé. \r\nAugmente l''ATK du monstre équipé de 1000 points pour chaque Monstre Normal que vous avez sacrifié.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5373478,'Cyber Dragon Zwei',replace(replace('Le nom de cette carte devient "Cyber Dragon" tant qu''elle est dans le Cimetière. \r\nUne fois par tour: vous pouvez révéler 1 Magie dans votre main; jusqu''à la End Phase, le nom de cette carte devient "Cyber Dragon". \r\nSi cette carte attaque un monstre de l''adversaire, elle gagne 300 ATK durant la Damage Step uniquement.','\r',char(13)),'\n',char(10)),'Traiter le nom de cette carte comme "Cyber Dragon"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5376159,'Règne Rouge',replace(replace('Si vous contrôlez un Monstre Synchro de min. Niveau 8: bannissez tous les monstres sur le Terrain (monstres avec le plus haut Niveau exclus), et aussi, les monstres face recto restants sur le Terrain ne sont pas affectés par d''autres effets de carte (leurs propres effets exclus) jusqu''à la fin de ce tour. \r\nSi un Monstre Synchro TÉNÈBRES Dragon est Invoqué par Synchronisation sur votre Terrain tant que cette carte est dans votre Cimetière: vous pouvez ajouter cette carte à votre main. \r\nVous ne pouvez utiliser cet effet de "Règne Rouge" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5380979,'Bienvenue Labrynth',replace(replace('Invoquez Spécialement 1 monstre "Labrynth" depuis votre Deck, et aussi, jusqu''à la fin du prochain tour après la résolution de cette carte, vous ne pouvez pas Invoquer Spécialement (monstres Démon exclus) depuis le Deck ou Extra Deck. \r\nSi un monstre quitte le Terrain par votre effet de Piège Normal, tant que cette carte est dans votre Cimetière, sauf le tour où elle y a été envoyée: vous pouvez Poser cette carte. \r\nVous ne pouvez utiliser chaque effet de "Bienvenue Labrynth" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5388481,'Soldat du Feu Noir N°1','Expert en explosifs des forces d''élites spéciales.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5399521,'Micro, Guerrier Symphonique',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nL''Échelle Pendule de cette carte devient 4, sauf si vous avez une carte "Guerrier Symphonique" dans votre autre Zone Pendule. \r\nUne fois par tour, durant votre End Phase: vous pouvez cibler 1 de vos monstres "Guerrier Symphonique" bannis; ajoutez-le à votre main.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez Invoquer Spécialement cette carte (depuis votre main) en retirant 3 Compteurs Symphonique depuis votre Terrain. \r\nAprès que vous avez Invoqué Normalement ou Spécialement cette carte, vous pouvez Invoquer Normalement 1 monstre durant votre Main Phase ce tour, en plus de votre Invocation Normale ou Pose Normale. \r\n(Vous ne pouvez gagner cet effet qu''une fois par tour.)','\r',char(13)),'\n',char(10)),'Invoquer par l''effet de "Micro, Guerrier Symphonique"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5402805,'Berserker du Tenyi','2+ monstres (un Monstre Lien inclus)','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405694,'Soldat du Lustre Noir','Vous pouvez Invoquer Rituellement cette carte avec "Rituel du Lustre Noir".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405695,'Soldat du Lustre Noir','Le plus puissant des guerriers, dont les facultés égalent celles du Dragon Blanc aux Yeux Bleus.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405696,'Soldat du Lustre Noir','Vous pouvez Invoquer Rituellement cette carte avec "Rituel du Lustre Noir".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5414777,'Monde des Esprits',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 monstre qui mentionne "Ancien Dragon Féerique" depuis votre Deck à votre main. \r\nVous ne pouvez activer les effets suivants que tant que vous contrôlez un Monstre Synchro LUMIÈRE Dragon de min. Niveau 7. \r\nChaque fois qu''un ou plusieurs monstres sont Invoqués Spécialement en Position d''Attaque: changez-les en Position de Défense. \r\nUne fois par tour, durant la End Phase: détruisez tous les monstres en Position d''Attaque sur le Terrain du joueur du tour. \r\nVous ne pouvez activer qu''1 "Monde des Esprits" par tour.','\r',char(13)),'\n',char(10)),'Activer','Passer en Position de Défense','Détruire','Ajouter cette carte à la main ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(5431722,'Flamme Queudragon',replace(replace('Ciblez 1 Magie face recto sur le Terrain; annulez ses effets (jusqu''à la fin de ce tour), puis vous pouvez placer 1 carte "Queudragon" ("Flamme Queudragon" exclu) depuis votre Cimetière ou bannissement au-dessous du Deck, puis piochez 1 carte. \r\nVous ne pouvez activer qu''1 "Flamme Queudragon" par tour.','\r',char(13)),'\n',char(10)),'','Récupérer et piocher ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5434080,'Chevalier sans Tête','Cet esprit hanté d''un chevalier accusé à tort erre à la recherche de vérité et de justice.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5438492,'Dame Guerrière des Terres Désolées','Lorsque cette carte est détruite au combat et envoyée au Cimetière: vous pouvez Invoquer Spécialement 1 monstre TERRE Guerrier avec max. 1500 ATK depuis votre Deck en Position d''Attaque.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5439384,'Naissance de la Flamme Proéminente',replace(replace('Ciblez 2 monstres FEU (1 Syntoniseur et 1 non-Syntoniseur) avec 200 DEF dans votre Cimetière; bannissez les deux monstres, et si vous le faites, Invoquez Spécialement 1 Monstre Synchro FEU depuis votre Extra Deck dont le Niveau est égal à la somme des Niveaux de ces monstres. \r\nVous ne pouvez activer qu''1 "Naissance de la Flamme Proéminente" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5464695,'Inpachi Ardent','Un esprit maléfique des bois qui brûle en permanence. Ses attaques de feu sont redoutables, mais il ne sera bientôt plus qu''un tas de cendres.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5466615,'Affrontement Myutant',replace(replace('Lorsque vous activez cette carte: vous pouvez cibler 1 Monstre à Effet contrôlé par votre adversaire; bannissez 1 monstre "Myutant" depuis votre Cimetière, et si vous le faites, annulez son effet jusqu''à la fin de ce tour (même si cette carte quitte le Terrain). \r\nLorsque votre monstre "Myutant" de min. Niveau 8 détruit un monstre de l''adversaire au combat: vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser cet effet de "Affrontement Myutant" qu''une fois par tour. \r\nVous ne pouvez activer qu''1 "Affrontement Myutant" par tour.','\r',char(13)),'\n',char(10)),'Annuler l''effet d''un monstre de l''adversaire ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5479217,'Impact Préhistorique','Si vous contrôlez un monstre Dinosaure avec min. 2500 ATK: détruisez toutes les cartes sur le Terrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5489987,'Fleur Cardian de Cerisier avec Rideau',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement par son propre effet. \r\nVous pouvez révéler cette carte dans votre main; piochez 1 carte, et si vous le faites, montrez-la, puis Invoquez Spécialement cette carte si la carte piochée est un monstre "Fleur Cardian". \r\nSinon, envoyez-la avec cette carte au Cimetière. \r\nDurant la Damage Step de chaque joueur, lorsque votre monstre "Fleur Cardian" combat un monstre de votre adversaire: vous pouvez défausser cette carte; jusqu''à la fin de ce tour, votre monstre combattant gagne 1000 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5494820,'Laser Cyclon',replace(replace('Seul "Gradius" peut être équipé de cette carte. \r\nAugmente l''ATK de ce "Gradius" de 300 points. \r\nLorsque ce "Gradius" attaque avec une ATK supérieure à la DEF du monstre en Position de Défense, infligez la différence aux Life Points de votre adversaire en tant que dommages de combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5498296,'Scarr, Éclaireur du Monde Ténébreux','Si cette carte est détruite au combat et envoyée au Cimetière: ajoutez 1 monstre "Monde Ténébreux" de max. Niveau 4 depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5506791,'Chat Majesspectre - Nekomata',replace(replace('Échelle Pendule = 2\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nLorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 carte "Majesspectre" depuis votre Deck à votre main durant la End Phase de ce tour. \r\nVous ne pouvez utiliser cet effet de "Chat Majesspectre - Nekomata" qu''une fois par tour. \r\nNi ciblable ni destructible par des effets de carte de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5519829,'Lily la Conseillère Télépathique','Lorsque cette carte est envoyée au Cimetière pour une Invocation Synchro, vous pouvez payer 500 Life Points pour que ce Monstre Synchro gagne 1000 points d''ATK jusqu''à la End Phase.','Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5524387,'Roche Marbrée Marincesse',replace(replace('2+ monstres EAU	\r\nVous pouvez cibler 1 carte "Marincesse" ("Roche Marbrée Marincesse" exclu) dans votre Cimetière; ajoutez-la à votre main. \r\nVous ne pouvez utiliser cet effet de "Roche Marbrée Marincesse" qu''une fois par tour. \r\nLorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez envoyer 1 monstre "Marincesse" depuis votre main au Cimetière; les monstres ne peuvent pas être détruits au combat par ce combat, et aussi, vous ne recevez aucun dommage de combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5530780,'Exosœur Gibrine',replace(replace('2 monstres de Niveau 4	\r\nNon destructible par les effets activés de monstres Invoqués Spécialement depuis le Cimetière. \r\nVous ne pouvez utiliser chacun des effets suivants de "Exosœur Gibrine" qu''une fois par tour. \r\nSi vous contrôlez cette carte qui a été Invoquée par Xyz ce tour en utilisant un monstre "Exosœur" comme Matériel (Effet Rapide): vous pouvez cibler 1 Monstre à Effet contrôlé par votre adversaire; jusqu''à la fin de ce tour, annulez ses effets. \r\nVous pouvez détacher 1 Matériel de cette carte; le reste de ce tour, tous les Monstres Xyz que vous contrôlez vont gagner 800 ATK.','\r',char(13)),'\n',char(10)),'Annuler les effets d''un monstre de l''adversaire','Augmenter l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5554990,'Électro-Beryx','Lorsque cette carte inflige des dommages de combat à votre adversaire avec une attaque directe, défaussez 1 carte au hasard depuis la main de votre adversaire.','Défausser 1 carte','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5556499,'Forteresse Méchabot',replace(replace('Vous pouvez défausser un ou plusieurs monstres Machine dont le Niveau total est égal à min. 8, puis Invoquez Spécialement cette carte (depuis votre main ou Cimetière). \r\nSi cette carte est détruite au combat et envoyée au Cimetière: ciblez 1 carte contrôlée par votre adversaire; détruisez la cible. \r\nAvant la résolution d''un effet de monstre de l''adversaire qui cible cette carte face recto, regardez la main de votre adversaire et défaussez-lui 1 carte.','\r',char(13)),'\n',char(10)),'Détruire 1 carte contrôlée par votre adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5556668,'Échange','Chaque joueur révèle sa main et ajoute 1 carte de la main de son adversaire à sa main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5559570,'Fierté de Juin des Notes Elfiques',replace(replace('1 Syntoniseur + 1 monstre non-Syntoniseur Magicien	\r\nTant que cette carte est dans la Zone Monstre Main centrale, aucun joueur ne peut déclarer d''attaques, sauf avec des monstres dans leurs Zones Monstre Main centrales. \r\nDurant la Main Phase, si cette carte est dans la Zone Monstre Main centrale (Effet Rapide): vous pouvez renvoyer cette carte à l''Extra Deck, et si vous le faites, Invoquez Spécialement max. 1 monstre "Notes Elfiques" depuis votre main, max. 1 monstre "Notes Elfiques" depuis votre Deck et max. 1 monstre "Notes Elfiques" depuis votre Cimetière. \r\nVous ne pouvez utiliser cet effet de "Fierté de Juin des Notes Elfiques" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5560911,'Destrudo le Frisson du Dragon Perdu',replace(replace('Si cette carte est dans votre main ou Cimetière: vous pouvez payer la moitié de vos LP, puis ciblez 1 monstre de max. Niveau 6 que vous contrôlez; Invoquez Spécialement cette carte, et si vous le faites, le Niveau de cette carte est réduit du Niveau du monstre ciblé, et aussi, placez cette carte au-dessous du Deck si elle quitte le Terrain. \r\nVous ne pouvez utiliser cet effet de "Destrudo le Frisson du Dragon Perdu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5562461,'Illusion des Ténèbres','Lorsqu''une Carte Magie/Piège ou un effet de monstre qui cible un monstre TÉNÈBRES sur le Terrain est activé: annulez l''activation, et si vous le faites, détruisez la carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5574510,'Shateki',replace(replace('Vous pouvez défausser 1 carte, puis ciblez 1 monstre contrôlé par votre adversaire avec un Niveau; lancez un dé à six faces et appliquez cet effet selon le résultat.\r\n● Supérieur à son Niveau: Détruisez le monstre, puis vous pouvez ajouter 1 monstre du même Niveau d''origine depuis votre Deck à votre main, et aussi, vous ne pouvez pas activer l''effet de "Shateki" le reste de ce tour.\r\n● Inférieur ou égal à son Niveau: Réduisez le Niveau du monstre de 1 (même si cette carte quitte le Terrain).','\r',char(13)),'\n',char(10)),'','Ajouter ce monstre à la main ?','Ce tour, vous ne pouvez pas activer le premier effet de "Shateki"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5577149,'Cadet des Gardes',replace(replace('Tous les monstres "des Gardes" que vous contrôlez gagnent 500 ATK. \r\nVous ne pouvez utiliser chacun des effets suivants de "Cadet des Gardes" qu''une fois par tour. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 "Festin de la Nature LV5" depuis votre Deck à votre main. \r\nVous pouvez Sacrifier cette carte; Invoquez Spécialement 1 monstre Guerrier de Niveau 8 depuis votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5577649,'Écrasement de Ferraille',replace(replace('Activable uniquement lorsqu''un monstre "Ferraille" que vous contrôlez est détruit et envoyé au Cimetière. \r\nDétruisez toutes les Cartes Magie et Piège face recto sur le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5592689,'Lotus du Samsara',replace(replace('Durant votre End Phase, si vous ne contrôlez aucune Carte Magie ou Piège, vous pouvez Invoquer Spécialement cette carte depuis votre Cimetière en Position d''Attaque face recto. \r\nLe contrôleur de cette carte reçoit 1000 points de dommages durant chacune de ses Standby Phases.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Infliger des dommages','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5600127,'Ver Drakonien Humanoïde','"Ver - Drakonien" + "Gélatine Humanoïde"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5605529,'Vaalmonica Schelta',replace(replace('Appliquez 1 de ces effets. \r\nSauf si vous avez une carte "Vaalmonica" dans votre Zone Pendule, votre adversaire choisit l''effet.\r\n● Gagnez 500 LP, puis vous pouvez placer 1 carte depuis votre main au-dessous du Deck, puis piochez 2 cartes.\r\n● Recevez 500 points de dommages, puis vous pouvez ajouter 1 Magie/Piège "Vaalmonica" ("Vaalmonica Schelta" exclu) depuis votre Deck à votre main.	\r\nVous ne pouvez activer qu''1 "Vaalmonica Schelta" par tour.','\r',char(13)),'\n',char(10)),'','Gagnez 500 LP','Subissez 500 dommages','Mélanger votre main dans le Deck, puis piocher ?','Ajouter une carte de votre Deck à votre main ?','','','','','','','','','','','');
INSERT INTO texts VALUES(5606466,'Trappe D.D.','Lorsque votre adversaire Pose exactement 1 monstre (et aucune autre carte): ciblez le monstre Posé et 1 monstre que vous contrôlez; détruisez les cibles, et si vous le faites, bannissez-les.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5609226,'Barrière Syntonisatrice',replace(replace('Sélectionnez 1 monstre Syntoniseur face recto que vous contrôlez. \r\nCe monstre ne peut pas être détruit au combat ou par les effets d''une carte, jusqu''à la End Phase du prochain tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5611760,'Pont Arc-en-Ciel du Salut',replace(replace('S''il y a min. 2 Types de Monstre différents parmi les monstres de min. Niveau 10 sur le Terrain: mélangez toutes les cartes (celle-ci exclue) depuis la main, Terrain et Cimetière de chaque joueur dans le Deck, puis chaque joueur pioche 5 cartes. \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 monstre "Bête Cristalline" et 1 Magie de Terrain depuis votre Deck à votre main. \r\nVous ne pouvez appliquer chaque effet de "Pont Arc-en-Ciel du Salut" qu''une fois par Duel.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5614808,'Baleine Aura Blanche',replace(replace('1 Syntoniseur EAU + 1+ monstre non-Syntoniseur EAU	\r\nLorsque cette carte est Invoquée par Synchronisation: vous pouvez détruire tous les monstres en Position d''Attaque de votre adversaire. \r\nDurant chaque Battle Phase, cette carte peut faire max. 2 attaques sur des monstres. \r\nSi cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants. \r\nSi cette carte en votre possession est détruite par une carte de l''adversaire et envoyée à votre Cimetière: vous pouvez bannir 1 autre monstre EAU depuis votre Cimetière; Invoquez Spécialement cette carte comme Syntoniseur.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5616412,'Coup de Poing Destructeur',replace(replace('Lorsque l''ATK d''un monstre attaquant sur le Terrain de votre adversaire est inférieure à la DEF du monstre attaqué en Position de Défense sur votre Terrain, détruisez le monstre attaquant. \r\nLes dommages sont calculés normalement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5628232,'Pingouin volant','Pingouin très rare qui s''envole grâce à des oreilles en forme d''ailes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5640330,'Hannibal Nécromancien',replace(replace('Si cette carte est Invoquée Normalement: placez 1 Compteur Magie sur elle (max. 1). \r\nVous pouvez retirer 1 Compteur Magie de cette carte, puis ciblez 1 Piège face recto sur le Terrain; détruisez la cible.','\r',char(13)),'\n',char(10)),'Placer un marqueur','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5641251,'Égalité F.A.',replace(replace('Lorsqu''un monstre de l''adversaire déclare une attaque directe: vous pouvez Invoquer Spécialement 1 monstre "F.A." depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Égalité F.A." qu''une fois par tour. \r\nUne fois par combat, si votre monstre "F.A." combat un monstre de l''adversaire, avant le calcul des dommages: vous pouvez faire lancer un dé à six faces à chaque joueur. \r\nSi votre résultat est supérieur, augmentez le Niveau de votre monstre combattant de 4 jusqu''à la fin de ce tour (même si cette carte quitte le Terrain). \r\nSi votre résultat est inférieur, détruisez votre monstre combattant. \r\nSi c''est égalité, chaque joueur relance le dé.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5645210,'Vénus Splendide',replace(replace('Tous les monstres non-Elfe perdent 500 ATK/DEF. \r\nL''activation et les effets de Cartes Magie/Piège activés sur votre Terrain ne peuvent pas être annulés.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5650082,'Force de Miroir Violente','Lorsqu''un monstre de l''adversaire déclare une attaque: renvoyez tous les monstres en Position d''Attaque de votre adversaire à la main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5672432,'Résurrection Potartiste','Si un ou plusieurs monstres que vous contrôlez sont détruits au combat ou par un effet de carte: Invoquez Spécialement 1 monstre "Potartiste" depuis votre main ou Cimetière.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5697558,'La Cité Cachée',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 monstre "Subterreur" depuis votre Deck à votre main. \r\nUne fois par tour: vous pouvez changer 1 monstre "Subterreur" en Position de Défense face verso que vous contrôlez en Position d''Attaque ou Défense face recto. \r\nUne fois par tour, lorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez changer 1 monstre "Subterreur" en Position de Défense face verso que vous contrôlez en Position d''Attaque ou Défense face recto, puis vous pouvez annuler l''attaque. \r\nVous ne pouvez activer qu''1 "La Cité Cachée" par tour.','\r',char(13)),'\n',char(10)),'Ajouter un monstre "Subterreur" à votre main ?','Changer la position de combat','Annuler l''attaque ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5703682,'Mille Energies',replace(replace('Augmentez l''ATK et la DEF d''origine de tous les Monstres Normaux de Niveau 2 (excepté les jetons) face recto sur votre Terrain de 1000 points. \r\nDétruisez tous les Monstres Normaux de Niveau 2 sur votre Terrain durant la End Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5728014,'Naissance d''un Rival !',replace(replace('Sélectionnez 1 monstre sur le Terrain de votre adversaire face recto. \r\nFaites l''Invocation Spéciale d''1 monstre de votre main qui a le même Niveau que le monstre sélectionné.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5758500,'Libération d''Âme','Ciblez max. 5 cartes dans les Cimetières; bannissez-les.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5763020,'Idole Triste','Vous pouvez bannir 1 Syntoniseur depuis votre Cimetière; Invoquez Spécialement cette carte depuis votre main.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5772618,'Drake-Volant Grande Vitesseroid',replace(replace('1 Syntoniseur VENT Machine + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez activer 1 de ces effets;\r\n● Détruisez toutes les autres cartes sur le Terrain.\r\n● Annulez les effets de toutes les cartes face recto actuellement contrôlées par votre adversaire.	\r\nSi cette carte en votre possession est envoyée à votre Cimetière par une carte de l''adversaire: vous pouvez ajouter 1 monstre "Vitesseroid" depuis votre Deck à votre main.\r\nVous ne pouvez utiliser chaque effet de "Drake-Volant Grande Vitesseroid" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer l''effet choisi','Détruire toutes les cartes sur le Terrain sauf cette carte','Annuler les effets de toutes les cartes face recto contrôlées par votre adversaire','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5779502,'Outsider',replace(replace('Durant votre tour, annulez les effets de tous les monstres face recto contrôlés par votre adversaire. \r\nDurant le tour de votre adversaire, annulez les effets de tous les monstres face recto que vous contrôlez.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5780210,'Créateur de Diapason','Si vous contrôlez un Monstre Synchro de min. Niveau 8, vous pouvez Invoquer Spécialement cette carte (depuis votre main).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5786513,'Tour Silencieux',replace(replace('Ciblez 1 monstre face recto que vous contrôlez; augmentez son Niveau de 3, et aussi, si vous avez activé cette carte en réponse à l''activation d''effet de monstre de votre adversaire, tant que vous contrôlez "Sarcophage Brillant" et un monstre qui le mentionne, annulez l''effet de l''adversaire. \r\nDurant le calcul des dommages, si votre monstre qui mentionne "Sarcophage Brillant" combat: vous pouvez bannir cette carte depuis votre Cimetière; terminez la Battle Phase. \r\nVous ne pouvez activer qu''1 "Tour Silencieux" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5795882,'Domaine de Vampire',replace(replace('Une fois par tour: vous pouvez payer 500 LP; durant votre Main Phase ce tour, vous pouvez Invoquer Normalement 1 monstre "Vampire" en plus de votre Invocation/Pose Normale. \r\n(Même si cette carte quitte le Terrain. Vous ne pouvez gagner cet effet qu''une fois par tour.) \r\nChaque fois que votre monstre "Vampire" inflige des dommages de combat à votre adversaire: gagnez le même montant de LP.','\r',char(13)),'\n',char(10)),'','','Invoquer par l''effet de "Domaine de Vampire"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5795980,'Attaque des Monarques',replace(replace('Vous pouvez Sacrifier 1 monstre Invoqué Normalement/Posé de min. Niveau 5 face recto, puis ciblez 1 carte face recto sur le Terrain; annulez ses effets, puis piochez 1 carte. \r\n(Ces effets restent annulés jusqu''à la fin de ce tour.) \r\nDurant votre Main Phase, si cette carte est dans votre Cimetière: vous pouvez bannir cette carte, puis déclarez 1 Attribut; jusqu''à la fin de ce tour, tous les monstres actuellement face recto sur le Terrain deviennent de cet Attribut.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Changer l''Attribut','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5800323,'Peuplier de la Forêt Blanche',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée Spécialement: vous pouvez cibler 2 monstres "Forêt Blanche" dans votre Cimetière; placez-les face recto dans les Zones Magie & Piège de leur propriétaire comme Magies Continues. \r\nDurant la Main Phase de votre adversaire, vous pouvez (Effet Rapide): immédiatement après la résolution de cet effet, Invoquez par Synchronisation en utilisant cette carte que vous contrôlez. \r\nVous ne pouvez utiliser chaque effet de "Peuplier de la Forêt Blanche" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Placer dans la Zone Magie/Piège','Invocation Synchro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5817857,'Maître des Goules Koa''ki Meiru',replace(replace('Durant chacune de vos End Phases, détruisez cette carte sauf si vous envoyez 1 "Noyau d''Énergie Koa''ki Meiru" depuis votre main au Cimetière ou révélez 1 monstre de Type Zombie dans votre main. \r\nSi un monstre "Koa''ki Meiru" que vous contrôlez doit être détruit au combat ou par l''effet d''une carte, vous pouvez retirer du jeu 1 monstre "Koa''ki Meiru" de votre Cimetière à la place.','\r',char(13)),'\n',char(10)),'Sélectionnez 1 "Noyau d''Énergie Koa''ki Meiru" à envoyer au Cimetière','Révélez 1 monstre Zombie à votre adversaire','Détruire "Maître des Goules Koa''ki Meiru"','Utiliser l''effet de "Maître des Goules Koa''ki Meiru" à la place de la destruction ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(5818294,'Bujingi Tortue','Durant le tour de chaque joueur, lorsqu''une carte ou un effet qui cible un monstre "Bujin" que vous contrôlez est activé (sauf durant la Damage Step): vous pouvez bannir cette carte depuis votre Cimetière; annulez l''effet.','Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5818798,'Gazelle, Roi des Bêtes Mythiques',replace(replace('Ce monstre se déplace si vite qu''il semble n''être qu''une illusion aux yeux des mortels.	\r\n\r\n(Cette carte est toujours traitée comme une carte "Bête Fantôme".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5821478,'Dragon Bombe Topologique',replace(replace('2+ Monstres à Effet	\r\nSi un autre monstre est Invoqué Spécialement dans une zone pointée par un Monstre Lien, tant que ce monstre est sur le Terrain: détruisez tous les monstres dans les Zones Monstre Main, et aussi, vos autres monstres ne peuvent pas attaquer le reste de ce tour. \r\nAprès le calcul des dommages, si cette carte a attaqué un monstre de l''adversaire: infligez des dommages à votre adversaire égaux à l''ATK d''origine du monstre de l''adversaire.','\r',char(13)),'\n',char(10)),'Détruire tous les monstres dans la Zone Monstre Principale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5829717,'Magicien Sombre le Chevalier de la Magie du Dragon',replace(replace('"Magicien Sombre" + 1 monstre Dragon ou Guerrier de min. Niveau 7	\r\nSi votre monstre attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire. \r\nUne fois par tour, lorsque votre monstre détruit un monstre de l''adversaire au combat: vous pouvez infliger des dommages à votre adversaire égaux à l''ATK d''origine du monstre détruit. \r\nSi cette carte est détruite: vous pouvez Invoquer Spécialement 1 "Magicien Sombre" ainsi qu''1 "Gaïa le Dragon Champion" depuis votre main, Deck, Extra Deck et/ou Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5832914,'Mallette Toon','Lorsque votre adversaire Invoque un ou plusieurs monstres tant que vous contrôlez un monstre Toon: mélangez ces monstres dans le Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5833312,'Duel Académie',replace(replace('Cette carte gagne ces effets selon les Types de Monstre sur le Terrain.\r\n● Guerrier, Bête ou Pyro: Une fois par tour, si vous activez une Carte Piège (sauf durant la Damage Step): vous pouvez cibler 1 carte contrôlée par votre adversaire; détruisez-la.\r\n● Dinosaure, Serpent de Mer ou Tonnerre: Une fois par tour, si vous activez une Carte Magie (sauf durant la Damage Step): vous pouvez infliger 1000 points de dommages à votre adversaire.\r\n● Machine, Elfe ou Démon: Une fois par tour, si vous activez un effet de monstre (sauf durant la Damage Step): vous pouvez cibler 1 monstre face recto que vous contrôlez; il gagne 1000 ATK (même si cette carte quitte le Terrain).','\r',char(13)),'\n',char(10)),'Si un Piège est activé : détruire une carte','Si une Magie est activée : infliger 1000 dommages','Si l''effet d''un monstre est activé : augmenter l''ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5833929,'Marraimommy Melffy',replace(replace('3+ monstres Bête de Niveau 2	\r\nUne fois par tour, vous pouvez aussi Invoquer par Xyz "Marraimommy Melffy" en utilisant "Mommy Melffy" que vous contrôlez (transférez ses Matériels). \r\nSi cette carte est Invoquée Spécialement: vous pouvez ajouter 1 Magie/Piège "Melffy" depuis votre Deck ou Cimetière à votre main. \r\nGagne une ATK égale à la somme des ATK/DEF des monstres "Melffy" qui lui sont attachés. \r\nVous pouvez détacher 5 Matériels de cette carte; renvoyez toutes les cartes contrôlées par votre adversaire à la main.','\r',char(13)),'\n',char(10)),'Invoquer Xyz en utilisant {CARD} comme Matériel ?','Ajouter à la main','Renvoyer à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5846183,'Disjonctarboucle Électroménageur',replace(replace('Durant le calcul des dommages, si un autre monstre "Électroménageur" que vous contrôlez combat un monstre de l''adversaire (Effet Rapide): vous pouvez défausser cette carte; le monstre que vous contrôlez ne peut pas être détruit par ce combat, et aussi, vous ne recevez aucun dommage de combat. \r\nSi un ou plusieurs monstres "Électroménageur" que vous contrôlez vont être détruits par un effet de carte, vous pouvez bannir cette carte depuis votre Terrain ou Cimetière à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5848934,'Magicienne Psychique de la Sérénité',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez payer 1000 LP; Posez 1 Magie Normale ou Jeu-Rapide "Téléportation" depuis votre Deck, Cimetière ou bannissement. \r\nSi cette carte Invoquée par Synchronisation est envoyée au Cimetière: vous pouvez cibler 1 carte contrôlée par votre adversaire, ou ciblez-en 2 si vous contrôlez un monstre Psychique (Fusion ou Synchro); renvoyez ces cartes à la main. \r\nVous ne pouvez utiliser chaque effet de "Magicienne Psychique de la Sérénité" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Poser','Renvoyer à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5851097,'Espace de Négation',replace(replace('Aucun joueur ne peut Invoquer Spécialement de monstres. \r\nSi une carte est envoyée depuis le Deck ou Terrain à votre Cimetière: détruisez cette carte.','\r',char(13)),'\n',char(10)),'Détruire cette carte','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5852388,'Xéno Météoraure',replace(replace('Si une ou plusieurs cartes sont détruites au combat ou par un effet de carte: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nDurant votre Main Phase: vous pouvez détruire 1 monstre Dinosaure dans votre main ou Terrain, puis Invoquez Spécialement 1 Monstre Normal Dinosaure depuis votre main ou Deck, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres Dragon, Dinosaure, Serpent de Mer ou Wyrm exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Xéno Météoraure" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte depuis votre main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5861892,'Force Arcane EX - Le Maître de la Lumière',replace(replace('Ni Invocable Normalement ni Posable. \r\nUniquement Invocable Spécialement (depuis votre main) en envoyant 3 monstres que vous contrôlez au Cimetière, et non Invocable Spécialement autrement. \r\nLorsque cette carte est Invoquée Spécialement: lancez une pièce et gagnez l''effet approprié.\r\n● Face: Lorsque cette carte détruit un monstre de votre adversaire au combat et l''envoie au Cimetière: vous pouvez cibler 1 carte dans votre Cimetière; ajoutez la cible à votre main.\r\n● Pile: Durant le tour de chaque joueur, lorsqu''une Carte Magie/Piège ou un effet de monstre qui cible cette carte est activé: cette carte perd exactement 1000 ATK et vous annulez l''activation, et si vous le faites, détruisez-la/le.','\r',char(13)),'\n',char(10)),'Lancer une pièce','Recycler','Annuler et détruire','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5901497,'Queen''s Double','Ce monstre peut attaquer directement les Life Points de votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5908650,'Shopina la Maestria de la Musique',replace(replace('Une fois par tour: vous pouvez cibler 1 monstre LUMIÈRE Elfe dans votre Cimetière; ajoutez-le à votre main. \r\nVous ne pouvez pas activer d''effets de monstre non-LUMIÈRE durant le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5914184,'Double Remboursement',replace(replace('Activable uniquement lorsque vous recevez min. 1000 points de dommage par un effet de carte de votre adversaire: placez 1 Compteur Remboursement sur cette carte pour chaque 1000 points de dommages reçus. \r\nDurant la End Phase du prochain tour de votre adversaire: détruisez cette carte, et si vous le faites, infligez 2000 points de dommage à votre adversaire pour chaque Compteur Remboursement sur cette carte.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5914858,'Junora le Mécène du Pouvoir de l''Accordage',replace(replace('1 Syntoniseur + 2 non-Syntoniseurs	\r\nPour l''Invocation Synchro de cette carte, vous pouvez traiter 1 monstre dans votre Zone Monstre Main centrale comme Syntoniseur. \r\nSi cette carte est Invoquée par Synchronisation: vous pouvez annuler les effets de toutes les cartes face recto contrôlées par votre adversaire. \r\n(Effet Rapide): vous pouvez activer cet effet; jusqu''à la fin de ce tour, les monstres contrôlés par votre adversaire dans la même colonne que les monstres "Notes Elfiques" que vous contrôlez ne peuvent pas être utilisés comme Matériel pour une Invocation Fusion, Synchro, Xyz ou Lien. \r\nVous ne pouvez utiliser cet effet de "Junora le Mécène du Pouvoir de l''Accordage" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Ne peut pas être utilisé comme Matériel','L''effet de "Junora le Mécène du Pouvoir de l''Accordage" est actuellement appliqué.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5915629,'Cadeau de Cupidité','Votre adversaire pioche 2 cartes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5916510,'Chevalier Étoilant',replace(replace('2 monstres de Niveau 4	\r\nVous pouvez détacher 1 Matériel de cette carte; Invoquez Spécialement 1 monstre LUMIÈRE depuis votre main. \r\nSi cette carte est dans votre Cimetière, sauf le tour où elle y a été envoyée: vous pouvez cibler 1 monstre LUMIÈRE Elfe de Niveau 4 que vous contrôlez; Invoquez Spécialement cette carte, et si vous le faites, attachez le monstre à cette carte comme Matériel. \r\nVous ne pouvez utiliser chaque effet de "Chevalier Étoilant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5929801,'Raidraptor - Pie-Grièche Frisottante',replace(replace('Si vous contrôlez un monstre "Raidraptor" ("Raidraptor - Pie-Grièche Frisottante" exclu): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi cette carte est envoyée au Cimetière: vous pouvez ajouter 1 "Raidraptor - Pie-Grièche Frisottante" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Raidraptor - Pie-Grièche Frisottante" qu''une fois par tour. \r\nVous ne pouvez pas Invoquer Spécialement de monstres (monstres "Raidraptor" exclus) le tour où vous activez un des effets de cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5941982,'Alternative Griffrayeur',replace(replace('Sacrifiez 3 monstres "Griffrayeur"; le reste de ce tour, votre adversaire peut uniquement Invoquer Spécialement des monstres en Position de Défense. \r\nDurant votre tour: vous pouvez bannir cette carte depuis votre Cimetière; infligez 100 points de dommages à votre adversaire pour chaque monstre en Position de Défense sur le Terrain. \r\nVous ne pouvez utiliser cet effet de "Alternative Griffrayeur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5969957,'Rechargeur Rokkette',replace(replace('Si un ou plusieurs monstres TÉNÈBRES que vous contrôlez qui ont été Invoqués Spécialement depuis l''Extra Deck sont détruits au combat ou par un effet de carte: vous pouvez envoyer cette carte depuis votre main ou Terrain au Cimetière, puis ciblez 1 de ces monstres détruits; Invoquez Spécialement 1 monstre TÉNÈBRES depuis votre Cimetière de nom d''origine différent du monstre ciblé. \r\nVous ne pouvez utiliser cet effet de "Rechargeur Rokkette" qu''une fois par tour. \r\nTant que vous contrôlez un monstre TÉNÈBRES qui a été Invoqué Spécialement depuis l''Extra Deck, les monstres de votre adversaire ne peuvent pas cibler cette carte avec une attaque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5972394,'Imitargile',replace(replace('Si votre adversaire contrôle un monstre: ciblez 1 monstre de max. Niveau 2 en Position de Défense que vous contrôlez; Invoquez Spécialement 1 monstre de même nom que le monstre sur le Terrain depuis votre Deck en Position de Défense, mais bannissez-le lorsqu''il quitte le Terrain. \r\nVous ne pouvez activer qu''1 "Imitargile" par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5973663,'L''Arbre du Monde',replace(replace('Chaque fois qu''un ou plusieurs monstres de Type Plante face recto sur le Terrain sont détruits, placez 1 Compteur Fleur sur cette carte. \r\nVous pouvez retirer le nombre de votre choix de Compteurs Fleur de cette carte pour activer ces effets.\r\n● 1 Compteur: Ciblez 1 monstre de Type Plante sur le Terrain; jusqu''à la fin de ce tour, la cible gagne 400 ATK/DEF. \r\n(Ce gain d''ATK reste même si cette carte quitte le Terrain.)\r\n● 2 Compteurs: Ciblez 1 carte sur le Terrain; détruisez la cible.\r\n● 3 Compteurs: Ciblez 1 monstre de Type Plante dans votre Cimetière; Invoquez Spécialement la cible.','\r',char(13)),'\n',char(10)),'1 : augmenter l''ATK/DEF','2 : détruire une carte','3 : Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5975022,'Mirmillon, Bête Gladiateur','Lorsque cette carte est Invoquée Spécialement par l''effet d''un monstre "Bête Gladiateur", détruisez 1 monstre face recto. À la fin de la Battle Phase, si cette carte a attaqué ou a été attaquée, vous pouvez la renvoyer dans le Deck pour Invoquer Spécialement 1 monstre "Bête Gladiateur" depuis votre Deck, sauf "Mirmillon, Bête Gladiateur".','Détruire','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5990062,'Énigme Inversée',replace(replace('Envoyez toutes les cartes de votre main et de votre Terrain au Cimetière. \r\nAnnoncez le type (Monstre, Magie ou Piège) de la carte du dessus de votre Deck. \r\nSi vous avez annoncé juste, échangez vos Life Points avec ceux de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5993144,'Cauri d''Hirondelle',replace(replace('Sacrifiez 1 monstre Bête Ailée dans votre main ou Terrain face recto; ajoutez 1 monstre Bête Ailée depuis votre Deck à votre main du même Niveau que le monstre Sacrifié avait. \r\nVous ne pouvez activer qu''1 "Cauri d''Hirondelle" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5997110,'D/D Arpenteur de Compte',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nUne fois par tour, si vous Invoquez par Pendulation un ou plusieurs monstres "D/D/D": vous pouvez cibler 3 monstres contrôlés par votre adversaire qui ont chacun le même Type ou Attribut; Sacrifiez 2 de ces 3 monstres face recto, et si vous le faites, le troisième gagne une ATK/DEF égales à la somme des ATK/DEF que les monstres Sacrifiés avaient sur le Terrain.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez défausser 1 autre monstre "D/D"; Invoquez Spécialement cette carte depuis votre main. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 monstre "D/D" avec 0 ATK ou DEF depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "D/D Arpenteur de Compte" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Sacrifier un monstre','Invocation Spéciale','Effet d''ajout à la main','Sélectionnez le(s) monstre(s) qui resteront sur le Terrain','','','','','','','','','','','','');
INSERT INTO texts VALUES(5998840,'Chevalier Épouvantard, Sabre XX',replace(replace('Non utilisable comme Matériel Synchro, sauf pour l''Invocation Synchro d''un monstre "Sabre X". \r\nLorsque cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre "Sabre X" de max. Niveau 4 depuis votre main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6004133,'Répétition Générale d''Acteur des Abysses',replace(replace('Au début de votre Main Phase 1: ajoutez 1 carte "Acteur des Abysses" et 1 Magie "Script des Abysses" depuis votre Deck à votre main. \r\nLe reste de ce tour après la résolution de cette carte, vous ne pouvez pas Invoquer par Pendulation de monstres (monstres "Acteur des Abysses" exclus).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6007213,'Uria, Seigneur des Flammes Aveuglantes',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en envoyant 3 Pièges face recto que vous contrôlez au Cimetière. \r\nGagne 1000 ATK pour chaque Piège Continu dans votre Cimetière. \r\nUne fois par tour: vous pouvez cibler 1 Magie/Piège Posé contrôlé par votre adversaire; détruisez la cible. \r\nAucun joueur ne peut activer de Cartes Magie/Piège en réponse à l''activation de cet effet.','\r',char(13)),'\n',char(10)),'Détruire des Magies/Pièges','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6007214,'Uria, Seigneur des Flammes Aveuglantes',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en envoyant 3 Pièges face recto que vous contrôlez au Cimetière. \r\nGagne 1000 ATK pour chaque Piège Continu dans votre Cimetière. \r\nUne fois par tour: vous pouvez cibler 1 Magie/Piège Posé contrôlé par votre adversaire; détruisez la cible. \r\nAucun joueur ne peut activer de Cartes Magie/Piège en réponse à l''activation de cet effet.','\r',char(13)),'\n',char(10)),'Détruire des Magies/Pièges','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6021033,'Empereur Dragon de la Damnation',replace(replace('"Zombie Épidémique" + 1+ monstre non-Syntoniseur Zombie	\r\nLorsque cette carte est Invoquée Spécialement: vous pouvez cibler 1 monstre Zombie dans le Cimetière de votre adversaire; Invoquez Spécialement la cible sur votre Terrain en Position d''Attaque, mais détruisez-la lorsque cette carte quitte le Terrain.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6022371,'Dragon de l''Eau Rassemblé',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement avec l''effet d''une Magie/Piège "Liaison". \r\nSi cette carte est Invoquée Spécialement: vous pouvez activer cet effet; les Monstres à Effet actuellement contrôlés par votre adversaire ne peuvent pas activer leurs effets le reste de ce tour, et aussi, changez leur ATK à 0 jusqu''à la fin de ce tour. \r\n(Effet Rapide): vous pouvez Sacrifier cette carte; Invoquez Spécialement 2 "Dragon de l''Eau" depuis votre main et/ou Deck en Position de Défense, en ignorant leurs conditions d''Invocation.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6039967,'Fräulein Vampire',replace(replace('Lorsqu''un monstre déclare une attaque: vous pouvez Invoquer Spécialement cette carte depuis votre main en Position de Défense. \r\nVous ne pouvez utiliser cet effet de "Fräulein Vampire" qu''une fois par tour. \r\nUne fois par combat, si votre monstre Zombie combat un monstre de l''adversaire, durant ce calcul des dommages (Effet Rapide): vous pouvez payer des LP en multiples de 100 (max. 3000); durant ce calcul des dommages uniquement, votre monstre combattant gagne autant d''ATK/DEF. À la fin de la Battle Phase, si cette carte a détruit un ou plusieurs monstres au combat: vous pouvez les Invoquer Spécialement depuis les Cimetières sur votre Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6043161,'Foreuse Ga10 R.B.',replace(replace('Si vous ne contrôlez aucun monstre face recto, ou que les seuls monstres face recto que vous contrôlez sont des monstres "R.B.", vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Foreuse Ga10 R.B." qu''une fois par tour de cette façon. \r\nDurant la Main Phase, si cette carte est liée à un Monstre Lien "R.B." (Effet Rapide): vous pouvez payer 500 LP, puis ciblez 1 monstre contrôlé par votre adversaire; détruisez le monstre ainsi que cette carte. \r\nVous ne pouvez utiliser cet effet de "Foreuse Ga10 R.B." qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6061630,'Canalisateur de Magie',replace(replace('Chaque fois qu''une Carte Magie est activée, placez 2 Compteurs Magie sur cette carte lorsque la Magie est résolue. \r\nUne fois par tour: vous pouvez retirer un nombre de votre choix de Compteurs Magie de cette carte; Invoquez Spécialement 1 monstre Magicien depuis votre main ou Cimetière dont le Niveau est égal au nombre de Compteurs Magie que vous avez retirés.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Sélectionnez le nombre de Marqueurs Magie à retirer','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6071005,'Marka, Artisanesorcière',replace(replace('Vous pouvez Sacrifier cette carte depuis votre main ou Terrain; ajoutez 1 Magie de Terrain ou Continue "Artisanesorcière" depuis votre Deck à votre main.\r\nSi un ou plusieurs monstres "Artisanesorcière" face recto que vous contrôlez quittent le Terrain à cause d''un effet de carte de l''adversaire, tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte (mais bannissez-la lorsqu''elle quitte le Terrain), et si vous le faites, Sacrifiez 1 monstre contrôlé par votre adversaire.\r\nVous ne pouvez utiliser chaque effet de "Marka, Artisanesorcière" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6075533,'Terreur de Trishula',replace(replace('Appliquez ces effets, dans l''ordre, selon le nombre de Monstres Synchro "Barrière de Glace" que vous contrôlez de noms différents;\r\n● 1+: Bannissez 1 carte contrôlée par votre adversaire.\r\n● 2+: Bannissez 1 carte depuis le Cimetière de votre adversaire.\r\n● 3+: Bannissez 1 carte au hasard depuis la main de votre adversaire.	\r\nLorsque votre adversaire active une carte ou un effet qui cible un ou plusieurs Monstres Synchro "Barrière de Glace" que vous contrôlez: vous pouvez bannir cette carte depuis votre Cimetière; annulez l''effet.\r\nVous ne pouvez utiliser chaque effet de "Terreur de Trishula" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6075801,'Paladin d''Or',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez équiper 1 monstre Dragon de Niveau 7 ou 8 depuis votre main ou Deck à cette carte. \r\nCette carte n''est pas affectée par les effets d''autres monstres tant qu''elle est équipée avec une Carte d''Équipement. \r\nVous pouvez Sacrifier 1 monstre et cette carte, puis ciblez 1 monstre Dragon de Niveau 7 ou 8 dans votre Cimetière; Invoquez-le Spécialement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6077601,'Fusion Frourreur',replace(replace('Invoquez par Fusion 1 Monstre de Fusion "Frourreur" depuis votre Extra Deck, en bannissant des Matériels de Fusion listés sur celui-ci depuis votre Terrain ou Cimetière. \r\nVous ne pouvez activer qu''1 "Fusion Frourreur" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6083904,'Diabrocken le Spectre Menaçant',replace(replace('Si cette carte est dans votre main (Effet Rapide): vous pouvez bannir 1 monstre FEU depuis votre Terrain face recto ou Cimetière; Invoquez Spécialement cette carte. \r\nSi cette carte est Invoquée Spécialement: vous pouvez cibler 1 carte face recto sur le Terrain; jusqu''à la fin de ce tour, annulez ses effets. \r\nSi cette carte est envoyée au Cimetière comme Matériel Lien: vous pouvez Poser 1 Magie Jeu-Rapide ou Piège Normal depuis votre Cimetière qui y a été envoyé ce tour. \r\nVous ne pouvez utiliser chaque effet de "Diabrocken le Spectre Menaçant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Annuler','Poser','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6089145,'Mur Transparent',replace(replace('Si "Monde Transparent" est sur le Terrain: vous pouvez ajouter 1 monstre qui mentionne "Monde Transparent" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Mur Transparent" qu''une fois par tour. \r\nLes monstres qui mentionnent "Monde Transparent" ne peuvent pas être détruits au combat, et aussi, vous ne recevez aucun dommage de combat de ce combat. \r\nTant que vous contrôlez un monstre de min. Niveau 7 qui mentionne "Monde Transparent", votre adversaire reçoit tous les effets de "Monde Transparent", peu importe les Attributs de monstre qu''il contrôle.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6103114,'Serpent à bec','Ce monstre s''enroule autour de son adversaire et le picore avec son énorme bec.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6103294,'Emissaire de l''Oasis',replace(replace('Tant qu''un Monstre Normal de Niveau 3 ou moins reste face recto sur votre Terrain, votre adversaire ne peut pas sélectionner cette carte comme cible d''une attaque. \r\nTant que cette carte reste face recto sur votre Terrain, tous les dommages de combat infligés au contrôleur de cette carte à l''issue d''un combat impliquant un Monstre Normal de Niveau 3 ou moins deviennent égaux à 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6104968,'Vermine Bubonique',replace(replace('FLIP: Vous pouvez prendre 1 carte "Vermine Bubonique" de votre Deck et l''Invoquer par Invocation Spéciale sur le Terrain en Position de Défense face verso. \r\nMélangez ensuite votre Deck.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invoquer Spécialement 1 "Vermine Bubonique" en Position de Défense face verso ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6112401,'Union avec l''Épée',replace(replace('Activable uniquement lorsque le seul monstre que vous contrôlez est 1 monstre "Sabre X" face recto. Équipez cette carte à ce monstre. \r\nIl gagne 800 points d''ATK. \r\nSi celui-ci détruit un monstre de l''adversaire au combat, piochez 1 carte.','\r',char(13)),'\n',char(10)),'Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6116731,'Nuée de Mille-Pattes',replace(replace('Si cette carte est retournée face recto: vous pouvez cibler 1 autre monstre sur le Terrain; changez-le en Position d''Attaque face recto ou Position de Défense face verso. \r\nVous ne pouvez utiliser cet effet de "Nuée de Mille-Pattes" qu''une fois par tour. \r\nUne fois par tour, durant votre Main Phase: vous pouvez changer cette carte en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'Changer la position de combat d''un autre monstre','Changer la position de combat de cette carte','Mettre ce monstre en Position de Défense face verso ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6128460,'Cuisson du Crâne Serviteur',replace(replace('Le nom de cette carte devient "Crâne Serviteur" tant qu''elle est dans le Cimetière. \r\nSi un ou plusieurs monstres Zombie de max. Niveau 3 que vous contrôlez vont être détruits au combat ou par un effet de carte, vous pouvez défausser cette carte à la place. \r\nSi cette carte est envoyée au Cimetière: vous pouvez ajouter 2 monstres de noms différents ("Cuisson du Crâne Serviteur" exclu) depuis votre Deck à votre main, qui soit sont "Crâne Serviteur" soit le mentionnent, puis défaussez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Cuisson du Crâne Serviteur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6133894,'Debilmazera',replace(replace('Cette carte ne peut ni être Invoquée par Invocation Normale ni être Posée. \r\nCette carte ne peut pas être Invoquée par Invocation Speciale excepté en sacrifiant 1 "Guerrier de Zera" face recto sur votre Terrain tant que "Pandémonium" est face recto sur votre Terrain. \r\nLorsque vous faites avec succés l''Invocation Spéciale de cette carte, votre adversaire défausse au hasard 3 cartes de sa main. \r\nCet effet n''est pas appliqué à moins que "Pandémonium" ne soit sur votre Terrain.','\r',char(13)),'\n',char(10)),'Défausser depuis la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6137095,'Dysfonction',replace(replace('Payez 500 Life Points. \r\nAnnulez l''activation d''une Carte Piège et renvoyez-la dans sa position d''origine.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6142213,'Roquette Turbo',replace(replace('Lorsque cette carte attaque, elle ne peut pas être détruite au combat. \r\nSi cette carte attaque, après le calcul des dommages, infligez des dommages égaux à la moitié de l''ATK de la cible d''attaque à votre adversaire.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6142488,'Souris Peluchimal',replace(replace('Durant votre Main Phase: vous pouvez Invoquer Spécialement max. 2 exemplaires de "Souris Peluchimal" depuis votre Deck. \r\nCet effet ne peut être utilisé qu''une fois tant que cette carte est face recto sur le Terrain. \r\nVous ne pouvez pas Invoquer Spécialement de monstres depuis l''Extra Deck (monstres "Frourreur" exclus) le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6148016,'Geargiagrenage',replace(replace('Invoquez Spécialement 2 monstres "Geargiano" depuis votre Deck et augmentez leur Niveau de 1. \r\nVous ne pouvez activer qu''1 "Geargiagrenage" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6150044,'Alakan le Chevalier Harlequin',replace(replace('"Chevalier de la Reine" + "Chevalier du Valet" + "Chevalier du Roi"	\r\nL''Invocation Fusion de cette carte ne peut être faite qu''avec les Matériels ci-dessus. \r\nUne fois par tour, lorsqu''une Carte Magie/Piège ou un effet de monstre qui cible cette carte face recto sur le Terrain est activé (Effet Rapide): vous pouvez défausser le même type de carte (Monstre, Magie ou Piège); annulez l''effet.','\r',char(13)),'\n',char(10)),'Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6150045,'Alakan le Chevalier Harlequin',replace(replace('"Chevalier de la Reine" + "Chevalier du Valet" + "Chevalier du Roi"	\r\nL''Invocation Fusion de cette carte ne peut être faite qu''avec les Matériels ci-dessus. \r\nUne fois par tour, lorsqu''une Carte Magie/Piège ou un effet de monstre qui cible cette carte face recto sur le Terrain est activé (Effet Rapide): vous pouvez défausser le même type de carte (Monstre, Magie ou Piège); annulez l''effet.','\r',char(13)),'\n',char(10)),'Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6153210,'Queudragon Ketu',replace(replace('Ajoutez 1 monstre "Queudragon" depuis votre Deck à votre main, puis si votre adversaire contrôle un monstre, vous pouvez Invoquer par Fusion 1 monstre Dragon ou Magicien depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain. \r\nVous ne pouvez activer qu''1 "Queudragon Ketu" par tour.','\r',char(13)),'\n',char(10)),'','Effectuer une Invocation Fusion ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6165656,'Numéro C88 : Poupée Truquée de Lion du Désastre',replace(replace('4 monstres de Niveau 9	\r\nUniquement Invocable Spécialement avec une Magie "Magie-Rang-Plus" ciblant "Numéro 88 : Poupée Truquée de Lion". \r\nAucun joueur ne peut cibler cette carte sur le Terrain avec des effets de carte. \r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte; infligez 1000 points de dommages à votre adversaire. \r\nDurant votre End Phase, si votre adversaire a max. 2000 LP et que cette carte n''a pas de Matériel, vous gagnez le Duel.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6172122,'Fusion aux Yeux Rouges',replace(replace('Invoquez par Fusion 1 Monstre Fusion qui liste un monstre "Yeux Rouges" comme Matériel depuis votre Extra Deck, en utilisant des monstres depuis votre main, Deck ou Terrain comme Matériel Fusion, et si vous le faites, son nom devient "Dragon Noir aux Yeux Rouges". \r\nVous ne pouvez Invoquer ni Normalement ni Spécialement d''autres monstres le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Fusion aux Yeux Rouges" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6178850,'Esprit de Combat',replace(replace('Le monstre équipé gagne 300 ATK pour chaque monstre contrôlé par votre adversaire. \r\nS''il va être détruit au combat, vous pouvez détruire cette carte à la place.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Esprit de Combat" à la place de la destruction ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6180710,'Requin Rêve',replace(replace('La première fois que cette carte va être détruite au combat chaque tour, elle n''est pas détruite. \r\nVous ne pouvez utiliser chacun des effets suivants de "Requin Rêve" qu''une fois par tour. \r\nSi vous ne contrôlez aucun monstre, ou si tous les monstres que vous contrôlez sont EAU: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nLorsqu''une carte ou un effet qui va vous infliger des dommages est activé, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte, et si vous le faites, faites devenir ces dommages d''effet sur vous 0. \r\nSi elle est Invoquée de cette façon, elle perd 1000 DEF, et aussi, bannissez-la lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6182103,'Ultimus Myutant',replace(replace('3 monstres "Myutant" de min. Niveau 8	\r\nLorsqu''une carte ou un effet est activé (Effet Rapide): vous pouvez bannir 1 carte "Myutant" depuis votre main, Cimetière ou Terrain face recto, du même type (Monstre, Magie ou Piège); annulez l''activation, et si vous le faites, bannissez la carte. \r\nSi cette carte Invoquée par Fusion que vous contrôlez est détruite par une carte de l''adversaire: vous pouvez ajouter max. 3 de vos cartes "Myutant" bannies (max. 1 Monstre, max. 1 Magie et max. 1 Piège) à votre main. \r\nVous ne pouvez utiliser chaque effet de "Ultimus Myutant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler l''activation et bannir','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6186304,'Force D',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 "Plasma - HÉROS de la Destinée" depuis votre Deck ou Cimetière à votre main. \r\nTant que vous contrôlez "Plasma - HÉROS de la Destinée", appliquez les effets suivants.\r\n● Vous ne pouvez pas piocher durant la Draw Phase.\r\n● Votre adversaire ne peut pas cibler de cartes que vous contrôlez avec des effets de carte.\r\n● Chaque "Plasma - HÉROS de la Destinée" que vous contrôlez gagne 100 ATK pour chaque monstre dans les Cimetières, ne peut pas être détruit par des effets de carte de votre adversaire, et aussi, peut faire une seconde attaque durant chaque Battle Phase.','\r',char(13)),'\n',char(10)),'Ajouter 1 "Plasma - HÉROS de la Destinée" depuis votre Deck ou Cimetière à votre main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6195332,'Exstellchevalier Ptolemy Ω7 de la Constellée',replace(replace('3 monstres de Niveau 7	\r\nUne fois par tour, durant votre Main Phase 2, vous pouvez aussi Invoquer par Xyz "Exstellchevalier Ptolemy Ω7 de la Constellée" en utilisant 1 Monstre Xyz "tellchevalier" ou "Constellée" que vous contrôlez (transférez ses Matériels). \r\nTant que vous avez min. 7 monstres "tellchevalier" de noms différents dans votre Cimetière et/ou bannissement, cette carte gagne 2700 ATK/DEF, et aussi, elle n''est pas affectée par les effets activés de votre adversaire. \r\nUne fois par tour (Effet Rapide): vous pouvez détacher un nombre de votre choix de Matériels de cette carte, puis ciblez autant de monstres contrôlés par votre adversaire; mélangez-les dans le Deck.','\r',char(13)),'\n',char(10)),'Invoquer Xyz en utilisant un Monstre Xyz "Stellchevalier" ou "Constellée" comme Matériel ?','Effet de renvoi au Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6203182,'D''Un Dard Deux Crapauds',replace(replace('Activez cette carte en ciblant 1 monstre dans le Cimetière de votre adversaire; Invoquez-le Spécialement sur le Terrain de votre adversaire, mais annulez ses effets, et aussi, équipez-le avec cette carte. \r\nLorsque cette carte quitte le Terrain, détruisez le monstre. \r\nLe monstre équipé ne peut ni attaquer ni être ciblé par une attaque. \r\nSi cette carte est envoyée au Cimetière parce que le monstre équipé a été utilisé comme Matériel pour une Invocation Fusion, Synchro, Xyz ou Lien: vous pouvez prendre le contrôle du monstre Invoqué. \r\nVous ne pouvez activer qu''1 "D''Un Dard Deux Crapauds" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6205579,'Parasite Fusion',replace(replace('Cette carte peut être utilisée comme substitut pour 1 Matériel de Fusion dont le nom est listé précisément sur la Carte Monstre de Fusion, mais les autres Matériels de Fusion doivent être corrects. \r\nSinon elle ne peut pas être utilisée comme Matériel de Fusion. \r\nSi cette carte est Invoquée Spécialement (sauf durant la Damage Step): vous pouvez Invoquer par Fusion 1 Monstre de Fusion depuis votre Extra Deck, en utilisant des monstres que vous contrôlez (cette carte incluse) comme Matériels de Fusion.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6214163,'Double Hameçon',replace(replace('Activez en défaussant 1 carte, puis ciblez max. 2 monstres dans votre Cimetière; Invoquez-les Spécialement. \r\nLorsqu''un de ces monstres quitte le Terrain, détruisez cette carte. \r\nLorsque cette carte quitte le Terrain, détruisez ces monstres. \r\nVous ne pouvez activer qu''1 "Double Hameçon" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6214884,'Brron, Roi Fou du Monde Ténébreux','Lorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez défausser 1 carte.','Choisissez 1 carte dans votre main à défausser au Cimetière','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6218704,'Dragon Arcray aux Yeux Impairs',replace(replace('Échelle Pendule = 13\r\n[ Effet Pendule ]\r\nSi vous avez 2 cartes dans vos Zones Pendule: vous pouvez Invoquer Spécialement cette carte, puis vous pouvez appliquer cet effet.\r\n● Mélangez 1 carte depuis votre Zone Pendule dans le Deck, puis si elle a été ajoutée à votre Extra Deck, vous pouvez l''Invoquer Spécialement, en ignorant ses conditions d''Invocation.	\r\nVous ne pouvez utiliser cet effet de "Dragon Arcray aux Yeux Impairs" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\n4 monstres Dragon (1 Fusion, 1 Synchro, 1 Xyz et 1 Pendule)	\r\n(Cette carte est toujours traitée comme "Z-ARC, Roi Suprême".)	\r\nCette carte face verso dans l''Extra Deck doit d''abord être soit Invoquée par Fusion soit Invoquée Spécialement en Sacrifiant 1 "Z-ARC, Roi Suprême" TÉNÈBRES de Niveau 12. \r\nSi cette carte est Invoquée Spécialement depuis l''Extra Deck: vous pouvez placer 1 Monstre Pendule depuis votre Deck dans votre Zone Pendule. \r\nSi cette carte dans la Zone Monstre est détruite: vous pouvez placer cette carte dans votre Zone Pendule.','\r',char(13)),'\n',char(10)),'','Mélanger 1 carte de votre Zone Pendule dans le Deck ?','Invoquer Spécialement ce monstre en ignorant ses conditions d''Invocation ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6218705,'Dragon Arcray aux Yeux Impairs',replace(replace('Échelle Pendule = 13\r\n[ Effet Pendule ]\r\nSi vous avez 2 cartes dans vos Zones Pendule: vous pouvez Invoquer Spécialement cette carte, puis vous pouvez appliquer cet effet.\r\n● Mélangez 1 carte depuis votre Zone Pendule dans le Deck, puis si elle a été ajoutée à votre Extra Deck, vous pouvez l''Invoquer Spécialement, en ignorant ses conditions d''Invocation.	\r\nVous ne pouvez utiliser cet effet de "Dragon Arcray aux Yeux Impairs" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\n4 monstres Dragon (1 Fusion, 1 Synchro, 1 Xyz et 1 Pendule)	\r\n(Cette carte est toujours traitée comme "Z-ARC, Roi Suprême".)	\r\nCette carte face verso dans l''Extra Deck doit d''abord être soit Invoquée par Fusion soit Invoquée Spécialement en Sacrifiant 1 "Z-ARC, Roi Suprême" TÉNÈBRES de Niveau 12. \r\nSi cette carte est Invoquée Spécialement depuis l''Extra Deck: vous pouvez placer 1 Monstre Pendule depuis votre Deck dans votre Zone Pendule. \r\nSi cette carte dans la Zone Monstre est détruite: vous pouvez placer cette carte dans votre Zone Pendule.','\r',char(13)),'\n',char(10)),'','Mélanger 1 carte de votre Zone Pendule dans le Deck ?','Invoquer Spécialement ce monstre en ignorant ses conditions d''Invocation ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6247535,'Dragon eXcharge Chargeborrelle',replace(replace('2 monstres TÉNÈBRES Dragon de Niveau 4	\r\nAucun joueur ne peut cibler cette carte Invoquée par Xyz avec des effets de monstre (ses propres effets exclus). \r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre face recto sur le Terrain; il perd 600 ATK/DEF, puis, vous pouvez Invoquer Spécialement 1 monstre "Borrelle" depuis votre Cimetière, mais bannissez-le durant la End Phase, et aussi, vous ne pouvez ni Invoquer Spécialement d''autres monstres ni attaquer directement le reste de ce tour.','\r',char(13)),'\n',char(10)),'','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6256844,'Genex-R Turbo','Lorsque cette carte est Invoquée Normalement, vous pouvez ajouter 1 monstre "Genex" de Niveau 1 depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6260554,'Un Coup de Tonneau','Lorsqu''une Carte Magie/Piège ou un effet de monstre est activé: Sacrifiez tous les "Jeton Bête Fantôme Méca" que vous contrôlez; annulez l''activation, et si vous le faites, détruisez-la/le.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6260560,'Lævateinn l''Épée Brûlante',replace(replace('2 monstres FEU	\r\nDurant la Main Phase (Effet Rapide): vous pouvez Sacrifier 1 autre monstre FEU, puis ciblez 1 monstre FEU dans votre Cimetière du même Type d''origine, mais d''un Niveau d''origine inférieur au monstre; Invoquez-le Spécialement en Position de Défense. \r\nSi une ou plusieurs cartes face verso dans votre Zone Magie & Piège vont être détruites par un effet de carte de l''adversaire, vous pouvez bannir cette carte que vous contrôlez à la place. \r\nVous ne pouvez utiliser chaque effet de "Lævateinn l''Épée Brûlante" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6276588,'Karakuri 919 "Kuick" le Ninja',replace(replace('Cette carte doit attaquer, si possible. \r\nLorsque cette carte face recto est sélectionnée comme cible d''une attaque, changez sa position de combat. \r\nLorsque cette carte détruit un monstre de l''adversaire au combat et l''envoie au Cimetière, sélectionnez 1 monstre "Karakuri" de Niveau 4 ou moins dans votre Cimetière, et Invoquez-le Spécialement en Position de Défense face recto.','\r',char(13)),'\n',char(10)),'Changer la position de combat','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6278008,'Cycle du Dragon Étoilé',replace(replace('Ciblez 1 Monstre Fusion, Synchro, Xyz ou Lien sur le Terrain; renvoyez le monstre face recto à l''Extra Deck, puis, selon son type de carte, vous pouvez Invoquer Spécialement 1 monstre approprié depuis l''un des Cimetières sur votre Terrain.\r\n● Fusion: Monstre du même Attribut.\r\n● Synchro: Monstre d''un Niveau inférieur.\r\n● Xyz: Monstre du même Niveau que son Rang.\r\n● Lien: Monstre du même Type.	\r\nVous ne pouvez activer qu''1 "Cycle du Dragon Étoilé" par tour.','\r',char(13)),'\n',char(10)),'','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6283472,'Fierté Amorphage',replace(replace('Échelle Pendule = 3\r\n[ Effet Pendule ]\r\nTant que vous contrôlez un monstre "Amorphage", aucun joueur ne reçoit de dommages d''effet. \r\nUne fois par tour, durant votre Standby Phase, Sacrifiez 1 monstre ou détruisez cette carte.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est Invoquée par Pendulation ou retournée face recto, aucun joueur ne peut Invoquer Spécialement de monstres (monstres "Amorphage" exclus) depuis l''Extra Deck tant que cette carte est face recto sur le Terrain.','\r',char(13)),'\n',char(10)),'Sacrifier 1 monstre que vous contrôlez ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6284176,'Kanzashi la Reine Rikka',replace(replace('2 monstres de Niveau 6	\r\nSi un ou plusieurs monstres sont Sacrifiés (sauf durant la Damage Step): vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre dans l''un des Cimetières; Invoquez-le Spécialement, mais annulez ses effets, et aussi, il devient un monstre Plante. \r\nSi un ou plusieurs monstres Plante que vous contrôlez vont être détruits par un effet de carte, vous pouvez Sacrifier 1 monstre Plante depuis votre main ou Terrain à la place. \r\nVous ne pouvez utiliser chaque effet de "Kanzashi la Reine Rikka" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6285791,'Le Ver Malfaisant','Cette carte face recto sur le Terrain est renvoyée dans la main de son propriétaire durant la End Phase de votre tour.','Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6297941,'Cambrioleur','Un rat furtif. Il viendra vers vous avec son énorme griffe gauche.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6309986,'Crépuscule à Cinq Étoiles',replace(replace('Si le seul monstre que vous contrôlez est 1 monstre de Niveau 5: Sacrifiez le monstre; Invoquez Spécialement 5 monstres (1 "Kuribah", 1 "Kuribeille", 1 "Kuribou", 1 "Kuribeh" et 1 "Kuriboh") depuis votre main, Deck et/ou Cimetière, mais ils ne peuvent pas être Sacrifiés pour une Invocation Sacrifice. \r\nVous ne pouvez activer qu''1 "Crépuscule à Cinq Étoiles" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6311717,'Luminine, Sorcière de la Bonne Aventure',replace(replace('Lorsque vous piochez cette carte: vous pouvez la révéler; Invoquez-la Spécialement depuis votre main. \r\nSi cette carte est Invoquée Spécialement depuis la main: vous pouvez cibler 1 monstre que vous contrôlez; envoyez-le au Cimetière, et si vous le faites, Invoquez Spécialement 1 monstre Magicien de Niveau 1 depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Luminine, Sorcière de la Bonne Aventure" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6320631,'Golem Koa''ki Meiru','Lorsque cette carte est détruite au combat et envoyée au Cimetière, vous pouvez ajouter 1 "Noyau d''Énergie Koa''ki Meiru" ou 1 monstre "Koa''ki Meiru" de Niveau 4 ou moins depuis votre Deck ou votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6325660,'Étincelle Dominus',replace(replace('Durant le tour où votre adversaire a activé un effet de monstre dans la main ou Cimetière, vous pouvez activer cette carte depuis votre main. \r\nCiblez 1 monstre contrôlé par votre adversaire; bannissez-le, puis si vous n''avez aucun Piège dans votre Cimetière, votre adversaire peut Invoquer Spécialement 1 monstre depuis sa main. \r\nSi vous avez activé cette carte depuis votre main, vous ne pouvez pas activer les effets de monstres TERRE, EAU, FEU et VENT le reste de ce Duel. \r\nVous ne pouvez activer qu''1 "Étincelle Dominus" par tour.','\r',char(13)),'\n',char(10)),'Bannir','Activer depuis la main en appliquant l''effet de "Étincelle Dominus"','Invocation Spéciale?','L''effet de "Étincelle Dominus" est actuellement appliqué.','','','','','','','','','','','','');
INSERT INTO texts VALUES(6327734,'Hu-Li le Bijou Mikanko',replace(replace('Si cette carte n''est pas équipée avec une Carte d''Équipement, vous ne recevez aucun dommage de combats impliquant cette carte. \r\nSi cette carte est équipée avec une Carte d''Équipement, elle ne peut pas être détruite au combat et votre adversaire reçoit les dommages de combat que vous auriez dû recevoir de combats impliquant cette carte. \r\nTant que vous contrôlez une Carte d''Équipement, votre adversaire ne peut pas cibler de cartes "Mikanko" que vous contrôlez avec des effets de carte. \r\nSi au moins l''un des joueurs équipe une ou plusieurs Cartes d''Équipement à cette carte: vous pouvez ajouter 1 Piège "Mikanko" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Hu-Li le Bijou Mikanko" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6327735,'Hu-Li le Bijou Mikanko',replace(replace('Si cette carte n''est pas équipée avec une Carte d''Équipement, vous ne recevez aucun dommage de combats impliquant cette carte. \r\nSi cette carte est équipée avec une Carte d''Équipement, elle ne peut pas être détruite au combat et votre adversaire reçoit les dommages de combat que vous auriez dû recevoir de combats impliquant cette carte. \r\nTant que vous contrôlez une Carte d''Équipement, votre adversaire ne peut pas cibler de cartes "Mikanko" que vous contrôlez avec des effets de carte. \r\nSi au moins l''un des joueurs équipe une ou plusieurs Cartes d''Équipement à cette carte: vous pouvez ajouter 1 Piège "Mikanko" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Hu-Li le Bijou Mikanko" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6330307,'DZW - Chimère Blindée',replace(replace('Vous pouvez cibler 1 monstre "Numéro C39" que vous contrôlez; équipez ce monstre depuis votre main ou votre Terrain à la cible. \r\nLe monstre équipé ne peut pas être détruit au combat. À la fin de la Damage Step, lorsque le monstre équipé attaque un monstre de votre adversaire, mais le monstre de votre adversaire n''a pas été détruit au combat: vous pouvez faire devenir 0 l''ATK du monstre de votre adversaire (même après que cette carte quitte le Terrain ou que le monstre n''est pas affecté par des effets de carte), et si vous le faites, le monstre équipé peut attaquer une seconde fois à la suite le même monstre.','\r',char(13)),'\n',char(10)),'Équiper','Attaques multiples','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6337436,'Magicien à Rafales','Tant que cette carte est face recto sur le Terrain, infligez 400 points de dommages aux Life Points de votre adversaire à chaque fois que vous activez 1 Carte Magie Normale.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6343408,'Fouilles Miraculeuses','Si min. 5 de vos monstres sont bannis: ciblez-en 3; renvoyez-les au Cimetière.','Choisissez la carte à renvoyer au Cimetière','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6351147,'Transaction Rollback',replace(replace('Payez la moitié de vos LP, puis ciblez 1 Piège Normal ("Transaction Rollback" exclu) dans le Cimetière de votre adversaire; cet effet devient l''effet d''activation de la carte. \r\nVous pouvez bannir cette carte depuis votre Cimetière, et payez la moitié de vos LP, puis ciblez 1 Piège Normal ("Transaction Rollback" exclu) dans votre Cimetière; cet effet devient l''effet d''activation de la carte. \r\nVous ne pouvez utiliser qu''1 effet de "Transaction Rollback" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6351548,'Chevalier de l''Aube',replace(replace('Si cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez envoyer 1 monstre LUMIÈRE depuis votre Deck au Cimetière. \r\nSi cette carte est envoyée depuis votre Deck au Cimetière: ciblez 1 monstre LUMIÈRE dans votre Cimetière; placez la cible au-dessus de votre Deck. \r\nVous ne pouvez utiliser qu''1 effet de "Chevalier de l''Aube" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Renvoyer au Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6353603,'Confrérie du Poing de Feu - Ours',replace(replace('Une fois par tour, lorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez Poser 1 Magie "Formation Feu" directement depuis votre Deck. \r\nUne fois par tour: vous pouvez envoyer 1 Magie/Piège "Formation Feu" face recto que vous contrôlez au Cimetière, puis ciblez 1 monstre sur le Terrain; détruisez la cible.','\r',char(13)),'\n',char(10)),'Poser','Détruire un monstre','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6355563,'Tête Action-Y',replace(replace('Si cette carte est Invoquée Spécialement: vous pouvez équiper 1 monstre LUMIÈRE Machine de Niveau 4 depuis votre main ou Cimetière à cette carte comme Magie d''Équipement, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres LUMIÈRE exclus) depuis l''Extra Deck le reste de ce tour. \r\nUne fois par tour, vous pouvez SOIT: ciblez 1 monstre Machine que vous contrôlez; équipez cette carte à la cible, SOIT: déséquipez cette carte et Invoquez-la Spécialement. \r\nSi le monstre équipé va être détruit au combat ou par un effet de carte, détruisez cette carte à la place.','\r',char(13)),'\n',char(10)),'Effet d''Équipement','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6357341,'Les Six Shinobis','Si vous contrôlez 6 monstres "Six Samouraïs" d''Attributs différents: sautez le prochain tour de votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6361316,'TASSE DE RÉVEIL ! Kuro',replace(replace('FLIP: Vous pouvez cibler 1 autre monstre face recto sur le Terrain; changez-le en Position de Défense face verso.\r\nVous pouvez révéler cette carte dans votre main; ajoutez 1 monstre Flip VENT ("TASSE DE RÉVEIL ! Kuro" exclu) depuis votre Deck à votre main, puis défaussez 1 carte. \r\n(Effet Rapide): vous pouvez cibler 1 monstre en Position de Défense face verso sur le Terrain; changez-le en Position de Défense face recto. \r\nVous ne pouvez utiliser chaque effet de "TASSE DE RÉVEIL ! Kuro" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet d''ajout à la main','Poser','Position de combat','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6367785,'Eldeen','La canne de ce monstre lance de puissants sortilèges.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368038,'Gaïa le Chevalier Implacable','Chevalier dont le destrier voyage plus vite que le vent. Sa charge de bataille est une force à ne pas sous-estimer.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368039,'Gaïa le Chevalier Implacable','Chevalier dont le destrier voyage plus vite que le vent. Sa charge de bataille est une force à ne pas sous-estimer.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368040,'Gaïa le Chevalier Implacable','Chevalier dont le destrier voyage plus vite que le vent. Sa charge de bataille est une force à ne pas sous-estimer.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6374519,'Spectacle Spécial Incroyable','Lorsque votre adversaire active une carte ou un effet qui cible un ou plusieurs monstres "Incroyable" que vous contrôlez: ciblez 1 de ces monstres "Incroyable" que vous contrôlez; renvoyez-le à la main, puis, vous pouvez Invoquer Spécialement 1 monstre "Incroyable" depuis votre main.','','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6387204,'Numéro C6 : Atlandis du Chaos Chronomal',replace(replace('3 monstres de Niveau 7	\r\nSi vous activez un des effets de cette carte, votre adversaire ne reçoit pas de dommages complémentaires ce tour. \r\nUne fois par tour: vous pouvez cibler 1 monstre contrôlé par votre adversaire; équipez la cible à cette carte comme une Carte Magie d''Équipement dont l''effet fait gagner 1000 ATK à ce monstre. \r\nSi cette carte a "Numéro 6 : Atlandis Chronomal" comme Matériel Xyz, elle gagne cet effet.\r\n● Vous pouvez détacher 3 Matériels Xyz de cette carte, et envoyez tous les monstres "Numéro" équipés par l''effet de cette carte au Cimetière (min. 1); mettez les Life Points de votre adversaire à 100.','\r',char(13)),'\n',char(10)),'Équiper','Les LP deviennent 100','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6390406,'Emblème du Destructeur de Dragon','Ajoutez 1 "Buster Blader" depuis votre Deck ou Cimetière à votre main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6400512,'Cybercommandant',replace(replace('Force de frappe équipée de lance-roquettes et de bazookas.	\r\n\r\n(Cette carte n''est pas traitée comme une carte "Cyber".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6417578,'Fusion Marionnette de l''Ombre El',replace(replace('Invoquez par Fusion 1 Monstre Fusion "Marionnette de l''Ombre" depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain. \r\nVous ne pouvez activer qu''1 "Fusion Marionnette de l''Ombre El" par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6430659,'Courrier Infecté','Une fois par tour: vous pouvez cibler 1 monstre de max. Niveau 4 que vous contrôlez; ce tour, il peut attaquer directement votre adversaire. À la fin de la Battle Phase, envoyez-le au Cimetière.','Attaque directe','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6438003,'Guerriers Anciens - Fallacieux Jia Wen',replace(replace('Vous pouvez cibler 1 Magie Continue/Piège Continu que vous contrôlez; envoyez-le au Cimetière, et si vous le faites, divisez par deux l''ATK de 2 monstres face recto sur le Terrain jusqu''à la fin de ce tour. \r\nSi une ou plusieurs cartes contrôlées par votre adversaire sont détruites au combat ou par un effet de carte: vous pouvez cibler 1 carte "Guerriers Anciens" ("Guerriers Anciens - Fallacieux Jia Wen" exclu) dans votre Cimetière; ajoutez-la à votre main. \r\nVous ne pouvez utiliser chaque effet de "Guerriers Anciens - Fallacieux Jia Wen" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Récupérer depuis le Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6442944,'Kaiser Serpent des Mers',replace(replace('Si votre adversaire contrôle un monstre et que vous n''en contrôlez aucun, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Kaiser Serpent des Mers" qu''une fois par tour de cette façon. \r\nLorsqu''elle est Invoquée de cette façon: vous pouvez Invoquer Spécialement 1 monstre Serpent de Mer de Niveau 8 depuis votre main ou Cimetière, mais son ATK/DEF deviennent 0. \r\nSi cette carte est Invoquée Spécialement, son Niveau devient 4 et son ATK d''origine devient 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6459419,'Rituel Shamanique Amazonesse','Détruisez tous les monstres "Amazonesse" que vous contrôlez, puis, vous pouvez Invoquer Spécialement un nombre de monstres "Amazonesse" de max. Niveau 4 depuis votre Cimetière en Position de Défense face recto, inférieur ou égal au nombre de monstres détruits par cet effet.','Invocation Spéciale ?','Invocation Spéciale ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6471156,'Acte de Poupées',replace(replace('Vous pouvez bannir 1 monstre "Poupée Truquée" depuis votre Cimetière; jusqu''à la fin de ce tour (même si cette carte quitte le Terrain), tous les monstres que vous contrôlez actuellement deviennent du Niveau du monstre banni. \r\nSi un ou plusieurs monstres "Poupée Truquée" face recto que vous contrôlez sont détruits au combat ou par un effet de carte de l''adversaire, et envoyés au Cimetière: vous pouvez cibler 1 de vos monstres "Poupée Truquée" bannis; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser chaque effet de "Acte de Poupées" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6480253,'Wroughtweiller','Si cette carte est détruite au combat et envoyée au Cimetière: ciblez 1 carte "HÉROS Élémentaire" et 1 "Polymérisation" dans votre Cimetière; ajoutez-les à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6483224,'Rayon, le Dragon de la Demi-Lune',replace(replace('Si votre adversaire contrôle un Monstre Xyz face recto, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nSi vous le faites, le Niveau de cette carte devient 8.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6494106,'Défaite de l''Œil Maléfique',replace(replace('Si vous contrôlez un monstre "Œil Maléfique": ciblez 1 monstre sur le Terrain, ou max. 2 à la place si "L''Œil Maléfique de Sélène" est dans votre Zone Magie & Piège; renvoyez-les à la main. \r\nVous ne pouvez activer qu''1 "Défaite de l''Œil Maléfique" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6498706,'Déploiement Fusion',replace(replace('Révélez 1 Monstre Fusion dans votre Extra Deck et Invoquez Spécialement 1 des Matériels Fusion dont le nom est mentionné sur le monstre depuis votre main ou Deck, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Fusion exclus) depuis l''Extra Deck le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Déploiement Fusion" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6498707,'Déploiement Fusion',replace(replace('Révélez 1 Monstre Fusion dans votre Extra Deck et Invoquez Spécialement 1 des Matériels Fusion dont le nom est mentionné sur le monstre depuis votre main ou Deck, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Fusion exclus) depuis l''Extra Deck le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Déploiement Fusion" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6500778,'Distillation du Chaos',replace(replace('Tant que cette carte est face recto sur le Terrain, les cartes envoyées à votre Cimetière sont bannies à la place. \r\nVous pouvez activer 1 de ces effets;\r\n● Ajoutez 1 "Macro Cosmos" ou 1 carte qui le mentionne ("Distillation du Chaos" exclu) depuis votre Deck à votre main.\r\n● Si "Macro Cosmos" est sur le Terrain: bannissez cette carte face recto depuis la Zone Magie & Piège; ajoutez 1 monstre LUMIÈRE avec ? ATK depuis votre Deck à votre main.	\r\nVous ne pouvez utiliser cet effet de "Distillation du Chaos" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter "Macro Cosmos" ou une carte qui le mentionne à la main','Ajouter un monstre à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6511113,'Traptrix Rafflesia',replace(replace('2 monstres de Niveau 4	\r\nNon affectée par des effets de Piège tant qu''elle a du Matériel. \r\nLes monstres "Traptrix" que vous contrôlez ("Traptrix Rafflesia" exclu) ne peuvent être détruits ni au combat ni par des effets de carte. \r\nVotre adversaire ne peut pas cibler de monstres "Traptrix" que vous contrôlez ("Traptrix Rafflesia" exclu) avec des effets de carte. \r\nUne fois par tour (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte et envoyer 1 Piège Normal "Trappe" qui remplit ses conditions d''activation depuis votre Deck au Cimetière; cet effet devient l''effet de la Carte Piège lorsque la carte est activée.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6540606,'Aoi, Artiste de l''Eau Spirituelle','Sacrifiez 1 monstre EAU; regardez la main de votre adversaire, puis envoyez 1 carte depuis sa main au Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6544078,'Izanagi',replace(replace('Vous pouvez Invoquer Spécialement cette carte depuis votre main en retirant du jeu 1 monstre Spirit de votre main. \r\nVous n''êtes pas obligé d''activer l''effet qui renvoie les monstres Spirit que vous contrôlez dans la main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6547248,'Nouveau Visage de la Troupe des Clowns',replace(replace('Durant la Standby Phase: vous pouvez mélanger 3 cartes "Troupe des Clowns" depuis votre Cimetière et/ou bannissement dans le Deck, puis piochez 1 carte. \r\nSi vous Invoquez par Sacrifice un monstre: vous pouvez cibler un nombre d''autres Magies/Pièges sur le Terrain, inférieur ou égal au nombre de monstres Sacrifiés pour son Invocation Sacrifice; détruisez-les. \r\nSi cette carte est envoyée au Cimetière, sauf depuis le Terrain: vous pouvez la placer face recto sur votre Terrain. \r\nVous ne pouvez utiliser chaque effet de "Nouveau Visage de la Troupe des Clowns" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Récupérer et piocher','Effet de destruction','Placer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6552938,'Raidraptor - Strix Gouvernail',replace(replace('Si cette carte est Invoquée Spécialement depuis la main par l''effet d''une carte "Raidraptor" ou Invoquée Normalement: vous pouvez infliger 600 points de dommages à votre adversaire. \r\nLorsqu''un monstre de l''adversaire déclare une attaque qui cible cette carte: vous pouvez Invoquer Spécialement max. 2 monstres "Raidraptor" depuis votre main, et si vous le faites, les monstres contrôlés par votre adversaire ne peuvent pas cibler ces monstres avec une attaque ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6552971,'A.I. Vous Rencontre',replace(replace('Révélez 1 monstre Cyberse avec 2300 ATK dans votre main ou Extra Deck, et ajoutez 1 monstre "@Ignister" du même Attribut depuis votre Deck à votre main. \r\nDurant la End Phase de ce tour, recevez 2300 points de dommages si vous n''avez pas Invoqué Spécialement le monstre révélé ou un monstre du même nom, après avoir résolu cet effet. \r\nLe reste de ce tour après la résolution de cette carte, vous ne pouvez pas activer d''effets de monstre (monstres Cyberse exclus). \r\nVous ne pouvez activer qu''1 "A.I. Vous Rencontre" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6556178,'Régénérateur Borrelle',replace(replace('Activez cette carte en ciblant 1 monstre "Rokkette" dans votre Cimetière; Invoquez-le Spécialement et équipez-le avec cette carte, mais bannissez-le lorsque cette carte quitte le Terrain. \r\nSi cette carte est envoyée au Cimetière parce que le monstre équipé est détruit: vous pouvez piocher 1 carte. \r\nVous ne pouvez utiliser chaque effet de "Régénérateur Borrelle" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6556909,'Âme aux Yeux Rouges',replace(replace('Le nom de cette carte devient "Dragon Noir aux Yeux Rouges" tant qu''elle est sur le Terrain ou dans le Cimetière. \r\nSi votre adversaire Invoque Spécialement un ou plusieurs monstres (sauf durant la Damage Step): vous pouvez envoyer cette carte depuis votre main ou Terrain au Cimetière; Invoquez Spécialement 1 monstre "Yeux Rouges" ("Âme aux Yeux Rouges" exclu) depuis votre main ou Deck. \r\nVous ne pouvez utiliser cet effet de "Âme aux Yeux Rouges" qu''une fois par tour. \r\n(Effet Rapide): vous pouvez cibler 1 "Dragon Noir aux Yeux Rouges" que vous contrôlez; infligez des dommages à votre adversaire égaux à l''ATK d''origine du monstre. \r\nVous ne pouvez utiliser cet effet de "Âme aux Yeux Rouges" qu''une fois par Duel.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6560411,'Dragon Rose Ronces',replace(replace('1 Syntoniseur Plante + 1+ monstre non-Syntoniseur	\r\nChaque fois que votre adversaire active un effet de monstre, infligez 600 points de dommages à votre adversaire, et si vous le faites, tous les monstres actuellement contrôlés par votre adversaire perdent 600 ATK. \r\nVous ne pouvez utiliser chacun des effets suivants de "Dragon Rose Ronces" qu''une fois par tour. \r\nDurant la Main Phase (Effet Rapide): vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 "Dragon Rose Noire" depuis votre Extra Deck (ceci est traité comme Invocation Synchro). \r\nVous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 Syntoniseur Plante de max. Niveau 4 depuis votre Cimetière.','\r',char(13)),'\n',char(10)),'','Invocation Spéciale','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6568731,'Narval Iceberg, Bête Glaciale',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur EAU	\r\nChaque fois qu''un ou plusieurs autres monstres que vous contrôlez sont détruits par une attaque ou effet de carte de votre adversaire: infligez 600 points de dommages à votre adversaire. \r\nDurant la Battle Phase, lorsque votre adversaire active une carte ou un effet tant que vous contrôlez un autre monstre (Effet Rapide): vous pouvez annuler l''effet, et si vous le faites, détruisez la carte. \r\nVous ne pouvez utiliser cet effet de "Narval Iceberg, Bête Glaciale" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6579928,'Six Samouraïs Secrets - Kizaru',replace(replace('Lorsque cette carte est Invoquée Spécialement: vous pouvez ajouter 1 monstre "Six Samouraïs" d''un Attribut différent de chaque monstre que vous contrôlez depuis votre Deck à votre main. \r\nSi exactement 1 monstre "Six Samouraïs" que vous contrôlez (et aucune autre carte) va être détruit par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6588580,'Station Spatiothermale Genex',replace(replace('"Contrôleur Genex" + 1 monstre FEU non Syntoniseur ou plus	\r\nCette carte gagne 200 points d''ATK pour chaque monstre FEU dans votre Cimetière. \r\nSi cette carte détruit un monstre de l''adversaire au combat, infligez 200 points de dommages à votre adversaire pour chaque monstre "Genex" dans votre Cimetière.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6589707,'Terreurs dans la Cité Cachée',replace(replace('Votre adversaire ne peut pas cibler les monstres en Position de Défense face verso que vous contrôlez avec des effets de carte. \r\nLes monstres que vous contrôlez qui ont été retournés face recto tant que cette carte était face recto sur le Terrain gagnent 1500 ATK/DEF. \r\nSi cette carte dans la Zone Magie & Piège de son propriétaire est détruite par un effet de carte de l''adversaire: vous pouvez cibler 1 monstre dans votre Cimetière; Invoquez-le Spécialement en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6595475,'Onomatopaire',replace(replace('Vous ne pouvez activer qu''1 "Onomatopaire" par tour. \r\nEnvoyez 1 carte depuis votre main au Cimetière; ajoutez max. 2 de ces monstres depuis votre Deck à votre main (vous ne pouvez pas en ajouter 2 de la même catégorie).\r\n● 1 monstre "Zubaba"\r\n● 1 monstre "Gagaga"\r\n● 1 monstre "Gogogo"\r\n● 1 monstre "Dododo"','\r',char(13)),'\n',char(10)),'Continuer à choisir des monstres à ajouter à la main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6602300,'Phénix de Flammes, l''Oiseau de Bombardement',replace(replace('1 monstre de Type Machine + 1 monstre de Type Pyro	\r\nUne fois par tour, durant votre Main Phase: vous pouvez infliger 300 points de dommages à votre adversaire pour chaque carte sur le Terrain. \r\nCette carte ne peut pas attaquer durant le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Infliger des dommages','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6609736,'Noh-P.U.N.K. Note du Cerf',replace(replace('Vous pouvez révéler 1 autre monstre "P.U.N.K." dans votre main; Invoquez Spécialement soit le monstre révélé soit cette carte, et envoyez l''autre au Cimetière. \r\nSi cette carte est envoyée depuis le Terrain à votre Cimetière: vous pouvez cibler 1 monstre "P.U.N.K." (monstres de Niveau 5 exclus) dans votre Cimetière; Invoquez-le Spécialement, mais vous ne pouvez pas Invoquer Spécialement "Noh-P.U.N.K. Note du Cerf" le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Noh-P.U.N.K. Note du Cerf" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6614221,'Roi de Brume',replace(replace('Vous pouvez Sacrifier 1 monstre ou aucun monstre pour Invoquer Normalement (mais pas Poser) cette carte. \r\nL''ATK de cette carte devient la somme des ATK d''origine des monstres Sacrifiés. \r\nAucun joueur ne peut Sacrifier de cartes.','\r',char(13)),'\n',char(10)),'Invoquer avec 1 Sacrifice','Invoquer sans Sacrifice','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6616912,'Gabrion le Seigneur du Temps',replace(replace('Non Invocable Spécialement depuis le Deck. \r\nSi vous ne contrôlez aucun monstre, vous pouvez Invoquer Normalement cette carte sans Sacrifices. \r\nNon destructible ni au combat ni par des effets de carte. \r\nVous ne recevez aucun dommage de combat d''attaques impliquant cette carte. À la fin de la Battle Phase, si cette carte a combattu: mélangez autant de cartes contrôlées par votre adversaire que possible dans les Decks, puis il pioche un nombre de cartes égal au nombre mélangé dans son Main Deck. \r\nUne fois par tour, durant votre Standby Phase: mélangez cette carte dans le Deck.','\r',char(13)),'\n',char(10)),'Invocation Normale sans Sacrifice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6622715,'Encodeur Bavard',replace(replace('2+ monstres Cyberse	\r\nUne fois par tour, avant le calcul des dommages, si votre monstre pointé par cette carte combat un monstre de l''adversaire avec une ATK supérieure: vous pouvez activer cet effet; ce combat, votre monstre ne peut pas être détruit au combat et vous ne recevez aucun dommage de combat. \r\nAprès ce calcul des dommages, jusqu''à la fin de ce tour, faites gagner à cette carte ou 1 monstre qu''elle pointe une ATK égale à l''ATK du monstre de l''adversaire combattu.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6625096,'Princesse Jolithon',replace(replace('Lorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez bannir cette carte; Invoquez Spécialement 1 monstre Poisson de max. Niveau 4 ("Princesse Jolithon" exclu) depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Princesse Jolithon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6628343,'Chevalier du Commencement',replace(replace('Un monstre "Soldat du Lustre Noir" Invoqué Rituellement en utilisant cette carte gagne ces effets. \r\nVous ne pouvez utiliser cet effet de "Chevalier du Commencement" qu''une fois par tour.\r\n● Une fois par tour: vous pouvez cibler 1 monstre contrôlé par votre adversaire; bannissez-le.\r\n● Lorsque cette carte détruit un monstre de votre adversaire au combat et l''envoie au Cimetière: vous pouvez activer cet effet; cette carte peut attaquer une seconde fois à la suite.	\r\nSi cette carte est bannie depuis le Cimetière: vous pouvez ajouter 1 Carte Magie Rituelle depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Chevalier du Commencement" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Bannir 1 monstre contrôlé par votre adversaire (Chevalier du Commencement)','Peut attaquer 1 fois de plus (Chevalier du Commencement)','L''effet de "Chevalier du Commencement" est actuellement appliqué.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6631034,'Givrosaure','Le métabolisme de ce monstre lui permet d''endurer de longues périodes de froid, exploitant sa puissance pour devenir une créature de glace ! Personne d''autre ne peut supporter de telles températures, particulièrement les victimes de son déchaînement glacial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6636319,'Evil★Jumelle Ki-sikil Transaction',replace(replace('1 monstre "Ki-sikil"	\r\nVous ne pouvez Invoquer par Lien "Evil★Jumelle Ki-sikil Transaction" qu''une fois par tour. \r\nVous pouvez envoyer 1 monstre "Lil-la" depuis votre Deck ou Extra Deck au Cimetière; ce tour, appliquez cet effet.\r\n● Chaque fois que votre adversaire active une carte ou un effet en réponse à l''activation d''effet de votre monstre "Ki-sikil" ou "Lil-la", piochez 1 carte lorsque la carte/effet est résolu.	\r\nVous ne pouvez utiliser cet effet de "Evil★Jumelle Ki-sikil Transaction" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6637331,'Bystial Druiswurm',replace(replace('Vous pouvez cibler 1 monstre LUMIÈRE ou TÉNÈBRES dans l''un des Cimetières; bannissez-le, et si vous le faites, Invoquez Spécialement cette carte depuis votre main. \r\nCeci est un Effet Rapide si votre adversaire contrôle un monstre. \r\nSi cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez cibler 1 monstre Invoqué Spécialement contrôlé par votre adversaire; envoyez-le au Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Bystial Druiswurm" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6659193,'Haut Magicien Trapèze Mageartiste',replace(replace('2 monstres Magicien de Niveau 5	\r\nNon destructible ni au combat ni par des effets de carte tant qu''elle a du Matériel. \r\nVotre adversaire reçoit les dommages d''effet que vous auriez dû recevoir, un nombre de fois chaque tour inférieur ou égal au nombre de Matériels attachés à cette carte. \r\nSi cette carte a "Magicien Trapèze Mageartiste" comme Matériel, elle gagne cet effet.\r\n● Vous pouvez détacher 1 Matériel de cette carte; durant chaque Battle Phase ce tour, cette carte peut faire max. 3 attaques.','\r',char(13)),'\n',char(10)),'3 attaques','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6691855,'Bouclier à Pics avec Chaîne',replace(replace('Ciblez 1 monstre face recto sur le Terrain; équipez cette carte à la cible. \r\nIl gagne 500 ATK. \r\nSi le monstre équipé combat tant qu''il est en Position de Défense, il gagne une DEF égale à son ATK durant le calcul des dommages uniquement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6696168,'Festiballon',replace(replace('Si cette carte combat un monstre, aucun de ces 2 monstres ne peut être détruit par ce combat. \r\nChaque fois qu''un monstre déclare une attaque, cette carte gagne 1000 ATK. \r\nDurant votre Main Phase: vous pouvez faire perdre exactement 5000 ATK à cette carte, et si vous le faites, détruisez toutes les autres cartes sur le Terrain. \r\nVous ne pouvez utiliser cet effet de "Festiballon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6713443,'Formation Feu Ultime - Seito','Bannissez 7 Cartes Magie/Piège "Formation Feu" depuis votre Cimetière; Invoquez Spécialement autant de monstres "Poing de Feu" que possible depuis votre Cimetière, puis vous pouvez Poser un nombre de Cartes Magie/Piège "Formation Feu" ("Formation Feu Ultime - Seito" exclu) directement depuis votre Deck, inférieur ou égal au nombre de monstres Invoqués Spécialement par cet effet.','Poser sur votre Terrain une Magie/Piège dont le nom contient "Formation de Feu" ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6728559,'Protos Archnéméses',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 3 monstres d''Attributs différents depuis votre Cimetière et/ou Terrain face recto. \r\nNon destructible par des effets de carte. \r\nVous pouvez déclarer 1 Attribut de monstre sur le Terrain; détruisez tous les monstres sur le Terrain de cet Attribut, et aussi, jusqu''à la fin du prochain tour, aucun joueur ne peut Invoquer Spécialement de monstres de cet Attribut. \r\nVous ne pouvez utiliser cet effet de "Protos Archnéméses" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6733059,'Le Repère du Crâne',replace(replace('Retirez du jeu n''importe quel nombre de monstres de votre Cimetière. \r\nDétruisez 1 monstre face recto sur le Terrain dont le Niveau est égal au nombre de monstres que vous avez retiré du jeu.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Le Repère du Crâne" maintenant ?','Détruire','Sélectionnez le nombre de monstres à bannir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6740720,'Seiyaryu','Dragon qui consume les forces du mal avec ses flammes mystiques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6763530,'Bannissement du Marqué',replace(replace('Ciblez 1 monstre "Despia" ou 1 Monstre Fusion de min. Niveau 8 dans votre Cimetière; Invoquez-le Spécialement, puis vous pouvez appliquer cet effet.\r\n● Invoquez par Fusion 1 Monstre Fusion de min. Niveau 8 depuis votre Extra Deck, en bannissant les Matériels Fusion mentionnés sur celui-ci depuis au moins l''un des Terrains.	\r\nVous ne pouvez activer qu''1 "Bannissement du Marqué" par tour.','\r',char(13)),'\n',char(10)),'Invocation Fusion ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6764709,'Dragster des Ténèbres F.A.',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en ayant un monstre "F.A." de min. Niveau 7 sur le Terrain, mais pas "Dragster des Ténèbres F.A." dans votre Zone Monstre. \r\nGagne une ATK égale à son Niveau x 300. \r\nChaque fois qu''une Carte Magie/Piège "F.A." ou effet de Magie/Piège "F.A." est activé: vous pouvez augmenter le Niveau de cette carte de 1. \r\nUne fois par tour: vous pouvez cibler 1 carte sur le Terrain; réduisez le Niveau de cette carte de 3, et si vous le faites, détruisez la cible.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6766208,'D/D/D Alexandre, Grand Roi des Rafales',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi min. 3 monstres "D/D/D" sont sur le Terrain, cette carte gagne 3000 ATK. \r\nSi un ou plusieurs autres monstres "D/D" sont Invoqués Normalement ou Spécialement sur votre Terrain, tant que ce monstre est sur le Terrain (sauf durant la Damage Step): vous pouvez cibler 1 monstre "D/D" dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser cet effet de "D/D/D Alexandre, Grand Roi des Rafales" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6767771,'Cri des Tiarmentations',replace(replace('Si un ou plusieurs monstres sont Invoqués Normalement ou Spécialement, et que vous contrôlez "Visas Starfrost" ou un monstre "Tiarmentations" (sauf durant la Damage Step): vous pouvez envoyer les 3 cartes du dessus de votre Deck au Cimetière, et aussi, tous les monstres contrôlés par votre adversaire perdent 500 ATK le reste de ce tour. \r\nSi cette carte est envoyée au Cimetière par un effet de carte: vous pouvez ajouter 1 Piège "Tiarmentations" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Cri des Tiarmentations" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6772168,'Océanos l''Invokhé',replace(replace('1 monstre "Aleister" + 1 monstre TÉNÈBRES ou EAU	\r\nTant que cette carte est dans la Zone Monstre Main, les monstres de votre adversaire ne peuvent pas cibler de monstres (celui-ci exclu) avec une attaque. \r\nTant que cette carte est dans la Zone Monstre Extra, les monstres envoyés au Cimetière de votre adversaire sont bannis à la place. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Monstre Fusion que vous contrôlez; ce tour, il peut attaquer directement. \r\nVous ne pouvez utiliser cet effet de "Océanos l''Invokhé" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Attaque directe','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6783559,'Fourmi Autodestructrice',replace(replace('FLIP: Chaque joueur reçoit 1000 points de dommages.\r\nSi cette carte est détruite au combat ou par un effet de carte, et envoyée au Cimetière: infligez 1000 points de dommages à votre adversaire. \r\nVous ne pouvez utiliser chaque effet de "Fourmi Autodestructrice" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6795211,'Téléportation','Une fois par tour, si votre adversaire contrôle un monstre et que vous ne contrôlez aucun monstre, vous pouvez payer 800 Life Points pour Invoquer Spécialement 1 monstre de Type Psychique depuis votre main.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6798031,'Croisement Ryzéal',replace(replace('Vous ne pouvez pas Invoquer par Xyz de monstres du même nom qu''une carte que vous contrôlez. \r\nVous pouvez cibler 2 cartes "Ryzéal" ("Croisement Ryzéal" exclu) dans votre Cimetière; placez-les au-dessous du Deck dans l''ordre de votre choix, puis piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Croisement Ryzéal" qu''une fois par tour. \r\nUne fois par tour, lorsqu''un effet de monstre activé par votre adversaire est résolu, vous pouvez détacher 1 Matériel d''un Monstre Xyz "Ryzéal" que vous contrôlez, et si vous le faites, annulez l''effet.','\r',char(13)),'\n',char(10)),'','Récupérer et piocher','Annuler','Appliquer l''effet de "Croisement Ryzéal" pour annuler ?','Effet d''annulation de monstre déjà utilisé','','','','','','','','','','','');
INSERT INTO texts VALUES(6799227,'Demi-Contre','Durant le calcul des dommages, si un monstre que vous contrôlez est attaqué: ciblez le monstre que vous contrôlez; jusqu''à la fin de ce tour, la cible gagne une ATK égale à la moitié de l''ATK d''origine du monstre attaquant.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6812770,'Trompeur à Tasse Mageartiste',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nVous pouvez cibler 1 Monstre Xyz "Mageartiste" que vous contrôlez; attachez-lui cette carte comme Matériel. \r\nSi une ou plusieurs cartes sont ajoutées à votre Extra Deck (sauf durant la Damage Step): vous pouvez ajouter 1 Monstre Pendule "Mageartiste" face recto depuis votre Extra Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Trompeur à Tasse Mageartiste" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est dans votre main: vous pouvez cibler 1 Monstre Xyz sur le Terrain; détachez-lui 1 Matériel, et si vous le faites, Invoquez Spécialement cette carte, puis faites perdre 600 ATK à 1 Monstre Xyz sur le Terrain. \r\nSi cette carte est détachée d''un Monstre Xyz et envoyée au Cimetière pour activer l''effet du monstre: vous pouvez cibler 2 Monstres Xyz que vous contrôlez; attachez 1 Matériel d''1 de ces monstres à l''autre. \r\nVous ne pouvez utiliser chaque effet de "Trompeur à Tasse Mageartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Devenir Matériel Xyz','Renvoyer à l''Extra Deck','Invocation Spéciale','Transférer des Matériels Xyz','Choisissez le monstre qui perdra des Matériels Xyz','','','','','','','','','','','');
INSERT INTO texts VALUES(6821579,'Propulseur VALCan R.B.',replace(replace('2 monstres Machine	\r\nSi cette carte est Invoquée par Lien: vous pouvez ajouter 1 Magie "R.B." depuis votre Deck à votre main. \r\nSi cette carte est dans la Zone Monstre Extra: vous pouvez Invoquer Spécialement 1 monstre "R.B." depuis votre main ou Cimetière en Position de Défense, puis vous pouvez déplacer cette carte que vous contrôlez dans une autre de vos Zones Monstre Main, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres Machine avec max. 1500 ATK exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Propulseur VALCan R.B." qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invocation Spéciale','Déplacer ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6830480,'Kagen, Ninja du Crépuscule',replace(replace('Échelle Pendule = 10\r\n[ Effet Pendule ]\r\nVous ne pouvez pas Invoquer par Pendulation de monstres (monstres "Ninja" exclus). \r\nCet effet ne peut pas être annulé. \r\nUne fois par tour, lorsque votre monstre "Ninja" déclare une attaque: jusqu''à la fin de la Damage Step (même si cette carte quitte le Terrain), vous pouvez faire gagner 1000 ATK au monstre.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nVous pouvez Sacrifier cette carte, puis ciblez 1 monstre "Ninja" que vous contrôlez; jusqu''à la fin de ce tour, il gagne 800 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6836211,'Le Grand Empereur Pingouin','Vous pouvez Sacrifier cette carte; Invoquez Spécialement max. 2 monstres "Pingouin" ("Le Grand Empereur Pingouin" exclu) depuis votre Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6840573,'Barox','"Panda Fou" + "Ryu-Kishin"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6849042,'Bête Dinosaure Millénaire',replace(replace('(Cette carte n''est pas traitée comme carte "Millénaire".)	\r\nVous pouvez Invoquer par Sacrifice cette carte en Position d''Attaque face recto en Sacrifiant 1 monstre Dinosaure. \r\nLorsqu''un ou plusieurs monstres Dinosaure sont Invoqués Spécialement depuis votre Cimetière tant que ce monstre est sur le Terrain (sauf durant la Damage Step): vous pouvez piocher 1 carte.','\r',char(13)),'\n',char(10)),'Invoquer par Sacrifice en Sacrifiant 1 monstre Dinosaure','Piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6850209,'Accord avec le Maître des Ténèbres',replace(replace('(Cette carte est toujours traitée comme une carte "Archdémon".)	\r\nSi un monstre de min. Niveau 8 sous votre contrôle a été envoyé au Cimetière ce tour: Invoquez Spécialement 1 "Dragon Furieux" depuis votre main ou Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6853254,'Le Retour des Grands Dragons',replace(replace('Ciblez 1 monstre Dragon de Niveau 7 ou 8 dans votre Cimetière; Invoquez-le Spécialement. \r\nSi un ou plusieurs monstres Dragon que vous contrôlez vont être détruits au combat ou par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière à la place.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Le Retour des Grands Dragons" à la place de la destruction ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6855503,'Masquerade le Dragon Ardent',replace(replace('1 monstre "Despia" + 1 monstre LUMIÈRE ou TÉNÈBRES	\r\nTant que vous contrôlez cette carte Invoquée par Fusion, votre adversaire doit payer 600 LP pour activer des cartes ou des effets. \r\nSi votre adversaire contrôle un Monstre Rituel, Fusion, Synchro, Xyz ou Lien, tant que cette carte est dans votre Cimetière (Effet Rapide): vous pouvez Invoquer Spécialement cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser cet effet de "Masquerade le Dragon Ardent" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6859683,'Probabilité de Succès : 0%','Envoyez 2 Monstres de Fusion choisis au hasard depuis le Extra Deck de votre adversaire au Cimetière.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6890729,'Liaison - DHO',replace(replace('Mélangez 1 "Duoterion", 1 "Hydrogeddon" et 1 "Oxygeddon" depuis votre main et/ou Cimetière dans le Deck; Invoquez Spécialement 1 "Dragon de l''Eau Rassemblé" depuis votre main ou Cimetière. \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 "Dragon de l''Eau" ou "Dragon de l''Eau Rassemblé" depuis votre Deck ou Cimetière à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6901008,'Roi Fantôme Hydride','Si vous utilisez cette carte que vous contrôlez comme Matériel Synchro, vous pouvez la traiter comme non-Syntoniseur.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6903857,'Briseur de Puissance',replace(replace('Si cette carte en votre possession est détruite par une attaque ou effet de carte de votre adversaire, et envoyée à votre Cimetière: ciblez 1 Carte Magie/Piège face recto contrôlée par votre adversaire; détruisez la cible. \r\nSi cette carte attaque, à la fin de la Damage Step, elle est changée en Position de Défense.','\r',char(13)),'\n',char(10)),'Détruire','Passer en Position de Défense','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6906306,'Rubisaphirus, le Joyau Inflexible',replace(replace('2+ monstres de Niveau 9	\r\nSi cette carte face recto va être détruite, vous pouvez détacher 1 Matériel de cette carte à la place. \r\nGagne les effets suivants, selon les Attributs de ses Matériels attachés.\r\n● FEU: Lorsque cette carte déclare une attaque sur un monstre avec une ATK supérieure: jusqu''à la fin de la Damage Step, vous pouvez faire devenir l''ATK de cette carte le double de son ATK actuelle.\r\n● EAU: Une fois par tour de l''adversaire (Effet Rapide): vous pouvez cibler 1 carte que vous contrôlez; ce tour, annulez les cartes ou effets activés par votre adversaire qui ciblaient la carte.','\r',char(13)),'\n',char(10)),'Doubler l''ATK','Ciblez votre propre carte','L''effet de "Rubisaphirus, le Joyau Inflexible" est actuellement appliqué.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6908161,'Enroulement de Chaînes Ragnaraika',replace(replace('2+ monstres (un monstre Insecte, Plante ou Reptile inclus)	\r\nSi votre adversaire active un effet de monstre (sauf durant la Damage Step): vous pouvez activer cet effet; ce tour, aucun joueur ne peut activer les effets des monstres dans la main. \r\nSi cette carte est dans votre Cimetière: vous pouvez cibler 1 monstre Insecte, Plante ou Reptile que vous contrôlez; placez-le au-dessous du Deck, et si vous le faites, Invoquez Spécialement cette carte, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres Insecte, Plante ou Reptile exclus) le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Enroulement de Chaînes Ragnaraika" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet de verrouillage','S''Invoquer Spécialement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6909330,'Porte Renferme-Âme',replace(replace('Pour activer cette carte vous ne devez contrôler aucun monstre, et un ou plusieurs Magies/Pièges Posés que vous contrôlez doivent avoir été détruits par un effet de carte ce tour. \r\nDurant la Main Phase, si exactement 1 monstre avec une ATK inférieure à vos LP est Invoqué et que vous avez "Z-ONE" dans votre Cimetière: détruisez le monstre, et si vous le faites, recevez 800 points de dommages, puis infligez 800 points de dommages à votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6917479,'Baron Rouge Vampire','Une fois par tour: vous pouvez payer 1000 LP, puis ciblez 1 monstre contrôlé par votre adversaire et 1 autre monstre "Vampire" que vous contrôlez; échangez le contrôle de ces monstres. À la fin de la Battle Phase, si cette carte a détruit un ou plusieurs monstres au combat: vous pouvez les Invoquer Spécialement depuis les Cimetières sur votre Terrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6924874,'Bébé Dragon, Familier de Harpie',replace(replace('Gagne des effets selon le nombre de monstres "Harpie" que vous contrôlez ("Bébé Dragon, Familier de Harpie" exclu).\r\n● 1+: Votre adversaire ne peut pas cibler de monstres "Harpie" que vous contrôlez ("Bébé Dragon, Familier de Harpie" exclu) avec une attaque.\r\n● 2+: Doublez l''ATK/DEF d''origine de cette carte.\r\n● 3+: Une fois par tour: vous pouvez cibler 1 carte contrôlée par votre adversaire; détruisez la cible.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6930746,'Dragon des Limites Schwarzschild','Si votre adversaire contrôle un monstre avec min. 2000 ATK, vous pouvez Invoquer Spécialement cette carte (depuis votre main).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6958551,'Ombre Toon',replace(replace('Si vous contrôlez "Monde des Toons": ciblez 1 monstre face recto contrôlé par votre adversaire; infligez des dommages à votre adversaire égaux à l''ATK du monstre face recto. \r\nVous ne pouvez activer qu''1 "Ombre Toon" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6958567,'Célébration Artisanesorcière',replace(replace('Activez 1 de ces effets;\r\n● Détruisez 1 monstre "Artisanesorcière" que vous contrôlez et 1 carte contrôlée par votre adversaire.\r\n● Invoquez par Fusion 1 Monstre Fusion "Artisanesorcière" depuis votre Extra Deck, en mélangeant des monstres Magicien depuis votre Cimetière et/ou bannissement dans le Deck.	\r\nDurant votre End Phase, si vous contrôlez un monstre "Artisanesorcière", tant que cette carte est dans votre Cimetière: vous pouvez ajouter cette carte à votre main.\r\nVous ne pouvez utiliser qu''1 effet de "Célébration Artisanesorcière" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Activer','Ajouter à la main','Effet de destruction','Invocation Fusion','','','','','','','','','','','','');
INSERT INTO texts VALUES(6967870,'Cliff, le Désamorceur - Scorpion Noir',replace(replace('Lorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez activer 1 de ces effets.\r\n● Ciblez 1 Magie/Piège sur le Terrain; détruisez la cible.\r\n● Envoyez les 2 cartes du dessus de son Deck au Cimetière.','\r',char(13)),'\n',char(10)),'Activer 1 effet','Détruisez 1 carte Magie ou Piège sur le Terrain.','Envoyez les 2 cartes du dessus du Deck de votre adversaire au Cimetière.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6979239,'Fée des Bois','Envoyez 1 Carte d''Équipement équipée à ce monstre au Cimetière pour infliger 500 points de dommages aux Life Points de votre adversaire.','Infliger des dommages aux LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6983839,'Dragon de la Tornade',replace(replace('2 monstres de Niveau 4	\r\nUne fois par tour (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 Magie/Piège sur le Terrain; détruisez-le.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6990577,'Andrake Dragarde',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement par un effet de carte. \r\nSi cette carte est Invoquée Spécialement depuis la main ou Deck: jusqu''à la fin du prochain tour, vous pouvez doubler l''ATK/DEF d''origine de cette carte. \r\nSi cette carte est Invoquée Spécialement depuis le Cimetière, ou si cette carte bannie est Invoquée Spécialement: vous pouvez cibler 1 monstre contrôlé par votre adversaire; détruisez-le. \r\nVous ne pouvez utiliser chaque effet de "Andrake Dragarde" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6992184,'Encore Pendule',replace(replace('Durant la Main Phase de votre adversaire: vous pouvez défausser 1 carte; immédiatement après la résolution de cet effet, Invoquez par Pendulation un ou plusieurs Monstres Pendule, et aussi, le reste de ce tour après la résolution de cette carte, les cartes dans vos Zones Pendule ne peuvent pas activer leurs effets et ne peuvent pas être détruites par vos effets de carte, et aussi, mélangez-les dans le Deck durant la End Phase. \r\nVous ne pouvez activer qu''1 "Encore Pendule" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7019529,'Insectes Soldats Volants','À chaque fois que cette carte attaque un monstre VENT, augmentez l''ATK de cette carte de 1000 points uniquement durant la Damage Step.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7020743,'Bambin Capricieux',replace(replace('2 monstres de Niveau 1	\r\nUne fois par Chaîne, si une activation de carte ou d''effet est annulée (sauf durant la Damage Step): vous pouvez attacher max. 1 carte depuis votre Cimetière et max. 1 carte depuis le Cimetière de votre adversaire à cette carte comme Matériel. \r\nCette carte gagne des effets selon le nombre de Matériels qui lui sont attachés.\r\n● 1+: Gagne 700 ATK/DEF pour chaque Matériel qui lui est attaché.\r\n● 4+: Non destructible ni au combat ni par des effets de carte.\r\n● 8+: (Effet Rapide): vous pouvez détacher 4 Matériels de cette carte; détruisez toutes les cartes sur le Terrain.','\r',char(13)),'\n',char(10)),'Attacher un Matériel Xyz','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7021574,'Kuribou',replace(replace('(Cette carte est toujours traitée comme une carte "Kuriboh".)	\r\nLorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez défausser cette carte; ajoutez 1 monstre "Kuriboh" ("Kuribou" exclu) depuis votre Deck à votre main. \r\nUne fois par tour (Effet Rapide): vous pouvez défausser 1 Piège, puis ciblez 1 monstre face recto contrôlé par votre adversaire; jusqu''à la fin de ce tour, il perd 1500 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7025445,'Géant de Puissance',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en envoyant 1 monstre de max. Niveau 4 depuis votre main au Cimetière. \r\nSi vous le faites, réduisez le Niveau de cette carte par le Niveau du monstre. \r\nSi cette carte attaque ou est attaquée, jusqu''à la fin de la Damage Step, les dommages d''effets que vous recevez deviennent 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7030340,'Usine des 100 Machines',replace(replace('Retirez du jeu tous les monstres "Morphtronique" depuis votre Cimetière. \r\nCiblez un monstre de Type Machine face recto que vous contrôlez, il gagne 200 points d''ATK pour chaque carte retirée, jusqu''à la End Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7044562,'Carte de l''Âme',replace(replace('Regardez votre Deck, et si vous le faites, vous pouvez ajouter 1 monstre depuis votre Deck à votre main, dont la somme de son ATK/DEF est égale à vos LP. \r\nVous ne pouvez activer qu''1 "Carte de l''Âme" par tour.','\r',char(13)),'\n',char(10)),'Choisir un monstre à ajouter à la main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7076131,'Prochain à Disparaître',replace(replace('Sélectionnez 1 monstre face recto sur votre Terrain. \r\nEnvoyez 1 carte de votre Deck au Cimetière avec le même nom de carte que la carte sélectionnée.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7080743,'Train Express Trolley Olley',replace(replace('Un Monstre Xyz qui a été Invoqué en utilisant cette carte sur le Terrain comme Matériel gagne cet effet.\r\n● S''il est Invoqué par Xyz: il gagne 800 ATK.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK (Train Express Trolley Olley)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7084129,'Bâton du Magicien',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez ajouter 1 Magie/Piège depuis votre Deck à votre main, qui mentionne "Magicien Sombre". \r\nDurant le tour de votre adversaire, si vous activez une Carte Magie/Piège ou effet de Magie/Piège tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez Sacrifier 1 monstre Magicien; ajoutez cette carte à votre main. \r\nVous ne pouvez utiliser chaque effet de "Bâton du Magicien" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Ajouter cette carte depuis le Cimetière à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7089711,'Hane-Hane','FLIP: Renvoyez 1 monstre sur le Terrain dans la main de son propriétaire.','Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7092142,'Renaissance Torrentielle',replace(replace('Lorsqu''un monstre EAU face recto que vous contrôlez est détruit au combat ou par un effet de carte, et envoyé au Cimetière: Invoquez Spécialement les monstres détruits et envoyés depuis le Terrain à votre Cimetière à ce moment, puis infligez 500 points de dommages à votre adversaire pour chacun de ces monstres Invoqués Spécialement. \r\nVous ne pouvez activer qu''1 "Renaissance Torrentielle" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7093411,'Bête Cristalline : Pégase de Saphir',replace(replace('Lorsque cette carte est Invoquée: vous pouvez placer face recto 1 monstre "Bête Cristalline" depuis votre main, Deck ou Cimetière dans votre Zone Magie & Piège comme Magie Continue. \r\nSi cette carte face recto est détruite dans une Zone Monstre, vous pouvez la placer face recto dans votre Zone Magie & Piège comme Magie Continue au lieu de l''envoyer au Cimetière.','\r',char(13)),'\n',char(10)),'Placer dans la Zone Magie & Piège lorsqu''il est détruit','Placer dans la Zone Magie & Piège','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7102732,'Golem Furieux Transparent',replace(replace('Vous n''êtes pas affecté par les effets de "Monde Transparent". \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez activer cet effet; ce tour, vos monstres qui mentionnent "Monde Transparent" peuvent attaquer directement. \r\nVous ne pouvez utiliser cet effet de "Golem Furieux Transparent" qu''une fois par tour. \r\nLorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez infliger 300 points de dommages à votre adversaire pour chaque carte dans sa main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7127502,'Lector Pendule, le Dracosseigneur',replace(replace('Échelle Pendule = 5\r\n[ Effet Pendule ]\r\nAnnulez les effets des Monstres Pendule face recto tant que votre adversaire les contrôle.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nAu début de la Damage Step, si cette carte combat un Monstre Pendule: détruisez le monstre ainsi que cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7133305,'Eau de la Vie',replace(replace('Si vous ne contrôlez aucun monstre: ciblez 1 monstre dans votre Cimetière; Invoquez Spécialement la cible en Position d''Attaque, et aussi, le reste de ce tour après la résolution de cette carte, vous ne pouvez pas activer d''effets de monstre (effets du monstre Invoqué Spécialement sur le Terrain exclus). \r\nVous ne pouvez activer qu''1 "Eau de la Vie" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7142724,'Berceau Enion de Cénote Jadeglace',replace(replace('Lorsque cette carte est activée: vous pouvez ajouter 1 de vos monstres "Jadeglace" qui est banni ou dans votre Cimetière à votre main. \r\nUne fois par tour, si un ou plusieurs monstres sont Invoqués Normalement ou Spécialement (sauf durant la Damage Step): vous pouvez cibler 1 monstre EAU que vous contrôlez; jusqu''à la fin de ce tour, le monstre ainsi que les monstres face recto actuellement contrôlés par votre adversaire perdent une ATK égale à l''ATK d''origine du monstre ciblé. \r\nVous ne pouvez activer qu''1 "Berceau Enion de Cénote Jadeglace" par tour.','\r',char(13)),'\n',char(10)),'Ajouter un monstre "Jadeglace" à votre main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7150545,'Requin Scie Circulaire',replace(replace('Vous pouvez cibler 1 monstre EAU que vous contrôlez; Invoquez Spécialement 1 monstre Poisson du même Niveau que le monstre mais de nom différent depuis votre Deck en Position de Défense, et si vous le faites, il ne peut pas activer ses effets ce tour, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Xyz exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Requin Scie Circulaire" qu''une fois par tour. \r\nSi cette carte est utilisée pour l''Invocation Xyz d''un monstre EAU, elle peut être traitée comme monstre de Niveau 3 ou 5.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7152333,'Goule Horreur de l''Ombre','Une fois par tour: vous pouvez faire devenir 0 l''ATK de cette carte, et si vous le faites, Invoquez Spécialement 1 monstre "Horreur de l''Ombre" avec 0 ATK depuis votre main.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7153114,'Barrière de Terrain',replace(replace('Les Magies de Terrain sur le Terrain ne peuvent pas être détruites. \r\nAucun joueur ne peut activer de nouvelles Cartes Magie de Terrain. \r\nVous ne pouvez contrôler qu''1 "Barrière de Terrain".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7161742,'Cordyceps Prédaplante','Durant votre Standby Phase: vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 2 monstres "Prédaplante" de max. Niveau 4 dans votre Cimetière; Invoquez-les Spécialement, et aussi, le reste de ce tour, vous ne pouvez ni Invoquer Spécialement de monstres (Monstres de Fusion exclus), ni Invoquer/Poser Normalement de monstres.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7165085,'Poupée d''Appât',replace(replace('Ciblez 1 carte Posée dans la Zone Carte Magie & Piège; révélez la cible, forcez son activation si c''est une Carte Piège, puis annulez son effet si le moment d''activation est incorrect, et si vous le faites, détruisez-la. \r\n(Si ce n''est pas une Carte Piège, retournez-la face verso.) \r\nLorsque cette carte est résolue, mélangez-la dans le Deck au lieu de l''envoyer au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7166709,'Sacrifice à Cordes d''Acier',replace(replace('Si cette carte est dans votre main ou Cimetière: vous pouvez révéler 1 monstre de min. Niveau 5 dans votre main, puis activez 1 de ces effets (mais vous ne pouvez utiliser chaque effet de "Sacrifice à Cordes d''Acier" qu''une fois par tour); durant la End Phase de ce tour, perdez 1000 LP si vous n''avez pas Invoqué Normalement le monstre révélé ou un monstre du même nom d''origine, après avoir activé cet effet.\r\n● Invoquez Spécialement cette carte depuis votre main.\r\n● Ajoutez cette carte depuis votre Cimetière à votre main.\r\n● Bannissez cette carte depuis votre Cimetière, et si vous le faites, ajoutez 1 monstre de min. Niveau 5 depuis votre Cimetière à votre main.','\r',char(13)),'\n',char(10)),'Activer','Invocation Spéciale','Ajouter à la main','Bannir cette carte','','','','','','','','','','','','');
INSERT INTO texts VALUES(7171149,'Golem Rouages Ancients Toon',replace(replace('Ne peut pas attaquer le tour où elle est Invoquée. \r\nTant que vous contrôlez "Monde des Toons" et que votre adversaire ne contrôle aucun monstre Toon, cette carte peut attaquer directement votre adversaire. \r\nSi cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire. \r\nSi cette carte attaque, votre adversaire ne peut pas activer de Magies/Pièges jusqu''à la fin de la Damage Step.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7180418,'Armure Exe',replace(replace('Cette carte ne peut pas attaquer le tour durant lequel elle est Invoquée par Invocation Normale, Invocation Flip ou Invocation Spéciale. \r\nDurant chacune de vos Standby Phases, retirez 1 Compteur Magie sur votre Terrain. \r\nSi vous ne le faites pas, détruisez cette carte.','\r',char(13)),'\n',char(10)),'Retirer 1 Compteur Magie ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7183277,'Aurkus le Druide, Seigneur Lumière',replace(replace('Aucun joueur ne peut cibler de monstres "Seigneur Lumière" (où qu''ils soient) avec des effets de carte. \r\nDurant chacune de vos End Phases: envoyez les 2 cartes du dessus de votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'Envoyer 2 cartes depuis le Deck au Cimetière','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7194917,'Numéro 52 : Roi Crabe des Diamants',replace(replace('2 monstres de Niveau 4	\r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte; changez la DEF de cette carte à 0, et si vous le faites, changez son ATK à 3000. \r\nCes changements durent jusqu''à la fin de ce tour. \r\nSi cette carte attaque, elle est changée en Position de Défense à la fin de la Battle Phase. \r\nSi cette carte est attaquée, changez-la en Position d''Attaque à la fin de la Damage Step si elle n''a pas de Matériel Xyz. \r\nVous ne pouvez contrôler qu''1 "Numéro 52 : Roi Crabe des Diamants".','\r',char(13)),'\n',char(10)),'Changer l''ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7198399,'Magicienne des Chocolats',replace(replace('Une fois par tour: vous pouvez défausser 1 monstre Magicien; piochez 1 carte. \r\nUne fois par tour, si cette carte est ciblée par une attaque: vous pouvez cibler 1 monstre Magicien ("Magicienne des Chocolats" exclu) dans votre Cimetière; Invoquez-le Spécialement, puis transférez-lui la cible de l''attaque, et si vous le faites, l''ATK du monstre attaquant devient la moitié de son ATK actuelle.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7200041,'Tireur Métallique',replace(replace('Lorsque cette carte est Invoquée par Invocation Normale, placez 2 compteurs sur elle. \r\nCette carte gagne 800 points d''ATK pour chaque compteur placé sur elle. \r\nSi cette carte doit être détruite par un effet de carte, retirez 1 des compteurs de cette carte à la place.','\r',char(13)),'\n',char(10)),'Placer un marqueur','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7206349,'Vernusylphe en Pleine Floraison',replace(replace('Tous les monstres que vous contrôlez gagnent 1000 ATK tant que vous contrôlez min. 5 monstres TERRE. \r\nVous ne pouvez utiliser chacun des effets suivants de "Vernusylphe en Pleine Floraison" qu''une fois par tour. \r\nVous pouvez bannir 1 "Vernusylphe et les Bourgeons de Fleurs" depuis votre main ou Cimetière; Invoquez Spécialement 1 "Vera la Déesse Vernusylphe" depuis votre Deck. \r\nSi un ou plusieurs monstres "Vernusylphe" sont Invoqués Spécialement depuis votre Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 monstre sur le Terrain ou dans l''un des Cimetières; renvoyez-le à la main.','\r',char(13)),'\n',char(10)),'','Renvoyer un monstre à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7225792,'Larves de Mon','Nouvelle étape dans la chaîne de l''évolution, cette créature est bien plus puissante que Larves.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7236721,'Décroc Griffrayeur',replace(replace('Votre adversaire ne peut pas cibler "Visas Starfrost" ou de Monstres Lien "Griffrayeur" que vous contrôlez avec des effets de carte, et aussi, ils ne peuvent pas être détruits par des effets de carte de votre adversaire. \r\nBannissez les monstres détruits au combat avec "Visas Starfrost" ou un Monstre Lien "Griffrayeur" que vous contrôlez. \r\nVous pouvez bannir 1 Monstre Lien "Griffrayeur" depuis votre Terrain ou Cimetière, puis ciblez 1 carte contrôlée par votre adversaire; détruisez-la. \r\nVous ne pouvez utiliser cet effet de "Décroc Griffrayeur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7241272,'Malédiction du Dragon de Feu',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 Magie de Terrain sur le Terrain; détruisez-la. \r\nUne fois par tour: vous pouvez Invoquer par Fusion 1 Monstre Fusion depuis votre Extra Deck, en utilisant des monstres que vous contrôlez (cette carte incluse) comme Matériels Fusion.','\r',char(13)),'\n',char(10)),'Détruire une Magie de Terrain','Invocation Fusion','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7243511,'Koalo-Koala',replace(replace('"Koala des Mers" + "Loutre des Arbres"	\r\nVous pouvez envoyer 1 monstre de Type Bête depuis votre main au Cimetière pour cibler 1 monstre contrôlé par votre adversaire; détruisez-le.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7264861,'Bête Enfernité','Si cette carte attaque tant que vous n''avez aucune carte dans votre main, votre adversaire ne peut activer aucune Carte Magie/Piège jusqu''à la fin de la Damage Step.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7268133,'Spadassin de la Vie Potartiste',replace(replace('Lorsque votre adversaire gagne des LP (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main, et si vous le faites, l''ATK de cette carte devient égale aux LP gagnés par votre adversaire. \r\nVous pouvez Sacrifier cette carte, puis ciblez 1 monstre face recto que vous contrôlez; jusqu''à la fin de ce tour, il gagne 1000 ATK.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Augmenter l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7279373,'Acteur des Abysses - Petite Étoile Brillante',replace(replace('Échelle Pendule = 9\r\n[ Effet Pendule ]\r\nVous ne pouvez pas Invoquer par Pendulation de monstres (monstres "Acteur des Abysses" exclus). \r\nCet effet ne peut pas être annulé. \r\nUne fois par tour: vous pouvez cibler 1 monstre "Acteur des Abysses" que vous contrôlez; il peut faire max. 3 attaques sur des monstres durant chaque Battle Phase ce tour, et aussi, les autres monstres que vous contrôlez ne peuvent pas attaquer le reste de ce tour (même si cette carte quitte le Terrain).\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nNon destructible au combat durant votre tour. \r\nDurant chaque Battle Phase, cette carte peut faire max. 3 attaques sur des monstres.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7291576,'Six Samouraïs Secrets - Genba',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez cibler 1 de vos monstres "Six Samouraïs" bannis; ajoutez-le à votre main. \r\nSi exactement 1 monstre "Six Samouraïs" que vous contrôlez (et aucune autre carte) va être détruit par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7293697,'Monde des Toons le Monde Parfait',replace(replace('Le nom de cette carte devient "Monde des Toons" tant qu''elle est dans la Zone Terrain.\r\nUne fois par tour: vous pouvez ajouter 1 carte "Toon", ou 1 carte qui mentionne un nom de carte "Toon", depuis votre Deck à votre main.\r\nVous ne pouvez utiliser cet effet de "Monde des Toons le Monde Parfait" que trois fois par tour.\r\nAvant la résolution d''une autre carte ou effet activé, vous pouvez bannir 1 monstre Toon que vous contrôlez jusqu''à immédiatement après la résolution de la carte/effet, et aussi, vous ne pouvez pas bannir de monstres du même nom d''origine avec cet effet de "Monde des Toons le Monde Parfait" le reste de ce tour.','\r',char(13)),'\n',char(10)),'','Ajouter à la main','','Bannir le monstre ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(7304544,'Ananas Naturia',replace(replace('Tous les monstres face recto que vous contrôlez deviennent des monstres Plante. \r\nUne fois par tour, durant votre Standby Phase, si vous ne contrôlez pas "Ananas Naturia" face recto, et que vous n''avez aucun monstre dans votre Cimetière (monstres Plante ou Bête exclus): vous pouvez Invoquer Spécialement cette carte depuis votre Cimetière. \r\nVous ne devez contrôler aucun Magie/Piège pour activer et résoudre cet effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7305060,'Avidité Amorphage',replace(replace('Échelle Pendule = 3\r\n[ Effet Pendule ]\r\nTant que vous contrôlez un monstre "Amorphage", aucun joueur ne peut ni activer de Cartes Piège ni leurs effets (cartes "Amorphage" exclues). \r\nUne fois par tour, durant votre Standby Phase, Sacrifiez 1 monstre ou détruisez cette carte.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est Invoquée par Pendulation ou retournée face recto, aucun joueur ne peut Invoquer Spécialement de monstres (monstres "Amorphage" exclus) depuis l''Extra Deck tant que cette carte est face recto sur le Terrain.','\r',char(13)),'\n',char(10)),'Sacrifier 1 monstre que vous contrôlez ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7320132,'Hlidskjálf, Relique Nordique',replace(replace('Invoquez Spécialement 1 monstre "Nordique" depuis votre Deck, mais vous ne pouvez pas Invoquer Spécialement de monstres (monstres "Ases" exclus) depuis l''Extra Deck, tant que le monstre est face recto sur le Terrain. \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 monstre "Nordique" depuis votre Deck à votre main, puis mélangez 1 carte depuis votre main dans le Deck. \r\nVous ne pouvez utiliser qu''1 effet de "Hlidskjálf, Relique Nordique" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Chercher dans le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7336745,'Préservation Dinomorphia',replace(replace('Lorsqu''un effet de monstre est activé, tant que vous contrôlez une carte "Dinomorphia": payez la moitié de vos LP; annulez l''activation, et si vous le faites, détruisez le monstre, et aussi, lorsque vous recevez des dommages de combat ce tour, les dommages reçus deviennent la moitié de vos LP à ce moment. \r\nDurant le calcul des dommages, tant que vos LP sont inférieurs ou égaux à 2000, si vous allez recevoir des dommages de combat: vous pouvez bannir cette carte depuis votre Cimetière; vous ne recevez aucun dommage de combat de ce combat. \r\nVous ne pouvez activer qu''1 "Préservation Dinomorphia" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7337976,'Apocalypse du Vide',replace(replace('Vous pouvez défausser 1 carte; envoyez 1 monstre Démon depuis votre Deck au Cimetière. \r\nVous pouvez envoyer cette carte face recto depuis votre Zone Magie & Piège au Cimetière; envoyez un nombre de monstres "Infernoid" de noms différents depuis votre main et/ou Deck au Cimetière, inférieur ou égal au nombre de monstres contrôlés par votre adversaire qui ont été Invoqués Spécialement depuis l''Extra Deck. \r\nVous ne pouvez utiliser qu''1 effet de "Apocalypse du Vide" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Défaussez 1 carte','Envoyer cette carte au Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7359741,'Chasseur Mécanique','Aux ordres du Roi des Machines, ce chasseur poursuit implacablement sa cible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7369217,'Lunatite - Parasite Métallisant',replace(replace('Une fois par tour, durant votre Main Phase, si vous contrôlez ce monstre sur le Terrain, vous pouvez l''équiper à un monstre face recto sur votre Terrain comme une Carte Magie d''Équipement, OU libérer cet équipement Union et faire l''Invocation Spéciale de cette carte en Position d''Attaque face recto. \r\nLorsque cette carte est équipée par l''effet de cette carte, ce monstre n''est plus affecté par les effets des Cartes Magie contrôlées par votre adversaire. \r\n(1 monstre ne peut être équipé que par 1 Monstre Union. Si le monstre équipé avec cette carte est détruit à l''issue d''un combat, détruisez cette carte à la place.)','\r',char(13)),'\n',char(10)),'Équiper','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7373632,'L''Évolution de Dieu',replace(replace('L''activation et l''effet de cette carte ne peuvent pas être annulés. \r\nChoisissez 1 monstre que vous contrôlez dont le Type d''origine est Bête Divine ou dont le nom d''origine est "Avatar le Démon de l''Enfer", "Deadroot le Démon de l''Enfer" ou "Eraser le Démon de l''Enfer" (les monstres déjà affectés par "L''Évolution de Dieu" exclus), et il gagne 1000 ATK/DEF, ses activations d''effet et ses effets activés ne peuvent pas être annulés, et aussi, il gagne l''effet suivant.\r\n● Lorsque cette carte déclare une attaque: vous pouvez faire envoyer à votre adversaire 1 monstre qu''il contrôle au Cimetière (son choix).','\r',char(13)),'\n',char(10)),'L''effet de "L''Évolution de Dieu" est actuellement appliqué.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7375867,'Mululu Queudragon',replace(replace('Durant la Main Phase (Effet Rapide): vous pouvez Invoquer par Fusion 1 Monstre Fusion "Queudragon" depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Fusion exclus) depuis l''Extra Deck le reste de ce tour. \r\nSi cette carte est envoyée au Cimetière comme Matériel pour une Invocation Fusion: vous pouvez Poser 1 Magie/Piège "Queudragon" depuis votre Deck, puis vous pouvez annuler les effets d''1 monstre face recto contrôlé par votre adversaire. \r\nVous ne pouvez utiliser chaque effet de "Mululu Queudragon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet de Fusion','Poser Magie/Piège','Annuler un monstre ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7382007,'Ogre Sheik Gouki',replace(replace('2 monstres "Gouki"	\r\nSi un ou plusieurs monstres "Gouki" sont ajoutés depuis le Deck à votre main, sauf en les piochant (sauf durant la Damage Step): vous pouvez Invoquer Spécialement un nombre de votre choix de monstres "Gouki" de Niveaux différents depuis votre main, mais pour chacun d''eux, tant qu''il reste face recto dans votre Zone Monstre, vous ne pouvez pas Invoquer Spécialement (monstres "Gouki" exclus). \r\nDurant votre Main Phase: vous pouvez Invoquer par Fusion 1 Monstre Fusion "Gouki" depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain. \r\nVous ne pouvez utiliser chaque effet de "Ogre Sheik Gouki" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Effet de Fusion','Invoqué Spécialement par l''effet de "Ogre Sheik Gouki"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7391448,'Gardien Goyo',replace(replace('1 Syntoniseur TERRE + 1+ monstre non-Syntoniseur	\r\nLorsque cette carte détruit un monstre de l''adversaire au combat et l''envoie au Cimetière: vous pouvez Invoquer Spécialement le monstre sur votre Terrain en Position de Défense.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7392745,'Mâchos','FLIP: Invoquez Spécialement 3 "Jeton Mâchos Junior" (Type Zombie/TERRE/Niveau 1/ATK 100/DEF 300) sur le Terrain de votre adversaire en Position de Défense.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7392746,'Jeton Mâchos Junior','Invoqué Spécialement avec l''effet de "Mâchos".','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7394770,'Fusion Brillante',replace(replace('Lorsque cette carte est activée: Invoquez par Fusion 1 Monstre Fusion "Chevalier-Gemmes" depuis votre Extra Deck, en utilisant des monstres depuis votre Deck comme Matériel Fusion, mais changez son ATK/DEF à 0. \r\nSi cette carte quitte le Terrain, détruisez le monstre. \r\nUne fois par tour: vous pouvez défausser 1 Magie; jusqu''à la fin du tour de votre adversaire, le monstre Invoqué Spécialement par l''effet de cette carte gagne une ATK/DEF égales à son ATK/DEF d''origine. \r\nVous ne pouvez activer qu''1 "Fusion Brillante" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7403341,'Cynet Conflit',replace(replace('Lorsqu''une Carte Magie/Piège ou un effet de monstre est activé tant que vous contrôlez un monstre "Codeur Bavard": annulez l''activation, et si vous le faites, bannissez la carte, et si vous le faites, votre adversaire ne peut activer ni de cartes ni d''effets de cartes du même nom d''origine que la carte qui a été bannie, jusqu''à la fin du prochain tour. \r\nVous ne pouvez activer qu''1 "Cynet Conflit" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7405310,'Porte Supplémentaire',replace(replace('Déclarez un Niveau entre 1 et 12; votre adversaire bannit 1 monstre de ce Niveau depuis son Extra Deck. \r\nSi votre adversaire n''a pas de monstre de ce Niveau dans son Extra Deck, vous défaussez 1 carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7407724,'Érica la Féé Rikka',replace(replace('Lorsqu''une attaque impliquant un autre monstre Plante que vous contrôlez est déclarée: vous pouvez Sacrifier cette carte depuis votre main ou Terrain face recto; jusqu''à la fin de ce tour, le monstre que vous contrôlez gagne 1000 ATK/DEF. \r\nSi un ou plusieurs monstres Plante que vous contrôlez sont Sacrifiés, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte en Position de Défense, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Érica la Féé Rikka" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7409792,'Dynathérium',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez Invoquer Spécialement "Dynathérium" qu''une fois par tour de cette façon. \r\nLorsqu''elle est Invoquée de cette façon: votre adversaire peut cibler 1 monstre de Niveau 4 dans l''un des Cimetières; il Invoque Spécialement la cible sur son Terrain.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement sur le Terrain de votre adversaire','Invocation Spéciale?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7436169,'Trivikarma',replace(replace('Ciblez 1 "Visas Starfrost" dans votre Zone Monstre et 1 Monstre à Effet contrôlé par votre adversaire; annulez les effets du monstre de l''adversaire, et si vous le faites, votre monstre ciblé gagne une ATK égale à la moitié de l''ATK ou DEF d''origine du monstre (la plus haute valeur). \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 Magie/Piège qui mentionne "Visas Starfrost" ("Trivikarma" exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Trivikarma" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7443908,'Hayaté, l''Étoile de la Terre',replace(replace('Si uniquement votre adversaire contrôle un monstre, ou si vous contrôlez un monstre LUMIÈRE, vous pouvez Invoquer Normalement cette carte sans Sacrifice. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez Invoquer Spécialement 1 monstre LUMIÈRE Guerrier de Niveau 5 depuis votre main. \r\nVous ne pouvez utiliser cet effet de "Hayaté, l''Étoile de la Terre" qu''une fois par tour. \r\nUne fois par tour, lorsque votre monstre Guerrier est ciblé par une attaque: vous pouvez faire perdre exactement 500 ATK à cette carte, et si vous le faites, annulez l''attaque.','\r',char(13)),'\n',char(10)),'Invocation Normale sans Sacrifice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7445307,'Double Assembwurm',replace(replace('Si cette carte est dans votre main ou Cimetière: vous pouvez bannir 2 autres monstres Cyberse depuis votre main et/ou face recto depuis votre Terrain; Invoquez Spécialement cette carte, mais son ATK sera divisée par deux. \r\nVous ne pouvez utiliser cet effet de "Double Assembwurm" qu''une fois par tour. \r\nUne fois par tour: vous pouvez bannir 1 carte depuis votre main; bannissez 1 monstre sur le Terrain avec une ATK inférieure ou égale à celle de cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7452945,'Armes Nobles de la Destinée',replace(replace('Vous ne pouvez contrôler qu''1 "Armes Nobles de la Destinée". Équipable uniquement à un monstre de Type Guerrier. \r\nUne fois par tour, le monstre équipé ne peut être détruit ni au combat ni par des effets de carte. \r\nSi cette carte face recto sur le Terrain est détruite et envoyée au Cimetière: vous pouvez cibler 1 monstre "Chevalier Noble" de Type Guerrier que vous contrôlez; équipez cette carte à la cible. \r\nVous ne pouvez utiliser cet effet de "Armes Nobles de la Destinée" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Équiper','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7459013,'Zure, Chevalier du Monde Ténébreux','Le nom de cet illustre chevalier est connu dans tout le Monde Ténébreux. Il ne pense jamais à opprimer le commun des mortels.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7459919,'Aile Noire - Zonda le Crépuscule',replace(replace('Vous ne pouvez pas Invoquer Spécialement de monstres (Monstres Synchro exclus) depuis l''Extra Deck. \r\nVous ne pouvez utiliser qu''1 des effets suivants de "Aile Noire - Zonda le Crépuscule" par tour, et uniquement une fois le tour. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre sur le Terrain; renvoyez-le à la main. \r\nVous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 monstre "Aile Noire" de min. Niveau 5 depuis votre main ou Deck, puis recevez des dommages égaux à son ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7473735,'Fusion Synchro Harmonique',replace(replace('Envoyez 1 Syntoniseur et 1 non-Syntoniseur depuis votre Terrain face recto au Cimetière; Invoquez Spécialement les deux monstres suivants depuis votre Extra Deck.\r\n● 1 Monstre Synchro qui pourrait être Invoqué par Synchronisation en utilisant uniquement ces 2 monstres dans le Cimetière comme Matériel.\r\n● 1 Monstre Fusion qui pourrait être Invoqué par Fusion en utilisant uniquement ces 2 monstres dans le Cimetière comme Matériel.	\r\nVous ne pouvez pas Invoquer Spécialement (Monstres Fusion ou Synchro exclus) depuis l''Extra Deck le tour où vous activez cette carte. \r\nVous ne pouvez activer qu''1 "Fusion Synchro Harmonique" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7477101,'Septième Tachyon',replace(replace('Révélez 1 Monstre Xyz "Numéro" dans votre Extra Deck qui a un numéro entre "101" et "107" dans son nom; ajoutez 1 monstre depuis votre Deck à votre main du même Type ou Attribut que le monstre, et du même Niveau que le Rang du monstre, puis placez 1 carte depuis votre main au-dessus du Deck, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Xyz exclus) depuis l''Extra Deck le reste de ce tour après la résolution de cette carte. \r\nVous ne pouvez activer qu''1 "Septième Tachyon" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7478431,'Tournesol Naturia','Lorsqu''un effet de monstre de votre adversaire est activé (Effet Rapide): vous pouvez Sacrifier 1 monstre "Naturia" et cette carte; annulez l''activation, et si vous le faites, détruisez la carte.','Annuler l''activation de l''effet d''un Monstre à Effet, et le détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7480763,'Dagda - Artéfact',replace(replace('2 monstres de noms différents	\r\nLorsqu''un effet d''une autre carte sur le Terrain est activé (Effet Rapide): vous pouvez Poser 1 monstre "Artéfact" depuis votre main ou Deck dans votre Zone Magie & Piège comme une Magie, mais détruisez-le durant la prochaine End Phase de votre adversaire. \r\nDurant le tour de votre adversaire, si cette carte Invoquée par Lien est détruite: vous pouvez Invoquer Spécialement 1 monstre "Artéfact" depuis votre Cimetière en Position de Défense. \r\nVous ne pouvez utiliser chaque effet de "Dagda - Artéfact" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7489323,'Milus Radieux','Tant que cette carte reste face recto sur le Terrain, augmentez l''ATK de tous les monstres TERRE de 500 points et diminuez l''ATK des monstres VENT de 400 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7496001,'Butin Springans',replace(replace('Si un Monstre Xyz face recto que vous contrôlez quitte le Terrain par un effet de carte: vous pouvez cibler 1 Monstre à Effet contrôlé par votre adversaire; ce tour, aucun joueur ne peut activer les effets du Monstre à Effet sur le Terrain. \r\nVous pouvez envoyer cette carte face recto au Cimetière; activez 1 "Grande Mer de Sable - Gold Golgonda" directement depuis votre Deck ou Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Butin Springans" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Choisissez le monstre qui ne pourra pas activer d''effets','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7500772,'Requin Aigle',replace(replace('Si votre adversaire contrôle min. 2 monstres, vous pouvez Invoquer Normalement cette carte sans Sacrifice. \r\nSi vous contrôlez "Requin Panthère", vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nVous ne pouvez contrôler qu''1 "Requin Aigle".','\r',char(13)),'\n',char(10)),'Invoquer sans Sacrifice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7511613,'Propulseur Duo Ryzéal',replace(replace('2+ monstres de Niveau 4	\r\nPour chaque Matériel que cette carte a, les monstres que vous contrôlez gagnent 100 ATK et les monstres contrôlés par votre adversaire perdent 100 ATK. \r\nVous ne pouvez utiliser chacun des effets suivants de "Propulseur Duo Ryzéal" qu''une fois par tour. \r\nSi cette carte est Invoquée Spécialement: vous pouvez attacher 1 monstre "Ryzéal" depuis votre Cimetière à cette carte comme Matériel. \r\nDurant votre Main Phase: vous pouvez détacher 2 Matériels d''un ou plusieurs monstres que vous contrôlez, et si vous le faites, ajoutez 2 cartes "Ryzéal" de noms différents depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Attacher un Matériel Xyz','Effet d''ajout à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7512044,'Rassemblement Cérébral',replace(replace('Ajoutez 1 carte "Rassemblement Cérébral" de votre Deck à votre main. \r\nVous ne pouvez utiliser qu''1 "Rassemblement Cérébral" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7526150,'Golgoil','Géant de fer qui surgit d''une crevasse dimensionnelle.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7540107,'Tripes Gouki',replace(replace('Cette carte en Position de Défense ne peut pas être détruite au combat. \r\nVous ne pouvez utiliser chacun des effets suivants de "Tripes Gouki" qu''une fois par tour.\r\n● Durant votre Main Phase: vous pouvez faire gagner 200 ATK à tous les monstres "Gouki" que vous contrôlez.\r\n● Si cette carte est envoyée depuis le Terrain au Cimetière: vous pouvez ajouter 1 carte "Gouki" ("Tripes Gouki" exclu) depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7541475,'Dragon Kabuki',replace(replace('Une fois par tour, avant le calcul des dommages, si votre monstre a attaqué un monstre de votre adversaire: vous pouvez changer la position de combat du monstre contrôlé par votre adversaire. \r\nUne fois par tour, avant le calcul des dommages, si un monstre de votre adversaire a attaqué votre monstre: vous pouvez changer la position de combat du monstre que vous contrôlez.','\r',char(13)),'\n',char(10)),'Changer la position de combat','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7548747,'Théurgie Magistus',replace(replace('Ciblez 1 monstre "Magistus" que vous contrôlez; équipez-le avec 1 monstre "Magistus" (monstres de Niveau 4 exclus) depuis votre Extra Deck, Cimetière ou Terrain face recto. \r\nSi vous avez min. 1 Monstre Fusion "Magistus", min. 1 Monstre Synchro "Magistus", min. 1 Monstre Xyz "Magistus" et min. 1 Monstre Lien "Magistus" dans votre Cimetière, vous pouvez l''équiper avec 1 Monstre Fusion, Synchro, Xyz ou Lien non-"Magistus" depuis votre Extra Deck, à la place. \r\nVous ne pouvez activer "Théurgie Magistus" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7562372,'Œil Mégasonique','Constitué d''un métal mystérieux, ce monstre est une machine infernale venue de l''extrémité de l''univers.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7563579,'Peluchefeu Mageartiste',replace(replace('Échelle Pendule = 5\r\n[ Effet Pendule ]\r\nSi un ou plusieurs monstres "Mageartiste" face recto que vous contrôlez sont détruits au combat ou par un effet de carte: vous pouvez Invoquer Spécialement cette carte, puis recevez 500 points de dommages. \r\nVous ne pouvez utiliser cet effet de "Peluchefeu Mageartiste" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte sur le Terrain est détruite au combat ou par un effet de carte: vous pouvez Invoquer Spécialement 1 monstre "Mageartiste" ("Peluchefeu Mageartiste" exclu) depuis votre main ou Deck. \r\nVous ne pouvez utiliser cet effet de "Peluchefeu Mageartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7565547,'Puissance Accumulée',replace(replace('Ciblez 1 monstre face recto sur le Terrain; équipez-le avec toutes les Cartes d''Équipement sur le Terrain. \r\nSi une Carte d''Équipement est maintenant équipée à une cible incorrecte, détruisez la Carte d''Équipement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7572887,'Dame Guerrière D.D.','Après le calcul des dommages, lorsque cette carte combat un monstre de l''adversaire: vous pouvez bannir le monstre, et aussi, bannissez cette carte.','Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7573135,'Auguste, Bête Gladiateur',replace(replace('Lorsque cette carte est Invoquée Spécialement par l''effet d''un monstre "Bête Gladiateur": vous pouvez Invoquer Spécialement 1 monstre "Bête Gladiateur" depuis votre main en Position de Défense. \r\nDurant la End Phase, mélangez-le dans le Deck. À la fin de la Battle Phase, si cette carte a attaqué ou a été attaquée: vous pouvez la mélanger dans le Deck; Invoquez Spécialement 1 monstre "Bête Gladiateur" ("Auguste, Bête Gladiateur" exclu) depuis votre Deck.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7574904,'Arsenal Myutant',replace(replace('Non Invocable Spécialement, sauf avec l''effet d''une carte "Myutant". \r\nVotre adversaire ne peut pas cibler cette carte avec des effets de Piège. \r\nVous ne pouvez utiliser chacun des effets suivants de "Arsenal Myutant" qu''une fois par tour. \r\nLorsque votre adversaire active un effet de monstre (Effet Rapide): vous pouvez bannir 1 carte depuis votre main ou Terrain, puis ciblez 1 monstre sur le Terrain; bannissez-le. \r\nSi cette carte en possession de son propriétaire est détruite par une carte de l''adversaire: vous pouvez cibler 1 de vos Magies "Myutant" bannies; ajoutez-la à votre main.','\r',char(13)),'\n',char(10)),'Bannir un monstre','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7576264,'Bête Fantôme Corne-Sauvage','Si cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7582066,'Démon du Cauchemar Psychique',replace(replace('1 Syntoniseur + 1 monstre non Syntoniseur de Type Psychique ou plus	\r\nUne fois par tour, durant votre Main Phase, vous pouvez sélectionner 1 carte au hasard dans la main de votre adversaire et deviner de quel type de carte il s''agit (Monstre, Magie ou Piège). \r\nSi vous devinez juste, cette carte gagne 1000 points d''ATK jusqu''à la End Phase de votre adversaire.','\r',char(13)),'\n',char(10)),'Deviner une carte dans la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7593748,'Poupée Truquée Gigantes',replace(replace('2 monstres "Poupée Truquée" de Niveau 4	\r\nVous pouvez détacher 2 Matériels de cette carte, puis ciblez max. 2 monstres contrôlés par votre adversaire; gagnez-en le contrôle jusqu''à la End Phase, et aussi, vous ne pouvez ni Invoquer Spécialement de monstres (monstres "Poupée Truquée" exclus) ni déclarer d''attaque (sauf avec des Monstres Xyz) le reste de ce tour. \r\nVous pouvez Sacrifier cette carte; jusqu''à la fin de ce tour, tous les monstres que vous contrôlez actuellement deviennent de Niveau 8. \r\nVous ne pouvez utiliser chaque effet de "Poupée Truquée Gigantes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Prendre le contrôle','Changer le Niveau','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7594154,'Demoiselles Poupées Trompeuses de Zenna',replace(replace('2+ Monstres à Effet	\r\nVous pouvez aussi utiliser 1 monstre dans votre main comme Matériel pour Invoquer par Lien cette carte. \r\nVous ne pouvez utiliser chacun des effets suivants de "Demoiselles Poupées Trompeuses de Zenna" qu''une fois par tour. \r\nSi cette carte est Invoquée par Lien: vous pouvez envoyer 1 monstre depuis votre Deck au Cimetière, ou si tous les Matériels utilisés pour son Invocation Lien étaient des monstres que vous contrôliez, vous pouvez envoyer 1 monstre depuis votre Extra Deck à la place. \r\nDurant votre prochaine Standby Phase après que cette carte a été envoyée depuis le Terrain au Cimetière: vous pouvez ajouter 1 monstre depuis votre Cimetière à votre main.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7602800,'Tourbillon Plume Noire',replace(replace('Une fois par tour, si vous Invoquez Spécialement un Monstre Synchro TÉNÈBRES depuis l''Extra Deck (sauf durant la Damage Step): vous pouvez cibler 1 de vos "Dragon Ailes Sombres" ou monstres "Aile Noire" qui est banni ou dans votre Cimetière avec une ATK inférieure au monstre Invoqué Spécialement; Invoquez-le Spécialement. \r\nUne fois par tour, si un monstre TÉNÈBRES que vous contrôlez va être détruit au combat ou par un effet de carte, vous pouvez retirer 1 Compteur Plumes Noires depuis votre Terrain à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7602840,'UFOroid','Lorsque cette carte est détruite au combat et envoyée au Cimetière: vous pouvez Invoquer Spécialement 1 monstre Machine avec max. 1500 ATK depuis votre Deck en Position d''Attaque face recto.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7608148,'Vif Arrière',replace(replace('Ciblez 1 carte que vous contrôlez; renvoyez-la à la main. \r\nSi cette carte est dans votre Cimetière: vous pouvez cibler 1 carte face recto que vous contrôlez; Posez cette carte (mais bannissez-la lorsqu''elle quitte le Terrain), et si vous le faites, renvoyez la carte face recto à la main, mais le reste de ce tour, vous ne pouvez activer ni de cartes ni d''effets de cartes du même nom que la carte avait une fois renvoyée à la main. \r\nVous ne pouvez utiliser qu''1 effet de "Vif Arrière" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7610394,'Réapparition de l''Œil Maléfique',replace(replace('Invoquez Spécialement 1 "Jeton Familier de l''Œil Maléfique" (Démon/TÉNÈBRES/Niveau 1/ATK 400/DEF 400), ou, si "L''Œil Maléfique de Sélène" est dans votre Zone Magie & Piège, vous pouvez en Invoquer Spécialement 2 à la place, et aussi, le reste de ce tour après la résolution de cette carte, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Démon exclus). \r\nVous pouvez bannir cette carte depuis votre Cimetière; ce tour, votre adversaire ne peut pas cibler de Magies/Pièges "Œil Maléfique" que vous contrôlez avec des effets de carte. \r\nVous ne pouvez utiliser chaque effet de "Réapparition de l''Œil Maléfique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Invoquer Spécialement 2 monstres ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7610395,'Jeton Familier de l''Œil Maléfique','Invoqué Spécialement avec l''effet de "Réapparition de l''Œil Maléfique".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7614732,'Plus Grande Polymérisation',replace(replace('Invoquez par Fusion 1 Monstre Fusion depuis votre Extra Deck, en utilisant min. 3 monstres depuis votre main ou Terrain comme Matériel Fusion, et si vous le faites, il gagne ces effets.\r\n● Cette carte ne peut pas être détruite par des effets de carte.\r\n● Si cette carte attaque un monstre en Position de Défense, infligez des dommages de combat perçants.','\r',char(13)),'\n',char(10)),'Invoquer par Fusion avec l''effet de "Plus Grande Polymérisation"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7617062,'Musée Fantôruse',replace(replace('Les monstres que vous contrôlez (monstres "Fantôruse" exclus) ne peuvent pas attaquer. \r\nLes monstres ne peuvent pas attaquer les monstres en Position de Défense face verso, mais ils peuvent attaquer directement si tous les monstres contrôlés par l''adversaire sont en Position de Défense face verso. À la fin de la Damage Step, changez les monstres qui ont infligé des dommages de combat à un joueur durant ce combat en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face verso','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7617253,'Chemin Arc-en-Ciel','Lorsqu''un monstre de l''adversaire déclare une attaque: envoyez 1 carte "Bête Cristalline" depuis votre Zone Magie & Piège au Cimetière, puis ciblez le monstre attaquant; annulez l''attaque, puis vous pouvez ajouter 1 "Dragon Arc-en-Ciel" ou "Dragon Arc-en-Ciel des Ténèbres" depuis votre Deck à votre main.','Ajouter 1 carte "Cristal Ultime" à votre main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7622360,'Archdémon Matador',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Rituel du Matador". \r\nSi cette carte est Invoquée Rituellement: vous pouvez ajouter 2 cartes "Archdémon" ("Archdémon Matador" exclu) depuis votre Deck à votre main, et aussi, cette carte ne peut pas attaquer le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Archdémon Matador" qu''une fois par tour. \r\nNon destructible au combat, et aussi, vous ne recevez aucun dommage de combat de combats impliquant cette carte. \r\nAprès le calcul des dommages, si cette carte a combattu un monstre: détruisez le monstre, et si vous le faites, infligez 1000 points de dommages à votre adversaire.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7623640,'Ceruli, Guru du Monde Ténébreux',replace(replace('Si cette carte est défaussée au Cimetière par un effet de carte: Invoquez Spécialement cette carte sur le Terrain de votre adversaire en Position de Défense. \r\nSi cette carte est Invoquée Spécialement par l''effet d''une carte "Monde Ténébreux": votre adversaire défausse 1 carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Votre adversaire défausse 1 carte','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7625614,'Armure en Or Massif','Tant que vous contrôlez le monstre équipé avec cette carte, votre adversaire ne peut pas attaquer d''autre monstre excepté le monstre équipé.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7628844,'Numéro C32 : Requin Drakonien LéVeiss',replace(replace('4 monstres de Niveau 5	\r\nVous pouvez aussi Invoquer par Xyz cette carte en défaussant 1 Magie, et en utilisant un Monstre Xyz "Requin Drakonien" de Rang 4 que vous contrôlez comme Matériel. \r\n(Transférez ses Matériels à cette carte.) \r\nUne fois par tour (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 Monstre à Effet contrôlé par votre adversaire; annulez ses effets, et si vous le faites, son ATK/DEF deviennent 0. \r\nCette carte peut faire une seconde attaque durant chaque Battle Phase, et aussi, s''il attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire.','\r',char(13)),'\n',char(10)),'Invoquer Xyz en utilisant le Monstre Xyz "Requin Drakonien" comme Matériel ?','Annuler l''effet','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7631534,'Pieds du Double Avatar - Un-Gyo Cuirassé',replace(replace('2 monstres "Double Avatar"	\r\nSi un ou plusieurs Monstres Fusion "Double Avatar" que vous contrôlez vont être détruits par un effet de carte, vous pouvez détruire 1 monstre "Double Avatar" que vous contrôlez à la place. \r\nDurant la Main Phase, si vous contrôlez un Monstre Fusion "Double Avatar" qui a été Invoqué par Fusion en utilisant un Monstre à Effet comme Matériel (Effet Rapide): vous pouvez cibler 1 monstre face recto Invoqué Spécialement depuis l''Extra Deck; jusqu''à la fin de ce tour, annulez ses effets. \r\nVous ne pouvez utiliser cet effet de "Pieds du Double Avatar - Un-Gyo Cuirassé" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7634581,'Orichalcos Shunoros',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement par son propre effet. À la fin de la Damage Step, si votre Monstre Normal est détruit au combat: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nGagne 1000 ATK pour chaque monstre contrôlé par votre adversaire. \r\nLes Monstres Normaux de Niveau 4 face recto sur le Terrain ne peuvent pas être détruits par des effets de carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7653207,'Jet Aqua','Ciblez 1 monstre de Type Poisson/Serpent de Mer/Aqua face recto que vous contrôlez; il gagne 1000 ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7656689,'Genni, la Domestique d''Endymion',replace(replace('(Cette carte est toujours traitée comme carte "Artisanesorcière".)	\r\nSi vous contrôlez un monstre Magicien et que cette carte est dans votre main: vous pouvez Invoquer Spécialement cette carte. \r\nDurant la Main Phase (Effet Rapide): vous pouvez cibler 1 monstre Magicien que vous contrôlez; bannissez-le, et si vous le faites, Invoquez Spécialement 1 monstre "Artisanesorcière" ("Genni, la Domestique d''Endymion" exclu) depuis votre Deck. \r\nVous ne pouvez utiliser chaque effet de "Genni, la Domestique d''Endymion" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Bannir et Invoquer Spécialement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7670542,'Plante bio','Monstre créé lors d''un grave accident survenu dans un laboratoire souterrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7672244,'Espion de Shien','Ciblez 1 monstre face recto que vous contrôlez; jusqu''à la End Phase de ce tour, donnez-en le contrôle à votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7700132,'Ver - Noble','FLIP: Si cette carte est retournée face recto par l''attaque d''un monstre de l''adversaire, infligez des dommages à votre adversaire égaux à la moitié de l''ATK du monstre attaquant.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7714344,'Li Potartiste',replace(replace('Une fois par tour, durant votre Main Phase, si cette carte a été Invoquée Normalement ou Spécialement ce tour: vous pouvez Invoquer Spécialement 1 monstre "Potartiste" de max. Niveau 3 depuis votre main en Position d''Attaque. \r\nDurant le tour de votre adversaire (Effet Rapide): vous pouvez bannir 1 monstre "Potartiste" ("Li Potartiste" exclu) et cette carte depuis votre Cimetière; la prochaine fois que vous recevez des dommages de combat ce tour, vous n''en recevez pas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7721912,'Lancier Chevalier Noble',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre de max. Niveau 8 que vous contrôlez; son nom devient "Fleur Synchronique", et aussi, il est traité comme un Syntoniseur, jusqu''à la End Phase. \r\nVous pouvez Sacrifier cette carte; ajoutez 1 Magie d''Équipement depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Lancier Chevalier Noble" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7733560,'Michion le Seigneur du Temps',replace(replace('Non Invocable Spécialement depuis le Deck. \r\nSi vous ne contrôlez aucun monstre, vous pouvez Invoquer Normalement cette carte sans Sacrifices. \r\nNon destructible ni au combat ni par des effets de carte. \r\nVous ne recevez aucun dommage de combat d''attaques impliquant cette carte. À la fin de la Battle Phase, si cette carte a combattu: divisez par deux les LP de votre adversaire. \r\nUne fois par tour, durant votre Standby Phase: mélangez cette carte dans le Deck.','\r',char(13)),'\n',char(10)),'Invocation Normale sans Sacrifice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7736719,'Cavalier du Vortex',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez mélanger 2 cartes depuis votre main dans le Deck, puis piochez 2 cartes. \r\nSi cette carte est détruite: piochez 1 carte.','\r',char(13)),'\n',char(10)),'Mélanger et piocher','Piocher','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7778726,'Hoshiningen à la Mode',replace(replace('2 monstres LUMIÈRE	\r\nTous les monstres LUMIÈRE sur le Terrain gagnent 500 ATK/DEF, et aussi, tous les monstres TÉNÈBRES sur le Terrain perdent 400 ATK/DEF. \r\nSi cette carte est détruite au combat ou par un effet de carte: vous pouvez cibler 1 monstre LUMIÈRE dans votre Cimetière; ajoutez-le à votre main. \r\nVous ne pouvez utiliser cet effet de "Hoshiningen à la Mode" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7782069,'Gouki L''Ogre Tyran',replace(replace('1 Monstre Lien "Gouki" + 1 monstre Guerrier, Dinosaure ou Cyberse	\r\nSi cette carte combat, votre adversaire ne peut activer ni de cartes ni d''effets jusqu''à la fin de la Damage Step. \r\nSi cette carte est Invoquée par Fusion: vous pouvez cibler un nombre de cartes sur le Terrain inférieur ou égal à la somme des Classifications Lien des monstres "Gouki" utilisés comme Matériel de cette carte (si vous avez utilisé un monstre de min. Link-3, aucun joueur ne peut activer ni ces cartes ciblées ni leurs effets en réponse à l''activation de cet effet); détruisez-les. \r\nVous ne pouvez utiliser cet effet de "Gouki L''Ogre Tyran" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Détruire','Ne peut pas activer d''effets','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7799906,'Sorcier Souriant Potartiste',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nSi un ou plusieurs monstres que vous contrôlez, dont l''ATK actuelle est supérieure à leur ATK d''origine, sont détruits au combat ou par un effet de carte: vous pouvez Invoquer Spécialement cette carte depuis votre Zone Pendule. \r\nVous ne pouvez utiliser cet effet de "Sorcier Souriant Potartiste" qu''une fois par tour.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 Magie/Piège "Souriant" depuis votre Deck à votre main. \r\nSi tous les monstres que vous contrôlez sont des monstres "Potartiste", "Yeux Impairs" et/ou des Monstres Pendule "Magicien", et que l''ATK actuelle de cette carte est supérieure à son ATK d''origine: vous pouvez piocher un nombre de cartes égal au nombre de monstres que vous contrôlez dont l''ATK actuelle est supérieure à leur ATK d''origine, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Sorcier Souriant Potartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7802006,'Mandragore','FLIP: Placez 1 Compteur Magie sur chaque carte face recto sur le Terrain sur laquelle vous pouvez placer un Compteur Magie.','Placer un marqueur','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7805147,'Soldats Draconiques','Une fois par tour, lorsque votre adversaire active une carte ou un effet (Effet Rapide): vous pouvez Invoquer Spécialement 1 monstre Dragon de max. Niveau 2 depuis votre Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7805359,'Niwatori','Il gobe ses ennemis d''un seul coup et use de leur essence comme énergie.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7811875,'Fracture de Gravité','Lorsque votre adversaire va Invoquer un ou plusieurs monstres: envoyez 1 Monstre Synchro face recto que vous contrôlez au Cimetière; annulez l''Invocation, et si vous le faites, détruisez le monstre, et votre adversaire ne peut pas Invoquer de monstre jusqu''à la fin de ce tour.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7817703,'Unité d''Énergie Morphtronique',replace(replace('Équipable uniquement à un monstre "Morphtronique" de niveau 3. \r\nSon ATK devient le double de son ATK d''origine. \r\nDurant votre deuxième Standby Phase après l''activation de cette carte, détruisez-la et recevez des dommages égaux à l''ATK d''origine du monstre équipé.','\r',char(13)),'\n',char(10)),'Détruire cette carte','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7841112,'Dragon des Étoiles Majestueux',replace(replace('"Dragon Majestueux" + "Dragon Poussière d''Étoile" + 1 monstre non-Syntoniseur	\r\nDurant le tour de chaque joueur, lorsque votre adversaire active une carte ou un effet: vous pouvez Sacrifier cette carte; annulez l''activation, et si vous le faites, détruisez toutes les cartes contrôlées par votre adversaire. \r\nUne fois par tour: vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; jusqu''à la fin de ce tour, annulez ses effets, et une fois ce tour, vous pouvez activer 1 de ses effets comme l''effet de cette carte. \r\nDurant la End Phase: ciblez 1 "Dragon Poussière d''Étoile" dans votre Cimetière; renvoyez cette carte depuis le Terrain à l''Extra Deck, puis Invoquez Spécialement la cible.','\r',char(13)),'\n',char(10)),'Annuler l''activation, puis détruire toutes les cartes contrôlées par votre adversaire','Annuler les effets','Renvoyer à l''Extra Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7841921,'Gaïa le Chevalier Implacable Attaquant',replace(replace('Vous pouvez Invoquer Normalement cette carte sans Sacrifices. \r\nSi cette carte est Invoquée Normalement sans Sacrifices, son ATK d''origine devient 1900. \r\nSi cette carte est Sacrifiée: vous pouvez ajouter 1 monstre "Soldat du Lustre Noir" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Gaïa le Chevalier Implacable Attaquant" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Normale sans Sacrifice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7845138,'Décomposition Sans Fin',replace(replace('Si vous avez max. 2000 LP, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nSi cette carte est Invoquée Normalement ou Spécialement: l''ATK de cette carte devient la moitié des LP de l''adversaire.','\r',char(13)),'\n',char(10)),'Changer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7850740,'Glissedauphin Xyz',replace(replace('Si un Monstre Xyz est Invoqué Spécialement sur votre Terrain (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nSi un ou plusieurs Monstres Xyz sont Invoqués Spécialement sur votre Terrain tant que cette carte est dans votre Cimetière, sauf le tour où cette carte a été envoyée à votre Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 de ces Monstres Xyz; attachez-lui cette carte comme Matériel. \r\nVous ne pouvez utiliser chaque effet de "Glissedauphin Xyz" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852509,'Boucle de Destruction',replace(replace('Le nom de cette carte devient "Anneau de Destruction" tant qu''elle est sur le Terrain. \r\nUne fois par tour, si un ou plusieurs monstres sur le Terrain sont détruits par un effet de carte (sauf durant la Damage Step): vous pouvez cibler 1 monstre sur le Terrain; détruisez-le, et si vous le faites, chaque joueur reçoit 500 points de dommages.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852510,'Boucle de Destruction',replace(replace('Le nom de cette carte devient "Anneau de Destruction" tant qu''elle est sur le Terrain. \r\nUne fois par tour, si un ou plusieurs monstres sur le Terrain sont détruits par un effet de carte (sauf durant la Damage Step): vous pouvez cibler 1 monstre sur le Terrain; détruisez-le, et si vous le faites, chaque joueur reçoit 500 points de dommages.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852878,'Trois Mille Aiguilles','À la fin de la Damage Step, si cette carte en Position de Défense a été attaquée par un monstre dont l''ATK est inférieure à la DEF de cette carte: détruisez le monstre attaquant.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7864030,'Chalumeau Samouraï Supralourd',replace(replace('Lorsqu''un monstre de votre adversaire déclare une attaque tant que vous n''avez aucune Carte Magie/Piège dans votre Cimetière: vous pouvez envoyer cette carte depuis votre main au Cimetière, puis ciblez 1 monstre "Samouraï Supralourd" que vous contrôlez; transférez-lui la cible de l''attaque et faites le calcul des dommages. \r\nUne fois par tour, lorsqu''un monstre de votre adversaire déclare une attaque: vous pouvez transférer la cible de l''attaque sur cette carte, et faites le calcul des dommages. \r\nNon destructible au combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7868571,'Oisargent Métalphose',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nUne fois par tour : vous pouvez cibler 1 autre carte face recto que vous contrôlez ; détruisez-la, et si vous le faites, Posez 1 Magie/Piège "Métalphose" directement depuis votre Deck.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSoldate bouillonnante équipée d''un vaisseau argenté supraluminique. Intraçable et invisible, personne ne peut échapper à son laser supersonique.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7889323,'Épreuve de Force Tri-Brigade',replace(replace('Si un monstre Bête, Bête-Guerrier ou Bête Ailée est Invoqué Spécialement sur votre Terrain (sauf durant la Damage Step): vous pouvez cibler 1 de vos monstres "Tri-Brigade" bannis; ajoutez-le à votre main. \r\nAprès le calcul des dommages, si votre monstre "Tri-Brigade" a combattu un monstre de l''adversaire: vous pouvez renvoyer le monstre de l''adversaire à la main. \r\nVous ne pouvez utiliser chaque effet de "Épreuve de Force Tri-Brigade" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Récupérer des monstres bannis','Renvoyer un monstre adverse à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7892180,'Kappa Psychique','Un monstre amphibien doté de nombreux pouvoirs qui le protége des attaques ennemies.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7894706,'Les Bêtes Sacrées du Spectre Chaotique',replace(replace('3 monstres de Niveau 10 qui ne peuvent pas être Invoqués/Posés Normalement	\r\nUniquement soit Invocable par Fusion soit Invocable Spécialement (depuis votre Extra Deck) en envoyant les cartes ci-dessus que vous contrôlez au Cimetière. \r\nVous ne pouvez Invoquer Spécialement "Les Bêtes Sacrées du Spectre Chaotique" qu''une fois par tour de cette façon, peu importe la méthode que vous utilisez. \r\nLes deux premières fois que cette carte sur le Terrain va être détruite par un effet de carte chaque tour, elle n''est pas détruite. \r\nUne fois par Chaîne, max. trois fois par tour (Effet Rapide): vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; annulez ses effets (jusqu''à la fin de ce tour), puis vous pouvez gagner des LP égaux à la moitié de l''ATK du monstre.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Gagner des LP ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7894707,'Les Bêtes Sacrées du Spectre Chaotique',replace(replace('3 monstres de Niveau 10 qui ne peuvent pas être Invoqués/Posés Normalement	\r\nUniquement soit Invocable par Fusion soit Invocable Spécialement (depuis votre Extra Deck) en envoyant les cartes ci-dessus que vous contrôlez au Cimetière. \r\nVous ne pouvez Invoquer Spécialement "Les Bêtes Sacrées du Spectre Chaotique" qu''une fois par tour de cette façon, peu importe la méthode que vous utilisez. \r\nLes deux premières fois que cette carte sur le Terrain va être détruite par un effet de carte chaque tour, elle n''est pas détruite. \r\nUne fois par Chaîne, max. trois fois par tour (Effet Rapide): vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; annulez ses effets (jusqu''à la fin de ce tour), puis vous pouvez gagner des LP égaux à la moitié de l''ATK du monstre.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Gagner des LP ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7902349,'Bras Gauche de l''Interdit','Bras gauche interdit scellé par la magie. Toute personne rompant ce sceau connaîtra la puissance infinie.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7903368,'Crâne de Cristal',replace(replace('Si cette carte est Invoquée: recevez 1000 points de dommages, puis changez cette carte en Position de Défense. \r\nDurant la End Phase, si vous n''avez pas reçu de dommages d''effet ce tour: vous pouvez soit ajouter à votre main soit Invoquer Spécialement 1 monstre Rocher avec 0 ATK depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Crâne de Cristal" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7913375,'Artillerie Tortue Catapulte',replace(replace('Vous pouvez Sacrifier 1 monstre; Invoquez Spécialement 1 monstre "Gaïa le Chevalier Implacable" ou 1 monstre Dragon de Niveau 5 depuis votre main ou Deck. \r\nVous ne pouvez utiliser cet effet de "Artillerie Tortue Catapulte" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7914843,'Lépidoptère Électromagnétique',replace(replace('FLIP: Ciblez 1 monstre de Type Machine contrôlé par votre adversaire; jusqu''à votre prochaine End Phase, prenez le contrôle de la cible.\r\nSi cette carte est détruite au combat: le monstre qui l''a détruite perd 500 ATK/DEF.','\r',char(13)),'\n',char(10)),'Prendre le contrôle','Diminuer l''ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7917970,'Vent Divin Dragunité',replace(replace('Durant votre Main Phase: vous pouvez appliquer 1 de ces effets, ou si "Ravin des Dragons" est dans votre Cimetière, vous pouvez appliquer n''importe lesquels, dans l''ordre;\r\n● Ajoutez 1 monstre Dragon ou Bête Ailée depuis votre Cimetière à votre main.\r\n● Invoquez Spécialement 1 monstre "Dragunité" depuis votre main, puis vous pouvez lui équiper 1 monstre "Dragunité" Dragon depuis votre Deck comme Magie d''Équipement.	\r\nVous ne pouvez utiliser cet effet de "Vent Divin Dragunité" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer','Ajouter cette carte à la main ?','Invocation Spéciale?','Équiper un monstre ?','','','','','','','','','','','','');
INSERT INTO texts VALUES(7922915,'Navigation des Magiciens',replace(replace('Invoquez Spécialement 1 "Magicien Sombre" depuis votre main, puis Invoquez Spécialement 1 monstre TÉNÈBRES Magicien de max. Niveau 7 depuis votre Deck. \r\nSi vous contrôlez "Magicien Sombre", sauf le tour où cette carte a été envoyée au Cimetière: vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Magie/Piège face recto contrôlé par votre adversaire; jusqu''à la fin de ce tour, annulez ses effets.','\r',char(13)),'\n',char(10)),'Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7925734,'Lien Pomme',replace(replace('Vous pouvez révéler cette carte dans votre main; bannissez (face recto) 1 carte face verso au hasard depuis votre Extra Deck, puis, Invoquez Spécialement cette carte si la carte bannie était un Monstre Lien. \r\nSinon, défaussez cette carte, et si vous le faites, piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Lien Pomme" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7930346,'Déesse Origami',replace(replace('Une fois par tour, durant votre Main Phase: vous pouvez lancer une pièce jusqu''à ce que le résultat soit pile, et si vous le faites, piochez 1 carte pour tous les 2 faces. \r\nChaque fois qu''un effet de lancer de pièce est résolu tant que ce monstre est sur le Terrain: doublez l''ATK de cette carte pour chaque face de cet effet.','\r',char(13)),'\n',char(10)),'','Doubler l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7934362,'Danseuse de Feu Mageartiste',replace(replace('Échelle Pendule = 6\r\n[ Effet Pendule ]\r\nUne fois par tour: vous pouvez cibler 1 monstre "Mageartiste" que vous contrôlez; s''il attaque un monstre en Position de Défense ce tour, infligez des dommages de combat perçants à votre adversaire.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 monstre "Mageartiste" ("Danseuse de Feu Mageartiste" exclu) depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Danseuse de Feu Mageartiste" qu''une fois par tour. \r\nSi cette carte sur le Terrain est détruite au combat ou par un effet de carte: vous pouvez cibler 1 monstre face recto sur le Terrain; il perd 500 ATK.','\r',char(13)),'\n',char(10)),'Donner des dégâts perçants','Effet d''ajout à la main','Diminuer l''ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7935043,'Égide du Seigneur Dragon des Océans','Jusqu''à la End Phase, les monstres EAU de max. Niveau 3 face recto que vous contrôlez ne peuvent être détruits ni au combat ni par des effets de carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7953868,'Oni au Sang Bleu',replace(replace('Lorsque cette carte est Invoquée Normalement ou par Flip: elle est changée en Position de Défense. \r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz que vous contrôlez pour cibler 1 monstre de Type Zombie de Niveau 4 dans votre Cimetière; Invoquez Spécialement la cible.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7969770,'Transefamilier','Une fois par tour: vous pouvez cibler 1 monstre que vous contrôlez; déplacez la cible dans une autre de vos Zones Monstre Main.','','Choisissez la zone vers laquelle déplacer','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7984540,'Daphnée Solairavalon',replace(replace('2 monstres Plante	\r\nCette carte ne peut pas être ciblée par des attaques, mais ça n''empêche pas votre adversaire de vous attaquer directement. \r\nVous pouvez Sacrifier 1 monstre, puis ciblez 2 Monstres Lien Plante ("Daphnée Solairavalon" exclu) dans votre Cimetière; renvoyez-les à l''Extra Deck. \r\nVous ne pouvez utiliser cet effet de "Daphnée Solairavalon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Choisissez la carte à renvoyer à l''Extra Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7986397,'Évolution Revendetterreur',replace(replace('Cette carte peut être utilisée pour Invoquer Rituellement un Monstre Rituel "Vendetterreur" depuis votre main ou Cimetière. \r\nVous devez aussi Sacrifier des monstres depuis votre main ou Terrain, et/ou envoyer 1 monstre "Vendetterreur" depuis votre Deck au Cimetière, dont le Niveau total est égal au Niveau du Monstre Rituel que vous Invoquez Rituellement. \r\nLe monstre Invoqué Rituellement est détruit durant la End Phase du prochain tour. \r\nVous ne pouvez activer qu''1 "Évolution Revendetterreur" par tour.','\r',char(13)),'\n',char(10)),'Envoyer 1 monstre "Vendetterreur" depuis votre Deck au Cimetière ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7987191,'Dragon Émeute Chargeborrelle',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Interverrouillage Lourd". \r\nLorsque votre adversaire Invoque Spécialement un ou plusieurs monstres (Effet Rapide): vous pouvez annuler l''Invocation Spéciale, et si vous le faites, détruisez les monstres, puis détruisez cette carte ou 1 monstre "Rokkette" que vous contrôlez. \r\nSi cette carte est dans votre Cimetière: vous pouvez cibler 1 monstre "Borrelle" ou "Rokkette" dans votre Cimetière; détruisez 1 carte que vous contrôlez ou dans votre main, et si vous le faites, ajoutez la cible à votre main. \r\nVous ne pouvez utiliser chaque effet de "Dragon Émeute Chargeborrelle" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8025950,'Boîte Gadget',replace(replace('(Cette carte est toujours traitée comme une carte "Morphtronique".)	\r\nLorsque cette carte est activée: placez 3 Compteurs Morph sur elle. \r\nUne fois par tour, durant votre Main Phase: vous pouvez retirer 1 Compteur Morph depuis votre Terrain, et si vous le faites, Invoquez Spécialement 1 "Jeton Boîte Gadget" (Machine/TERRE/Niveau 1/ATK 0/DEF 0). \r\nTant que le Jeton est dans la Zone Monstre, le joueur qui l''a Invoqué ne peut pas Invoquer Spécialement de monstres (Monstres Synchro exclus) depuis l''Extra Deck. \r\nVous ne pouvez activer qu''1 "Boîte Gadget" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8025951,'Jeton Boîte Gadget','Invoqué Spécialement avec l''effet de "Boîte Gadget".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8034697,'Marionnette Magique',replace(replace('Chaque fois qu''une Carte Magie est activée, placez 1 Compteur Magie sur cette carte lorsque la Carte Magie est résolue. \r\nGagne 200 ATK pour chaque Compteur Magie sur elle. \r\nVous pouvez retirer 2 Compteurs Magie de cette carte, puis ciblez 1 monstre sur le Terrain; détruisez-le.','\r',char(13)),'\n',char(10)),'Placer des Compteurs Magie','Détruire un monstre','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8038143,'Transmigration Tachyon',replace(replace('Si vous contrôlez un monstre "Yeux Galactiques": activez en min. Maillon 2 de la Chaîne; annulez les activations des Cartes Magie/Piège et effets de monstre de votre adversaire activés avant cette carte dans cette Chaîne, et si vous le faites, mélangez les cartes annulées sur le Terrain dans le Deck. \r\nSi vous contrôlez un monstre "Dragon Tachyon aux Yeux Galactiques", vous pouvez activer cette carte depuis votre main.','\r',char(13)),'\n',char(10)),'Activer en appliquant l''effet de "Transmigration Tachyon".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8039562,'Fauchon Dragunité',replace(replace('Vous pouvez bannir cette carte depuis votre main ou Cimetière, puis ciblez 1 monstre "Dragunité" que vous contrôlez; équipez-lui 1 monstre "Dragunité" Dragon depuis votre Deck ou Cimetière comme Magie d''Équipement. \r\nTant que cette carte est équipée à un monstre "Dragunité": vous pouvez envoyer cette carte au Cimetière, puis ciblez 1 carte face recto contrôlée par votre adversaire; bannissez-la. \r\nVous ne pouvez utiliser chaque effet de "Fauchon Dragunité" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Effet d''Équipement','Effet de bannissement','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8041569,'Dame Lacustre Laval','Si cette carte est dans votre Cimetière et que vous avez min. 3 monstres "Laval" de noms différents dans votre Cimetière: vous pouvez bannir cette carte et 1 autre monstre "Laval" depuis votre Cimetière pour cibler 1 carte Posée contrôlée par votre adversaire; détruisez la cible.','Détruire 1 carte Posée contrôlée par votre adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8057630,'Renforcement de Noyau',replace(replace('Sélectionnez et Invoquez Spécialement 1 monstre "Koa''ki Meiru" depuis votre Cimetière en Position d''Attaque. \r\nLorsque ce monstre est détruit durant votre End Phase, le contrôleur de cette carte reçoit des dommages égaux à l''ATK de ce monstre. \r\nLorsque cette carte est retirée du Terrain, détruisez ce monstre. \r\nLorsque ce monstre est détruit, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8058240,'Chaîne d''engagement','Les maillons mystiques de cette chaîne peuvent voler leur pouvoir aux ennemis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8062132,'Vénominaga, Déesse des Serpents Venimeux',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement avec "Avènement du Dieu Serpent" ou par son propre effet. \r\nGagne 500 ATK pour chaque monstre Reptile dans votre Cimetière. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte, et aussi, elle n''est affectée ni par les autres cartes ni par leurs effets. \r\nLorsque cette carte est détruite au combat et envoyée au Cimetière: vous pouvez bannir 1 autre monstre Reptile depuis votre Cimetière; Invoquez Spécialement cette carte. \r\nLorsque cette carte inflige des dommages de combat à votre adversaire: placez 1 Compteur Hyper-Venin sur elle. \r\nLorsque le 3e Compteur Hyper-Venin est placé sur cette carte, vous gagnez le Duel.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Placer un marqueur','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8078366,'Escouade d''Attaque de l''Atlantide','Cette carte gagne 800 ATK tant que vous contrôlez un monstre de Type Poisson/Serpent de Mer/Aqua face recto (cette carte exclue).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8080257,'Dansépées des Flammes',replace(replace('Si un ou plusieurs monstres sont Invoqués Spécialement: Invoquez Spécialement 1 Monstre Fusion de max. Niveau 7 depuis votre Extra Deck qui est "Spadassin des Flammes" ou qui le mentionne, puis vous pouvez changer 1 monstre face recto sur le Terrain en Position de Défense face verso. \r\nDurant la Battle Phase de votre adversaire: vous pouvez bannir cette carte depuis votre Cimetière, et Sacrifiez 1 monstre en Position de Défense face verso; Invoquez Spécialement 1 "Spadassin des Flammes" ou 1 monstre qui le mentionne depuis votre Deck ou Extra Deck. \r\nVous ne pouvez utiliser cet effet de "Dansépées des Flammes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale depuis l''Extra Deck','Invoquer Spécialement un monstre depuis le Deck/l''Extra Deck','Mettre un monstre en Position de Défense face verso ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8083925,'Accueil Live☆Jumelle',replace(replace('Défaussez 1 carte; Invoquez Spécialement 1 monstre "Ki-sikil" ou 1 monstre "Lil-la" depuis votre Deck, et aussi, le reste de ce tour après la résolution de cette carte, vous ne pouvez pas Invoquer Spécialement de monstres (monstres "Evil★Jumelle" exclus) depuis l''Extra Deck. \r\nVous ne pouvez activer qu''1 "Accueil Live☆Jumelle" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8085950,'Burning Dragon',replace(replace('Si votre adversaire contrôle min. 2 monstres et que cette carte est dans votre main: vous pouvez Invoquer Spécialement cette carte. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez défausser 1 Magie; détruisez toutes les Magies et tous les Pièges sur le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Burning Dragon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8091563,'Super Défense Lio',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre "Super Défense" ou "Orbital 7" depuis votre main. \r\nUne fois par tour, lorsqu''exactement 1 monstre "Super Défense" ou "Orbital 7" (et aucune autre carte) est ajouté depuis votre Cimetière à votre main (sauf durant la Damage Step): vous pouvez l''Invoquer Spécialement depuis votre main.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8102334,'Porte Bloqueur',replace(replace('Annulez les effets des Magies de Terrain de votre adversaire. \r\nVotre adversaire ne peut pas placer de Compteurs sur les cartes sur le Terrain. \r\nVotre adversaire ne peut pas cibler d''autres monstres que vous contrôlez avec des effets de carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8124921,'Jambe Droite de l''Interdit','Jambe droite interdite scellée par la magie. Toute personne rompant ce sceau connaîtra la puissance infinie.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8129306,'Primula la Féé Rikka',replace(replace('Si un monstre que vous contrôlez est Sacrifié (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main en Position de Défense. \r\nVous pouvez cibler max. 2 monstres Plante que vous contrôlez; jusqu''à la fin de ce tour, augmentez leur Niveau de 2. \r\nVous ne pouvez utiliser chaque effet de "Primula la Féé Rikka" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8131171,'Serpent Sinistre',replace(replace('Durant votre Standby Phase, si cette carte est dans votre Cimetière: vous pouvez la renvoyer à votre main, et aussi, bannissez 1 "Serpent Sinistre" depuis votre Cimetière durant la prochaine End Phase de votre adversaire. \r\nVous ne pouvez utiliser cet effet de "Serpent Sinistre" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8148322,'Fusion Prédaprime',replace(replace('Si un ou plusieurs monstres "Prédaplante" sont sur le Terrain: Invoquez par Fusion 1 Monstre Fusion TÉNÈBRES depuis votre Extra Deck, en utilisant des monstres depuis au moins l''un des Terrains comme Matériel (min. 2 monstres TÉNÈBRES que vous contrôlez inclus). \r\nVous ne pouvez activer qu''1 "Fusion Prédaprime" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8152834,'Tarai',replace(replace('Si cette carte est dans votre main: vous pouvez cibler 1 monstre face recto dans la Zone Monstre Main qui a activé son effet sur le Terrain ce tour; détruisez-le, et si vous le faites, Invoquez Spécialement cette carte dans la zone dans laquelle le monstre était. \r\nVous ne pouvez utiliser cet effet de "Tarai" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8165596,'Numéro 90 : Seigneur Photon aux Yeux Galactiques',replace(replace('2 monstres de Niveau 8	\r\nSi cette carte a une carte "Photon" comme Matériel, elle ne peut pas être détruite par des effets de carte. \r\nVous ne pouvez utiliser chacun des effets suivants de "Numéro 90 : Seigneur Photon aux Yeux Galactiques" qu''une fois par tour.\r\n● Lorsqu''un monstre de l''adversaire active son effet (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''effet du monstre, et si le Matériel détaché était une carte "Galactique", détruisez la carte.\r\n● Durant le tour de votre adversaire (Effet Rapide): vous pouvez prendre 1 carte "Photon" ou "Galactique" depuis votre Deck, et soit l''ajouter à votre main soit l''attacher à cette carte comme Matériel.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Chercher dans le Deck ou attacher un Matériel Xyz','Superposer comme Matériel Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8170654,'Épieuvre de Maïs Géante',replace(replace('Lorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez Invoquer Spécialement cette carte depuis votre main en Position de Défense, et si vous le faites, transférez la cible de l''attaque sur cette carte et faites le calcul des dommages. \r\nVous pouvez cibler 1 monstre Plante que vous contrôlez ("Épieuvre de Maïs Géante" exclu); l''ATK du monstre et de cette carte devient la somme des ATK d''origine des deux monstres. \r\nVous ne pouvez utiliser chaque effet de "Épieuvre de Maïs Géante" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Modifier l''ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8173184,'Contrôleur Genex Réparé',replace(replace('1 monstre "Genex" de max. Niveau 4	\r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Contrôleur Genex Réparé" qu''une fois par tour. \r\nSi cette carte est Invoquée par Lien: vous pouvez ajouter 1 monstre "Genex" depuis votre Cimetière à votre main. \r\nUne fois par Chaîne, si un ou plusieurs monstres "Genex" sont ajoutés à votre main, sauf en les piochant, vous pouvez (sauf durant la Damage Step): immédiatement après la résolution de cet effet, Invoquez Normalement 1 monstre "Genex", et aussi, vous ne pouvez pas Invoquer Spécialement depuis l''Extra Deck le reste de ce tour, sauf par Invocation Synchro en utilisant un Syntoniseur "Genex" comme Matériel.','\r',char(13)),'\n',char(10)),'Ajouter du Cimetière à la main','Invocation','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8175346,'Poki Draco','Lorsque cette carte est Invoquée Normalement: vous pouvez ajouter 1 "Poki Draco" depuis votre Deck à votre main.','Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8192327,'Phosphorage le Seigneur Élémentaire',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en ayant exactement 5 monstres LUMIÈRE dans votre Cimetière. \r\nLorsque cette carte est Invoquée Spécialement: vous pouvez détruire tous les monstres contrôlés par votre adversaire. \r\nVous ne pouvez utiliser cet effet de "Phosphorage le Seigneur Élémentaire" qu''une fois par tour. \r\nSi cette carte face recto quitte le Terrain, sautez la Battle Phase de votre prochain tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198620,'Dragon Profondâme Dragonécro',replace(replace('2 monstres Zombie	\r\nDoit d''abord être Invoquée par Fusion. \r\nLes monstres ne peuvent pas être détruits au combat avec cette carte. À la fin de la Damage Step, si cette carte a combattu un monstre: changez l''ATK du monstre à 0, et aussi, si le monstre est toujours face recto sur le Terrain, Invoquez Spécialement 1 "Jeton Âme des Ténèbres" (Zombie/TÉNÈBRES/Niveau ?/ATK ?/DEF 0) du même Niveau/ATK que le Niveau/ATK d''origine du monstre. \r\nVous ne pouvez contrôler qu''1 "Dragon Profondâme Dragonécro".','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198621,'Jeton Âme des Ténèbres','Invoqué Spécialement avec l''effet de "Dragon Profondâme Dragonécro".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198712,'Fin du Monde',replace(replace('Cette carte est utilisée pour Invoquer Rituellement "Ruine, Reine de l''Oubli" ou "Peine, Roi de l''Armageddon". \r\nVous devez aussi Sacrifier des monstres depuis votre main ou Terrain dont le Niveau total est exactement égal au Niveau du Monstre Rituel que vous Invoquez Rituellement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8200556,'Myutant ST-46',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 Magie/Piège "Myutant" depuis votre Deck à votre main. \r\nVous pouvez Sacrifier cette carte, puis bannissez 1 carte depuis votre main ou Terrain face recto; Invoquez Spécialement 1 monstre depuis votre main ou Deck, selon la carte bannie.\r\n● Monstre: "Bête Myutant"\r\n● Magie: "Brume Myutant"\r\n● Piège: "Arsenal Myutant"\r\nVous ne pouvez utiliser chaque effet de "Myutant ST-46" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8201910,'Garçon-Étoile','Tant que cette carte reste face recto sur le Terrain, augmentez l''ATK de tous les monstres EAU de 500 points et diminuez l''ATK des monstres FEU de 400 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8226374,'Poupée Truquée Humpty Dumpty',replace(replace('Lorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez Invoquer Spécialement 1 monstre "Poupée Truquée" depuis votre main. \r\nVous ne pouvez utiliser cet effet de "Poupée Truquée Humpty Dumpty" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8233522,'Araneoïde, Allié de la Justice','(Effet Rapide): vous pouvez défausser cette carte au Cimetière, puis ciblez max. 2 monstres LUMIÈRE dans le Cimetière de votre adversaire; bannissez les cibles.','Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8240199,'Sage avec des Yeux de Bleu',replace(replace('Lorsque cette carte est Invoquée Normalement: vous pouvez ajouter 1 Syntoniseur LUMIÈRE de Niveau 1 ("Sage avec des Yeux de Bleu" exclu) depuis votre Deck à votre main. \r\nVous pouvez défausser cette carte, puis ciblez 1 Monstre à Effet que vous contrôlez; envoyez-le au Cimetière, et si vous le faites, Invoquez Spécialement 1 monstre "Yeux Bleus" depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Sage avec des Yeux de Bleu" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8243121,'Lyrilusc - Plumes Fantômes',replace(replace('Ciblez 1 monstre "Lyrilusc" que vous contrôlez; l''ATK de tous les monstres actuellement contrôlés par votre adversaire devient l''ATK actuelle du monstre, et aussi, leur Niveau/Rang devient 1. \r\nLorsqu''un monstre de l''adversaire déclare une attaque sur votre monstre "Lyrilusc": vous pouvez bannir cette carte depuis votre Cimetière; jusqu''à la fin de ce tour, l''ATK de votre monstre devient l''ATK du monstre de l''adversaire. \r\nVous ne pouvez utiliser chaque effet de "Lyrilusc - Plumes Fantômes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8251996,'Ouragan Ojama Delta !!','Si vous contrôlez "Ojama Vert", "Ojama Jaune" et "Ojama Noir": détruisez toutes les cartes contrôlées par votre adversaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8252010,'Gottoms, Sabre X',replace(replace('1 Syntoniseur + 1+ monstre TERRE	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez ajouter 1 Magie/Piège "Sabre" ou "Gottoms" depuis votre Deck à votre main. \r\nLorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez lui défausser 1 carte au hasard. \r\nLorsque votre monstre "Sabre X" est ciblé par une attaque tant que cette carte est dans votre Cimetière: vous pouvez Invoquer Spécialement cette carte, puis transférez la cible de l''attaque sur cette carte. \r\nVous ne pouvez utiliser chaque effet de "Gottoms, Sabre X" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Défausser 1 carte','Invocation Spéciale','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8264361,'Dharc la Charmeuse des Ténèbres Obscures',replace(replace('2 monstres (un monstre TÉNÈBRES inclus)	\r\n(Cette carte est toujours traitée comme carte "Familier Possédé".)	\r\nVous pouvez cibler 1 monstre TÉNÈBRES dans le Cimetière de votre adversaire; Invoquez-le Spécialement dans votre zone pointée par cette carte. \r\nSi cette carte Invoquée par Lien est détruite au combat, ou est détruite par un effet de carte de l''adversaire tant qu''elle est dans la Zone Monstre de son propriétaire: vous pouvez ajouter 1 monstre TÉNÈBRES avec max. 1500 DEF depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Dharc la Charmeuse des Ténèbres Obscures" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8267140,'Cyclone Cosmique','Payez 1000 LP, puis ciblez 1 Magie/Piège sur le Terrain; bannissez-le.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8275702,'Promesse du Cristal','Ciblez 1 carte "Bête Cristalline" dans votre Zone Magie & Piège; Invoquez Spécialement la cible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8279188,'Amulette des Abysses',replace(replace('Lorsque le monstre de votre adversaire déclare une attaque, vous pouvez défausser 1 carte pour annuler l''attaque. \r\nDétruisez cette carte durant la 3ème End Phase de votre adversaire après son activation.','\r',char(13)),'\n',char(10)),'Utiliser l''effet de "Amulette des Abysses" maintenant ?','Annuler l''attaque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8284390,'Avion Élastique Vitesseroid',replace(replace('Si un monstre est Invoqué Spécialement sur votre Terrain (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres VENT exclus) le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Avion Élastique Vitesseroid" qu''une fois par tour. \r\nSi cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 monstre face recto sur le Terrain; jusqu''à la fin de ce tour, il perd 600 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8310162,'Dragon Paradoxe Corrompu',replace(replace('"Rouage Dimensionnel Corrompu" + 1 monstre "Corrompu" non Syntoniseur	\r\nLorsque cette carte est Invoquée par Synchronisation, vous pouvez sélectionner 1 Monstre Synchro dans l''un des Cimetières et l''Invoquer Spécialement. \r\nIl ne peut y avoir qu''1 seul "Dragon Paradoxe Corrompu" face recto sur le Terrain. \r\nSi "Monde Corrompu" n''est pas face recto sur le Terrain, détruisez cette carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8315896,'Candelato, le Monstre de Lumière',replace(replace('(Cette carte est toujours traitée comme carte "Bête Fantôme".)	\r\nGagne 1000 ATK/DEF pour chaque carte dans votre main.\r\nVous ne pouvez utiliser chacun des effets suivants de "Candelato, le Monstre de Lumière" qu''une fois par tour.\r\nVous pouvez défausser 2 autres cartes; Invoquez Spécialement cette carte depuis votre main, puis vous pouvez ajouter 1 carte depuis votre Deck à votre main qui a un effet de lancer de pièce.\r\nLorsqu''une carte ou un effet qui inclut un effet qui ajoute une ou plusieurs cartes depuis le Deck à la main est activé (Effet Rapide): vous pouvez annuler l''effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Annuler','Ajouter à la main?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8316565,'Choc du Contre','Durant la Battle Phase, lorsqu''une Carte Magie/Piège ou un effet de monstre est activé tant que vous contrôlez un monstre "Boxeur Indomptable": annulez l''activation, et si vous le faites, détruisez la carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8316661,'Miztoji Mythologique','Vous pouvez envoyer cette carte depuis votre main au Cimetière, puis ciblez 1 monstre non-Syntoniseur "Mythologique" que vous contrôlez; le monstre est traité comme un Syntoniseur tant qu''il est face recto sur le Terrain.','Choisissez 1 monstre à utiliser comme Syntoniseur','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8321183,'Retour Bête Spirituelle','Bannissez 1 monstre "Bête Spirituelle" depuis votre main, puis ciblez 1 de vos monstres "Bête Spirituelle" bannis ou dans votre Cimetière; Invoquez-le Spécialement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8323633,'Espionnage',replace(replace('Déclarez 1 nom de Carte Monstre. \r\nSi votre adversaire fait l''Invocation Normale, l''Invocation Spéciale ou l''Invocation Flip d''un (ou plusieurs) de ce(s) monstre(s) face recto, retirez ce(s) monstre(s) et cette carte du jeu.','\r',char(13)),'\n',char(10)),'Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8324284,'Bouclier Spirituel',replace(replace('Une fois par combat, lorsqu''un monstre de l''adversaire déclare une attaque: vous pouvez bannir 1 monstre Démon ou Zombie depuis votre Cimetière; annulez l''attaque. \r\nUne fois par tour, lorsque votre adversaire active une carte ou un effet qui va détruire une ou plusieurs cartes: vous pouvez bannir 1 monstre Démon ou Zombie depuis votre Cimetière; annulez l''activation. \r\nUne fois par tour, durant la End Phase, si vous ne contrôlez aucun monstre Démon ou Zombie: envoyez cette carte au Cimetière.','\r',char(13)),'\n',char(10)),'Annuler l''attaque','Annuler l''activation','Envoyer au Cimetière','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8327462,'Oiseau-crâne','"Takuhee" + "Temple des Crânes"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8339504,'Transfert Xyz',replace(replace('Sacrifiez 1 Monstre Xyz; Invoquez Spécialement 1 monstre du même Type, Attribut et Rang que le monstre Sacrifié avait sur le Terrain, mais de nom différent, depuis votre Extra Deck, et si vous le faites, attachez-lui cette carte comme Matériel Xyz. \r\nDurant la End Phase, envoyez-le au Cimetière. \r\nVous ne pouvez activer qu''1 "Transfert Xyz" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8353769,'Mangeur d''air','Monstre qui se nourrit d''oxygène en étouffant ceux qui l''entourent.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8372133,'Familier Rouge',replace(replace('Vous pouvez Sacrifier 1 monstre Démon, puis ciblez 1 Monstre Synchro TÉNÈBRES Dragon dans votre Cimetière; Invoquez-le Spécialement en Position de Défense, mais annulez ses effets. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Monstre Synchro TÉNÈBRES Dragon que vous contrôlez et déclarez un Niveau de 1 et 8; jusqu''à la fin de ce tour, le monstre devient de ce Niveau. \r\nVous ne pouvez utiliser chaque effet de "Familier Rouge" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Choisissez le Niveau à changer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8379983,'Lionne Dorée de Clair de Lune',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 monstre "Clair de Lune" ("Lionne Dorée de Clair de Lune" exclu) depuis votre Deck à votre main, puis défaussez 1 carte. \r\nSi un ou plusieurs monstres "Clair de Lune" sont envoyés à votre Cimetière, tant que cette carte est dans votre Zone Monstre, même durant la Damage Step: vous pouvez en cibler 1; ajoutez-le à votre main. \r\nVous ne pouvez utiliser chaque effet de "Lionne Dorée de Clair de Lune" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Recycler','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8384771,'Gumgumouton Potartiste',replace(replace('Échelle Pendule = 1\r\n[ Effet Pendule ]\r\nUne fois par tour, lorsqu''une attaque impliquant un monstre que vous contrôlez et un monstre de votre adversaire est déclarée: vous pouvez activer cet effet; le monstre que vous contrôlez ne peut pas être détruit par ce combat.\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nUne fois par tour, lorsqu''une attaque impliquant un monstre que vous contrôlez et un monstre de votre adversaire est déclarée: vous pouvez activer cet effet; le monstre que vous contrôlez ne peut pas être détruit par ce combat.','\r',char(13)),'\n',char(10)),'Ne sera pas détruit par ce combat','Ne sera pas détruit par ce combat','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8387138,'Numéro 27 : Cuirassé Cuiranoid',replace(replace('2+ monstres de Niveau 4	\r\nÀ la fin de la Battle Phase, si cette carte a détruit un monstre de l''adversaire au combat: vous pouvez Invoquer Spécialement 1 Monstre Xyz Machine de min. Rang 10 depuis votre Extra Deck, en utilisant cette carte face recto que vous contrôlez comme Matériel. \r\n(Ceci est traité comme Invocation Xyz. Transférez ses Matériels au monstre Invoqué.) \r\nVous ne pouvez utiliser cet effet de "Numéro 27 : Cuirassé Cuiranoid" qu''une fois par tour. \r\nSi cette carte face recto sur le Terrain va être détruite au combat ou par un effet de carte, vous pouvez détacher 1 Matériel de cette carte à la place.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8396952,'Force Arcane I - Le Magicien',replace(replace('Lorsque cette carte est Invoquée, lancez une pièce:\r\n● Face: Lorsqu''une Carte Magie est activée, l''ATK de cette carte devient le double de son ATK d''origine jusqu''à la End Phase de ce tour.\r\n● Pile: Lorsqu''une Carte Magie est activée, votre adversaire augmente ses Life Points de 500 points.','\r',char(13)),'\n',char(10)),'Lancer une pièce','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8400623,'Ananta, Dragon Maléfique',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement en bannissant tous les monstres Reptile que vous contrôlez et dans votre Cimetière. \r\nL''ATK/DEF de cette carte deviennent le nombre de monstres bannis pour son Invocation Spéciale x 600. \r\nUne fois par tour, durant votre End Phase: ciblez 1 carte sur le Terrain; détruisez la cible.','\r',char(13)),'\n',char(10)),'Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8414337,'Tempête de Poussières Gusto','Votre adversaire ne peut ni activer de cartes ni d''effets lorsque des monstres "Gusto" que vous contrôlez déclarent leurs attaques ce tour.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8428836,'Rituel des Enfers de la Prédiction',replace(replace('Cette carte est utilisée pour Invoquer Rituellement un Monstre Rituel "Princesse de la Prédiction" depuis votre main ou Cimetière en Position d''Attaque face recto ou Position de Défense face verso. \r\nVous devez aussi Sacrifier des monstres depuis votre main ou Terrain, dont le Niveau total est supérieur ou égal au Niveau du Monstre Rituel que vous Invoquez Rituellement. \r\nDurant la Standby Phase, si vous contrôlez un Monstre Rituel "Princesse de la Prédiction": vous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 monstre non-Rituel "Princesse de la Prédiction" depuis votre Deck en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8437145,'Prophète du Vide',replace(replace('Ciblez 1 monstre "Infernoid" que vous contrôlez; ce tour, la cible n''est pas affectée par des effets de carte de votre adversaire. \r\nSi un ou plusieurs monstres "Infernoid" que vous contrôlez vont être détruits par un effet de carte, vous pouvez bannir cette carte depuis votre Cimetière au lieu de détruire 1 de ces monstres.','\r',char(13)),'\n',char(10)),'Bannir "Prophète du Vide" depuis votre Cimetière à la place ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8445808,'Jeune Fille Amoureuse',replace(replace('Les monstres contrôlés par votre adversaire qui peuvent attaquer doivent attaquer cette carte. \r\nNon destructible au combat. À la fin de la Damage Step, si cette carte a combattu un monstre de l''adversaire: vous pouvez activer 1 de ces effets;\r\n● Placez 1 Compteur Jeune Fille sur 1 monstre face recto contrôlé par votre adversaire.\r\n● Prenez le contrôle d''1 monstre contrôlé par votre adversaire avec un Compteur Jeune Fille.','\r',char(13)),'\n',char(10)),'','','Activer','Placer un marqueur','Prendre le contrôle','','','','','','','','','','','');
INSERT INTO texts VALUES(8454126,'Contrôleuse de Nephtys',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Réincarnation de Nephtys". \r\nSi cette carte est Invoquée Rituellement: vous pouvez Invoquer Spécialement 1 Monstre Rituel "Nephtys" ("Contrôleuse de Nephtys" exclu) depuis votre main ou Deck (ceci est traité comme une Invocation Rituelle). \r\nSi cette carte est Sacrifiée ou détruite par un effet de carte "Nephtys": vous pouvez activer cet effet; durant la prochaine Standby Phase, détruisez max. 3 cartes "Nephtys" (Monstres Rituels exclus), 1 depuis votre main, 1 depuis votre Deck et 1 depuis votre Terrain. \r\nVous ne pouvez utiliser chaque effet de "Contrôleuse de Nephtys" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8463720,'D/D/D Beowulf, Roi du Fléau des Dragons',replace(replace('1 monstre "D/D/D" + 1 monstre "D/D"	\r\nSi un monstre "D/D" que vous contrôlez attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire. \r\nUne fois par tour, durant votre Standby Phase: vous pouvez détruire toutes les cartes dans les Zones Magie & Piège.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8471389,'Loup Giga-Tech','Ce loup de métal transperce n''importe quelle armure de ses crocs aiguisés.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8483333,'Manticore Mosaïque',replace(replace('Durant la Standby Phase de votre prochain tour après que vous avez Invoqué par Sacrifice cette carte face recto sur le Terrain: Invoquez Spécialement autant de monstres ayant été utilisés pour son Invocation par Sacrifice que possible depuis le Cimetière. \r\nIls ne peuvent pas déclarer d''attaque et leurs effets sont annulés.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8487449,'Bouffon Équilibriste',replace(replace('Vous ne pouvez contrôler qu''1 "Bouffon Équilibriste". \r\nVous pouvez Invoquer Spécialement cette carte (depuis votre main) en Position d''Attaque. \r\nSi elle est Invoquée de cette façon, durant la prochaine End Phase de votre adversaire: ciblez 1 monstre face recto contrôlé par votre adversaire; renvoyez la cible ainsi que cette carte face recto à la main.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491308,'Assaut de l''Air - As - Hayaté',replace(replace('1 monstre "Assaut de l''Air - As" non-VENT	\r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Assaut de l''Air - As - Hayaté" qu''une fois par tour. \r\nPeut attaquer directement. \r\nAprès le calcul des dommages, si cette carte a combattu: vous pouvez envoyer 1 carte "Assaut de l''Air" depuis votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491309,'Assaut de l''Air - As - Hayaté',replace(replace('1 monstre "Assaut de l''Air - As" non-VENT	\r\nVous ne pouvez Invoquer Spécialement un ou plusieurs "Assaut de l''Air - As - Hayaté" qu''une fois par tour. \r\nPeut attaquer directement. \r\nAprès le calcul des dommages, si cette carte a combattu: vous pouvez envoyer 1 carte "Assaut de l''Air" depuis votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491961,'Lyrilusc - Récital Sturnidé',replace(replace('2+ monstres de Niveau 1	\r\nSi cette carte est Invoquée par Xyz: vous pouvez cibler 1 monstre face recto sur le Terrain; il gagne 300 ATK/DEF pour chaque Matériel attaché à cette carte. \r\nUne fois par tour: vous pouvez détacher 1 Matériel de cette carte; ajoutez 1 monstre Bête Ailée de Niveau 1 depuis votre Deck à votre main. \r\nTous les dommages de combat que vous recevez de combats impliquant cette carte Invoquée par Xyz sont aussi infligés à votre adversaire.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','Chercher dans le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8495780,'Artisan des Profondeurs',replace(replace('Si cette carte est ajoutée depuis le Deck ou Cimetière à votre main par un effet de monstre EAU: vous pouvez révéler cette carte; regardez la main de votre adversaire. \r\nSi cette carte est Invoquée Spécialement: vous pouvez envoyer la carte du dessus de votre Deck au Cimetière, puis ciblez 1 monstre EAU de max. Niveau 4 ("Artisan des Profondeurs" exclu) dans votre Cimetière; Invoquez-le Spécialement, mais annulez ses effets. \r\nVous ne pouvez utiliser chaque effet de "Artisan des Profondeurs" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8505920,'Association du Gardien de la Porte',replace(replace('"Sanga du Tonnerre" + "Kazejin" + "Suijin"	\r\nUniquement Invocable Spécialement (depuis votre Extra Deck) en bannissant les cartes ci-dessus depuis votre main, Terrain et/ou Cimetière. \r\nLorsque votre adversaire active une carte ou un effet qui cible une ou plusieurs cartes que vous contrôlez (Effet Rapide): vous pouvez annuler l''effet, et si vous le faites, détruisez la carte. \r\nVous ne pouvez utiliser cet effet de "Association du Gardien de la Porte" que trois fois par tour. \r\nSi cette carte face recto Invoquée Spécialement contrôlée par son propriétaire quitte le Terrain à cause d''une carte de l''adversaire: vous pouvez Invoquer Spécialement 1 monstre "Gardien de la Porte" de max. Niveau 11 depuis votre Deck ou Extra Deck, en ignorant ses conditions d''Invocation.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8508055,'Chu-Suke, Le Guerrier Rongeur','Guerrier sans peur arpentant le globe pour devenir le meilleur guerrier du monde des rongeurs. Soyez prudent en l''approchant de peur qu''il ne vous ratatine.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8512558,'Onomatopée Utopique',replace(replace('(Cette carte est toujours traitée comme carte "Zubaba", "Gagaga", "Gogogo" et "Dododo".)	\r\nDurant votre Main Phase: vous pouvez Invoquer Spécialement max. 1 monstre "Zubaba", max. 1 monstre "Gagaga", max. 1 monstre "Gogogo" et/ou max. 1 monstre "Dododo" ("Onomatopée Utopique" exclu) depuis votre main en Position de Défense, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Xyz exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Onomatopée Utopique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8522996,'Le Premier Monarque',replace(replace('Invoquez Spécialement cette carte comme un Monstre à Effet (Démon/TÉNÈBRES/Niveau 6/ATK 1000/DEF 2400).	\r\n(Cette carte est toujours aussi un Piège.) \r\nSi elle est Invoquée de cette façon: vous pouvez défausser 1 carte, puis déclarez 1 Attribut; cette carte devient de cet Attribut, et elle peut être traitée comme 2 Sacrifices pour l''Invocation Sacrifice d''un monstre de même Attribut que cette carte. \r\nSi cette carte est Invoquée de cette façon, vous ne pouvez pas Invoquer Spécialement de monstres (monstres de même Attribut que cette carte exclus).','\r',char(13)),'\n',char(10)),'Changer l''Attribut','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8529136,'Poing de Ferraille',replace(replace('Ciblez 1 "Robot Guerrier" que vous contrôlez; s''il combat un monstre de l''adversaire ce tour tant que vous le contrôlez, appliquez ces effets.\r\n● Jusqu''à la fin de la Damage Step, votre adversaire ne peut activer ni de cartes ni d''effets.\r\n● S''il attaque un monstre en Position de Défense, infligez des dommages de combat perçants à votre adversaire.\r\n● Doublez les dommages de combat reçus par votre adversaire.\r\n● Il ne peut pas être détruit au combat.\r\n● À la fin de la Damage Step, détruisez le monstre de l''adversaire qui l''a combattu.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8540986,'Veidos le Dragon des Ténèbres Infinies',replace(replace('"Veidos le Dragon Éruption de l''Extinction" + 2+ monstres Pyro de max. Niveau 9	\r\nNon destructible par des effets de carte, et aussi, votre adversaire ne peut pas la cibler avec des effets de monstre. \r\nSi cette carte est Invoquée par Fusion: vous pouvez détruire toutes les Magies et tous les Pièges contrôlés par votre adversaire. \r\nLorsque votre adversaire active une carte ou un effet sur le Terrain (Effet Rapide): vous pouvez envoyer 1 carte "Cendré" face recto que vous contrôlez au Cimetière; détruisez la carte. \r\nVous ne pouvez utiliser cet effet de "Veidos le Dragon des Ténèbres Infinies" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Détruire une Carte Magie/Piège','Détruire la carte qui a activé son effet','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8559524,'Ordre du Diapason',replace(replace('Défaussez 1 monstre "Diapason"; ajoutez 1 monstre Démon de max. Niveau 4 depuis votre Deck à votre main. \r\nVous ne pouvez activer qu''1 "Ordre du Diapason" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8559793,'Raidraptor - Nid',replace(replace('Si vous contrôlez min. 2 monstres "Raidraptor": vous pouvez ajouter 1 monstre "Raidraptor" depuis votre Deck ou Cimetière à votre main. \r\nVous ne pouvez utiliser cet effet de "Raidraptor - Nid" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8561192,'Léo, le Garde de l''Arbre Sacré',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nVotre adversaire ne peut pas cibler cette carte avec des effets de carte, sauf durant votre Main Phase 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8567955,'Seigneur Répartiteur',replace(replace('Une fois par tour: vous pouvez payer 1000 LP; durant votre Main Phase ce tour, vous pouvez Invoquer Normalement 1 monstre Cyberse en plus de votre Invocation/Pose Normale. \r\n(Vous ne pouvez gagner cet effet qu''une fois par tour.) \r\nSi cette carte est bannie: vous pouvez Invoquer Spécialement 1 monstre de max. Niveau 4 depuis votre main. \r\nVous ne pouvez utiliser cet effet de "Seigneur Répartiteur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Invoquer par l''effet de "Seigneur Répartiteur"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8571567,'Aile Noire - Shamal la Tempête de Sable',replace(replace('Vous pouvez envoyer cette carte depuis votre main ou Terrain au Cimetière; placez face recto 1 "Tourbillon Plume Noire" depuis votre Deck dans votre Zone Magie & Piège. \r\nSi "Dragon Ailes Sombres" ou un ou plusieurs Monstres Synchro "Aile Noire" sont Invoqués Spécialement sur votre Terrain, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez bannir cette carte, puis ciblez 1 monstre "Aile Noire" dans votre Cimetière; ajoutez-le à votre main, puis recevez 700 points de dommages. \r\nVous ne pouvez utiliser chaque effet de "Aile Noire - Shamal la Tempête de Sable" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8576764,'Reptauphin Greethys Gourmand',replace(replace('Vous pouvez cibler 1 monstre Poisson, Serpent de Mer ou Aqua dans votre Cimetière avec un Niveau inférieur ou égal au nombre de cartes dans la main de votre adversaire; Invoquez-le Spécialement, mais il ne peut pas activer ses effets ce tour. \r\nVous ne pouvez utiliser cet effet de "Reptauphin Greethys Gourmand" qu''une fois par tour. \r\nSi cette carte est envoyée au Cimetière comme Matériel Synchro: vous pouvez faire gagner 200 ATK/DEF au Monstre Synchro qui a été utilisé cette carte comme Matériel pour chaque carte actuellement dans la main de votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8581705,'Reine Infernale - Archdémon',replace(replace('Une fois par tour, durant votre Standby Phase, vous devez payer 500 LP (ceci est obligatoire), ou cette carte est détruite. \r\nLors de la résolution d''un effet de carte de l''adversaire qui cible cette carte, lancez un dé à six faces et annulez l''effet si le résultat est 2 ou 5, et si vous le faites, détruisez la carte. \r\nUne fois par tour, durant la Standby Phase: ciblez 1 monstre "Archdémon" sur le Terrain; jusqu''à la fin de ce tour, il gagne 1000 ATK.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8593259,'Bloqueur Clay, HÉROS Élémentaire',replace(replace('1 monstre "HÉROS Élémentaire" + 1 monstre Guerrier	\r\nSi cette carte est Invoquée Spécialement: vous pouvez Invoquer Spécialement 1 monstre "HÉROS Élémentaire" depuis votre Deck, puis si votre adversaire contrôle une carte, vous pouvez infliger 400 points de dommages à votre adversaire pour chacune, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres "HÉROS" exclus) depuis l''Extra Deck le reste de ce tour.\r\nVous ne pouvez utiliser cet effet de "Bloqueur Clay, HÉROS Élémentaire" qu''une fois par tour.\r\nLes autres monstres "HÉROS Élémentaire" que vous contrôlez ne peuvent être détruits ni au combat ni par des effets de carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Infliger des dommages ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8594079,'Brachiosaurus Préhistorique','Tant qu''un autre monstre "Préhistorique" face recto est sur le Terrain, cette carte ne peut pas être détruite au combat.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8602351,'Échidné Reptilia',replace(replace('2 monstres (un monstre Reptile inclus)	\r\nSi cette carte est Invoquée par Lien: vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; changez son ATK à 0. \r\nDurant votre Main Phase, si votre adversaire contrôle un ou plusieurs monstres avec 0 ATK: vous pouvez ajouter un nombre de monstres Reptile de noms différents depuis votre Deck à votre main, inférieur ou égal au nombre de monstres contrôlés par votre adversaire avec 0 ATK, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Reptile exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Échidné Reptilia" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8608979,'Union de la Super Équipe de la Force des Potes !',replace(replace('Ciblez 1 monstre face recto sur le Terrain; Invoquez Spécialement 1 monstre depuis votre main ou Cimetière du même Type d''origine que celui du monstre, mais de nom d''origine différent. \r\nSi cette carte dans la Zone Magie & Piège de son propriétaire est détruite par un effet de carte de l''adversaire: vous pouvez Poser 1 "Union de la Super Équipe de la Force des Potes !" directement depuis votre Deck dans votre Zone Magie & Piège.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8611007,'Dragun Lavalval',replace(replace('1 Syntoniseur + 1 monstre non-Syntoniseur FEU ou plus	\r\nUne fois par tour: vous pouvez ajouter 1 monstre "Laval" depuis votre Deck à votre main, puis envoyez 1 monstre "Laval" depuis votre main au Cimetière.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8617563,'Raidraptor - Strix Courageuse',replace(replace('2 monstres de Niveau 5	\r\nUn Monstre Xyz "Raidraptor" qui a cette carte comme Matériel gagne cet effet.\r\n● Cette carte gagne une ATK égale à son Rang x 100.	\r\nVous ne pouvez utiliser qu''1 des effets suivants de "Raidraptor - Strix Courageuse" par tour, et uniquement une fois le tour. \r\nVous pouvez détacher 1 Matériel de cette carte; Posez 1 Magie/Piège "Raidraptor" depuis votre Deck. \r\nSi cette carte a un monstre Bête Ailée comme Matériel: vous pouvez détacher 1 Matériel de cette carte; ajoutez 1 Magie "Magie-Rang-Plus" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Poser','Ajouter à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8628798,'Dynamite D.D.','Infligez 300 points de dommages aux Life Points de votre adversaire pour chacune de ses cartes retirée du jeu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8632967,'Évokarma','Lorsqu''un ou plusieurs monstres sont Invoqués Spécialement par l''effet d''un monstre "Évoltile" que vous contrôlez, votre adversaire ne peut ni activer de cartes ni d''effets.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8633261,'Int Ryzéal',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en envoyant 1 carte depuis votre main ou Terrain au Cimetière. \r\nSi elle est Invoquée de cette façon, vous ne pouvez pas Invoquer Spécialement (Monstres Xyz de Rang 4 exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez Invoquer Spécialement "Int Ryzéal" qu''une fois par tour de cette façon. \r\nSi cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre "Ryzéal" ("Int Ryzéal" exclu) depuis votre Deck. \r\nVous ne pouvez utiliser cet effet de "Int Ryzéal" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invoquer Spécialement depuis le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8634636,'Chat Noir à Queue Blanche','FLIP: Retournez 2 Cartes Monstre sur le Terrain de votre adversaire et 1 Carte Monstre sur votre Terrain dans la main de leur propriétaire.','Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8643186,'D/D Recrues',replace(replace('Si votre adversaire contrôle plus de monstres que vous: ciblez un nombre de votre choix de monstres "D/D" et/ou cartes "Contrat des Ténèbres" dans votre Cimetière, inférieur ou égal à la différence; ajoutez ces cartes à votre main. \r\nVous ne pouvez activer qu''1 "D/D Recrues" par tour.','\r',char(13)),'\n',char(10)),'Récupérer des cartes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8649148,'Balayeur des Profondeurs','Vous pouvez Sacrifier cette carte, puis ciblez 1 Carte Magie/Piège sur le Terrain; détruisez la cible.','Détruire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8653757,'Arrêt du Temps Photon',replace(replace('Prenez 1 Magie Continue/Piège Continu "Photon" ou "Galactique" depuis votre Deck, et soit ajoutez-le à votre main soit placez-le face recto sur votre Terrain. \r\nSi cette carte Posée contrôlée par son propriétaire est détruite par un effet de carte de votre adversaire durant le tour de votre adversaire et que vous contrôlez "Dragon Photon aux Yeux Galactiques" ou un Monstre Xyz qui l''a comme Matériel: vous pouvez activer cet effet; passez à la End Phase de ce tour.','\r',char(13)),'\n',char(10)),'','Placer face recto','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8660395,'Ninaruru, Déesse de Verre Magistus',replace(replace('2 monstres Magicien de Niveau 4	\r\nTant que cette carte est une Carte d''Équipement, le monstre équipé peut faire max. 2 attaques sur des monstres durant chaque Battle Phase. \r\nVous ne pouvez utiliser chacun des effets suivants de "Ninaruru, Déesse de Verre Magistus" qu''une fois par tour. \r\nVous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre Magicien de min. Niveau 4 dans votre Cimetière; ajoutez-le à votre main. \r\nTant que cette carte est équipée à un monstre: vous pouvez cibler 1 carte "Magistus" dans votre Zone Magie & Piège et 1 Magie/Piège contrôlé par votre adversaire; détruisez-les.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8662794,'Brisecodeur Zero Day',replace(replace('Les Monstres Lien qui pointent cette carte (Monstres Lien "Brisecodeur" exclus) perdent 1000 ATK. \r\nSi un ou plusieurs Monstres Lien "Brisecodeur" sur le Terrain sont détruits au combat ou par un effet de carte, tant que cette carte est sur le Terrain: détruisez cette carte. \r\nSi cette carte est détruite au combat ou par un effet de carte: vous pouvez ajouter 1 "Brisecodeur Zero Day" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8687195,'Lutin Onirique','Lorsque cette carte est attaquée par un monstre de votre adversaire, sélectionnez 1 autre monstre sur votre Terrain et désignez-le comme cible de l''attaque, puis calculez les dommages.','Remplacement de combat','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8690387,'Esprit de la Terre Servant Géo Gremlin',replace(replace('1 Syntoniseur TÉNÈBRES + 1+ monstre non-Syntoniseur	\r\nDurant la Main Phase (Effet Rapide): vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; votre adversaire choisit 1 de ces effets pour vous à appliquer.\r\n● Détruisez le monstre.\r\n● Gagnez des LP égaux à l''ATK du monstre.	\r\nDurant la Battle Phase (Effet Rapide): vous pouvez Invoquer par Fusion 1 Monstre Fusion "Esprit de la Terre" depuis votre Extra Deck, en bannissant ses Matériels depuis votre main, Terrain et/ou Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Esprit de la Terre Servant Géo Gremlin" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Détruire ce monstre','Votre adversaire gagne des LP égaux à l''ATK de ce monstre','','','','','','','','','','','','');
INSERT INTO texts VALUES(8692301,'Zircone, Chevalier-Gemmes','1 monstre "Chevalier-Gemmes" + 1 monstre Rocher','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8696773,'Hydre Flamme Chimérique',replace(replace('Votre adversaire ne peut pas cibler cette carte avec des effets de carte. \r\nVous ne pouvez pas Invoquer Spécialement de monstres (monstres FEU exclus). \r\nUn Monstre Xyz qui a été Invoqué en utilisant cette carte comme Matériel Xyz gagne cet effet.\r\n● Lorsqu''il est Invoqué par Xyz: vous pouvez cibler 1 monstre "Flamme Chimérique" dans votre Cimetière; attachez la cible à cette carte comme Matériel Xyz.','\r',char(13)),'\n',char(10)),'Attacher du Matériel','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8698851,'Contre Attaque D','Lorsqu''un monstre "HÉROS de la Destinée" face recto que vous contrôlez est ciblé par une attaque: détruisez le monstre attaquant.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8700633,'Bête Rustre Téméraire',replace(replace('Durant la Main Phase, si votre adversaire Invoque Spécialement min. 3 monstres ce tour (Effet Rapide): vous pouvez Invoquer Spécialement cette carte depuis votre main ou Cimetière. \r\nVous ne pouvez utiliser cet effet de "Bête Rustre Téméraire" qu''une fois par tour. \r\nTant que vous ne contrôlez aucun autre monstre, cette carte en Position d''Attaque ne peut pas être détruite au combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8706701,'Miroir Rouge',replace(replace('Lorsqu''un monstre de votre adversaire déclare une attaque: vous pouvez envoyer cette carte depuis votre main au Cimetière, puis ciblez 1 monstre FEU de Type Démon ("Miroir Rouge" exclu) dans votre Cimetière; ajoutez-le à votre main. \r\nSi vous Invoquez par Synchronisation tant que cette carte est dans votre Cimetière (sauf durant la Damage Step ou le tour où cette carte a été envoyée au Cimetière): vous pouvez ajouter cette carte à votre main. \r\nVous ne pouvez utiliser chaque effet de "Miroir Rouge" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8715625,'Bokoichi, le Wagon de Terreur','Un wagon terrifiant à l''usage exclusif de Dekoichi, capable de tout transporter, mais dont peu de marchandises arrivent indemnes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8719957,'Écaille-Abysses de Kraken',replace(replace('Équipable uniquement à un monstre "Sirènemure". \r\nIl gagne 400 ATK. \r\nLorsqu''un effet de monstre qui a été activé sur le Terrain de votre adversaire est résolu, annulez l''effet, puis envoyez cette carte au Cimetière.','\r',char(13)),'\n',char(10)),'Annuler l''effet','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8728498,'Donner, Dague Mercefourrure',replace(replace('2 monstres de Types différents	\r\nVous pouvez cibler 1 monstre "Mercefourrure" que vous contrôlez et 1 monstre contrôlé par votre adversaire; détruisez-les. \r\nVous pouvez Sacrifier 1 monstre; Invoquez Spécialement 1 monstre "Mercefourrure" depuis votre main ou Cimetière de nom d''origine différent du monstre Sacrifié, puis, si vous avez Sacrifié un Monstre Lien pour activer cet effet, vous pouvez Invoquer Spécialement 1 tel monstre en plus. \r\nVous ne pouvez utiliser qu''1 effet de "Donner, Dague Mercefourrure" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Détruire les deux monstres','Invocation Spéciale','Choisir un autre monstre à Invoquer Spécialement ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8730435,'Bouclier de Combat Archdémon des Bêtes Gladiateurs',replace(replace('Équipable uniquement à un monstre "Bête Gladiateur". \r\nSi le monstre équipé va être détruit, détruisez cette carte à la place. \r\nLorsque cette carte est envoyée à votre Cimetière parce que le monstre équipé que vous contrôliez a été mélangé dans votre Deck: renvoyez cette carte à votre main.','\r',char(13)),'\n',char(10)),'Renvoyer à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8736823,'Hime du Monde Virtuel - Nyannyan',replace(replace('Si un ou plusieurs monstres de Niveau 3 sont Invoqués Normalement ou Spécialement sur votre Terrain, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte comme un Syntoniseur, mais bannissez-la lorsqu''elle quitte le Terrain, et aussi, vous ne pouvez Invoquer Spécialement que des monstres de min. Niveau/Rang 3 le reste de ce tour. \r\nSi cette carte est bannie: vous pouvez cibler 1 de vos autres cartes bannies; mélangez-la dans le Deck. \r\nVous ne pouvez utiliser chaque effet de "Hime du Monde Virtuel - Nyannyan" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8763963,'Beelzeus des Dragons Diaboliques',replace(replace('1 Syntoniseur TÉNÈBRES + 2+ monstres non-Syntoniseur	\r\nNon destructible ni au combat ni par des effets de carte. \r\nLes autres monstres que vous contrôlez ne peuvent pas attaquer. \r\nUne fois par tour: vous pouvez cibler 1 monstre contrôlé par votre adversaire; les dommages de combat reçus par votre adversaire d''attaques impliquant cette carte ce tour sont divisés par deux, et aussi, changez l''ATK du monstre à 0, et si vous le faites, gagnez des LP égaux à son ATK d''origine.','\r',char(13)),'\n',char(10)),'Absorber l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8775395,'Déchaînement de l''Œil Maléfique',replace(replace('Envoyez 1 monstre "Œil Maléfique" et 1 Magie/Piège "Œil Maléfique" depuis votre Deck au Cimetière; ajoutez 1 Magie d''Équipement "Œil Maléfique" depuis votre Deck à votre main, mais le reste de ce tour, chaque fois que vous activez une carte ou effet non-"Œil Maléfique", vous perdez 500 LP. \r\nSi vous Invoquez par Lien un Monstre Lien "Œil Maléfique": vous pouvez bannir cette carte depuis votre Cimetière; équipez 1 Magie d''Équipement "Œil Maléfique" depuis votre Cimetière à 1 Monstre Lien "Œil Maléfique" que vous contrôlez. \r\nVous ne pouvez utiliser chaque effet de "Déchaînement de l''Œil Maléfique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8778267,'Fusion Perçante',replace(replace('Ce tour, si un ou plusieurs monstres ont été détruits au combat: Invoquez par Fusion 1 Monstre Fusion depuis votre Extra Deck, en utilisant des monstres depuis votre main ou Terrain, et si vous le faites, il gagne cet effet.\r\n● (Effet Rapide): vous pouvez Sacrifier cette carte, puis ciblez 1 monstre face recto que vous contrôlez; il gagne 500 ATK.	\r\nVous ne pouvez activer qu''1 "Fusion Perçante" par tour.','\r',char(13)),'\n',char(10)),'Activer','L''effet de "Fusion Perçante" est actuellement appliqué.','Augmenter l''ATK (Fusion Perçante)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8783685,'Sablier de Vie','Cette créature offre la puissance au lieu de réduire la vie.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8785161,'Raidraptor - Vautour Sauvage','Durant votre Main Phase, si cette carte a été Invoquée Normalement ou Spécialement ce tour: vous pouvez Sacrifier cette carte; Invoquez Spécialement 2 monstres "Raidraptor" depuis votre main et/ou Cimetière dont le Niveau total est égal à 6.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8794055,'Les Plus Lointaines Profondes Limites',replace(replace('Tant que vous contrôlez un Monstre Synchro Poisson, cette carte ne peut être ni détruite ni bannie par des effets de carte. \r\nVous ne pouvez utiliser chacun des effets suivants de "Les Plus Lointaines Profondes Limites" qu''une fois par tour. \r\nVous pouvez bannir 1 monstre Poisson depuis votre main ou Cimetière; ajoutez 1 monstre "Ghoti" depuis votre Deck à votre main. \r\nSi un ou plusieurs monstres Poisson sont Invoqués Normalement ou Spécialement sur votre Terrain, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 monstre Poisson que vous contrôlez; bannissez-le, et si vous le faites, ajoutez cette carte à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8794435,'Maju Garzett','L''ATK de cette carte devient égale à la somme des ATK originales des 2 monstres que vous avez sacrifié pour l''Invocation Sacrifice de cette carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8802510,'Seigneur Structure-PSY Lambda',replace(replace('2 monstres (Jetons exclus)	\r\nVous pouvez activer les effets des monstres "Pièce Structure-PSY" dans votre main même tant que vous contrôlez un ou plusieurs monstres. \r\nSi un monstre Psychique face recto que vous contrôlez est banni face recto tant que vous contrôlez ce monstre (sauf durant la Damage Step): vous pouvez activer cet effet; durant la End Phase de ce tour, ajoutez 1 carte "Structure-PSY" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Seigneur Structure-PSY Lambda" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8805651,'Phuloch Mégalithe',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec une carte "Mégalithe". \r\nVous ne pouvez pas activer les effets suivants de "Phuloch Mégalithe" dans la même Chaîne. \r\nSi cette carte est Invoquée Rituellement: vous pouvez ajouter 1 carte "Mégalithe" depuis votre Cimetière à votre main. \r\nDurant la Main Phase (Effet Rapide): vous pouvez activer cet effet; Invoquez Rituellement 1 Monstre Rituel "Mégalithe" ("Phuloch Mégalithe" exclu) depuis votre Cimetière, en Sacrifiant des monstres (cette carte sur votre Terrain incluse) depuis votre main ou Terrain, dont la somme des Niveaux est supérieure ou égale à son Niveau. \r\nVous ne pouvez utiliser cet effet de "Phuloch Mégalithe" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Recycler','Invocation Rituel','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8806072,'Guerrier des Combos','Si une Chaîne (de 2 Blocks ou plus) se produit pendant votre Main Phase 1, cette carte peut attaquer deux fois durant la Battle Phase ce tour.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8809344,'Nyarla, Entité Éloignée',replace(replace('2 monstres de Niveau 4	\r\nLorsque cette carte est Invoquée par Xyz: vous pouvez défausser un nombre de votre choix de cartes; augmentez le Rang de cette carte du nombre de cartes défaussées. \r\nUne fois par tour, tant que cette carte a du Matériel Xyz: vous pouvez cibler 1 monstre dans votre Cimetière; détachez tous les Matériels de cette carte, et si vous le faites, attachez la cible à cette carte comme Matériel. \r\nLorsqu''un monstre est attaché par cet effet, le Type et Attribut de cette carte deviennent les mêmes que le Type et Attribut d''origine du monstre.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8814959,'Mandragora Colonie du Mal','Si votre adversaire contrôle plus de monstres que vous, vous pouvez Invoquer Spécialement cette carte (depuis votre main).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8820526,'Briseur en Argile Potartiste',replace(replace('Si cette carte Invoquée par Sacrifice combat un monstre de l''adversaire, durant le calcul des dommages: jusqu''à la fin de ce tour, vous pouvez faire perdre 500 ATK au monstre de l''adversaire pour chaque Monstre Pendule face recto actuellement dans votre Extra Deck. \r\nLorsque vous Invoquez par Pendulation min. 2 monstres en même temps tant que cette carte est dans votre Cimetière: vous pouvez ajouter cette carte depuis le Cimetière à votre main. \r\nVous ne pouvez utiliser chaque effet de "Briseur en Argile Potartiste" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8822710,'Porte Cosmique, Allié de la Justice','Si votre adversaire contrôle min. 2 monstres (un monstre LUMIÈRE inclus), vous pouvez Invoquer Spécialement cette carte (depuis votre main).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8836329,'Dragon de la Tempête Déchaînée - Beaufort IX',replace(replace('Vous pouvez Invoquer Rituellement cette carte avec "Souffle des Acclamations". \r\nLorsqu''un monstre de l''adversaire déclare une attaque directe: vous pouvez défausser cette carte; annulez l''attaque, et si vous le faites, annulez les effets du monstre. \r\n(Effet Rapide): vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire; renvoyez le monstre ainsi que cette carte à la main. \r\nVous ne pouvez utiliser chaque effet de "Dragon de la Tempête Déchaînée - Beaufort IX" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8837932,'Mandala Cubique',replace(replace('Si vous contrôlez un monstre "Cubique": activez cette carte en ciblant un nombre de votre choix de monstres qui sont dans le Cimetière de votre adversaire parce qu''ils ont été détruits et y ont été envoyés ce tour; Invoquez-les Spécialement sur le Terrain de votre adversaire, mais chacun d''eux devient ATK 0 et a 1 Compteur Cubique placé sur lui. \r\n(Les monstres avec un Compteur Cubique ne peuvent pas attaquer, et aussi, annulez leurs effets.) \r\nTant que votre adversaire contrôle un des monstres Invoqués par cet effet, annulez les effets de monstre activés par votre adversaire. \r\nLorsque le dernier de ces monstres quitte le Terrain, détruisez cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8841431,'Centur-Ion Primera Primus',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nNon destructible au combat, sauf s''il a été Invoqué Spécialement depuis l''Extra Deck. \r\nVous ne pouvez utiliser chacun des effets suivants de "Centur-Ion Primera Primus" qu''une fois par tour. \r\nSi cette carte est Invoquée par Synchronisation: vous pouvez ajouter 1 carte "Emblema" depuis votre Deck ou Cimetière à votre main, puis vous pouvez détruire 2 cartes (1 sur chaque Terrain). \r\nSi une ou plusieurs cartes "Centur-Ion" face recto que vous contrôlez quittent le Terrain par un effet de carte de l''adversaire, tant que cette carte est dans votre Cimetière (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte.','\r',char(13)),'\n',char(10)),'Ajouter à la main','Invocation Spéciale','Détruire la carte ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8842266,'Poison du Vieillard',replace(replace('Activez 1 de ces effets;\r\n● Gagnez 1200 LP.\r\n● Infligez 800 points de dommages à votre adversaire.','\r',char(13)),'\n',char(10)),'Gagnez 1200 LP','Infligez 800 points de dommages à votre adversaire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8843569,'Retour d''Ailes',replace(replace('Si tous les monstres que vous contrôlez sont des monstres Bête Ailée et que vous contrôlez min. 2 monstres de noms d''origine différents: payez 600 LP; piochez 2 cartes. \r\nVous ne pouvez activer qu''1 "Retour d''Ailes" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8852158,'Wendikuruhu Marionnette de l''Ombre Ree',replace(replace('1 monstre "Marionnette de l''Ombre" + 1 monstre VENT	\r\nDoit d''abord être Invoquée par Fusion. \r\n(Effet Rapide): vous pouvez changer un nombre de votre choix de monstres face verso sur le Terrain en Position de Défense face recto, puis, vous pouvez compter le nombre de monstres Flip parmi eux, et changez max. autant de monstres face recto sur le Terrain (les monstres changés exclus) en Position de Défense face verso. \r\nVous ne pouvez utiliser cet effet de "Wendikuruhu Marionnette de l''Ombre Ree" qu''une fois par tour. \r\nSi cette carte est envoyée au Cimetière: vous pouvez cibler 1 carte "Marionnette de l''Ombre" dans votre Cimetière; ajoutez-la à votre main.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense face recto','Ajouter à la main','Mettre un monstre en Position de Défense face verso ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8868767,'Dégime',replace(replace('Lancez un dé à six faces. \r\nAppliquez cet effet selon le tour.\r\n● Durant votre tour: bannissez un nombre de cartes depuis votre Cimetière égal au résultat.	\r\nPuis, si le résultat est 1, envoyez aussi 6 cartes du dessus de votre Deck au Cimetière.\r\n● Durant le tour de votre adversaire: envoyez un nombre de cartes du dessus de votre Deck au Cimetière égal au résultat.	\r\nPuis, si le résultat est 6, bannissez aussi 1 carte depuis votre Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8873112,'Chakram - Artéfact',replace(replace('Vous pouvez Poser cette carte depuis votre main dans votre Zone Magie & Piège comme une Carte Magie. \r\nDurant le tour de votre adversaire, si cette carte Posée dans la Zone Magie & Piège est détruite et envoyée à votre Cimetière: Invoquez-la Spécialement. \r\nDurant le tour de chaque joueur, lorsqu''une carte ou un effet qui va détruire une ou plusieurs Cartes Magie/Piège que vous contrôlez est activé, tant que cette carte est dans votre main: vous pouvez renvoyer 1 Carte Magie/Piège Posée que vous contrôlez à la main; Invoquez Spécialement cette carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8875971,'Éclaireur Séraphin Étoile','Lorsque cette carte est Invoquée Normalement: vous pouvez Invoquer Spécialement 1 monstre "Séraphin Étoile" depuis votre main.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8903700,'Démon Jinn, Juge des Rituels',replace(replace('Lorsque vous Invoquez Rituellement un monstre, vous pouvez bannir cette carte depuis votre Cimetière comme 1 des monstres requis pour l''Invocation Rituelle. \r\nSi un joueur Invoque Rituellement en utilisant cette carte, l''autre joueur ne peut pas Invoquer Spécialement tant que le monstre Invoqué Rituellement est face recto sur le Terrain.','\r',char(13)),'\n',char(10)),'L''effet de "Démon Jinn, Juge des Rituels" est actuellement appliqué.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8910240,'Papillon Rose',replace(replace('Durant votre Main Phase, vous pouvez Invoquer par Sacrifice 1 monstre de min. Niveau 7 en Position d''Attaque, en plus de votre Invocation/Pose Normale. \r\n(Vous ne pouvez gagner cet effet qu''une fois par tour.) \r\nTant que vous contrôlez un autre monstre Insecte, cette carte peut attaquer directement.','\r',char(13)),'\n',char(10)),'Invoquer par Sacrifice grâce à l''effet de "Papillon Rose"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8910971,'Seigneur Gaïa le Chevalier Implacable',replace(replace('Si votre adversaire contrôle un monstre et que vous n''en contrôlez aucun, vous pouvez Invoquer Spécialement cette carte (depuis votre main). \r\nUne fois par tour, si un ou plusieurs monstres avec une ATK supérieure à cette carte sont Invoqués Spécialement sur le Terrain de votre adversaire (sauf durant la Damage Step): jusqu''à la fin de ce tour, vous pouvez faire gagner 700 ATK à cette carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8915275,'Boîte Maléfique',replace(replace('Si vous contrôlez "Monde des Toons": vous pouvez Invoquer Spécialement cette carte depuis votre main, puis vous pouvez ajouter à votre main ou Poser 1 Piège "Toon" depuis votre Deck.\r\nVous ne pouvez utiliser cet effet de "Boîte Maléfique" qu''une fois par tour.\r\nCette carte est traitée comme un monstre Toon tant que "Monde des Toons" est sur le Terrain.\r\nUne fois par tour (Effet Rapide): vous pouvez cibler 1 carte dans l''un des Cimetières; placez-la au-dessous du Deck.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Récupérer depuis le Cimetière','Sélectionner une Carte Piège ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8944575,'Le Drdek','Globe oculaire bipède dont les griffes redoutables épargnent rarement ses ennemis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8949584,'Héros Vivant','Si vous ne contrôlez aucun monstre face recto: payez la moitié de vos LP; Invoquez Spécialement 1 monstre "HÉROS Élémentaire" de max. Niveau 4 depuis votre Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8951260,'Jouer Carte sur Table','À chacun de leurs tours respectifs, chaque joueur doit révéler sa main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8953369,'Chevauchement Kashtira',replace(replace('Ciblez 1 monstre sur le Terrain; bannissez 1 monstre avec 1500 ATK/2100 DEF depuis votre main, votre Cimetière ou face recto sur l''un des Terrains, et si vous le faites, le monstre ciblé gagne 1500 ATK. \r\nSi cette carte est bannie et que vous contrôlez un monstre "Kashtira": vous pouvez cibler 1 Monstre à Effet contrôlé par votre adversaire; jusqu''à la fin de ce tour, annulez ses effets. \r\nVous ne pouvez utiliser chaque effet de "Chevauchement Kashtira" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8955148,'Rituel de Litmus le Maudit',replace(replace('Cette carte est utilisée pour Invoquer Rituellement "Litmus le Maudit". \r\nVous devez aussi Sacrifier des monstres depuis votre main ou Terrain, dont le Niveau total est égal à min. 8. \r\nSi cette carte est dans le Cimetière: vous pouvez cibler 1 "Litmus le Maudit" dans votre Cimetière; mélangez-le ainsi que cette carte depuis le Cimetière dans le Deck, puis piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Rituel de Litmus le Maudit" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8963089,'Héosvarog l''Aube Mécanique',replace(replace('2 monstres LUMIÈRE Machine	\r\nSi cette carte est Invoquée par Fusion: vous pouvez activer cet effet; durant la Standby Phase du prochain tour, ajoutez 1 carte depuis votre Cimetière à votre main, avec un effet qui Invoque par Fusion un ou plusieurs monstres. \r\nLorsque votre adversaire active une Carte Magie/Piège ou effet de Magie/Piège (Effet Rapide): vous pouvez bannir 1 monstre LUMIÈRE Machine face recto que vous contrôlez, ou 2 monstres LUMIÈRE Machine depuis votre Cimetière; annulez l''activation. \r\nVous ne pouvez utiliser chaque effet de "Héosvarog l''Aube Mécanique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Récupérer des cartes liées à la Fusion','Annuler l''activation','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8964854,'Attaque Combinée',replace(replace('Durant une Battle Phase, vous pouvez utiliser cet effet sur 1 monstre équipé d''un Monstre Union. \r\nLibérez l''équipement Union du monstre qui a attaqué ce tour et vous pouvez attaquer avec ce monstre à nouveau ce tour-ci.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8967776,'Sephylon, le Seigneur Ultime du Temps',replace(replace('(Cette carte est toujours traitée comme une carte "Seigneur du Temps".)	\r\nNi Invocable Normalement ni Posable Normalement. \r\nUniquement Invocable Spécialement (depuis votre main) en ayant min. 10 monstres dans votre Cimetière. \r\nUne fois par tour: vous pouvez Invoquer Spécialement 1 monstre Elfe de min. Niveau 8 depuis votre main ou Cimetière, mais ses effets sont annulés, et aussi, son ATK devient 4000.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8972398,'Omni Dragon Brotaur',replace(replace('Si un monstre que vous contrôlez est détruit au combat ou par un effet de carte de l''adversaire: vous pouvez Invoquer Spécialement cette carte depuis le Cimetière (si elle y était lorsque le monstre a été détruit) ou la main (même si elle n''y était pas), mais bannissez-la lorsqu''elle quitte le Terrain. \r\nSi cette carte est Invoquée Spécialement: vous pouvez cibler 1 monstre face recto sur le Terrain; défaussez 1 carte, et si vous le faites, ajoutez 1 monstre depuis votre Deck à votre main, du même Type et Attribut que la cible, mais de nom différent. \r\nVous ne pouvez utiliser chaque effet de "Omni Dragon Brotaur" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte','Chercher dans le Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8978197,'Roi Seigneur des D',replace(replace('Le nom de cette carte devient "Seigneur des D" tant qu''elle est sur le Terrain. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez défausser 1 Magie/Piège; ajoutez 1 "La Flûte d''Invocation du Dragon", "La Mélodie du Réveil des Dragons" ou "Rhapsodie de la Résurrection du Dragon" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9000988,'Dragon Pièce Potartiste',replace(replace('Échelle Pendule = 5\r\n[ Effet Pendule ]\r\nUne fois par tour: vous pouvez cibler 1 monstre de Type Dragon que vous contrôlez qui a été Invoqué Spécialement depuis l''Extra Deck; ce tour, si le monstre que vous contrôlez combat un monstre de votre adversaire, bannissez le monstre de votre adversaire après le calcul des dommages (même si cette carte quitte le Terrain).\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nLes autres monstres de Type Dragon que vous contrôlez gagnent 500 ATK, et aussi, ils ne peuvent pas être détruits par des effets de carte.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9012916,'Dragon Ailes Sombres',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi vous allez recevoir des dommages d''un effet de carte, placez 1 Compteur Plumes Noires sur cette carte à la place. \r\nCette carte perd 700 ATK pour chaque Compteur Plumes Noires sur elle. \r\nUne fois par tour: vous pouvez retirer tous les Compteurs Plumes Noires de cette carte, puis ciblez 1 monstre face recto contrôlé par votre adversaire; la cible perd 700 ATK pour chaque Compteur Plumes Noires retiré, et si elle le fait, infligez des dommages à votre adversaire égaux à l''ATK perdue par cet effet.','\r',char(13)),'\n',char(10)),'Diminuer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9012917,'Dragon Ailes Sombres',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi vous allez recevoir des dommages d''un effet de carte, placez 1 Compteur Plumes Noires sur cette carte à la place. \r\nCette carte perd 700 ATK pour chaque Compteur Plumes Noires sur elle. \r\nUne fois par tour: vous pouvez retirer tous les Compteurs Plumes Noires de cette carte, puis ciblez 1 monstre face recto contrôlé par votre adversaire; la cible perd 700 ATK pour chaque Compteur Plumes Noires retiré, et si elle le fait, infligez des dommages à votre adversaire égaux à l''ATK perdue par cet effet.','\r',char(13)),'\n',char(10)),'Diminuer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9024198,'D/D/D Roi des Abysses Gilgamesh',replace(replace('2 monstres "D/D"	\r\nSi cette carte est Invoquée Spécialement: vous pouvez activer cet effet; vous ne pouvez pas Invoquer Spécialement de monstres (monstres "D/D" exclus) le reste de ce tour, et aussi, placez 2 Monstres Pendule "D/D" de noms différents depuis votre Deck dans vos Zones Pendule, et si vous le faites, recevez 1000 points de dommages. \r\nSi cette carte Invoquée par Lien est détruite au combat avec un monstre attaquant de l''adversaire, ou par un effet de carte de l''adversaire tant qu''elle est dans la Zone Monstre de son propriétaire: vous pouvez Invoquer Spécialement 1 monstre "D/D" depuis votre Extra Deck ou Cimetière en Position de Défense. \r\nVous ne pouvez utiliser chaque effet de "D/D/D Roi des Abysses Gilgamesh" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9024367,'Dragon Galactique',replace(replace('Cette carte ne peut pas attaquer directement, et peut uniquement attaquer des monstres de Type Dragon. \r\nSi cette carte combat un monstre de Type Dragon, cette carte gagne 1000 ATK durant la Damage Step uniquement, et aussi, le monstre a ses effets annulés durant cette Battle Phase, tant que cette carte reste face recto sur le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9028399,'Calcifida Croûté Cataclysmique',replace(replace('Si un ou plusieurs monstres TERRE face recto que vous contrôlez sont détruits au combat ou par un effet de carte de l''adversaire: vous pouvez Invoquer Spécialement cette carte depuis votre main, puis, vous pouvez envoyer 1 monstre depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser cet effet de "Calcifida Croûté Cataclysmique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte depuis votre main','Envoyer un monstre depuis votre Deck au Cimetière ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9030160,'Contrat des Ténèbres avec l''Obscurité Éternelle',replace(replace('Tant que vous avez 2 cartes "D/D" dans vos Zones Pendule, votre adversaire ne peut ni cibler de monstres sur le Terrain avec des effets de Magie/Piège, ni les Sacrifier pour une Invocation Sacrifice, ni les utiliser comme Matériels pour une Invocation Fusion, Synchro ou Xyz. \r\nUne fois par tour, durant votre Standby Phase: recevez 1000 points de dommages.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9032529,'Larme Gracieuse','Ajoutez 1 carte depuis votre main à la main de votre adversaire, puis gagnez 2000 LP.','Choisissez la/les carte(s) de votre main à donner à votre adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9047460,'Aile Noire - Vapeur de la Cape',replace(replace('Si cette carte face recto quitte le Terrain: Invoquez Spécialement 1 "Jeton Vapeur" (Aqua/VENT/Niveau 1/ATK 100/DEF 100). \r\nSi cette carte est dans votre Cimetière: vous pouvez Sacrifier 1 monstre; Invoquez Spécialement cette carte depuis le Cimetière. \r\nVous ne pouvez utiliser cet effet de "Aile Noire - Vapeur de la Cape" qu''une fois par Duel. \r\nSi cette carte Invoquée de cette façon est utilisée comme Matériel Synchro, tous les autres Matériels Synchro doivent être des monstres "Aile Noire".','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9047461,'Jeton Vapeur','Invoqué Spécialement avec l''effet de "Aile Noire - Vapeur de la Cape".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9053187,'Gagagigo le Ressuscité','3 monstres de Niveau 4','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9056100,'Général Grunard de la Barrière de Glace',replace(replace('Durant votre Main Phase, vous pouvez Invoquer Normalement 1 monstre "Barrière de Glace" en plus de votre Invocation/Pose Normale. \r\n(Vous ne pouvez gagner cet effet qu''une fois par tour.)','\r',char(13)),'\n',char(10)),'Invoquer par l''effet de "Général Grunard de la Barrière de Glace"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9059700,'Barrière Enfernité','Lorsque votre adversaire active une Carte Magie/Piège ou un effet de monstre, tant que vous contrôlez un monstre "Enfernité" en Position d''Attaque face recto et que vous n''avez aucune carte dans votre main: annulez l''activation, et si vous le faites, détruisez la carte ou le monstre.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9061682,'Andwraith Mythologique',replace(replace('1 Syntoniseur "Mythologique" + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée Spécialement: votre adversaire peut défausser 1 carte pour annuler cet effet, sinon vous pouvez piocher 2 cartes, puis défaussez 1 carte. \r\nSi un ou plusieurs monstres sont envoyés depuis la main de votre adversaire au Cimetière (sauf durant la Damage Step): vous pouvez cibler 1 de ces monstres; Invoquez-le Spécialement sur votre Terrain, mais annulez ses effets. \r\nVous ne pouvez utiliser chaque effet de "Andwraith Mythologique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Piochez, puis défaussez 1 carte','Défausser 1 carte pour annuler l''effet de "Andwraith Mythologique" ?','Invoquer Spécialement le monstre de votre adversaire','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9064354,'Usine de Production en Plus des Ténèbres',replace(replace('Vous pouvez envoyer 1 monstre depuis votre main ou Terrain au Cimetière; piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Usine de Production en Plus des Ténèbres" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9069157,'Dragonroid',replace(replace('Une fois par tour, si cette carte est dans votre Cimetière: jusqu''à la fin de ce tour, vous pouvez faire devenir cette carte un monstre Dragon tant qu''elle est dans le Cimetière. \r\nVous pouvez défausser cette carte, puis activez 1 de ces effets;\r\n● Ajoutez 1 monstre non-VENT "roid" depuis votre Deck à votre main.\r\n● Ce tour, l''activation de vos cartes et effets qui incluent un effet qui Invoque par Fusion un Monstre Fusion ne peut pas être annulée, et aussi, votre adversaire ne peut activer ni de cartes ni d''effets lorsqu''un monstre est Invoqué par Fusion de cette façon.	\r\nVous ne pouvez utiliser cet effet de "Dragonroid" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Résistance de Fusion','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9070454,'Aura d''Utopie Draconique',replace(replace('Lorsque votre adversaire active un effet de monstre sur le Terrain: annulez l''activation, et si vous le faites, détruisez la carte, puis, vous pouvez appliquer l''effet suivant.\r\n● Bannissez 1 monstre depuis votre main, et si vous le faites, Invoquez Spécialement le monstre qui a été détruit et envoyé au Cimetière par cet effet sur votre Terrain, mais annulez ses effets.	\r\nVous ne pouvez activer qu''1 "Aura d''Utopie Draconique" par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement ce monstre ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9074847,'Émeute Majeure','Si un ou plusieurs monstres que vous contrôlez sont renvoyés à votre main par un effet de carte de l''adversaire: renvoyez autant de monstres sur le Terrain à la main que possible, puis chaque joueur Invoque Spécialement un nombre de monstres depuis sa main, en Position de Défense face verso, égal au nombre de Cartes Monstre qui ont été renvoyées à sa main.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9076207,'Ninja Armé',replace(replace('FLIP: Ciblez 1 Carte Magie sur le Terrain; détruisez la cible. \r\n(Si la cible est Posée, révélez-la et détruisez-la si c''est une Carte Magie. Sinon, remettez-la dans sa position d''origine.)','\r',char(13)),'\n',char(10)),'Détruire une Carte Magie','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9091064,'Âme du Vainqueur Jiaolong',replace(replace('Si vous révélez une ou plusieurs cartes dans votre main pour activer une carte ou effet "Âme du Vainqueur" (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\n(Effet Rapide): vous pouvez activer 1 de ces effets, en révélant un ou plusieurs monstres dans votre main avec les Attributs listés;\r\n● FEU: Changez la position de combat d''1 monstre sur le Terrain.\r\n● 2 FEU: Ajoutez 1 carte "Âme du Vainqueur" ("Âme du Vainqueur Jiaolong" exclu) depuis votre Deck à votre main.	\r\nVous ne pouvez utiliser chaque effet de "Âme du Vainqueur Jiaolong" qu''une fois par tour, et ne pouvez en activer que max. 1 dans la même Chaîne.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte depuis votre main','Révélez 1 monstre FEU','Révélez 2 monstres FEU','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9097866,'Face Débug',replace(replace('Si vous contrôlez min. 2 Monstres Lien: vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nDurant le calcul des dommages, si votre Monstre Lien combat un Monstre Lien de l''adversaire (Effet Rapide): vous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 Monstre Lien dans votre Cimetière; votre monstre combattant ne peut pas être détruit par ce combat, et aussi, jusqu''à la fin de ce tour, il gagne une ATK égale à l''ATK de la cible. \r\nVous ne pouvez utiliser chaque effet de "Face Débug" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Augmenter l''ATK et éviter la destruction au combat','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9102835,'Fusion Salamandra',replace(replace('Équipable uniquement à un monstre FEU Guerrier. \r\nIl gagne 700 ATK. \r\nSi le monstre équipé va être détruit au combat ou par un effet de carte, vous pouvez détruire cette carte à la place. \r\nTant que cette carte est équipée à un Monstre Fusion que vous contrôlez: vous pouvez envoyer cette carte et le monstre équipé au Cimetière, et si vous le faites, Invoquez Spécialement 1 "Spadassin des Flammes" ou 1 Monstre Fusion qui le mentionne depuis votre Extra Deck. \r\n(Ceci est traité comme une Invocation Fusion.) \r\nVous ne pouvez utiliser cet effet de "Fusion Salamandra" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','Invoquez par Fusion "Spadassin des Flammes", ou un Monstre Fusion qui mentionne le nom de cette carte','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9106362,'Gongochat Potartiste',replace(replace('Échelle Pendule = 2\r\n[ Effet Pendule ]\r\nUne fois par tour, lorsqu''un monstre de votre adversaire déclare une attaque directe: vous pouvez activer cet effet; vous ne recevez aucun dommage de combat de ce combat (même si cette carte quitte le Terrain).\r\n----------------------------------------\r\n[ Effet de Monstre ]\r\nUne fois par tour, lorsqu''une attaque impliquant un monstre que vous contrôlez et un monstre de votre adversaire est déclarée: vous pouvez activer cet effet; vous ne recevez aucun dommage de combat de ce combat.','\r',char(13)),'\n',char(10)),'Les dommages de combat deviennent 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9107531,'Artilleur Électrique',replace(replace('Si vous Invoquez Normalement ou Spécialement un ou plusieurs monstres FEU (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main, puis vous pouvez envoyer 1 monstre Pyro de Niveau 8 depuis votre Deck au Cimetière. \r\nVous ne pouvez utiliser cet effet de "Artilleur Électrique" qu''une fois par tour. \r\nUne fois par tour, si une Carte Magie est activée (sauf durant la Damage Step): vous pouvez faire gagner 300 ATK à tous les monstres FEU que vous contrôlez actuellement.','\r',char(13)),'\n',char(10)),'Envoyer depuis votre Deck au Cimetière ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9109991,'Aile Noire - Foehn la Chaîne d''Acier',replace(replace('Cette carte peut attaquer directement votre adversaire. \r\nSi cette carte inflige des dommages de combat à votre adversaire par une attaque directe: ciblez 1 monstre en Position d''Attaque contrôlé par votre adversaire; changez la cible en Position de Défense.','\r',char(13)),'\n',char(10)),'Passer en Position de Défense','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9113513,'Ostinato',replace(replace('Si vous ne contrôlez aucun monstre: Invoquez par Fusion 1 Monstre Fusion "Musique" depuis votre Extra Deck, en utilisant 2 monstres depuis votre main et/ou Deck comme Matériel. \r\nDurant la End Phase de ce tour, détruisez le monstre Invoqué par Fusion par cet effet, et si vous le faites, si tous les Matériels qui ont été utilisés pour son Invocation Fusion sont dans votre Cimetière, vous pouvez tous les Invoquer Spécialement.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement le monstre Matériel de Fusion ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9126351,'Grenouille Démon',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en défaussant 1 autre monstre EAU. \r\nLorsque cette carte est Invoquée: vous pouvez envoyer 1 monstre EAU Aqua de max. Niveau 2 depuis votre Deck ou Terrain face recto au Cimetière. \r\nUne fois par tour: vous pouvez renvoyer 1 monstre que vous contrôlez à la main; durant votre Main Phase ce tour, vous pouvez Invoquer Normalement 1 monstre "Grenouille" ("Grenouille Démon" exclu) en plus de votre Invocation/Pose Normale. \r\n(Vous ne pouvez gagner cet effet qu''une fois par tour.)','\r',char(13)),'\n',char(10)),'Invoquer par l''effet de "Grenouille Démon"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9145181,'Scellement de Rituel','Détruisez 1 Monstre Rituel face recto sur le Terrain.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9156135,'Apprenti Magicien',replace(replace('Si cette carte est Invoquée: ciblez 1 carte face recto sur le Terrain sur laquelle vous pouvez placer un Compteur Magie; placez 1 Compteur Magie sur la cible. \r\nLorsque cette carte est détruite au combat: vous pouvez Invoquer Spécialement 1 monstre Magicien de max. Niveau 2 depuis votre Deck en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'Placer des Compteurs Magie','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9159938,'Anthracite','Ce monstre entièrement gris n''a que rarement été aperçu par des yeux de mortels.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9161357,'Numéro 6 : Atlandis Chronomal',replace(replace('2 monstres de Niveau 6	\r\nLorsque cette carte est Invoquée par Xyz: vous pouvez cibler 1 monstre "Numéro" dans votre Cimetière; équipez la cible à cette carte. \r\nCette carte gagne une ATK égale à la moitié de l''ATK du monstre équipé. \r\nUne fois par tour: vous pouvez détacher 1 Matériel Xyz de cette carte, puis envoyez le monstre équipé par cet effet au Cimetière; divisez par deux les Life Points de votre adversaire. \r\nVous ne pouvez pas mener votre Battle Phase le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Équiper','Diviser les LP par deux','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9175957,'Taïaut Springans',replace(replace('Lorsque vous activez cette carte, vous pouvez aussi détacher max. 3 Matériels de monstres que vous contrôlez; ajoutez 1 monstre "Springans" depuis votre Deck à votre main, puis, si vous avez détaché un Matériel à l''activation, vous pouvez Invoquer Spécialement autant de monstres "Springans" depuis votre main ou Cimetière. \r\nDurant votre Main Phase, si cette carte est dans votre Cimetière: vous pouvez cibler 1 Monstre Xyz sur le Terrain; détachez-en 1 Matériel, et si vous le faites, ajoutez cette carte à votre main. \r\nVous ne pouvez utiliser qu''1 effet de "Taïaut Springans" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','Détacher un Matériel Xyz pour activer ?','Invoquer Spécialement un monstre "Springans" ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9190563,'Nuageur RAM',replace(replace('Vous pouvez Sacrifier 1 monstre, puis ciblez 1 monstre Cyberse dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez utiliser cet effet de "Nuageur RAM" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9197735,'Statue de dragon','Guerrier de pierre au cœur de dragon.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9201964,'Fortune D',replace(replace('Activable uniquement lorsque votre adversaire déclare une attaque directe en retirant du jeu 1 monstre "HÉROS de la Destinée" depuis votre Cimetière. \r\nTerminez la Battle Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9205573,'Evil★Jumelle Ki-sikil',replace(replace('2 monstres (un monstre "Ki-sikil" inclus)	\r\nSi cette carte est Invoquée Spécialement et que vous contrôlez un monstre "Lil-la": vous pouvez piocher 1 carte. \r\nDurant la Main Phase, si vous ne contrôlez aucun monstre "Lil-la" (Effet Rapide): vous pouvez Invoquer Spécialement 1 monstre "Lil-la" depuis votre Cimetière, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Démon exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Evil★Jumelle Ki-sikil" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Piocher','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9205574,'Evil★Jumelle Ki-sikil',replace(replace('2 monstres (un monstre "Ki-sikil" inclus)	\r\nSi cette carte est Invoquée Spécialement et que vous contrôlez un monstre "Lil-la": vous pouvez piocher 1 carte. \r\nDurant la Main Phase, si vous ne contrôlez aucun monstre "Lil-la" (Effet Rapide): vous pouvez Invoquer Spécialement 1 monstre "Lil-la" depuis votre Cimetière, et aussi, vous ne pouvez pas Invoquer Spécialement de monstres (monstres Démon exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Evil★Jumelle Ki-sikil" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Piocher','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9212051,'MISSION ESPIRALE - Secours',replace(replace('Détruisez cette carte durant votre 3e End Phase après activation. \r\nUne fois par tour: vous pouvez cibler 1 monstre "ESPIRALE" dans votre Cimetière; ajoutez-le à votre main. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre "ESPIRALE" dans votre Cimetière; Invoquez-le Spécialement. \r\nVous ne pouvez contrôler qu''1 "MISSION ESPIRALE - Secours".','\r',char(13)),'\n',char(10)),'Activer sans résoudre l''effet','Activer et résoudre l''effet','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9213491,'Fille Psychique de la Sérénité',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez bannir 1 carte depuis votre main, et si vous le faites, Invoquez Spécialement 1 monstre Psychique de max. Niveau 4 ("Fille Psychique de la Sérénité" exclu) depuis votre Deck, et aussi, vous ne pouvez pas Invoquer Spécialement (monstres Psychique exclus) depuis l''Extra Deck le reste de ce tour. \r\nVous pouvez cibler un nombre de monstres face recto sur le Terrain, inférieur ou égal au nombre de monstres Psychique que vous contrôlez; jusqu''à la fin de ce tour, augmentez leur Niveau de 1. \r\nVous ne pouvez utiliser chaque effet de "Fille Psychique de la Sérénité" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Augmenter le Niveau','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9236985,'Miroirphoto Gishki',replace(replace('Cette carte peut être utilisée pour Invoquer Rituellement un Monstre Rituel "Gishki". \r\nVous devez aussi payer des Life Points égaux au Niveau du monstre Invoqué Rituellement x 500 (lorsque cette carte est résolue).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9238125,'Vernusylphe des Montagnes Fondantes',replace(replace('Vous pouvez défausser cette carte, et 1 monstre ou 1 carte "Vernusylphe"; piochez 1 carte, puis vous pouvez Invoquer Spécialement 1 monstre TERRE depuis votre Cimetière, et aussi, vous ne pouvez pas activer d''effets de monstre non-TERRE le reste de ce tour. \r\nVous pouvez cibler 1 monstre "Vernusylphe" que vous contrôlez; durant chaque Battle Phase ce tour, il peut faire une seconde attaque. \r\nVous ne pouvez utiliser chaque effet de "Vernusylphe des Montagnes Fondantes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement depuis le Cimetière ?','L''effet de "Vernusylphe des Montagnes Fondantes" est actuellement appliqué.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9251497,'Kingyo Sukui',replace(replace('Vous pouvez cibler 1 monstre dans le Cimetière de votre adversaire; dévoilez la carte du dessus de votre Deck, et si c''est un monstre du même Attribut que la cible, ajoutez-le à votre main, et si vous le faites, mélangez la cible dans le Deck. \r\nSinon, envoyez la carte dévoilée au Cimetière, et aussi, détruisez cette carte. \r\nVous ne pouvez utiliser cet effet de "Kingyo Sukui" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9260791,'Dragonuage aux Yeux Galactiques',replace(replace('Vous pouvez Sacrifier cette carte; Invoquez Spécialement 1 monstre "Yeux Galactiques" ("Dragonuage aux Yeux Galactiques" exclu) depuis votre main ou Cimetière. \r\nVous ne pouvez utiliser cet effet de "Dragonuage aux Yeux Galactiques" qu''une fois par tour. \r\nSi cette carte est dans le Cimetière: vous pouvez cibler 1 Monstre Xyz "Yeux Galactiques" que vous contrôlez; attachez-lui cette carte comme Matériel Xyz. \r\nVous ne pouvez utiliser cet effet de "Dragonuage aux Yeux Galactiques" qu''une fois par Duel.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Attacher du Matériel','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9264485,'Serviteur d''Horus','Votre adversaire ne peut pas cibler des monstres "Horus Dragon de la Flamme Noire" face recto avec des Magies/Pièges ou effets de carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9267769,'Flashbang',replace(replace('Activable uniquement après le calcul des dommages lorsqu''un monstre contrôlé par votre adversaire attaque directement. \r\nC''est maintenant la End Phase de ce tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9272381,'Stellchevalier Constellée Diamant',replace(replace('3+ monstres LUMIÈRE de Niveau 5	\r\nDurant votre Main Phase 2, vous pouvez aussi Invoquer par Xyz cette carte en utilisant un Monstre Xyz "tellchevalier" que vous contrôlez ("Stellchevalier Constellée Diamant" exclu) comme Matériel. \r\n(Transférez ses Matériels à cette carte.) \r\nTant que cette carte a du Matériel, aucun joueur ne peut envoyer de cartes depuis le Deck au Cimetière, et les cartes qui sont renvoyées depuis le Cimetière à la main sont bannies à la place. \r\nLorsqu''un effet de monstre TÉNÈBRES de l''adversaire est activé (Effet Rapide): vous pouvez détacher 1 Matériel de cette carte; annulez l''activation, et si vous le faites, détruisez-le.','\r',char(13)),'\n',char(10)),'Invoquer Xyz en utilisant un Monstre Xyz "Stellchevalier" comme Matériel ?','Annuler et détruire','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9275482,'UFOLumière',replace(replace('Votre adversaire ne peut pas cibler cette carte sur le Terrain avec des effets de carte, sauf durant la Battle Phase. \r\nSi cette carte combat un monstre, aucun de ces 2 monstres ne peut être détruit par ce combat. \r\nDurant la End Phase: vous pouvez piocher 1 carte, puis vous devez bannir un nombre de votre choix de cartes depuis votre main (min. 1), et si vous le faites, cette carte gagne 500 ATK pour chacune d''elles. \r\nVous ne pouvez utiliser cet effet de "UFOLumière" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9283801,'La Révolte des Monarques',replace(replace('Défaussez 1 carte; révélez 3 monstres depuis votre Deck, avec min. 2400 ATK et 1000 DEF et/ou 800 ATK/1000 DEF, votre adversaire en choisit 1 pour vous à ajouter à votre main, et vous envoyez les cartes restantes au Cimetière, et aussi, vous ne pouvez pas Invoquer Spécialement depuis l''Extra Deck le reste de ce tour après la résolution de cette carte. \r\nVous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 monstre avec 800 ATK/1000 DEF depuis votre main. \r\nVous ne pouvez utiliser chaque effet de "La Révolte des Monarques" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Activer','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9284723,'Boa Venin',replace(replace('Une fois par tour, vous pouvez placer 2 Compteurs Venin sur 1 monstre contrôlé par votre adversaire. \r\nSi vous activez cet effet, cette carte ne peut pas attaquer durant ce tour.','\r',char(13)),'\n',char(10)),'Placer un marqueur','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9287078,'Cercueil Maléfique','Lorsque votre adversaire Invoque Normalement ou Spécialement un ou plusieurs monstres: ciblez 1 de ces monstres et 1 monstre Magicien que vous contrôlez; envoyez les deux monstres au Cimetière, puis vous pouvez Invoquer Spécialement 1 monstre TÉNÈBRES Magicien depuis votre Deck ou Cimetière.','Invoquer Spécialement 1 monstre Magicien TÉNÈBRES depuis votre Deck ou Cimetière ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9293977,'Dragon Métallique','"Ogre d''Acier N°1" + "Dragon Inférieur"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9298235,'Grue Peluchimal','Lorsqu''un ou plusieurs monstres "Peluchimal" face recto que vous contrôlez sont détruits par une attaque ou effet de carte de votre adversaire, et envoyés à votre Cimetière: ciblez 1 de ces monstres détruits; ajoutez-le à votre main, et si vous le faites, piochez 1 carte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9322133,'Laser Effaceur Psychique',replace(replace('Envoyez 1 monstre contrôlé par votre adversaire qui a été Invoqué Spécialement depuis l''Extra Deck au Cimetière, puis votre adversaire gagne des LP égaux à l''ATK ou DEF d''origine du monstre (la plus haute valeur). \r\nVous ne pouvez activer qu''1 "Laser Effaceur Psychique" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9327502,'Voltaïque, HÉROS Élémentaire','Lorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez cibler 1 de vos monstres "HÉROS Élémentaire" bannis; Invoquez Spécialement la cible.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9334391,'Lien Cristallin',replace(replace('Ajoutez 1 monstre "Bête Cristalline" depuis votre Deck à votre main, et placez 1 monstre "Bête Cristalline" de nom différent depuis votre Deck face recto dans votre Zone Magie & Piège comme Magie Continue. \r\nVous ne pouvez activer qu''1 "Lien Cristallin" par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9336190,'Les Chevaliers Fantômes des Griffes de la Brume',replace(replace('Ciblez 1 de vos monstres "Les Chevaliers Fantômes" bannis; ajoutez-le à votre main. \r\nLorsqu''un monstre de l''adversaire déclare une attaque directe tant que cette carte est dans votre Cimetière: vous pouvez cibler 1 monstre "Les Chevaliers Fantômes" de max. Niveau 4 dans votre Cimetière; Invoquez Spécialement le monstre, et si vous le faites, Invoquez Spécialement cette carte comme un Monstre Normal du même Niveau d''origine que le monstre (Guerrier/TÉNÈBRES/ATK 0/DEF 0).	\r\n(Cette carte N''EST PAS traitée comme un Piège.) \r\nSi elle est Invoquée de cette façon, bannissez cette carte lorsqu''elle quitte le Terrain.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9341993,'Apaisement Inflexcipateur','Sacrifiez un nombre de votre choix de monstres "Inflexcipateur", puis ciblez un nombre de cartes sur le Terrain égal au nombre Sacrifié +1; détruisez-les.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9342162,'Cagna, Malebranche des Abysses Ardents',replace(replace('Si vous contrôlez un monstre (monstres "Abysses Ardents" exclus), détruisez cette carte. \r\nVous ne pouvez utiliser qu''1 de ces effets de "Cagna, Malebranche des Abysses Ardents" par tour, et uniquement une fois le tour.\r\n● Si vous ne contrôlez aucune Carte Magie/Piège: vous pouvez Invoquer Spécialement cette carte depuis votre main.\r\n● Si cette carte est envoyée au Cimetière: vous pouvez envoyer 1 Carte Magie/Piège "Abysses Ardents" depuis votre Deck au Cimetière.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Envoyer au Cimetière','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9348522,'Château dans le Ciel',replace(replace('1 Syntoniseur + 1+ non-Syntoniseur	\r\nLorsque cette carte est Invoquée par Synchronisation: vous pouvez cibler 1 monstre de Niveau 9 dans votre Cimetière; Invoquez Spécialement la cible. \r\nLes monstres de max. Niveau 8 ne peuvent pas attaquer le tour où ils sont Invoqués Normalement ou Spécialement.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9349094,'Bête-Arbre Sacrée, Hyperyton',replace(replace('2 monstres de Niveau 9	\r\nDurant votre tour, lorsque vous activez une carte ou un effet (Effet Rapide): vous pouvez cibler 1 carte du même type (Monstre, Magie ou Piège) dans votre Cimetière; attachez-le à cette carte comme Matériel. \r\nDurant le tour de votre adversaire, lorsqu''une carte ou un effet est activé (Effet Rapide): vous pouvez détacher 1 Matériel du même type (Monstre, Magie ou Piège) de cette carte, et si vous le faites, annulez l''activation, et si vous faites ça, détruisez la carte. \r\nVous ne pouvez utiliser chaque effet de "Bête-Arbre Sacrée, Hyperyton" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9350312,'Vernusylphe des Collines Florissantes',replace(replace('Les monstres "Vernusylphe" que vous contrôlez ne peuvent pas être détruits par des effets de carte. \r\nVous pouvez défausser cette carte, et 1 monstre ou 1 carte "Vernusylphe"; ajoutez 1 carte "Vernusylphe" ("Vernusylphe des Collines Florissantes" exclu) depuis votre Deck à votre main, puis vous pouvez Invoquer Spécialement 1 monstre TERRE depuis votre Cimetière, et aussi, vous ne pouvez pas activer d''effets de monstre non-TERRE le reste de ce tour. \r\nVous ne pouvez utiliser cet effet de "Vernusylphe des Collines Florissantes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement depuis le Cimetière ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9354555,'Voile Photon',replace(replace('Mélangez 3 monstres LUMIÈRE depuis votre main dans le Deck, puis ajoutez 1, 2 ou 3 monstres LUMIÈRE de max. Niveau 4 depuis votre Deck à votre main. \r\nSi vous ajoutez min. 2 monstres, ils doivent avoir le même nom.','\r',char(13)),'\n',char(10)),'Ajouter une autre carte à la main ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9365703,'Guerrier de Célérité','Une fois par Battle Step, si cette carte a été Invoquée Normalement ce tour (sauf durant la Damage Step): jusqu''à la fin de la Battle Phase, vous pouvez faire devenir son ATK le double de son ATK d''origine.','Changer l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9373534,'Fuhma Shuriken',replace(replace('Équipable uniquement à un monstre "Ninja". \r\nIl gagne 700 ATK. \r\nLorsque cette carte est envoyée depuis le Terrain au Cimetière: infligez 700 points de dommages à votre adversaire.','\r',char(13)),'\n',char(10)),'Infligez 700 points de dommages à votre adversaire','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9391354,'Dragon Gravibroyeur','Vous pouvez envoyer au cimetière 1 Carte Magie Continue face recto que vous contrôlez pour détruire 1 monstre contrôlé par votre adversaire.','Détruire un monstre','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9396662,'Mage Miroir de la Barrière de Glace',replace(replace('Vous pouvez Sacrifier 1 autre Monstre à Effet; Invoquez Spécialement max. 3 "Jeton Barrière de Glace" (Aqua/EAU/Niveau 1/ATK 0/DEF 0), et si vous le faites, augmentez le Niveau de cette carte de ce nombre, et aussi, vous ne pouvez pas Invoquer Spécialement (Monstres Synchro EAU exclus) depuis l''Extra Deck le reste de ce tour. \r\nSi cette carte est envoyée au Cimetière: vous pouvez ajouter 1 de vos cartes "Barrière de Glace" ("Mage Miroir de la Barrière de Glace" exclu) qui est bannie ou dans votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Mage Miroir de la Barrière de Glace" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un Jeton','Ajouter à la main','Choisissez le nombre de Jetons à Invoquer Spécialement','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9396663,'Jeton Barrière de Glace','Invoqué Spécialement avec l''effet de "Communicatrice de la Barrière de Glace".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9400127,'Flogos, l''Infini Ogdoadique',replace(replace('Si cette carte est envoyée depuis le Terrain au Cimetière, ou Invoquée Spécialement depuis le Cimetière: vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire et 1 monstre dans son Cimetière avec une ATK supérieure ou égale à la cible; Invoquez Spécialement le monstre depuis le Cimetière sur son Terrain, et si vous le faites, envoyez l''autre monstre qu''il contrôle au Cimetière. \r\nSi cette carte est dans votre Cimetière: vous pouvez envoyer 1 carte depuis votre main au Cimetière; ajoutez cette carte à votre main. \r\nVous ne pouvez utiliser chaque effet de "Flogos, l''Infini Ogdoadique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9402966,'Boule de Combat Samouraï Supralourd',replace(replace('Si tous les monstres que vous contrôlez sont des monstres "Samouraï Supralourd", et que vous n''avez aucune Carte Magie/Piège dans votre Cimetière: vous pouvez cibler 1 monstre face recto contrôlé par votre adversaire qui a un Niveau; envoyez-le ainsi que cette carte depuis le Terrain au Cimetière, puis Invoquez Spécialement 1 Monstre Synchro "Samouraï Supralourd" depuis votre Extra Deck dont le Niveau est égal à la somme des Niveaux d''origine de ces 2 monstres dans le Cimetière. \r\n(Cette Invocation Spéciale est traitée comme une Invocation Synchro.) \r\nVous ne pouvez utiliser cet effet de "Boule de Combat Samouraï Supralourd" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9409625,'Machine Vide',replace(replace('La première fois que cette carte face recto sur le Terrain va être détruite par un effet de carte de l''adversaire, elle n''est pas détruite. \r\nUne fois par tour, vous pouvez activer 1 de ces effets.\r\n● Défaussez 1 monstre de Niveau 10; piochez 1 carte.\r\n● Si c''est la seule carte dans votre Zone Magie & Piège: ciblez 1 monstre "Seigneur du Temps" dans votre Cimetière; mélangez-le dans le Deck, puis, vous pouvez Poser 1 "Machine Infinie" directement depuis votre main ou Deck.','\r',char(13)),'\n',char(10)),'Piocher','Récupérer depuis le Cimetière','Poser "Machine Infinie" ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9411399,'Malveillant - HÉROS de la Destinée','Vous pouvez bannir cette carte depuis votre Cimetière; Invoquez Spécialement 1 "Malveillant - HÉROS de la Destinée" depuis votre Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9416697,'Eanoc, Sentinelle du Ghoti',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez cibler 1 de vos monstres Poisson de max. Niveau 4 bannis; Invoquez-le Spécialement en Position de Défense, mais annulez ses effets. \r\nVous pouvez bannir 1 monstre Poisson depuis votre main ou Terrain face recto; ajoutez 1 Piège "Ghoti" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Eanoc, Sentinelle du Ghoti" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9418365,'Bujin Hirume',replace(replace('Ni Invocable Normalement ni Posable. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 1 monstre "Bujin" ("Bujin Hirume" exclu) depuis votre Cimetière. \r\nSi cette carte, qui a été Invoquée de cette façon, est détruite par une carte de votre adversaire (au combat ou par un effet de carte) et envoyée depuis votre Terrain à votre Cimetière, et que chaque joueur a une main: vous pouvez défausser 1 carte, puis votre adversaire défausse 1 carte. \r\nVous ne pouvez contrôler qu''1 "Bujin Hirume".','\r',char(13)),'\n',char(10)),'Défausser 1 carte','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9418534,'Résurrecteur Jinzo',replace(replace('Cette carte peut attaquer directement. \r\nLorsque cette carte est envoyée au Cimetière: vous pouvez cibler 1 "Jinzo" dans votre Cimetière; Invoquez-le Spécialement, mais détruisez-le durant votre End Phase.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9430387,'LaLa Li-oon','Créature de nuage électrique dont la pluie acide est très dangereuse.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9433350,'Dragon Blanc aux Yeux Bleus Corrompu',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 1 "Dragon Blanc aux Yeux Bleus" depuis votre Deck. \r\nIl ne peut y avoir qu''1 monstre "Corrompu" sur le Terrain. \r\nLes autres monstres que vous contrôlez ne peuvent pas déclarer d''attaque. \r\nS''il n''y a aucune Magie de Terrain face recto sur le Terrain, détruisez cette carte.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9453320,'Abysstrite, l''Esprit de l''Atlantide',replace(replace('2+ monstres EAU de Niveau 7	\r\nLes monstres EAU que vous contrôlez gagnent 300 ATK/DEF pour chaque Matériel attaché à cette carte. \r\nVous ne pouvez utiliser chacun des effets suivants de "Abysstrite, l''Esprit de l''Atlantide" qu''une fois par tour. \r\nSi cette carte est Invoquée par Xyz: vous pouvez cibler 1 monstre Poisson, Serpent de Mer ou Aqua de max. Niveau 7 dans votre Cimetière; Invoquez-le Spécialement. \r\nVous pouvez détacher 1 Matériel de cette carte; Posez 1 Piège "-Abysses" depuis votre Deck.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Poser','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9464441,'Éveillé Inflexcipateur - Dragite',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nDurant votre Main Phase: vous pouvez dévoiler les 5 cartes du dessus de votre Deck, et si vous le faites, vous pouvez renvoyer un nombre de cartes contrôlées par votre adversaire à la main, inférieur ou égal au nombre de monstres Rocher dévoilés, et aussi, placez les cartes dévoilées au-dessous de votre Deck dans l''ordre de votre choix. \r\nLorsque votre adversaire active une Carte Magie/Piège ou effet de Magie/Piège, tant qu''un monstre EAU est dans votre Cimetière (Effet Rapide): vous pouvez annuler l''activation, et si vous le faites, détruisez-la. \r\nVous ne pouvez utiliser chaque effet de "Éveillé Inflexcipateur - Dragite" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','Renvoyer une carte à la main ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9482987,'Endymion, Magistus de la Maîtrise',replace(replace('Vous pouvez cibler 1 monstre "Magistus" que vous contrôlez; équipez-le avec 1 monstre "Magistus" depuis votre Extra Deck. \r\nVous pouvez cibler 1 Magie face recto que vous contrôlez; détruisez-la, et si vous le faites, piochez 1 carte, puis placez 1 carte depuis votre main au-dessous du Deck. \r\nVous ne pouvez utiliser chaque effet de "Endymion, Magistus de la Maîtrise" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Équipez 1 monstre "Magistus" depuis l''Extra Deck','Piochez 1 carte, puis placez 1 carte de votre main au-dessous du Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9485511,'Goal U.A.',replace(replace('Vous pouvez Invoquer Spécialement cette carte (depuis votre main) en renvoyant 1 monstre "U.A." que vous contrôlez ("Goal U.A." exclu) à la main. \r\nVous ne pouvez Invoquer Spécialement "Goal U.A." qu''une fois par tour de cette façon. \r\nUne fois par tour, durant le tour de votre adversaire: vous pouvez cibler 1 monstre "U.A." que vous contrôlez; une fois durant ce tour, il ne peut être détruit ni au combat ni par des effets de carte (ceci est un Effet Rapide).','\r',char(13)),'\n',char(10)),'Ne peut pas être détruit','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9486959,'Onibimaru le Balayeur d''Âmes',replace(replace('2+ monstres de Niveau 2	\r\nVous pouvez détacher 1 Matériel de cette carte, puis ciblez 1 monstre contrôlé par votre adversaire; jusqu''à la End Phase de votre adversaire, bannissez-le. \r\nSi cette carte contrôlée par son propriétaire est détruite par une carte de l''adversaire: vous pouvez cibler un nombre de monstres bannis, inférieur ou égal au nombre de Matériels que cette carte avait; mélangez-les dans le Deck. \r\nVous ne pouvez utiliser chaque effet de "Onibimaru le Balayeur d''Âmes" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9491461,'Chevalier Ganbara Gagaga',replace(replace('Vous pouvez révéler 1 monstre "Gagaga" dans votre Extra Deck; Invoquez Spécialement cette carte depuis votre main, puis vous pouvez appliquer 1 de ces effets.\r\n● Invoquez Spécialement 1 monstre "Gagaga" depuis votre main.\r\n● Changez la position de combat d''1 monstre sur le Terrain.	\r\nSi cette carte est détachée d''un Monstre Xyz pour activer l''effet du monstre: vous pouvez ajouter 1 monstre "Gogogo" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Chevalier Ganbara Gagaga" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Ajouter à la main','Invocation Spéciale','Changer la position de combat','Ne pas résoudre l''effet','','','','','','','','','','','');
INSERT INTO texts VALUES(9505425,'Crowley, Magistus des Grimoires',replace(replace('Vous pouvez envoyer 1 monstre Magicien depuis votre main ou Terrain face recto au Cimetière; Invoquez Spécialement cette carte depuis votre main. \r\nVous pouvez déclarer 1 Attribut; jusqu''à la fin de ce tour, cette carte devient de cet Attribut. \r\nVous pouvez bannir cette carte depuis votre Cimetière, puis ciblez 1 monstre "Magistus" que vous contrôlez; équipez-le avec 1 monstre "Magistus" (monstres de Niveau 4 exclus) depuis votre Cimetière. \r\nVous ne pouvez utiliser chaque effet de "Crowley, Magistus des Grimoires" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9523599,'Ranimateur de Données',replace(replace('Si cette carte est utilisée comme Matériel pour une Invocation Lien: vous pouvez cibler 1 autre monstre Cyberse de max. Niveau 4 dans votre Cimetière, qui a été utilisé comme Matériel pour l''Invocation Lien; Invoquez-le Spécialement en Position de Défense. \r\nVous ne pouvez utiliser cet effet de "Ranimateur de Données" qu''une fois par Duel.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9540040,'Tortue de pierre','Tortue de pierre quasiment indestructible.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9547962,'Circuit d''Euler',replace(replace('Les monstres de votre adversaire ne peuvent pas attaquer si vous contrôlez min. 3 monstres "Tindangle". \r\nUne fois par tour, durant votre Standby Phase: vous pouvez cibler 1 monstre "Tindangle" que vous contrôlez; donnez-en le contrôle à votre adversaire. \r\nVous pouvez bannir cette carte depuis votre Cimetière et défausser 1 carte "Tindangle"; ajoutez 1 "Circuit d''Euler" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Circuit d''Euler" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9551692,'Maître d''Ham',replace(replace('2 monstres Bête	\r\nSi cette carte est Invoquée par Fusion ou retournée face recto: vous pouvez Invoquer Spécialement 1 monstre Flip depuis votre main ou Deck en Position de Défense face verso. \r\nSi cette carte est dans votre Cimetière: vous pouvez bannir 2 monstres Flip depuis votre Terrain face recto et/ou Cimetière; Invoquez Spécialement cette carte en Position de Défense face verso, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser chaque effet de "Maître d''Ham" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9553721,'Source de Puissance Shinobiseau',replace(replace('Les monstres Spirit que vous contrôlez gagnent 500 ATK/DEF. \r\nSi un ou plusieurs monstres VENT face recto que vous contrôlez sont renvoyés à votre main (sauf durant la Damage Step): vous pouvez ajouter 1 monstre Spirit ou Carte Magie Rituelle depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Source de Puissance Shinobiseau" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9560338,'Faucheur de la Prophétie',replace(replace('Lorsque cette carte est Invoquée Normalement ou Spécialement: vous pouvez activer cet effet; appliquez autant d''effets que possible, selon le nombre de Cartes Magie "Livre de Magie" de noms différents dans votre Cimetière. \r\nVous ne pouvez utiliser l''effet de "Faucheur de la Prophétie" qu''une fois par tour.\r\n● Min. 3: Cette carte gagne 600 ATK.\r\n● Min. 4: Ajoutez 1 Carte Magie "Livre de Magie" depuis votre Deck à votre main.\r\n● Min. 5: Invoquez Spécialement 1 monstre TÉNÈBRES de Type Magicien de min. Niveau 5 depuis votre Deck.','\r',char(13)),'\n',char(10)),'Plusieurs effets','Augmenter l''ATK','Chercher dans le Deck','Invocation Spéciale','','','','','','','','','','','','');
INSERT INTO texts VALUES(9567495,'Portail du Dragon',replace(replace('2 monstres de Niveau 6	\r\nUne fois par tour, vous pouvez aussi Invoquer par Xyz "Portail du Dragon" en utilisant 1 Monstre Xyz de max. Rang 3 que vous contrôlez (transférez ses Matériels). \r\nNon utilisable comme Matériel pour une Invocation Xyz le tour où elle a été Invoquée par Xyz. \r\nUne fois par tour: vous pouvez activer cet effet; le reste de ce tour, cette carte peut attaquer une fois tous les monstres contrôlés par votre adversaire, et aussi, détachez un nombre de votre choix de Matériels de cette carte, et si vous le faites, elle gagne 1000 ATK pour chaque type de carte (Monstre, Magie ou Piège) détaché, et si elle le fait, les monstres actuellement contrôlés par votre adversaire perdent autant d''ATK.','\r',char(13)),'\n',char(10)),'Invoquer Xyz en utilisant un Monstre Xyz comme Matériel ?','Activer','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9576193,'Monstre-Surprise','Ciblez 1 monstre face recto que vous contrôlez et 1 monstre dans votre Cimetière du même Niveau; bannissez la cible depuis le Cimetière, puis piochez 1 carte et révélez-la, puis si la carte piochée est un monstre du même Niveau que le monstre sur le Terrain, Invoquez-le Spécialement.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9581215,'Trappe de Chaîne',replace(replace('Lorsque votre adversaire active un effet de monstre en réponse à l''activation d''une carte ou d''un effet: annulez l''effet de l''adversaire, puis, votre adversaire peut bannir 1 carte depuis sa main ou Deck du même nom d''origine que la carte annulée. \r\nS''il ne l''a pas fait, vous pouvez bannir 1 carte au hasard depuis sa main.','\r',char(13)),'\n',char(10)),'Bannir une carte du même nom ?','Bannir une carte de la main de votre adversaire ?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9583383,'César Gagaga',replace(replace('Ne peut pas attaquer sauf si vous contrôlez un autre monstre "Gagaga" face recto. \r\nUne fois par tour: vous pouvez bannir 1 monstre qui a un Niveau depuis votre Cimetière; les Niveaux de tous les monstres "Gagaga" face recto que vous contrôlez actuellement deviennent le Niveau du monstre. \r\nCette carte ne peut pas être utilisée comme Monstre-Matériel de Synchro.','\r',char(13)),'\n',char(10)),'Changer le Niveau','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9591819,'Évasion Gagaga',replace(replace('Lorsque votre adversaire active un effet de monstre, tant que vous contrôlez un monstre "Gagaga": annulez l''activation, puis vous pouvez défausser 1 carte, et si vous le faites, Invoquez Spécialement 1 monstre "Gagaga" depuis votre Deck. \r\nVous pouvez bannir cette carte depuis votre Cimetière; changez autant de monstres "Gagaga" que vous contrôlez que possible en Position de Défense, et si vous le faites, les monstres "Gagaga" que vous contrôlez ne peuvent être détruits ni au combat ni par des effets de carte le reste de ce tour. \r\nVous ne pouvez utiliser chaque effet de "Évasion Gagaga" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler l''activation','Changer la position de combat','Invocation Spéciale?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9596126,'Sorcier du Chaos',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) en bannissant 1 monstre LUMIÈRE et 1 monstre TÉNÈBRES depuis votre Cimetière. \r\nUne fois par tour: vous pouvez cibler 1 monstre face recto sur le Terrain; bannissez la cible. \r\nCette carte ne peut pas attaquer le tour où vous activez cet effet.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Bannir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9597987,'Tenchi Kaimei',replace(replace('(Cette carte est toujours traitée comme carte "Ninjitsu" et "Nin-Jitsu".)	\r\nLorsqu''un monstre "Ninja" que vous contrôlez inflige des dommages de combat à votre adversaire: vous pouvez cibler 1 carte contrôlée par votre adversaire; détruisez-la. \r\nSi cette carte face recto dans la Zone Terrain de son propriétaire a quitté le Terrain à cause d''un effet de l''adversaire et est maintenant dans le Cimetière ou bannie: vous pouvez cibler un nombre de votre choix de monstres "Ninja" de noms différents dans votre Cimetière; Invoquez-les Spécialement en Position de Défense face verso.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603252,'Vice-Madame, Artisanesorcière',replace(replace('1 monstre "Artisanesorcière" + 1 monstre Magicien	\r\nLorsqu''une Carte Magie, effet de Magie ou effet de monstre non-Fusion Magicien est activé (Effet Rapide): vous pouvez activer 1 de ces effets (mais vous ne pouvez utiliser chaque effet de "Vice-Madame, Artisanesorcière" qu''une fois par tour).\r\n● Détruisez 1 carte sur le Terrain.\r\n● Invoquez Spécialement 1 monstre "Artisanesorcière" de max. Niveau 6 depuis votre main ou Deck.\r\n● Ajoutez 1 Magie/Piège "Artisanesorcière" depuis votre Cimetière à votre main.','\r',char(13)),'\n',char(10)),'Détruire 1 carte sur le Terrain','Invoquer Spécialement depuis la main/le Deck','Ajouter du Cimetière à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603253,'Vice-Madame, Artisanesorcière',replace(replace('1 monstre "Artisanesorcière" + 1 monstre Magicien	\r\nLorsqu''une Carte Magie, effet de Magie ou effet de monstre non-Fusion Magicien est activé (Effet Rapide): vous pouvez activer 1 de ces effets (mais vous ne pouvez utiliser chaque effet de "Vice-Madame, Artisanesorcière" qu''une fois par tour).\r\n● Détruisez 1 carte sur le Terrain.\r\n● Invoquez Spécialement 1 monstre "Artisanesorcière" de max. Niveau 6 depuis votre main ou Deck.\r\n● Ajoutez 1 Magie/Piège "Artisanesorcière" depuis votre Cimetière à votre main.','\r',char(13)),'\n',char(10)),'Détruire 1 carte sur le Terrain','Invoquer Spécialement depuis la main/le Deck','Ajouter du Cimetière à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603356,'Chevalier de l''Ombre - Archdémon',replace(replace('Une fois par tour, durant votre Standby Phase, vous devez payer 900 LP (ceci est obligatoire), ou cette carte est détruite. \r\nLors de la résolution d''un effet de carte de l''adversaire qui cible cette carte, lancez un dé à six faces et annulez l''effet si le résultat est 3, et si vous le faites, détruisez la carte. \r\nLes dommages de combat infligés par cette carte à votre adversaire sont divisés par deux.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9608555,'Salamangrande Dragon de l''Embrasement',replace(replace('2 monstres de Niveau 4	\r\nSi cette carte va être détruite au combat ou par un effet de carte, détachez-lui 1 Matériel à la place. \r\nDurant la Battle Phase, si cette carte n''a pas de Matériel (Effet Rapide): vous pouvez Invoquer Spécialement 1 Monstre Xyz "Salamangrande" depuis votre Extra Deck, en utilisant cette carte face recto que vous contrôlez comme Matériel. \r\n(Ceci est traité comme une Invocation Xyz. Transférez ses Matériels au monstre Invoqué.) \r\nVous ne pouvez utiliser cet effet de "Salamangrande Dragon de l''Embrasement" qu''une fois par tour. \r\nSi cette carte est Invoquée par Xyz en utilisant "Salamangrande Dragon de l''Embrasement" comme Matériel: vous pouvez détruire 1 monstre contrôlé par votre adversaire.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9617996,'Régulex Croisédia',replace(replace('2 Monstres à Effet (un monstre "Croisédia" inclus)	\r\nGagne une ATK égale à la somme des ATK d''origine de tous les monstres pointés par cette carte. \r\nLes monstres pointés par cette carte ne peuvent pas attaquer. \r\nSi un ou plusieurs Monstres à Effet sont Invoqués Spécialement dans une ou plusieurs zones pointées par cette carte (sauf durant la Damage Step): vous pouvez ajouter 1 Magie/Piège "Croisédia" depuis votre Deck à votre main. \r\nVous ne pouvez utiliser cet effet de "Régulex Croisédia" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9622164,'R.D.D. - Réincarnation d''une Dimension Différente',replace(replace('Défaussez 1 carte, puis ciblez 1 de vos monstres bannis; Invoquez-le Spécialement en Position d''Attaque, et équipez-le avec cette carte. \r\nLorsque cette carte quitte le Terrain, détruisez le monstre.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9627299,'Ichiki Sayori-Hime',replace(replace('Non Invocable Spécialement. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Normalement ou retournée face recto ce tour: renvoyez cette carte à la main. \r\nVous ne pouvez utiliser chacun des effets suivants de "Ichiki Sayori-Hime" qu''une fois par tour. \r\nSi vous contrôlez un monstre avec 800 ATK ou DEF, et que cette carte est dans votre main: immédiatement après la résolution de cet effet, vous pouvez Invoquer Normalement cette carte. \r\nSi cette carte est Invoquée Normalement: vous pouvez ajouter 1 monstre LUMIÈRE ou TÉNÈBRES de Niveau 4 avec 800 ATK ou DEF ("Ichiki Sayori-Hime" exclu) depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'','Invocation','Ajouter à la main','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9627468,'Ruche Énorme Hégémon - Zexstagger',replace(replace('Gagne 300 ATK pour chaque monstre Insecte (cette carte exclue) sur le Terrain. \r\nVous ne pouvez utiliser chacun des effets suivants de "Ruche Énorme Hégémon - Zexstagger" qu''une fois par tour. \r\nSi un ou plusieurs monstres Insecte sont Invoqués Spécialement (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main. \r\nDurant la End Phase: activez cet effet; chaque joueur peut Invoquer Spécialement 1 monstre Insecte depuis sa main ou Cimetière, mais annulez ses effets.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement cette carte depuis votre main','','Invoquer Spécialement 1 monstre Insecte ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9628664,'Iris, la Mère de la Terre',replace(replace('Après qu''une Chaîne de 3 Blocks ou plus soit résolue, piochez 1 carte. \r\nCet effet ne s''active pas si plusieurs cartes/effets avec le même nom ont été activés dans cette Chaîne.','\r',char(13)),'\n',char(10)),'Piocher','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9633505,'Gardien Kay''est',replace(replace('Non Invocable sauf si vous contrôlez "Kay''est - Bâton de Silence" face recto. \r\nCette carte n''est pas affectée par les effets de Magie et ne peut pas être ciblée par des attaques, mais elle n''empêche pas votre adversaire de vous attaquer directement.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9634146,'Signal du Guerrier',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nUne fois par tour, durant la Standby Phase: placez 1 Compteur Signal sur chaque carte face recto dans la Zone Terrain, et aussi, placez-en 1 sur cette carte. \r\nCette carte avec un ou plusieurs Compteurs Signal ne peut être détruite ni au combat ni par des effets de carte de votre adversaire. \r\nUne fois par tour: vous pouvez retirer 4, 7 ou 10 Compteurs Signal depuis le Terrain; appliquez cet effet, selon le nombre retiré.\r\n● 4: Infligez 800 points de dommages à votre adversaire.\r\n● 7: Piochez 1 carte.\r\n● 10: Détruisez 1 carte sur le Terrain.','\r',char(13)),'\n',char(10)),'Placer un marqueur','4 : Infligez 800 points de dommages à votre adversaire.','7 : Piochez 1 carte.','10 : Détruisez 1 carte sur le Terrain.','','','','','','','','','','','','');
INSERT INTO texts VALUES(9637706,'Wombat Des','Vous ne recevez aucun dommage d''effet.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9653271,'Attaque Kaminari','"Ocurayon" + "Méga Thunderball"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9659580,'Karma Cubique',replace(replace('Lorsque cette carte est activée: vous pouvez cibler 1 monstre "Cubique" que vous contrôlez ("Vijam la Graine Cubique" exclu); envoyez un nombre de votre choix de "Vijam la Graine Cubique" depuis votre main et/ou Deck au Cimetière, puis le monstre gagne 800 ATK pour chacun d''eux (même si cette carte quitte le Terrain). \r\nDurant le tour de votre adversaire, si "Vijam la Graine Cubique" est Invoqué Spécialement par l''effet d''un monstre "Cubique": envoyez cette carte au Cimetière, et si vous le faites, divisez par deux les LP de votre adversaire. \r\nVous pouvez bannir cette carte depuis votre Cimetière; ajoutez 1 monstre "Cubique" depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Activer en ciblant un monstre "Cubique" ?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9666558,'Dragon Golem','Votre adversaire ne peut pas prendre pour cible d''attaque les monstres de Type Dragon face recto (celui-ci exclu).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9674034,'Frêne de l''Œil de Serpent',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez ajouter 1 monstre FEU de Niveau 1 depuis votre Deck à votre main. \r\nVous pouvez envoyer 2 cartes face recto que vous contrôlez (cette carte incluse) au Cimetière; Invoquez Spécialement 1 monstre "Œil de Serpent" ("Frêne de l''Œil de Serpent" exclu) depuis votre main ou Deck. \r\nVous ne pouvez utiliser chaque effet de "Frêne de l''Œil de Serpent" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9677699,'Pantoufles de Verre',replace(replace('Si cette carte est équipée à un monstre Elfe, il gagne 1000 ATK. \r\nSi cette carte est équipée à un monstre non-Elfe, il ne peut pas attaquer, et aussi, il perd 1000 ATK. \r\nSi cette carte est envoyée au Cimetière parce que le monstre équipé est détruit: vous pouvez cibler 1 "Prinzessin" que vous contrôlez; équipez cette carte à la cible. \r\nVous ne pouvez utiliser cet effet de "Pantoufles de Verre" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9709452,'Flamme Gaïa, Force du Soleil',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi cette carte attaquante détruit un monstre de l''adversaire au combat: elle peut faire une seconde attaque à la suite. \r\nUne fois par tour, à la fin de la Battle Phase: vous pouvez cibler un nombre de monstres FEU dans votre Cimetière, inférieur ou égal au nombre de monstres que cette carte a détruits au combat ce tour; ajoutez-les à votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9715126,'Ordre Amorceur - Force d''Équipement','Lorsque le monstre d''un joueur déclare une attaque et que tous les monstres que vous contrôlez sont des monstres Machine face recto (min. 1): détruisez un nombre de monstres en Position d''Attaque contrôlés par votre adversaire, inférieur ou égal au nombre de monstres Machine que vous contrôlez.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9718968,'Trancheur Photon','S''il y a un Monstre Xyz face recto sur le Terrain, vous pouvez Invoquer Spécialement cette carte (depuis votre main) en Position de Défense face recto.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9720537,'Sceau du Propriétaire','Rendez le contrôle de tous les monstres sur le Terrain à leur propriétaire.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9726840,'Assaut de l''Air - Mobilisation - Connexion !','Si vous ne contrôlez aucun monstre dans votre Zone Monstre Main: vous ne pouvez pas Invoquer Spécialement (monstres "Assaut de l''Air - As" exclus) depuis l''Extra Deck le reste de ce tour après la résolution de cette carte, et aussi, envoyez 1 autre carte que vous contrôlez au Cimetière, et si vous le faites, Invoquez Spécialement 1 monstre "Assaut de l''Air - As" depuis votre Extra Deck dans la Zone Monstre Extra, et si vous avez min. 1 monstre "Assaut de l''Air - As" LUMIÈRE et min. 1 monstre "Assaut de l''Air - As" TÉNÈBRES sur votre Terrain et/ou dans votre Cimetière, le monstre Invoqué gagne 1000 ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9742784,'Avion à Réaction Synchronique',replace(replace('Si cette carte est envoyée au Cimetière comme Matériel Synchro: vous pouvez ajouter 1 monstre "Robot" depuis votre Deck à votre main. \r\nSi cette carte est dans votre Cimetière: vous pouvez envoyer 1 carte depuis votre main au Cimetière; Invoquez Spécialement cette carte, mais bannissez-la lorsqu''elle quitte le Terrain. \r\nVous ne pouvez utiliser qu''1 effet de "Avion à Réaction Synchronique" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'Chercher dans le Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9744376,'Goblin, Gestionnaire Avisé','Piochez un nombre de cartes de votre Deck égal au nombre de "Goblin, Gestionnaire Avisé" dans votre Cimetière + 1, sélectionnez 1 carte de votre main et renvoyez-la sous votre Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9748752,'Caius, le Monarque des Ombres','Si cette carte est Invoquée par Sacrifice: ciblez 1 carte sur le Terrain; bannissez la cible, et si vous le faites, infligez 1000 points de dommages à votre adversaire si c''est un monstre TÉNÈBRES.','Bannir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9753964,'Bouillant Dragon Rouge Archdémon des Abysses',replace(replace('1 Syntoniseur + 1 Monstre Synchro non-Syntoniseur TÉNÈBRES Dragon	\r\n(Effet Rapide): vous pouvez cibler 1 carte face recto contrôlée par votre adversaire; jusqu''à la fin de ce tour, annulez ses effets. \r\nLorsque cette carte inflige des dommages de combat à votre adversaire: vous pouvez cibler 1 Syntoniseur dans votre Cimetière; Invoquez-le Spécialement en Position de Défense. \r\nVous ne pouvez utiliser chaque effet de "Bouillant Dragon Rouge Archdémon des Abysses" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Annuler l''effet','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9763474,'Lézardose Exténué',replace(replace('2 monstres de noms différents	\r\nVous pouvez bannir 1 monstre depuis votre Terrain face recto ou Cimetière avec max. 2000 ATK, puis ciblez 1 monstre face recto sur le Terrain; faites devenir son ATK égale à l''ATK d''origine du monstre banni pour activer cet effet (jusqu''à la fin de ce tour), puis si vous avez banni un monstre qui était Reptile à l''origine, piochez 1 carte. \r\nVous ne pouvez utiliser cet effet de "Lézardose Exténué" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9765723,'Contrat des Ténèbres avec la Sorcière',replace(replace('Vous pouvez envoyer 1 carte "D/D" ou "Contrat des Ténèbres" depuis votre main au Cimetière, puis ciblez 1 carte sur le Terrain; détruisez-la. \r\nVous ne pouvez utiliser cet effet de "Contrat des Ténèbres avec la Sorcière" qu''une fois par tour. \r\nTous les monstres de Type Démon que vous contrôlez gagnent 1000 ATK durant le tour de votre adversaire uniquement. \r\nUne fois par tour, durant votre Standby Phase: recevez 1000 points de dommages.','\r',char(13)),'\n',char(10)),'Détruire une carte','Subir des dommages','Utiliser l''effet ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9780364,'Dressage de Gladiateur',replace(replace('Si un monstre "Bête Gladiateur" face recto est sur le Terrain, activez 1 des ces effets:\r\n● Sélectionnez 1 monstre face recto contrôlé par votre adversaire et changez sa position de combat.\r\n● Sélectionnez 1 monstre "Bête Gladiateur" face recto contrôlé par votre adversaire et prenez son contrôle jusqu''à la fin de la End Phase.','\r',char(13)),'\n',char(10)),'Changer la position de combat','Prendre le contrôle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9785661,'Azamina Sol Erysichthon',replace(replace('1 monstre Illusion + 1 monstre Démon	\r\nSi cette carte est Invoquée par Fusion: vous pouvez cibler 1 carte sur le Terrain; envoyez-la au Cimetière. \r\nDurant la Standby Phase: vous pouvez cibler 1 carte "Azamina" ou "Butin du Péché" dans votre Cimetière; ajoutez-la à votre main. \r\nVous ne pouvez utiliser chaque effet de "Azamina Sol Erysichthon" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Renvoyer à la main','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9786492,'Rituel du Dragon Blanc',replace(replace('Cette carte est utilisée pour Invoquer Rituellement "Paladin du Dragon Blanc". \r\nVous devez aussi Sacrifier des monstres depuis votre main ou Terrain dont le Niveau total est égal à min. 4.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9791914,'Sentinelle Argent',replace(replace('Vous pouvez Poser cette carte depuis votre main dans votre Zone Carte Magie & Piège comme une Carte Magie. \r\nDurant la End Phase du tour où cette carte Posée dans votre Zone Carte Magie & Piège a été détruite par un effet de carte de votre adversaire et envoyée au Cimetière: ciblez 1 carte contrôlée par votre adversaire (si possible); Invoquez Spécialement cette carte depuis le Cimetière, et si vous le faites, détruisez la cible (s''il y en a une).','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9794980,'Idlee l''Incarnation, Chevalier du Cauchemar',replace(replace('Les monstres de Niveau 9 que vous contrôlez ne peuvent pas être détruits par des effets de carte. \r\nVous ne pouvez utiliser chacun des effets suivants de "Idlee l''Incarnation, Chevalier du Cauchemar" qu''une fois par tour.\r\n● Si la somme des Classifications Lien des monstres sur le Terrain est min. 8 (Effet Rapide): vous pouvez Invoquer Spécialement cette carte depuis votre main.\r\n● Si cette carte est Invoquée Spécialement, tant que votre adversaire contrôle plus de Monstres Lien que vous: vous pouvez envoyer tous les Monstres Lien sur le Terrain au Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9798352,'Prufinesse, le Trappeur Tactique',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez bannir 1 Piège depuis votre Deck; augmentez le Niveau de cette carte de 1. \r\nVous pouvez cibler 1 Piège dans l''un des Cimetières; bannissez-le, et si vous le faites, augmentez le Niveau de cette carte de 1. \r\nSi cette carte en possession de son propriétaire est détruite par une carte de l''adversaire: vous pouvez Poser 1 de vos Pièges Normaux bannis. \r\nVous ne pouvez utiliser chaque effet de "Prufinesse, le Trappeur Tactique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9817927,'Panda Gyaku-Gire',replace(replace('Augmentez l''ATK de cette carte de 500 points pour chaque monstre sur le Terrain de votre adversaire. \r\nLorsque cette carte attaque avec une ATK supérieure à la DEF du monstre en Position de Défense, infligez la différence aux Life Points de votre adversaire en tant que dommages de combat.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9822220,'Seigneur de la Prison Divine',replace(replace('Durant votre Main Phase: vous pouvez activer cet effet; jusqu''à la fin du tour de votre adversaire, cette carte dans votre main devient révélée. \r\nTant que cette carte est révélée par cet effet, les cartes Posées sur le Terrain ne peuvent pas être détruites par des effets de carte. \r\nSi une Carte Magie/Piège Posée est activée (sauf durant la Damage Step): vous pouvez Invoquer Spécialement cette carte depuis votre main, puis, si vous avez activé cet effet tant que cette carte était révélée, vous pouvez révéler et Poser 1 Magie/Piège depuis votre Deck, mais bannissez-le durant la End Phase du prochain tour. \r\nVous ne pouvez utiliser qu''1 effet de "Seigneur de la Prison Divine" par tour, et uniquement une fois le tour.','\r',char(13)),'\n',char(10)),'','Invoquer Spécialement cette carte depuis votre main','Poser 1 Carte Magie/Piège depuis votre Deck ?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9831539,'Porte Tannhäuser','Ciblez 2 monstres que vous contrôlez du même Type avec max. 1000 ATK; le Niveau des deux monstres devient la somme des Niveaux de ces 2 monstres.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9837195,'Musto, Oracle de Gusto','Une fois par tour: vous pouvez cibler 1 monstre "Gusto" dans votre Cimetière et 1 monstre face recto sur le Terrain; mélangez la première cible dans le Deck, et jusqu''à la End Phase, annulez les effets de la seconde cible.','Annuler les effets','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9839115,'Vagnawa le Dragon Mangeur de Lune',replace(replace('1 Syntoniseur + 1+ monstre non-Syntoniseur	\r\nSi cette carte est Invoquée par Synchronisation: vous pouvez activer cet effet; cette carte gagne 300 ATK pour chaque Niveau que les non-Syntoniseurs utilisés avaient, puis infligez 300 points de dommages à votre adversaire pour chaque Niveau que le Syntoniseur utilisé avait. \r\nLe gain d''ATK dure jusqu''à la fin du prochain tour. \r\nVous ne pouvez utiliser cet effet de "Vagnawa le Dragon Mangeur de Lune" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9839945,'Lyna la Charmeuse de Lumière Chatoyante',replace(replace('2 monstres (un monstre LUMIÈRE inclus)	\r\n(Cette carte est toujours traitée comme carte "Familier Possédé".)	\r\nVous pouvez cibler 1 monstre LUMIÈRE dans le Cimetière de votre adversaire; Invoquez-le Spécialement dans votre zone pointée par cette carte. \r\nSi cette carte Invoquée par Lien est détruite au combat, ou détruite par un effet de carte de l''adversaire tant qu''elle est dans la Zone Monstre de son propriétaire: vous pouvez ajouter 1 monstre LUMIÈRE avec max. 1500 DEF depuis votre Deck à votre main. \r\nVous ne pouvez utiliser chaque effet de "Lyna la Charmeuse de Lumière Chatoyante" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9845733,'Emblème de l''Émergence',replace(replace('Cette carte est utilisée pour faire l''Invocation Spéciale de "Cú Chulainn, l''Émergent". \r\nVous devez également sacrifier des monstres dont le total cumulé de Niveaux est de 4 ou plus depuis le Terrain ou votre main.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9848939,'Archer des Sylves',replace(replace('Cette carte ne peut pas être Invoquée Normalement ou Posée. \r\nCette carte ne peut pas être Invoquée Spécialement excepté en ayant 2 Monstres Normaux ou plus dans votre Cimetière. \r\nVous pouvez Sacrifier cette carte pour ajouter 1 monstre Gémeau depuis votre Deck à votre main.','\r',char(13)),'\n',char(10)),'Ajouter à la main','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9852718,'Détachement','Durant la Battle Phase de votre adversaire: envoyez 1 Magie depuis votre main au Cimetière; terminez la Battle Phase, puis les monstres face recto actuellement sur le Terrain ont leurs effets annulés jusqu''à la fin de ce tour.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9861795,'Mogmole',replace(replace('Lorsque cette carte sur le Terrain est détruite et envoyée au Cimetière: vous pouvez l''Invoquer Spécialement depuis votre Cimetière en Position de Défense face recto. \r\nVous ne pouvez utiliser l''effet de "Mogmole" qu''une fois par Duel.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9888196,'Armure Invincible, Allié de la Justice',replace(replace('1 Syntoniseur + 2+ monstres non-Syntoniseur	\r\nUne fois par tour, si votre adversaire contrôle un monstre LUMIÈRE: vous pouvez activer 1 de ces effets.\r\n● Ciblez 1 carte Posée contrôlée par votre adversaire; détruisez la cible.\r\n● Envoyez 1 carte depuis votre main au Cimetière; détruisez toutes les Magies et tous les Pièges contrôlés par votre adversaire.\r\n● Envoyez toute votre main au Cimetière; regardez la main de votre adversaire et envoyez tous les monstres LUMIÈRE dans sa main au Cimetière, puis, infligez des dommages à votre adversaire égaux à la somme des ATK de ces monstres envoyés au Cimetière.','\r',char(13)),'\n',char(10)),'Détruire 1 carte Posée sur le Terrain de votre adversaire','Détruire toutes les Cartes Magie/Piège sur le Terrain de votre adversaire','Envoyez tous les monstres LUMIÈRE dans la main de votre adversaire au Cimetière','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9897998,'Gusto Codor','Lorsque cette carte détruit un monstre de votre adversaire au combat et l''envoie au Cimetière: vous pouvez Invoquer Spécialement un monstre VENT de Type Psychique avec max. 1500 DEF depuis votre Deck.','Invocation Spéciale','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9910360,'Grenouille D3S',replace(replace('"Grenouille Des" + "Grenouille Des" + "Grenouille Des"	\r\nUne Invocation Fusion de cette carte ne peut être réalisée qu''avec les Monstres-Matériels de Fusion ci-dessus. \r\nAugmentez l''ATK de cette carte de 500 points pour chaque "Grenouille d''Arbre" dans votre Cimetière.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9925982,'Vengeance des Ailes Noires','Lorsqu''un monstre Bête Ailée que vous contrôlez est détruit au combat et envoyé au Cimetière: Invoquez Spécialement 2 "Jeton Aile Noire - Emblème Noir" (Bête Ailée/TÉNÈBRES/Niveau 2/ATK 0/DEF 800).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9925983,'Jeton Aile Noire - Emblème Noir','Invoqué Spécialement avec l''effet de "Vengeance des Ailes Noires".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9929398,'Aile Noire - Gofu la Vague de l''Ombre',replace(replace('Ni Invocable Normalement ni Posable Normalement. \r\nDoit d''abord être Invoquée Spécialement (depuis votre main) tant que vous ne contrôlez aucun monstre. \r\nLorsque cette carte est Invoquée Spécialement depuis la main: vous pouvez Invoquer Spécialement 2 "Jeton de la Vague de l''Ombre" (Type Bête Ailée/TÉNÈBRES/Niveau 1/ATK 0/DEF 0), mais ils ne peuvent ni être Sacrifiés ni être utilisés comme Matériels de Synchro. \r\nVous pouvez bannir cette carte et min. 1 non-Syntoniseur face recto que vous contrôlez, puis ciblez 1 Monstre Synchro "Aile Noire" dans votre Cimetière dont le Niveau est égal à la somme des Niveaux que les monstres bannis avaient sur le Terrain; Invoquez-le Spécialement, et si vous le faites, il est traité comme un Syntoniseur.','\r',char(13)),'\n',char(10)),'Invoquer Spécialement un Jeton','Invocation Spéciale','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9929399,'Jeton de la Vague de l''Ombre','Invoqué Spécialement avec l''effet de "Aile Noire - Gofu la Vague de l''Ombre". Ce Jeton ne peut pas être Sacrifié ou utilisé comme Matériel de Synchro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9940036,'Agrégateur Méréologique',replace(replace('2+ monstres de Niveau 9	\r\nSi cette carte est Invoquée par Xyz: vous pouvez envoyer 1 monstre depuis votre Extra Deck au Cimetière. \r\nVous pouvez cibler un nombre de monstres dans votre Cimetière, inférieur ou égal au nombre de Matériels que cette carte a; détachez un nombre de Matériels de cette carte égal au nombre des cibles dans le Cimetière, et si vous le faites, attachez les cibles à cette carte. \r\nSi cette carte est envoyée au Cimetière: vous pouvez cibler 1 carte face recto sur le Terrain; jusqu''à la fin de ce tour, annulez ses effets. \r\nVous ne pouvez utiliser chaque effet de "Agrégateur Méréologique" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9952083,'Chaîne d''Invocation',replace(replace('Activez en min. Maillon 3 de la Chaîne: ce tour, vous pouvez mener max. 3 Invocations/Poses Normales, pas uniquement 1. \r\nVous ne pouvez pas activer cette carte si plusieurs cartes de même nom ou les effets de ces cartes sont déjà activés dans cette Chaîne.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9978697,'Pellina, Sabre X',replace(replace('Si cette carte est Invoquée Normalement ou Spécialement: vous pouvez l''envoyer au Cimetière; Invoquez Spécialement 2 monstres "Sabre X" ("Pellina, Sabre X" exclu) depuis votre Deck, mais détruisez-les durant la End Phase. \r\nSi cette carte est envoyée au Cimetière comme Matériel Synchro pour un monstre "Sabre X": vous pouvez appliquer 1 de ces effets.\r\n● Le monstre peut faire une seconde attaque durant chaque Battle Phase.\r\n● Le monstre peut attaquer directement.	\r\nVous ne pouvez utiliser chaque effet de "Pellina, Sabre X" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'Invocation Spéciale','Conférer un effet','Attaquer deux fois','Attaque directe','Peut attaquer 2 fois','Peut attaquer directement','','','','','','','','','','');
INSERT INTO texts VALUES(9989792,'Forteresse Triamid',replace(replace('Tous les monstres de Type Rocher sur le Terrain gagnent 500 DEF. \r\nLes monstres "Triamid" sur le Terrain ne peuvent pas être détruits par des effets de carte. \r\nSi cette carte face recto dans la Zone Terrain est envoyée au Cimetière: vous pouvez cibler 1 monstre "Triamid" dans votre Cimetière; ajoutez-la à votre main. \r\nVous ne pouvez utiliser cet effet de "Forteresse Triamid" qu''une fois par tour.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9995766,'Tradition Impériale',replace(replace('Les Pièges Continus face recto ("Tradition Impériale" exclu) ne peuvent être détruits ni au combat ni par un effet de carte. \r\nVous ne pouvez contrôler qu''1 "Tradition Impériale".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9999961,'Rage Bestiale','Tous les monstres que vous contrôlez gagnent 200 points d''ATK pour chacun de vos monstres de Type Bête et de Type Bête Ailée retirés du jeu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000000,'Obelisk, le Tourmenteur',replace(replace('Nécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les cartes et les effets ne peuvent pas être activés. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Spécialement: envoyez-la au Cimetière. \r\nVous pouvez Sacrifier 2 monstres; détruisez tous les monstres contrôlés par votre adversaire. \r\nCette carte ne peut pas déclarer d''attaque le tour où cet effet est activé.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Détruire tous les monstres de votre adversaire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000001,'Obelisk, le Tourmenteur',replace(replace('Nécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les cartes et les effets ne peuvent pas être activés. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Spécialement: envoyez-la au Cimetière. \r\nVous pouvez Sacrifier 2 monstres; détruisez tous les monstres contrôlés par votre adversaire. \r\nCette carte ne peut pas déclarer d''attaque le tour où cet effet est activé.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Détruire tous les monstres de votre adversaire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000002,'Obelisk, le Tourmenteur',replace(replace('Nécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les cartes et les effets ne peuvent pas être activés. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Spécialement: envoyez-la au Cimetière. \r\nVous pouvez Sacrifier 2 monstres; détruisez tous les monstres contrôlés par votre adversaire. \r\nCette carte ne peut pas déclarer d''attaque le tour où cet effet est activé.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Détruire tous les monstres de votre adversaire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000003,'Obelisk, le Tourmenteur',replace(replace('Nécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les cartes et les effets ne peuvent pas être activés. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Spécialement: envoyez-la au Cimetière. \r\nVous pouvez Sacrifier 2 monstres; détruisez tous les monstres contrôlés par votre adversaire. \r\nCette carte ne peut pas déclarer d''attaque le tour où cet effet est activé.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Détruire tous les monstres de votre adversaire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000004,'Obelisk, le Tourmenteur',replace(replace('Nécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les cartes et les effets ne peuvent pas être activés. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Spécialement: envoyez-la au Cimetière. \r\nVous pouvez Sacrifier 2 monstres; détruisez tous les monstres contrôlés par votre adversaire. \r\nCette carte ne peut pas déclarer d''attaque le tour où cet effet est activé.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Détruire tous les monstres de votre adversaire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000005,'Obelisk, le Tourmenteur',replace(replace('Nécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les cartes et les effets ne peuvent pas être activés. \r\nAucun joueur ne peut cibler cette carte avec des effets de carte. \r\nUne fois par tour, durant la End Phase, si cette carte a été Invoquée Spécialement: envoyez-la au Cimetière. \r\nVous pouvez Sacrifier 2 monstres; détruisez tous les monstres contrôlés par votre adversaire. \r\nCette carte ne peut pas déclarer d''attaque le tour où cet effet est activé.','\r',char(13)),'\n',char(10)),'Envoyer au Cimetière','Détruire tous les monstres de votre adversaire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000010,'Le Dragon Ailé de Râ',replace(replace('Non Invocable Spécialement. \r\nNécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les autres cartes et effets ne peuvent pas être activés. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez payer des LP jusqu''à n''en avoir plus que 100; cette carte gagne une ATK/DEF égales au montant des LP payés. \r\nVous pouvez payer 1000 LP, puis ciblez 1 monstre sur le Terrain; détruisez la cible.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK/DEF','Détruire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000011,'Le Dragon Ailé de Râ',replace(replace('Non Invocable Spécialement. \r\nNécessite 3 Sacrifices pour son Invocation Normale (non Posable Normalement). \r\nL''Invocation Normale de cette carte ne peut pas être annulée. \r\nLorsqu''elle est Invoquée Normalement, les autres cartes et effets ne peuvent pas être activés. \r\nLorsque cette carte est Invoquée Normalement: vous pouvez payer des LP jusqu''à n''en avoir plus que 100; cette carte gagne une ATK/DEF égales au montant des LP payés. \r\nVous pouvez payer 1000 LP, puis ciblez 1 monstre sur le Terrain; détruisez la cible.','\r',char(13)),'\n',char(10)),'Augmenter l''ATK/DEF','Détruire','Sacrifier 3 monstres pour Invoquer','','','','','','','','','','','','','');
